/* Contenido de charlas (perello): más información y preguntas más exigentes. Lo aplica mejoras_comunes.js (sección 23). */
window.__mjContenidoAplicar && window.__mjContenidoAplicar({"grupo":"per","temas":[{"id":"autocuidado","sec":"todos","title":"Actos inseguros, condiciones inseguras y autocuidado","thumb":"auto_cadena","learn":[{"s":"pe_cinta_mal","t":"¿Qué es un acto inseguro?","x":"Es una acción u omisión de la persona que se aparta de la forma segura de trabajar. Ejemplos en la planta:<ul><li>Meter la mano en una cinta, cerradora o llenadora en marcha.</li><li>Cortar con cuchillo sin guantes o hacia el cuerpo.</li><li>Pasar bajo una carga levantada por la grúa horquilla.</li><li>Subirse a las horquillas, a un pallet o a una ruma.</li><li>Operar un equipo sin capacitación ni autorización.</li></ul>","k":"Nunca metas la mano en una máquina en marcha: detén y bloquea primero."},{"s":"auto_cond","t":"¿Qué es una condición insegura?","x":"Es una situación del lugar, la máquina o el material que puede causar un accidente. Ejemplos:<ul><li>Agua, jugo o aceite en el piso sin señalizar.</li><li>Cable eléctrico dañado o cruzando el paso.</li><li>Pallet roto o ruma de cajas inclinada.</li><li>Extintor tapado por cajas.</li><li>Resguardo suelto o parada de emergencia que no funciona.</li><li>Luz quemada en un pasillo.</li></ul>Toda condición insegura se corrige o se reporta."},{"s":"auto_cadena","t":"Cómo se arma un accidente","x":"Un accidente rara vez tiene una sola causa. Es como una fila de fichas de dominó: <b>apuro, sin EPP, derrame, accidente</b>. Casi siempre se junta un acto inseguro con una condición insegura. <b>Si sacas una ficha, la cadena se corta</b> y el accidente no ocurre. La mayoría de los accidentes se relacionan con una acción insegura, y esa ficha depende de ti."},{"s":"auto_porque","t":"¿Por qué cometemos actos inseguros?","x":"<ul><li><b>Apuro:</b> “hay que sacar el camión”, sobre todo en temporada alta.</li><li><b>Exceso de confianza:</b> “llevo años haciéndolo”.</li><li><b>Costumbre:</b> de tanto verlo, el riesgo se vuelve invisible.</li><li><b>Cansancio:</b> en turnos largos baja la atención.</li><li><b>“Siempre se ha hecho así”:</b> que nunca haya pasado nada no demuestra que sea seguro; el riesgo sigue ahí.</li></ul>"},{"s":"auto_ppa","t":"Para, piensa, actúa","x":"Úsalo antes de cada tarea, y sobre todo si es nueva, si algo cambió o si te piden algo urgente:<ul><li><b>Para:</b> detente unos segundos.</li><li><b>Piensa:</b> ¿qué puede salir mal? ¿Tengo el EPP correcto? ¿La máquina está detenida y bloqueada? ¿Estoy autorizado?</li><li><b>Actúa:</b> hazlo de forma segura. Si tienes una duda, pregunta a tu jefatura antes de empezar.</li></ul>"},{"s":"auto_companero","t":"Me cuido y cuido a mi compañero","x":"Si ves a un compañero a punto de hacer algo riesgoso, avísale con respeto: “Espera, detén y bloquea antes de destrabar”. No es meterse en lo ajeno: es cuidarnos entre todos. Si insiste en hacerlo mal, avisa de inmediato a la jefatura. Y si te avisan a ti, agradece y corrige: te pueden estar salvando una mano."},{"s":"auto_reporte","t":"Reporta las condiciones inseguras","x":"Avisar es parte del autocuidado. Si ves un derrame, un cable dañado, una protección rota o tienes un casi accidente, <b>avisa a tu jefatura o al Comité Paritario</b>. Si puedes hacerlo sin riesgo, actúa de inmediato: pon un cono junto al derrame o seca el agua. No lo tapes con un cartón ni lo dejes para después: lo que no se reporta, no se corrige."},{"s":"auto_184","t":"Ante un riesgo grave: detente, aléjate y avisa","x":"Un rack con carga que se dobla, una fuga de vapor o de amoníaco, humo en la sala de caldera: son riesgos graves e inminentes. <b>Detén la tarea, aléjate, aleja a los demás y avisa de inmediato</b> a tu jefatura. El Código del Trabajo (art. 184 bis) te da derecho a interrumpir el trabajo y abandonar el lugar en ese caso, sin que puedas ser sancionado por ello. Nunca intentes arreglarlo tú.","k":"Ante un riesgo grave e inminente, detente, aléjate y avisa de inmediato."},{"s":"auto_ri","t":"Tus obligaciones: Reglamento Interno y EPP","x":"Cada trabajador de {EMP} debe:<ul><li>Cumplir el Reglamento Interno de Orden, Higiene y Seguridad (Ley 16.744, art. 67).</li><li>Usar y cuidar el EPP.</li><li>Seguir los procedimientos de trabajo.</li><li>No operar equipos sin capacitación ni autorización, aunque sepas manejarlos.</li><li>No trabajar bajo los efectos del alcohol o drogas.</li></ul>Si un accidente se debe a negligencia inexcusable del trabajador, la ley permite multarlo (art. 70)."},{"s":"auto_conse","t":"Autocuidado: piensa en quién te espera","x":"Un accidente no solo te afecta a ti:<ul><li><b>Tú:</b> dolor, secuelas, meses sin hacer lo que te gusta.</li><li><b>Tu familia:</b> preocupación, cuidados, cambios en la casa.</li><li><b>Tu equipo:</b> un compañero menos y el susto.</li></ul>La acción insegura típica es “ahorrarse” un paso por apuro. Decide seguro antes, no después: vuelve a casa igual que como llegaste."}],"quiz":[{"s":"pe_cinta_mal","v":[{"q":"Meter la mano en la cinta en marcha para sacar una lata trabada es:","o":["Un acto inseguro","Una condición insegura","Un riesgo aceptable si es rápido","Una falla de la máquina"],"w":"Es una decisión de la persona que se aparta de la forma segura de trabajar."},{"q":"Un trabajador saca una lata trabada de la cerradora sin detenerla. ¿Cómo se clasifica lo que hizo?","o":["Acto inseguro, porque es una decisión de la persona","Condición insegura, porque la lata estaba trabada","Condición insegura, porque la máquina no paró sola","No es inseguro si usa guantes de nitrilo"],"w":"La lata trabada es la condición; meter la mano sin detener es el acto inseguro."},{"q":"Si la cinta avanza lento, meter la mano para sacar una lata trabada no es un acto inseguro.","vf":false,"w":"Falso. Aunque vaya lento, la cinta puede atrapar la mano. Primero se detiene y se bloquea."}]},{"s":"auto_cond","v":[{"q":"Un cable dañado cruzando el pasillo es:","o":["Una condición insegura","Un acto inseguro","Un peligro solo para el eléctrico","Algo normal si nadie lo pisa"],"w":"Es un peligro que está en el lugar: se corrige o se reporta."},{"q":"En tu recorrido ves un pallet roto, agua en el piso y un extintor tapado. Estas situaciones son:","o":["Condiciones inseguras: se corrigen o se reportan","Actos inseguros de quien pasa cerca de ellas","Problemas de aseo que no afectan la seguridad","Riesgos que solo atiende el Comité Paritario"],"w":"Son peligros del ambiente. Cualquier trabajador puede y debe reportarlos."},{"q":"¿Cuál de estas es una condición insegura?","o":["Un extintor tapado por una caja","Correr por un pasillo mojado","Trabajar sin guantes en la línea","Pasar bajo la carga de la grúa"],"w":"Las otras son acciones de personas; el extintor tapado es una condición del lugar."}]},{"s":"auto_cadena","v":[{"q":"La mayoría de los accidentes se relacionan con:","o":["Una acción insegura, como apurarse o no usar el EPP","Fallas de máquinas que nadie puede prever","La mala suerte de estar en el lugar equivocado","Las condiciones del clima en la temporada"],"w":"Por eso nuestras decisiones son clave para evitarlos."},{"q":"En la cadena del dominó (apuro, sin EPP, derrame, accidente), ¿qué pasa si sacas una ficha?","o":["La cadena se corta y el accidente no ocurre","El accidente ocurre igual, pero más tarde","Solo se corta si sacas la última ficha","Solo sirve si la ficha es la condición insegura"],"w":"Cualquier ficha que saques corta la cadena, y muchas dependen de ti."},{"q":"Si eliminas una de las causas de la cadena, por ejemplo usando el EPP, el accidente puede no ocurrir.","vf":true,"w":"Verdadero. Al sacar una ficha del dominó, la cadena se corta."}]},{"s":"auto_porque","v":[{"q":"Un compañero dice: “llevo diez años haciéndolo así y nunca me ha pasado nada”. ¿Qué causa de actos inseguros refleja?","o":["Exceso de confianza","Cansancio","Apuro","Falta de EPP"],"w":"Creer que la experiencia protege hace bajar la guardia."},{"q":"En plena temporada te dicen “hay que sacar el camión”. ¿Qué causa de actos inseguros puede aparecer?","o":["El apuro","La costumbre","El exceso de confianza","El cansancio"],"w":"La presión por terminar lleva a saltarse pasos."},{"q":"Que una tarea “siempre se haya hecho así” sin accidentes significa que:","o":["No demuestra que sea segura: el riesgo puede seguir ahí","Es segura y no necesita revisión","Es segura mientras la haga alguien con experiencia","Solo debe revisarse si cambia la jefatura"],"w":"Que no haya pasado nada todavía no elimina el riesgo."}]},{"s":"auto_ppa","v":[{"q":"¿Qué significa “Para, piensa, actúa”?","o":["Detenerte, ver qué puede salir mal y hacerlo seguro","Parar la máquina, pensar rápido y seguir igual","Esperar a que la jefatura decida por ti","Trabajar más lento durante todo el turno"],"w":"Unos segundos de análisis antes de actuar evitan lesiones."},{"q":"Te piden una tarea en la autoclave que nunca has hecho. Según “Para, piensa, actúa”, ¿qué haces?","o":["Me detengo, evalúo el riesgo y pregunto antes","La hago tal como me la mostró un compañero una vez","La hago rápido para no atrasar la producción","Empiezo y, si algo sale mal, pido ayuda a alguien"],"w":"Ante una tarea nueva o una duda, se pregunta antes de empezar."},{"q":"¿En qué momento es más importante aplicar “Para, piensa, actúa”?","o":["Cuando la tarea es nueva o algo cambió","Solo al comenzar el turno","Solo cuando hay una visita de la ACHS","Cuando ya ocurrió un accidente"],"w":"Lo nuevo o lo que cambió trae riesgos que aún no conoces."}]},{"s":"auto_ok","v":[{"q":"¿Qué hace segura esta forma de trabajar en la cinta?","o":["Resguardo puesto, orden y parada a mano","Velocidad baja y un compañero siempre mirando","Guantes gruesos para poder meter la mano","Un letrero de precaución pegado sobre la cinta"],"w":"Las barreras físicas y la parada de emergencia protegen aunque alguien se distraiga."},{"q":"¿Cuál es la forma segura de trabajar en una cinta transportadora?","o":["Con el resguardo puesto y la parada a mano","Sin el resguardo, para ver mejor el producto","Con guantes, aunque se meta la mano en marcha","Con la cinta en marcha lenta mientras se limpia"],"w":"El resguardo nunca se retira y la parada de emergencia debe estar a mano."},{"q":"Si la parada de emergencia está cerca, se puede trabajar en la cinta sin el resguardo.","vf":false,"w":"Falso. La parada sirve después del problema; el resguardo evita que la mano entre."}]},{"s":"auto_reporte","v":[{"q":"Ves aceite derramado en el pasillo. ¿Qué haces?","o":["Lo señalizo, si es seguro, y aviso a mi jefatura","Paso por el lado con cuidado y sigo trabajando","Espero a que lo vea y lo limpie el personal de aseo","Lo tapo con un cartón para que nadie resbale"],"w":"Señalizar y avisar evita que otro resbale. El cartón esconde el peligro."},{"q":"Encuentras jugo en el piso de la línea y no puedes limpiarlo en ese momento. ¿Qué haces?","o":["Pongo un cono y aviso a la jefatura","Sigo, porque limpiar no es parte de mi tarea","Lo cubro con cajas para que nadie lo pise","Le aviso solo a mi compañero de al lado"],"w":"Primero se advierte a todos y se reporta para que se corrija."},{"q":"¿Por qué hay que reportar una condición insegura aunque todavía no haya pasado nada?","o":["Porque si no se reporta, no se corrige y otro se lesiona","Porque así se identifica al culpable del problema","Porque solo así queda registro para la auditoría","Porque es una tarea exclusiva del Comité Paritario"],"w":"Reportar a tiempo permite corregir antes del accidente."}]},{"s":"auto_184","v":[{"q":"Un rack con carga empieza a doblarse. ¿Qué haces?","o":["Me alejo, alejo a los demás y aviso de inmediato","Intento enderezarlo con ayuda de un compañero","Saco rápido la carga de abajo para alivianarlo","Sigo trabajando y lo aviso al final del turno"],"w":"Es un riesgo grave e inminente: alejarse, advertir y avisar."},{"q":"Según el Código del Trabajo (art. 184 bis), ante un riesgo grave e inminente puedes:","o":["Interrumpir la tarea, alejarte y avisar de inmediato","Seguir hasta terminar, porque detenerse es abandono","Detenerte solo si la jefatura lo autoriza antes","Detenerte, pero sin avisar para no alarmar"],"w":"La ley te da derecho a detenerte y alejarte, con aviso inmediato a la jefatura."},{"q":"Si te detienes y te alejas ante un riesgo grave e inminente, la empresa puede sancionarte por abandonar tu puesto.","vf":false,"w":"Falso. El art. 184 bis protege al trabajador que se detiene ante un riesgo grave e inminente."}]},{"s":"auto_ri","v":[{"q":"¿Cuál de estas es una obligación del trabajador según el Reglamento Interno?","o":["Usar el EPP y seguir los procedimientos de trabajo","Comprar su propio EPP si se le daña","Operar cualquier equipo que sepa manejar","Reparar las máquinas que fallan en su línea"],"w":"Usar el EPP y seguir los procedimientos son deberes de seguridad del trabajador."},{"q":"Sabes manejar la grúa horquilla porque aprendiste en otro trabajo, pero aquí no te han autorizado. ¿Puedes operarla?","o":["No, sin autorización de la empresa no se opera","Sí, si tengo licencia de conducir clase D al día","Sí, si es solo para mover un pallet cerca","Sí, si la jefatura no está en ese momento"],"w":"Saber manejar no basta: se requiere capacitación y autorización de la empresa."},{"q":"Usar el EPP y cumplir el Reglamento Interno es una obligación del trabajador.","vf":true,"w":"Verdadero. Son parte de tus deberes de seguridad (Ley 16.744, art. 67)."}]},{"s":"auto_companero","v":[{"q":"Un compañero va a sacar una lata trabada sin detener la cinta. ¿Qué haces?","o":["Le aviso con respeto que detenga y bloquee primero","No digo nada: cada uno sabe lo que hace","Lo ayudo a sacarla rápido para no atrasarnos","Le comento a la jefatura al final del turno"],"w":"Avisar a tiempo es cuidarnos entre todos."},{"q":"Le pides a un compañero que detenga la cinta antes de destrabar y él sigue igual. ¿Qué haces?","o":["Insisto y, si sigue, aviso de inmediato a la jefatura","Lo dejo, porque ya cumplí con avisarle una vez","Lo comento en la próxima charla de seguridad","Le tiro del brazo para sacarlo de la cinta"],"w":"Si el riesgo continúa, la jefatura debe saberlo de inmediato."},{"q":"Avisar a un compañero que está haciendo algo riesgoso es:","o":["Cuidarnos entre todos, no acusar","Meterse en el trabajo ajeno","Tarea que corresponde solo a la jefatura","Correcto solo si eres más antiguo que él"],"w":"Cualquiera puede y debe advertir un riesgo, con respeto."}]}]},{"id":"peligros","sec":"todos","title":"Peligros y riesgos: identificación y control (MIPER)","thumb":"pyramid","learn":[{"s":"peligros_vs","t":"Peligro y riesgo no son lo mismo","x":"<b>Peligro</b> es lo que puede causar daño: la cinta en marcha, el vapor de un autoclave, el agua en el piso. <b>Riesgo</b> es la <b>posibilidad</b> de que ese peligro te dañe y qué tan grave sería. Ejemplo: la cinta es el peligro; que te atrape la mano es el riesgo. Con resguardo y bloqueo el riesgo baja, aunque la cinta siga siendo un peligro."},{"s":"pe_planta","t":"Los peligros de nuestras plantas","x":"<ul><li><b>Cintas, cerradoras y líneas:</b> atrapamiento.</li><li><b>Cuchillos y bordes de latas:</b> cortes.</li><li><b>Piso húmedo por lavado o derrames:</b> resbalones y caídas.</li><li><b>Autoclaves, caldera, marmitas y hornos:</b> quemaduras y vapor a presión.</li><li><b>Grúa horquilla y camiones en patio:</b> atropellos.</li><li><b>Químicos de aseo:</b> quemaduras e inhalación.</li><li><b>Cámaras de frío, ruido y tareas repetitivas.</b></li></ul>Conocerlos es el primer paso para controlarlos."},{"s":"peligros_miper","t":"La matriz MIPER","x":"La <b>Matriz de Identificación de Peligros y Evaluación de Riesgos</b> ordena cada tarea con sus peligros, sus riesgos y las medidas de control. Por ejemplo: tarea corte, peligro cuchillo, riesgo corte, control guantes y técnica. Según el DS 44, la empresa debe identificar los peligros, evaluar los riesgos de cada puesto, informártelos y actualizar la matriz cuando cambia un proceso o tras un accidente."},{"s":"peligros_eval","t":"¿Cómo se evalúa un riesgo?","x":"Se hacen dos preguntas: <b>¿qué tan seguido puede pasar?</b> (probabilidad) y <b>¿qué tan grave sería?</b> (consecuencia). El resultado es un riesgo bajo, medio o alto. Un atrapamiento en una cerradora quizás no es frecuente, pero puede costar una mano: por eso es un riesgo alto y se controla primero. Un riesgo alto sin control no se trabaja."},{"s":"peligros_jerarquia","t":"Jerarquía de controles","x":"De más a menos efectivo:<ul><li><b>Eliminar</b> el peligro: por ejemplo, automatizar una tarea.</li><li><b>Sustituir:</b> un químico de aseo corrosivo por otro menos peligroso que limpie igual.</li><li><b>Ingeniería:</b> resguardos, paradas de emergencia, ventilación.</li><li><b>Administrativos:</b> procedimientos, bloqueo, señalización, capacitación.</li><li><b>EPP:</b> la última barrera, porque no elimina el peligro.</li></ul>","k":"Primero se elimina o controla el peligro en su origen; el EPP es la última barrera."},{"s":"pe_cinta_ok","t":"Ejemplo: la cinta transportadora","x":"Un mismo peligro necesita varias capas de control: el <b>resguardo y la parada de emergencia</b> (ingeniería), el <b>bloqueo antes de limpiar</b> y el procedimiento de trabajo seguro (administrativos), y <b>guantes y ropa ajustada</b> (EPP). Si falta una capa, las otras quedan solas y el riesgo sube. Por eso ninguna se omite, ni siquiera “por un segundo”."},{"s":"peligros_irl","t":"Conoce los riesgos de tu puesto","x":"Según el DS 44, {EMP} debe informarte los riesgos de tu puesto, las medidas preventivas y la forma correcta de trabajar: al ingresar, al cambiar de puesto o de tarea y cuando llega una máquina o un proceso nuevo. Es tu derecho a saber. Tu parte: <b>ponerlas en práctica</b> todos los días y preguntar antes de empezar si algo no te quedó claro."},{"s":"peligros_reporta","t":"Reporta las condiciones inseguras","x":"Resguardo suelto, cable pelado, pallet roto, piso mojado sin señalizar, luz quemada: avísalo a tu jefatura o al Comité Paritario, aunque no sea de tu área. Si puedes corregirlo sin riesgo (secar el agua, recoger una lata), hazlo. Si no, no uses lo que está dañado, advierte a los demás y avisa. Un peligro avisado a tiempo es un accidente evitado."},{"s":"peligros_auto","t":"Autocuidado: acción insegura y condición insegura","x":"La condición insegura es el peligro que está en el lugar, como un resguardo roto. La acción insegura es lo que hacemos, como sacar el resguardo para destrabar más rápido. La mayoría de los accidentes se relacionan con una acción insegura. La decisión segura: <b>detener la máquina, bloquearla y avisar</b>. Nunca retires ni anules una protección.","k":"Nunca retires un resguardo: detén la máquina, bloquéala y avisa."}],"quiz":[{"s":"peligros_vs","v":[{"q":"Una cinta transportadora en marcha es un ejemplo de:","o":["Peligro","Riesgo","Medida de control","Acto inseguro"],"w":"La cinta es la fuente que puede causar daño: un peligro."},{"q":"El vapor de un autoclave puede causar una quemadura. En prevención, el vapor es:","o":["El peligro","El riesgo","La consecuencia","El control administrativo"],"w":"El vapor es la fuente del daño; la posibilidad de quemarse es el riesgo."},{"q":"¿Cuál de estos es un peligro y no un riesgo?","o":["La cinta en marcha","La posibilidad de que te atrape la mano","Qué tan grave sería el atrapamiento","Qué tan seguido ocurre un atrapamiento"],"w":"El peligro es la fuente; el riesgo es la posibilidad y la gravedad del daño."}]},{"s":"peligros_vs","v":[{"q":"La posibilidad de quedar atrapado en la cinta y qué tan grave sería es:","o":["El riesgo","El peligro","La medida de control","El acto inseguro"],"w":"Riesgo es la posibilidad de daño y su gravedad."},{"q":"Si se instala un resguardo en la cinta, ¿qué cambia?","o":["Baja el riesgo, pero la cinta sigue siendo un peligro","Desaparece el peligro y ya no queda ningún riesgo","Sube el riesgo porque se ve menos lo que pasa","No cambia nada mientras la cinta siga funcionando"],"w":"Los controles bajan el riesgo; el peligro sigue existiendo."},{"q":"Un mismo peligro puede tener un riesgo bajo o alto según las medidas de control que existan.","vf":true,"w":"Verdadero. Los controles reducen la posibilidad o la gravedad del daño."}]},{"s":"peligros_jerarquia","v":[{"q":"¿Cuál es la medida de control más efectiva?","o":["Eliminar el peligro","Entregar el mejor EPP","Capacitar a todos los trabajadores","Poner señalización visible"],"w":"Eliminar está en la cima de la jerarquía de controles."},{"q":"¿Cuál es el orden de los controles, de más a menos efectivo?","o":["Eliminar, sustituir, ingeniería, administrativos, EPP","EPP, administrativos, ingeniería, sustituir, eliminar","Sustituir, eliminar, EPP, ingeniería, administrativos","Ingeniería, EPP, eliminar, administrativos, sustituir"],"w":"Primero se ataca el peligro en su origen; el EPP queda al final."},{"q":"Cambiar un químico de aseo corrosivo por otro menos peligroso que limpia igual es un control de:","o":["Sustitución","Ingeniería","EPP","Tipo administrativo"],"w":"Reemplazar algo peligroso por algo menos peligroso es sustituir."}]},{"s":"peligros_jerarquia","v":[{"q":"El EPP es la primera medida que se debe aplicar para controlar un riesgo.","vf":false,"w":"Falso. Es la última barrera, después de los demás controles."},{"q":"Al EPP (casco, lentes, guantes, zapatos) le dicen «la última barrera». ¿Qué quiere decir?","o":["Que te protege del peligro que no se pudo eliminar antes","Que es lo más caro de la empresa","Que solo se usa cuando hay una inspección","Que reemplaza a los resguardos de las máquinas"],"w":"Primero se intenta sacar o controlar el peligro (barandas, protecciones, orden, procedimientos). Lo que queda, lo frena el EPP en tu cuerpo."},{"q":"Para controlar el atrapamiento en una máquina, ¿qué conviene aplicar primero?","o":["Un resguardo en la máquina","Guantes más gruesos","Un letrero de advertencia","Una charla de cinco minutos"],"w":"El control de ingeniería está antes que la señalización y el EPP."}]},{"s":"pe_cerradora","v":[{"q":"Instalar un resguardo en la cerradora es un control:","o":["De ingeniería","Administrativo","De EPP","De sustitución"],"w":"Los resguardos y las paradas de emergencia son controles de ingeniería."},{"q":"¿Cuál de estos es un control de ingeniería en la cerradora?","o":["El resguardo fijo y su parada de emergencia","El procedimiento escrito de limpieza","Los guantes de nitrilo del operador","La capacitación anual del personal"],"w":"Ingeniería es modificar la máquina o el lugar para aislar el peligro."},{"q":"Un resguardo en la cerradora es un control de ingeniería, porque separa a la persona del peligro.","vf":true,"w":"Verdadero. Actúa sobre la máquina, no depende de la conducta de la persona."}]},{"s":"peligros_irl","v":[{"q":"¿Cuándo debe informarte la empresa los riesgos de tu puesto?","o":["Al ingresar y cada vez que cambias de puesto","Solo cuando ocurre un accidente en tu área","Solo si tú lo pides por escrito a la jefatura","Una vez al año, en la charla anual de seguridad"],"w":"El DS 44 exige informar los riesgos al ingresar y ante cambios."},{"q":"Llega una máquina nueva a tu línea. ¿Qué corresponde antes de operarla?","o":["Que me informen sus riesgos y cómo usarla","Probarla yo mismo para aprender cómo funciona","Usarla igual que la anterior, porque son parecidas","Esperar a que un compañero la use primero"],"w":"Una máquina nueva trae riesgos nuevos: se informa antes de usarla."},{"q":"La obligación de informar los riesgos de tu puesto la establece:","o":["El DS 44","La Ley de Tránsito","La Ley Karin","La Ley 20.949 de cargas"],"w":"El DS 44 regula la gestión preventiva e incluye informar los riesgos."}]},{"s":"peligros_ignora","v":[{"q":"Un trabajador ve aceite en el piso y un pallet roto, y sigue de largo pensando “no es mío”. ¿Qué debió hacer?","o":["Advertir a los demás y avisar a la jefatura","Nada, porque no es de su área","Esperar a que lo vea el encargado de bodega","Arreglar el pallet roto él solo"],"w":"Ver un peligro y avisarlo permite corregirlo antes de que alguien se lesione."},{"q":"¿Por qué está mal pasar de largo ante una condición insegura de otra área?","o":["Porque el siguiente que pase puede lesionarse","Porque la jefatura podría estar mirando","Porque así lo exige el contrato de aseo","Porque el Comité Paritario pone multas"],"w":"El peligro afecta a cualquiera que pase, sea o no de esa área."},{"q":"Si una condición insegura no es de tu área, no te corresponde avisarla.","vf":false,"w":"Falso. Cualquier trabajador debe avisar los peligros que ve."}]},{"s":"peligros_reporta","v":[{"q":"Ves un pallet roto en el rack. ¿Qué haces?","o":["No lo uso, advierto y aviso a mi jefatura","Le pongo solo carga liviana para que aguante","Lo cambio de lugar yo solo, con cuidado","Lo dejo y lo anoto para informarlo a fin de mes"],"w":"Es una condición insegura: no se usa, se advierte y se reporta."},{"q":"Ves agua en el piso junto al rack y puedes secarla sin riesgo. ¿Qué haces?","o":["La seco o señalizo, y aviso si se repite","La dejo, porque el piso se seca solo","Paso por el lado con cuidado y sigo trabajando","Les aviso solo a mis compañeros de línea"],"w":"Si se puede corregir sin riesgo, se hace; si se repite, hay una causa que reportar."},{"q":"¿A quién avisas una condición insegura?","o":["A tu jefatura o al Comité Paritario","Solo a tus compañeros de turno","Solo a la ACHS","A nadie, si puedes esquivarla"],"w":"La jefatura y el Comité Paritario pueden gestionar la corrección."}]},{"s":"peligros_auto","v":[{"q":"Sacar el resguardo de la cerradora para destrabar más rápido es:","o":["Una acción insegura","Una condición insegura","Un control administrativo","Una práctica aceptada si es rápido"],"w":"Es una decisión de la persona: una acción insegura que puede costar una mano."},{"q":"La cerradora se traba y el resguardo impide sacar la lata. ¿Cuál es la decisión segura?","o":["Detener la máquina, bloquearla y avisar","Retirar el resguardo y destrabar con cuidado","Pedir a un compañero que vigile mientras destrabas","Meter la mano por un costado del resguardo"],"w":"Con la máquina detenida y bloqueada nadie queda atrapado."},{"q":"Un resguardo roto y la decisión de retirarlo a propósito son, en ese orden:","o":["Condición insegura y acción insegura","Acción insegura y condición insegura","Riesgo y peligro","Control de ingeniería y control administrativo"],"w":"Lo que está en el lugar es condición; lo que hace la persona es acción."}]}]},{"id":"epp","sec":"todos","mins":5,"title":"Uso y cuidado del EPP","thumb":"pe_epp_todo","learn":[{"s":"pe_epp_todo","t":"¿Qué es el EPP?","x":"Son los Elementos de Protección Personal. En la conservera: <b>gorro con cofia, mascarilla, pechera blanca, guantes de nitrilo y botas blancas</b>. Protegen tu salud y también la inocuidad de los alimentos. El EPP <b>no elimina el peligro</b>: solo reduce el daño si ocurre el contacto. Por eso es la última barrera, después de controlar el peligro en la máquina o el proceso."},{"s":"pe_epp_give","t":"Lo que dice la ley","x":"El empleador debe entregar <b>gratis</b> los EPP adecuados al riesgo y enseñar a usarlos (DS 594, art. 53; Ley 16.744, art. 68). No se descuentan del sueldo, y el recambio por desgaste o daño también es sin costo. El trabajador, por su parte, <b>está obligado a usarlos</b> todo el tiempo que esté expuesto al riesgo.","k":"La empresa entrega el EPP gratis; tú estás obligado a usarlo."},{"s":"epp_cert","t":"EPP certificado","x":"El EPP debe contar con certificación de calidad (DS 18 de 1982). Usa solo el que te entrega la empresa para tu puesto. No reemplaces un guante o una mascarilla por uno traído de la casa o hecho a mano: puede verse parecido, pero no protege igual. Si el que tienes no te sirve, pide otro modelo a tu jefatura."},{"s":"pe_epp_area","t":"Cada área, su EPP","x":"<ul><li><b>Conservera y proceso:</b> cofia, mascarilla, pechera blanca, guantes de nitrilo y botas blancas.</li><li><b>Deshidratado de mosqueta:</b> cotona y cofia; guantes de cabritilla en hornos y carros, multiflex en selección y embandejado.</li><li><b>Aseo y sanitización:</b> guantes largos, antiparras y pechera.</li><li><b>Caldera y autoclaves:</b> guantes para calor y fonos donde se indique.</li><li><b>Cámaras de frío:</b> ropa térmica.</li><li><b>Patio y bodega:</b> chaleco reflectante y zapatos de seguridad.</li></ul>"},{"s":"pe_epp_revisa","t":"Revísalo antes de usarlo","x":"Antes de cada turno revisa:<ul><li>Guantes sin hoyos, cortes ni partes gastadas.</li><li>Mascarilla limpia y con elásticos firmes.</li><li>Cofia sin roturas.</li><li>Pechera sin rajaduras.</li><li>Botas con la suela en buen estado, porque una suela lisa resbala.</li></ul>Si algo está dañado, <b>pide recambio antes de empezar</b>. No lo parches con cinta ni te pongas otro guante encima del roto."},{"s":"pe_epp_ok","t":"Bien puesto, o no sirve","x":"<ul><li>Todo el pelo dentro de la cofia.</li><li>La mascarilla cubre <b>nariz y boca</b>, nunca va en el cuello.</li><li>Guantes de tu talla: si sobran, se enganchan; si aprietan, se rompen.</li><li>Pechera amarrada y botas puestas.</li><li>Sin anillos, pulseras ni relojes: contaminan el producto y pueden engancharse en una máquina.</li></ul>Mal puesto es lo mismo que no tenerlo."},{"s":"epp_time","t":"Todo el tiempo que estés expuesto","x":"Un corte “rapidito” sin guantes basta para lesionarte. Ponte el EPP <b>antes</b> de entrar a la zona o empezar la tarea, y sácatelo solo al salir. En la sanitización, por ejemplo, las antiparras y los guantes largos se usan desde que preparas el químico hasta que terminas de enjuagar. El accidente no espera a que te pongas el EPP."},{"s":"epp_care","t":"Cuídalo","x":"<ul><li>Mantenlo limpio, seco y guardado en el lugar que indique la jefatura.</li><li>La mascarilla y los guantes desechables se cambian según se indique y <b>no se prestan</b>: son personales.</li><li>No le hagas cortes, perforaciones ni modificaciones: deja de proteger como fue diseñado.</li><li>No lo dejes sobre la máquina ni en el piso.</li></ul>Un EPP cuidado dura más y protege mejor."},{"s":"epp_self","t":"Autocuidado con el EPP","x":"La acción insegura típica es sacarse la mascarilla o los guantes “un ratito” por calor o incomodidad. Decide seguro: si te molesta, pide otra talla o modelo a tu jefatura, pero no trabajes sin él. Y si ves a un compañero sin su EPP, recuérdaselo con respeto. La incomodidad se arregla; una lesión, no."}],"quiz":[{"s":"pe_epp_give","v":[{"q":"¿Quién paga el EPP que necesitas para tu puesto?","o":["La empresa: se entrega sin costo para el trabajador","El trabajador, descontado en cuotas del sueldo","La ACHS, solo después de un accidente","Se divide el costo entre empresa y trabajador"],"w":"El DS 594 y la Ley 16.744 obligan a entregar el EPP gratis."},{"q":"Se te rompió la pechera por el uso normal. ¿Cómo es el recambio?","o":["Se pide a la jefatura y se entrega sin costo","Se descuenta de la liquidación de sueldo","Debo comprarla yo en el comercio","Solo se cambia una vez por temporada"],"w":"El recambio por desgaste o daño también es gratuito."},{"q":"La empresa puede descontar del sueldo el costo del EPP que entrega.","vf":false,"w":"Falso. El EPP es gratuito para el trabajador."}]},{"s":"pe_epp_mal","v":[{"q":"Una trabajadora entra a la línea con el pelo fuera de la cofia, la mascarilla en el cuello y sin guantes. ¿Qué está mal?","o":["Las tres cosas: pelo, mascarilla y guantes","Solo la falta de guantes","Solo la mascarilla; el pelo da lo mismo","Nada grave si su tarea es corta"],"w":"Todo el pelo en la cofia, mascarilla en nariz y boca, y guantes puestos."},{"q":"¿Cómo debe ir la mascarilla mientras trabajas en la línea?","o":["Cubriendo nariz y boca todo el tiempo","Cubriendo solo la boca para respirar mejor","En el cuello, y se sube si pasa la jefatura","Bajo la nariz cuando hace mucho calor"],"w":"Si no cubre nariz y boca, no protege ni a ti ni al producto."},{"q":"¿Cuál es la forma correcta de usar la cofia?","o":["Con todo el pelo dentro","Con el pelo dentro, pero el flequillo afuera","Sobre el pelo, aunque quede pelo suelto atrás","Solo cuando se manipula producto abierto"],"w":"Un pelo fuera de la cofia contamina el alimento y puede engancharse."}]},{"s":"pe_epp_todo","v":[{"q":"El EPP no elimina el peligro: solo reduce el daño si se usa bien.","vf":true,"w":"Verdadero. Por eso es la última barrera de la jerarquía de controles."},{"q":"¿Qué hace realmente el EPP?","o":["Reduce el daño, pero no elimina el peligro","Elimina el peligro de la tarea mientras se use","Reemplaza a los resguardos de la máquina","Permite trabajar con la máquina en marcha"],"w":"El peligro sigue ahí; el EPP es la última barrera."},{"q":"En la conservera, además de proteger tu salud, la cofia y la mascarilla protegen:","o":["La inocuidad de los alimentos","La máquina de posibles daños","La velocidad de la línea","El orden del puesto de trabajo"],"w":"Evitan que pelo o saliva lleguen al producto."}]},{"s":"epp_time","v":[{"q":"¿Cuándo debes usar tu EPP?","o":["Todo el tiempo que estés expuesto al riesgo","Solo cuando la jefatura está presente","Solo en tareas de más de 10 minutos","Solo al manipular producto abierto"],"w":"El EPP se usa durante toda la exposición."},{"q":"Vas a hacer un corte “rapidito” con cuchillo y no tienes los guantes a mano. ¿Qué haces?","o":["Busco mis guantes y recién ahí corto","Lo hago con cuidado, es solo un corte","Uso un paño en lugar del guante","Pido a un compañero que sostenga la fruta"],"w":"Un segundo sin guantes basta para un corte."},{"q":"¿En qué momento te pones el EPP?","o":["Antes de entrar a la zona o empezar la tarea","Apenas comienza a funcionar la línea","Cuando la tarea se vuelve peligrosa","Después del primer descanso del turno"],"w":"El EPP se pone antes de exponerse, no durante."}]},{"s":"pe_epp_area","v":[{"q":"En la conservera y el proceso, ¿qué EPP se usa?","o":["Cofia, mascarilla, pechera, guantes de nitrilo y botas blancas","Cofia, chaleco reflectante, guantes de cabritilla y zapatos","Mascarilla, ropa térmica, fonos y botas negras de seguridad","Gorro, antiparras, guantes para calor y zapatos de seguridad"],"w":"Ese es el EPP del área de conservera y proceso."},{"q":"Trabajas en los hornos del deshidratado de mosqueta moviendo carros calientes. ¿Qué guantes corresponden?","o":["Guantes de cabritilla","Guantes de nitrilo","Guantes multiflex","Guantes largos de aseo"],"w":"En hornos y carros se usan guantes de cabritilla; multiflex en selección y embandejado."},{"q":"Vas a sanitizar la línea con químicos. ¿Qué EPP de aseo corresponde?","o":["Guantes largos, antiparras y pechera","Guantes de nitrilo cortos y mascarilla","Ropa térmica y zapatos de seguridad","Guantes de cabritilla y cotona"],"w":"Los químicos pueden salpicar ojos y brazos: guantes largos, antiparras y pechera."}]},{"s":"pe_epp_revisa","v":[{"q":"Tu guante tiene un hoyo. ¿Qué haces?","o":["Pido recambio antes de seguir","Sigo con ese guante hasta el descanso","Lo parcho con cinta adhesiva","Me pongo otro guante encima del roto"],"w":"EPP dañado no protege: se pide recambio."},{"q":"¿Qué debes revisar en tu EPP antes de usarlo?","o":["Que no tenga hoyos, cortes ni rajaduras","Solo que esté limpio por fuera","Solo que sea del color que usa tu área","Que tenga tu nombre escrito con plumón"],"w":"Un EPP con daños deja pasar el peligro."},{"q":"Si las botas tienen la suela gastada pero no están rotas, igual protegen contra resbalones.","vf":false,"w":"Falso. Una suela lisa resbala en el piso mojado: se pide recambio."}]},{"s":"epp_self","v":[{"q":"Los guantes te quedan grandes. ¿Qué haces?","o":["Pido otra talla","Trabajo sin guantes","Les corto la punta de los dedos","Me pongo dos pares, uno sobre otro"],"w":"Se pide la talla correcta; no se trabaja sin EPP ni se modifica."},{"q":"Hace calor en la línea y un compañero se baja la mascarilla “un ratito”. ¿Qué es lo correcto?","o":["Mantenerla puesta y pedir otra si incomoda","Bajarla solo mientras nadie esté mirando","Bajarla si está lejos del producto expuesto","Sacarla cada media hora para descansar"],"w":"Sacarse el EPP por incomodidad es la acción insegura típica."},{"q":"Si el EPP te incomoda, lo correcto es pedir otra talla o modelo, no dejar de usarlo.","vf":true,"w":"Verdadero. La incomodidad se arregla; una lesión, no."}]},{"s":"epp_care","v":[{"q":"¿Cómo se cuida el EPP?","o":["Limpio, guardado en su lugar y sin modificaciones","Dejado sobre la máquina para tenerlo a mano","Con cortes para que sea más cómodo","Lavado solo al final de la temporada"],"w":"Un EPP limpio, guardado y sin cambios protege como fue diseñado."},{"q":"Un compañero olvidó su mascarilla y te pide la tuya de repuesto ya usada. ¿Qué haces?","o":["No la presto: que pida una nueva a la jefatura","Se la presto, si es un compañero de confianza","Se la paso después de sacudirla bien","Se la presto solo por un rato mientras consigue otra"],"w":"La mascarilla es personal y no se presta."},{"q":"¿Qué pasa si le haces cortes o modificaciones a tu EPP?","o":["Deja de proteger como fue diseñado","Protege igual, solo se ve peor","Solo pierde la garantía del fabricante","Protege mejor porque ajusta más"],"w":"Cualquier modificación cambia cómo protege."}]}]},{"id":"orden","sec":"todos","mins":5,"title":"Orden y aseo","thumb":"tidy","learn":[{"s":"orden_trip","t":"El desorden también accidenta","x":"Las caídas al mismo nivel están entre los accidentes más comunes. Casi siempre hay algo en el piso que no debería estar: <b>restos de proceso, latas, cables, una herramienta o agua fuera del lavado</b>. Un resbalón con una caja en las manos, cuando no ves el piso, puede terminar en un esguince, un golpe en la cabeza o un corte con el borde de una lata."},{"s":"orden_aisle","t":"Pasillos despejados","x":"Los pasillos deben permitir el paso seguro de personas y materiales, <b>libres de obstáculos</b> (DS 594, art. 8). Por ahí pasan personas, carros y la grúa horquilla. Nunca dejes pallets, bins ni carros “un rato” en el pasillo: obligas a otros a esquivar y a meterse en la ruta de la grúa. Respeta las líneas pintadas del piso."},{"s":"orden_stack","t":"Cajas y pallets bien apilados","x":"<ul><li>Sobre pallet en buen estado, en piso firme y nivelado.</li><li>Rumas <b>parejas y estables</b>, sin cajas salidas ni aplastadas.</li><li>Lo pesado abajo y a una <b>altura segura</b>, que no se incline.</li><li>Sin invadir el pasillo ni apoyar la ruma en la pared.</li><li>Nunca te subas a una ruma ni saques una caja de abajo: se desarma desde arriba.</li></ul>Si ves una ruma inclinada, aléjate y avisa."},{"s":"orden_exits","t":"Salidas, extintores y tableros libres","x":"Nunca dejes materiales delante de una <b>salida de emergencia, un extintor o un tablero eléctrico</b>, ni siquiera por unos minutos. En una emergencia cada segundo cuenta: nadie debería tener que mover pallets para escapar, apagar un amago o cortar la energía. Si encuentras uno tapado, despéjalo si puedes y avisa a tu jefatura.","k":"Nunca bloquees una salida, un extintor o un tablero eléctrico."},{"s":"orden_cables","t":"Cables en el piso","x":"Una extensión cruzando el pasillo es un tropiezo seguro, y el cable se daña con las ruedas de carros y transpaletas. Llévala <b>por el borde</b>, por arriba o protegida, nunca tapada con cartón. Al terminar, <b>enróllala y guárdala</b>. Si ves un cable pelado, sobre todo en zona húmeda, no lo toques ni lo muevas con el pie: avisa de inmediato."},{"s":"orden_scraps","t":"Restos de proceso","x":"La línea deja <b>cáscaras, hojas, mosqueta, jugo y latas</b> en el piso. Hacen resbalar y tapan las canaletas. Recógelos <b>durante el turno</b>, a medida que se generan, no solo al final, y bótalos en el contenedor. No los barras bajo la máquina. Deja las canaletas y rejillas despejadas para que el agua escurra y el piso no se inunde."},{"s":"orden_spill","t":"Derrames: avisa, señaliza y limpia","x":"Si cae agua, jugo, aceite o un químico al piso: <b>avisa, señaliza y limpia</b> de inmediato. Pon un cono o letrero para que nadie pase mientras limpias. Si es un químico, límpialo según su Hoja de Datos de Seguridad (HDS) y con el EPP que indica. No lo tapes con cartón ni lo dejes “para después”: el siguiente que pase puede resbalar."},{"s":"pe_espuma","t":"Limpieza segura","x":"La sanitización se hace con la <b>línea detenida y bloqueada</b>, nunca con la máquina en marcha, ni siquiera lento. Usa el EPP de aseo: guantes largos, antiparras y pechera. La manguera a presión <b>no se apunta a tableros eléctricos, motores ni personas</b>. Al terminar, recoge las mangueras y deja el piso seco y despejado.","k":"Sanitiza solo con la línea detenida y bloqueada."},{"s":"orden_5s","t":"Las 5S: cinco hábitos simples","x":"<ul><li><b>Separar:</b> saca del puesto lo que no sirve.</li><li><b>Ordenar:</b> un lugar para cada cosa y cada cosa en su lugar.</li><li><b>Limpiar:</b> al limpiar, revisa si algo está dañado.</li><li><b>Estandarizar:</b> marca lugares, rumas y pasillos.</li><li><b>Sostener:</b> hazlo todos los días, no solo cuando hay visita.</li></ul>Lo que sacas, lo devuelves: ordenar es parte del trabajo."},{"s":"orden_self","t":"Autocuidado: orden y aseo","x":"La mayoría de los accidentes se relacionan con una <b>acción insegura</b>. En orden y aseo, la típica es <b>“lo ordeno después”</b> o tomar un atajo: subirse a una ruma de pallets para alcanzar algo, o pasar por encima de un cable. Para lo alto se usa una escala. Decide seguro: ordena al momento y <b>avisa</b> condiciones inseguras, como un piso roto o una luz quemada."}],"quiz":[{"s":"orden_trip","v":[{"q":"¿Cuál es una causa frecuente de caídas al mismo nivel en la planta?","o":["Restos, latas o agua fuera del lavado en el piso","Usar botas blancas con suela antideslizante","Caminar por la ruta peatonal marcada en el piso","Trabajar con la línea detenida y bloqueada"],"w":"Lo que queda en el piso hace tropezar o resbalar."},{"q":"Llevas una caja y no ves el piso. ¿Qué riesgo aumenta si hay latas o cáscaras tiradas?","o":["Tropezar o resbalar y caer con la carga","Solo ensuciar las botas y la pechera","Que la caja pese más de lo normal","Ninguno, si caminas lento y con cuidado"],"w":"Sin ver el piso, cualquier resto puede provocar una caída con carga."},{"q":"En la mayoría de las caídas al mismo nivel hay algo en el piso que no debería estar.","vf":true,"w":"Verdadero. Por eso mantener el piso despejado previene caídas."}]},{"s":"orden_5s","v":[{"q":"En las 5S, ¿qué significa “Ordenar”?","o":["Un lugar para cada cosa y cada cosa en su lugar","Sacar del puesto lo que no sirve","Limpiar y revisar si algo está dañado","Hacerlo todos los días, no solo con visitas"],"w":"Ordenar es asignar un lugar a cada cosa y devolverla ahí."},{"q":"¿Qué S consiste en sacar del puesto lo que no sirve?","o":["Separar","Ordenar","Estandarizar","Sostener"],"w":"Separar es la primera S: fuera lo que no se usa."},{"q":"Mantener el orden todos los días, y no solo cuando hay una visita, corresponde a la S de:","o":["Sostener","Limpiar","Separar","Estandarizar"],"w":"Sostener es convertir el orden en hábito."}]},{"s":"orden_exitBad","v":[{"q":"Hay pallets y cajas delante de la salida, del extintor y del tablero eléctrico. ¿Qué se debe hacer?","o":["Despejarlos de inmediato y avisar a la jefatura","Dejarlos, porque en una emergencia se mueven","Dejar solo un pasillo angosto para pasar","Poner un letrero que indique dónde está la salida"],"w":"Salidas, extintores y tableros siempre despejados."},{"q":"¿Por qué no se deja material delante de un tablero eléctrico?","o":["Porque en una emergencia hay que cortar la energía","Porque el tablero se ensucia con el cartón","Porque así lo indica el letrero de peligro","Porque solo el eléctrico puede acercarse a él"],"w":"Un tablero tapado retrasa el corte de energía en una emergencia."},{"q":"Dejar pallets delante de una salida de emergencia está permitido si es por menos de una hora.","vf":false,"w":"Falso. Una emergencia puede ocurrir en cualquier minuto: la salida va siempre libre."}]},{"s":"orden_spill","v":[{"q":"Se derramó jugo en el piso de la línea. ¿Qué haces?","o":["Aviso, señalizo y limpio de inmediato","Lo limpio al final del turno con el aseo general","Le tiro un cartón encima para absorberlo","Sigo trabajando y aviso en el descanso"],"w":"Avisar, señalizar y limpiar evita que otro resbale."},{"q":"Se derramó un químico de limpieza. ¿Cómo se limpia?","o":["Según su HDS y con el EPP que indica","Con agua abundante y sin EPP","Con un trapo cualquiera, lo más rápido posible","Se deja que se evapore solo"],"w":"La HDS indica cómo limpiarlo y con qué protección."},{"q":"¿Cuál es el orden correcto ante un derrame en el pasillo?","o":["Avisar, señalizar y limpiar","Limpiar, secar y después avisar","Señalizar y dejarlo para el turno siguiente","Avisar y esperar a que limpie otro"],"w":"Se avisa y se señaliza primero para que nadie pase mientras se limpia."}]},{"s":"pe_espuma","v":[{"q":"¿Cómo se sanitiza una cinta transportadora?","o":["Con la línea detenida y bloqueada, y con el EPP de aseo","Con la cinta en marcha lenta, para que llegue a todo","Con la cinta detenida, sin bloquear, si es rápido","Solo con agua a presión, sin necesidad de EPP"],"w":"Con la máquina detenida y bloqueada nadie queda atrapado."},{"q":"Antes de comenzar la sanitización de la línea, ¿qué es lo primero?","o":["Detener y bloquear la línea","Aplicar la espuma de arriba hacia abajo","Mojar el piso para que no se pegue la suciedad","Ponerse solo los guantes"],"w":"Sin detener y bloquear, la máquina puede partir con tus manos dentro."},{"q":"¿Qué EPP se usa en la sanitización?","o":["Guantes largos, antiparras y pechera","Guantes de nitrilo cortos y mascarilla","Cofia y botas blancas solamente","Chaleco reflectante y zapatos"],"w":"Los químicos pueden salpicar ojos y brazos."}]},{"s":"pe_espuma","v":[{"q":"Durante el aseo se puede apuntar la manguera a presión a los tableros eléctricos si están cerrados.","vf":false,"w":"Falso. Nunca a tableros, motores ni personas, estén abiertos o cerrados."},{"q":"Durante el lavado con manguera a presión, ¿hacia dónde no debes apuntar?","o":["A tableros eléctricos, motores ni personas","Al piso y a las canaletas de desagüe","A las bandejas y rodillos de la cinta","A las paredes lavables de la sala"],"w":"El agua en equipos eléctricos puede causar descargas; a presión, lesiona a las personas."},{"q":"Al terminar la sanitización, ¿cómo debe quedar el área?","o":["Con el piso seco y las mangueras recogidas","Con el piso mojado para que se vea limpio","Con espuma para la próxima limpieza","Con las mangueras extendidas para el otro turno"],"w":"Piso mojado y mangueras en el suelo provocan caídas."}]},{"s":"orden_stack","v":[{"q":"¿Cómo debe quedar una ruma de cajas?","o":["Pareja, estable y fuera del pasillo","Lo más alta posible, para ahorrar espacio","Apoyada en la pared del pasillo para que no caiga","Con las cajas más pesadas arriba de la ruma"],"w":"Una ruma estable no se cae sobre nadie."},{"q":"Necesitas una caja que está en la base de una ruma. ¿Qué haces?","o":["Desarmo desde arriba o pido ayuda; nunca saco la de abajo","La saco tirando rápido para que no alcance a caer","Me subo a la ruma para sacar las de arriba","La saco de lado, sujetando la ruma con el hombro"],"w":"Sacar la caja de abajo desarma la ruma sobre ti."},{"q":"Una ruma debe armarse sobre un pallet en buen estado, en piso firme y nivelado.","vf":true,"w":"Verdadero. Una base dañada o desnivelada hace que la ruma se incline."}]},{"s":"orden_cables","v":[{"q":"Necesitas una extensión que cruza el pasillo. ¿Qué haces?","o":["La llevo por el borde y la guardo al terminar","La dejo cruzando el pasillo, porque todos la ven","La tapo con cartón para que no se note","La estiro bien tensa para que no haga bulto"],"w":"Un cable atravesado hace tropezar y se daña con las ruedas."},{"q":"Ves un cable pelado en el piso húmedo de la línea. ¿Qué haces?","o":["No lo toco y aviso de inmediato","Lo cubro con cinta aislante yo mismo","Lo corro con el pie hacia el borde","Lo desconecto tirando del cable"],"w":"Cable pelado y humedad: riesgo de descarga eléctrica."},{"q":"Terminaste de usar una extensión. ¿Qué corresponde?","o":["Enrollarla y guardarla","Dejarla conectada para el turno siguiente","Dejarla enrollada en el pasillo","Colgarla de la máquina"],"w":"Guardarla evita tropiezos y que se dañe."}]},{"s":"orden_scraps","v":[{"q":"¿Cuándo se sacan las cáscaras y restos del piso?","o":["Durante el turno, a medida que se generan","Solo al final del turno, en el aseo general","Una vez por semana, en la limpieza profunda","Solo cuando la jefatura lo pide"],"w":"Acumulados hacen resbalar y tapan las canaletas."},{"q":"¿Por qué hay que mantener despejadas las canaletas y rejillas?","o":["Para que el agua escurra y el piso no se inunde","Para que se vean limpias en una visita","Para que las máquinas funcionen más rápido","Porque así lo pide el personal de aseo"],"w":"Canaletas tapadas dejan agua en el piso: caídas."},{"q":"Barrer los restos bajo la máquina es una forma aceptable de mantener el orden.","vf":false,"w":"Falso. Los restos van al contenedor; bajo la máquina se acumulan y hacen resbalar."}]},{"s":"orden_self","v":[{"q":"Ves una luz quemada en el pasillo y un sector del piso roto. ¿Qué haces?","o":["Aviso a mi jefatura para que se repare","Nada, porque no afecta mi trabajo","Lo comento solo con mis compañeros","Lo aviso solo si alguien se cae"],"w":"Ver algo mal y no avisarlo también es una acción insegura."},{"q":"Un compañero se sube a una ruma de pallets para alcanzar algo arriba. ¿Qué le dices?","o":["Que se baje y use una escala o pida ayuda","Que suba rápido para no demorar","Que se afirme de la pared mientras sube","Que lo haga solo si la ruma parece firme"],"w":"Las rumas no son escaleras: pueden desarmarse."},{"q":"¿Cuál es la acción insegura típica en orden y aseo?","o":["Dejarlo para después: “lo ordeno al final”","Recoger los restos durante el turno","Guardar la herramienta donde corresponde","Avisar que el piso está dañado"],"w":"Lo que se deja para después queda como trampa para otro."}]}]},{"id":"cargas","sec":"todos","mins":5,"title":"Manejo manual de cargas","thumb":"cargas_tecnica","learn":[{"s":"cargas_intro","t":"¿Qué es el manejo manual de carga?","x":"Es cualquier tarea en que usas tu cuerpo para <b>levantar, bajar, empujar, arrastrar o trasladar</b> algo. En nuestras plantas: cajas de conservas, sacos, bins de mosqueta, bandejas y carros. La zona que más se lesiona es la <b>espalda baja (zona lumbar)</b>, y una lesión ahí puede acompañarte por años. También sufren hombros, rodillas y muñecas."},{"s":"cargas_limites","t":"Los límites de la ley","x":"Según la Ley 20.949 (Código del Trabajo):<ul><li><b>Hombres adultos:</b> máximo 25 kg (art. 211-H).</li><li><b>Mujeres y menores de 18 años:</b> máximo 20 kg (art. 211-J).</li><li><b>Trabajadoras embarazadas:</b> tienen prohibido cargar y descargar manualmente, sin importar el peso (art. 211-I).</li></ul>Que la ley permita 25 kg no significa que levantarlos mal sea seguro. Una faja no aumenta tu límite.","k":"Si la carga supera tu límite legal, usa ayuda mecánica: nunca la cargues solo."},{"s":"cargas_piensa","t":"Antes de levantar, piensa 5 segundos","x":"<ul><li>¿Cuánto pesa? Si no lo sabes, pruébalo moviéndolo un poco.</li><li>¿Tiene buen agarre o es largo e incómodo?</li><li>¿El camino está libre y el piso seco?</li><li>¿Dónde lo voy a dejar? ¿Hay espacio?</li></ul>Si algo no calza, pide ayuda o usa transpaleta o carro, y pide que sequen o despejen el camino antes de pasar."},{"s":"cargas_tecnica","t":"Levanta con las piernas, no con la espalda","x":"<ul><li>Pies separados, a los lados de la carga.</li><li>Flecta las rodillas y mantén la espalda recta.</li><li>Agarra firme con toda la mano y pega la carga al cuerpo.</li><li>Sube con la fuerza de las piernas, sin tirones.</li><li>Para dejarla, haz lo mismo al revés.</li></ul>Como en una grúa: mientras más lejos del cuerpo va la carga, más esfuerzo hace tu espalda.","k":"Levanta con las piernas, la espalda recta y la carga pegada al cuerpo."},{"s":"cargas_giro","t":"No gires la cintura","x":"Pasa mucho al dejar un saco en el pallet de al lado: se gira el tronco con los pies quietos. Torcer la cintura con peso es la receta para una lesión lumbar. <b>Gira moviendo los pies</b>, con la carga siempre frente a ti. Tampoco lances la carga ni la pases con los brazos estirados hacia el lado."},{"s":"cargas_ayuda","t":"Ayuda mecánica: tu mejor compañera","x":"Un saco de azúcar de 35 kg supera el límite legal. Para eso están la <b>transpaleta, el carro, el volteador de bins u otra ayuda mecánica</b>. Úsala también con pallets y cajas pesadas. Revísala antes de usarla: ruedas, freno y manilla. <b>Empujar es mejor que tirar</b>: ves el camino y usas el peso de tu cuerpo, sin caminar de espaldas."},{"s":"pe_bandeja_dos","t":"Bandejas y cargas incómodas: entre dos","x":"Una bandeja grande o un tambor no siempre pesa tanto, pero es incómodo y se balancea. Entre dos: <b>uno solo dirige</b> y avisa (“¡Arriba!”, “¡Vamos!”, “¡Abajo!”) y ambos levantan, caminan y bajan al mismo tiempo. Antes de partir, revisen que el camino esté libre y el piso seco. Si hablan los dos a la vez, nadie sabe cuándo levantar."},{"s":"cargas_zona","t":"Lo pesado, a la altura correcta","x":"La zona más segura para manipular es <b>entre las rodillas y los hombros</b>. Guarda lo más pesado en los niveles del medio del rack, y lo liviano arriba o abajo. Evita levantar sobre los hombros o desde el suelo con los brazos estirados. Para alcanzar algo alto usa una escala: <b>nunca te subas al rack</b>."},{"s":"cargas_auto","t":"Autocuidado: tú decides","x":"La mayoría de los accidentes se relacionan con una acción insegura. En cargas, la típica es <b>“es rápido, lo levanto solo”</b>: apurarse, doblar la espalda o cargar sobre el límite. La decisión segura: <b>pedir ayuda o usar la transpaleta</b>. Avisa las condiciones inseguras: transpaleta con una rueda trabada, piso irregular o pasillo bloqueado. Si sientes dolor, avisa a tu jefatura."}],"quiz":[{"s":"cargas_limites","v":[{"q":"Según la ley, ¿cuál es el peso máximo que un trabajador hombre adulto puede manipular manualmente?","o":["25 kg","20 kg","35 kg","50 kg"],"w":"Código del Trabajo, art. 211-H: 25 kg."},{"q":"Hay que mover a mano un saco de 30 kg. ¿Lo puede cargar solo un trabajador hombre adulto?","o":["No: supera los 25 kg, se usa ayuda mecánica","Sí, porque el límite es 50 kg","Sí, si lo levanta con buena técnica","Sí, si es solo un tramo corto"],"w":"El límite legal es 25 kg, con cualquier técnica o distancia."},{"q":"Si un trabajador hombre levanta con buena técnica, puede cargar más de 25 kg sin infringir la ley.","vf":false,"w":"Falso. El límite de 25 kg es fijo; la técnica no lo aumenta."}]},{"s":"cargas_limites","v":[{"q":"¿Cuál es el límite de carga manual para mujeres y menores de 18 años?","o":["20 kg","25 kg","15 kg","30 kg"],"w":"Art. 211-J del Código del Trabajo: 20 kg."},{"q":"Una temporera debe mover cajas de 22 kg. ¿Qué corresponde?","o":["Usar ayuda mecánica: supera su límite de 20 kg","Cargarlas, porque están bajo los 25 kg","Cargarlas, si se toma pausas entre una caja y otra","Cargarlas, si usa una faja lumbar ajustada"],"w":"Para mujeres el límite es 20 kg; la faja no lo aumenta."},{"q":"Un trabajador de 17 años, ¿cuánto puede cargar como máximo?","o":["20 kg","25 kg","Lo mismo que un adulto","No tiene límite si es fuerte"],"w":"Menores de 18 años: máximo 20 kg."}]},{"s":"cargas_q_emb","v":[{"q":"¿Qué dice la ley sobre la carga manual para una trabajadora embarazada?","o":["Tiene prohibido cargar y descargar manualmente","Puede cargar hasta 20 kg, como toda mujer","Puede cargar hasta 10 kg durante el embarazo","Puede cargar si usa una faja lumbar adecuada"],"w":"Art. 211-I: prohibición total, sin importar el peso."},{"q":"Una trabajadora embarazada debe mover cajas livianas de 8 kg. ¿Qué corresponde?","o":["No las carga: se le asigna otra tarea","Las carga, porque son livianas","Las carga, si las lleva de a una y despacio","Las carga solo durante la mañana, descansada"],"w":"La prohibición rige para cualquier peso."},{"q":"Las trabajadoras embarazadas tienen prohibido cargar y descargar manualmente, aunque la carga sea liviana.","vf":true,"w":"Verdadero. Así lo establece el art. 211-I del Código del Trabajo."}]},{"s":"cargas_malL","v":[{"q":"Un trabajador levanta una caja del pallet con las piernas estiradas y la espalda doblada. ¿Qué está haciendo mal?","o":["Usa la espalda: debe flectar rodillas y mantenerla recta","Nada, si la caja pesa menos de 25 kg","Solo le falta usar guantes de agarre","Debería levantarla más rápido para que dure menos"],"w":"Rodillas flectadas, espalda recta y la carga pegada al cuerpo."},{"q":"¿Cuál es la técnica correcta para levantar una caja del piso?","o":["Rodillas flectadas, espalda recta y carga pegada al cuerpo","Piernas rectas y espalda doblada para llegar más rápido","Brazos estirados para mantener la caja lejos","Espalda recta, pero con la caja lejos del cuerpo"],"w":"Las piernas hacen la fuerza y la espalda se mantiene recta."},{"q":"¿Por qué la carga debe ir pegada al cuerpo?","o":["Porque lejos del cuerpo, la espalda hace más esfuerzo","Para que no se vea la etiqueta de la caja","Porque así se camina más rápido con ella","Para que sea el pecho el que haga la fuerza"],"w":"Como en una grúa: la carga lejos multiplica el esfuerzo lumbar."}]},{"s":"cargas_giro","v":[{"q":"Si tengo que dejar la carga a mi lado, lo correcto es girar la cintura sin mover los pies.","vf":false,"w":"Falso. Se gira moviendo los pies; torcer la cintura con carga daña la espalda."},{"q":"Debes pasar un saco del carro al pallet que está a tu lado. ¿Cómo lo haces?","o":["Giro moviendo los pies, con la carga frente a mí","Giro la cintura con los pies quietos","Lanzo el saco al pallet para ahorrar esfuerzo","Lo paso estirando los brazos hacia el lado"],"w":"Primero los pies, después el cuerpo, con la carga al frente."},{"q":"¿Qué movimiento con carga es el más peligroso para la espalda baja?","o":["Torcer la cintura con los pies quietos","Caminar con la carga pegada al cuerpo","Flectar las rodillas al bajar","Girar moviendo los pies"],"w":"La torsión con peso es una causa típica de lesión lumbar."}]},{"s":"cargas_ayuda","v":[{"q":"Un saco de azúcar pesa 35 kg. ¿Qué haces?","o":["Uso transpaleta, carro u otra ayuda mecánica","Lo levanto rápido para que el esfuerzo dure poco","Lo arrastro por el piso con la espalda doblada","Lo cargo con buena técnica, solo un tramo corto"],"w":"Supera el límite de 25 kg: se usa ayuda mecánica."},{"q":"Hay que mover un carro o una transpaleta con carga. ¿Qué es mejor?","o":["Empujarlo: ves el camino y usas tu peso","Tirarlo caminando de espaldas para controlarlo","Tirarlo de lado para girar mejor en las curvas","Da lo mismo empujar o tirar si la carga es igual"],"w":"Empujar permite ver el camino y cuida la espalda."},{"q":"¿Qué ayudas mecánicas puedes usar para cargas pesadas en la planta?","o":["Transpaleta, carro o volteador de bins","Faja lumbar y guantes de agarre","Una escalera y una cuerda","Un pallet arrastrado a mano"],"w":"La ayuda mecánica reemplaza el esfuerzo del cuerpo; la faja no."}]},{"s":"pe_bandeja_dos","v":[{"q":"Para trasladar una bandeja grande entre dos, lo más importante es:","o":["Que uno dirija y ambos se muevan a la vez","Que cada uno camine a su propio ritmo","Que el más fuerte lleve casi todo el peso","Que los dos den las órdenes para coordinarse"],"w":"Una sola voz dirige; ambos levantan y bajan al mismo tiempo."},{"q":"Antes de levantar una bandeja entre dos, ¿qué revisan?","o":["Que el camino esté libre y el piso seco","Solo cuánto pesa la bandeja","Que ambos tengan exactamente la misma altura","Que la jefatura esté mirando"],"w":"Con una carga incómoda, un tropiezo hace caer a los dos."},{"q":"Al cargar entre dos, conviene que ambos den las órdenes para coordinarse mejor.","vf":false,"w":"Falso. Si hablan los dos, nadie sabe cuándo levantar: dirige uno solo."}]},{"s":"cargas_piensa","v":[{"q":"Antes de levantar una carga, ¿qué debes revisar?","o":["Peso, agarre, camino y dónde la dejarás","Solo el peso indicado en la etiqueta de la caja","Solo que el camino hasta el destino esté libre","Solo que tengas los guantes de trabajo puestos"],"w":"Pensar 5 segundos evita cargas muy pesadas, tropiezos y golpes."},{"q":"No sabes cuánto pesa una caja. ¿Qué haces antes de levantarla?","o":["La muevo un poco para probar su peso","La levanto de un tirón para ver","La levanto con una sola mano","La levanto rápido y, si pesa, la suelto"],"w":"Probar el peso evita un esfuerzo brusco que lesiona la espalda."},{"q":"El piso del camino está mojado y la caja es incómoda. ¿Qué haces?","o":["Pido ayuda o uso un carro, y que sequen","La llevo igual, caminando rápido para no caer","La llevo sobre el hombro para ver mejor el piso","La arrastro por el piso mojado para no cargarla"],"w":"Si algo no calza en la revisión, se busca ayuda antes de levantar."}]},{"s":"cargas_q_rack","v":[{"q":"¿Dónde conviene guardar lo más pesado en un rack?","o":["En los niveles del medio del rack","En el nivel más alto, para despejar abajo","En el suelo, al fondo del rack","Donde quede espacio libre en ese momento"],"w":"Entre rodillas y hombros se manipula con menos esfuerzo."},{"q":"¿Cuál es la zona más segura para manipular una carga?","o":["Entre las rodillas y los hombros","Sobre la cabeza","Bajo las rodillas","Al lado del cuerpo, con el brazo estirado"],"w":"Fuera de esa zona la espalda y los hombros trabajan forzados."},{"q":"Para alcanzar una caja en la parte alta del rack se usa una escala; nunca se trepa al rack.","vf":true,"w":"Verdadero. Trepar el rack puede provocar una caída o que el rack se vuelque."}]},{"s":"cargas_q_apuro","v":[{"q":"Vas atrasado y la caja es pesada. ¿Cuál es la decisión segura?","o":["Detenerme y pedir ayuda o usar ayuda mecánica","Levantarla solo de un tirón para ganar tiempo","Arrastrarla con la espalda doblada","Levantarla sin probar el peso"],"w":"Pedir ayuda toma segundos; una lesión lumbar, meses."},{"q":"¿Cuál es la acción insegura más típica al manipular cargas?","o":["Pensar “es rápido, lo levanto solo”","Usar la transpaleta","Pedir ayuda a un compañero","Revisar el camino antes de partir"],"w":"El apuro lleva a cargar mal o sobre el límite."},{"q":"La transpaleta tiene una rueda trabada. ¿Qué haces?","o":["No la uso y aviso a la jefatura","La uso haciendo más fuerza","Cargo a mano mientras tanto","La reparo yo con un martillo"],"w":"Un equipo dañado es una condición insegura: se reporta."}]}]},{"id":"accidente","sec":"todos","mins":5,"title":"Accidentes del trabajo: se pueden evitar","thumb":"pe_evitable","learn":[{"s":"pe_evitable","t":"Los accidentes se pueden evitar","x":"Un accidente no es mala suerte: casi siempre hay una causa que se pudo controlar. Un paso que se saltó, un EPP que no se usó, una máquina intervenida sin detenerla y bloquearla, o un equipo operado sin autorización. Si la causa se puede identificar, también se puede prevenir. Prevenir es parte del trabajo de todos, no solo de la jefatura."},{"s":"accidente_que","t":"¿Qué es un accidente del trabajo?","x":"Según la Ley 16.744 (art. 5), es toda lesión que sufres <b>a causa o con ocasión del trabajo</b> y que te produce incapacidad o la muerte. En la planta: un corte con cuchillo o lata, una quemadura con vapor, un resbalón en la línea, un lumbago al levantar. El seguro también cubre el accidente de trayecto y las enfermedades profesionales."},{"s":"auto_cadena","t":"¿Por qué ocurren?","x":"La mayoría empieza con una <b>acción insegura</b> (apurarse, no usar el EPP, meter la mano en una máquina en marcha), muchas veces sumada a una <b>condición insegura</b> (piso con restos, resguardo suelto). Es como una fila de fichas de dominó: si sacas una, el accidente no ocurre. Cada investigación busca esas fichas para corregirlas, no para buscar culpables."},{"s":"pe_autocuidado","t":"Cómo los evitamos","x":"<ul><li>Usa tu EPP todo el tiempo de exposición.</li><li>Sigue los procedimientos de trabajo.</li><li><b>Detén, bloquea y avisa</b> antes de limpiar o destrabar, aunque sea “un segundo”.</li><li>No operes equipos sin capacitación ni autorización.</li><li>Mantén el orden y el aseo.</li><li>Informa las condiciones inseguras.</li></ul>Cada tarea hecha segura es un accidente menos."},{"s":"accidente_casi","t":"Los casi accidentes también se avisan","x":"Un casi accidente es un hecho que pudo lesionar a alguien, pero esta vez no lo hizo: un pallet que cae cerca, un resbalón que no terminó en caída, la grúa horquilla que pasó rozando. <b>No pasó nada esta vez</b>, pero la causa sigue ahí. Avísalo a tu jefatura para que se corrija antes de que alguien se lesione."},{"s":"accidente_avisa","t":"Si a pesar de todo ocurre","x":"Avisa <b>de inmediato</b> a tu jefatura, aunque parezca leve: lo que no se avisa a tiempo después es difícil de acreditar. {EMP} hace la denuncia (DIAT) y te deriva a la ACHS; si la empresa no la hace, puedes hacerla tú o tu familia. En la ACHS di que fue un accidente del trabajo. La atención es <b>gratuita</b>. Si es grave, llama al <b>1404</b>.","k":"Aunque parezca leve, avisa de inmediato a tu jefatura."},{"s":"accidente_companero","t":"Si un compañero se accidenta","x":"Primero tu seguridad: no te expongas al mismo peligro y detén la máquina solo si es seguro. Si cayó de altura o recibió un golpe fuerte, <b>no lo muevas</b>: puede tener una lesión de columna. Llama al <b>1404 (ACHS)</b> o al 131 (SAMU) y avisa a la jefatura. No le des agua ni comida. Acompáñalo y háblale hasta que llegue la ayuda."},{"s":"ind_grave","t":"Accidente grave: paraliza, delimita y avisa","x":"Según la SUSESO, es grave, por ejemplo, el accidente con <b>caída de más de 1,8 m, amputación, atrapamiento, pérdida de conocimiento, o que requiera rescate o reanimación</b>. Además de pedir ayuda: <b>paraliza</b> la faena, <b>delimita</b> la zona sin mover nada que no sea necesario para el rescate, y <b>avisa</b> de inmediato a la jefatura. La empresa informa a la Inspección del Trabajo y a la SEREMI de Salud.","k":"Accidente grave: paraliza la faena, delimita la zona y avisa de inmediato."},{"s":"accidente_trayecto","t":"El trayecto también se cuida","x":"El accidente en el <b>trayecto directo</b>, de ida o regreso, entre tu casa y el trabajo está cubierto por la Ley 16.744. Si te desvías por motivos personales, por ejemplo a visitar a alguien, deja de ser trayecto directo. Si ocurre, atiéndete de inmediato, avisa a tu jefatura y reúne pruebas: constancia en Carabineros y datos de testigos. Camina atento, sin celular ni audífonos."},{"s":"pe_cinta_mal","t":"Autocuidado: el accidente empieza con una decisión","x":"La mayoría de los accidentes se relacionan con una <b>acción insegura</b>: apurarse, saltarse un paso, no usar el EPP, meter la mano en la cinta para “ganar tiempo” pensando que “es un segundo”. La decisión segura: <b>detener y bloquear, usar el EPP, pedir ayuda</b>. Y avisar las condiciones inseguras también es autocuidado. Ningún apuro vale una mano."}],"quiz":[{"s":"pe_evitable","v":[{"q":"¿Por qué decimos que los accidentes se pueden evitar?","o":["Porque casi siempre tienen una causa controlable","Porque con suerte no le ocurren a nadie","Porque el seguro laboral paga todos los gastos","Porque solo les ocurren a los trabajadores nuevos"],"w":"Si la causa se identifica, se puede prevenir."},{"q":"Un trabajador se corta al destrabar una cerradora sin detenerla. ¿Qué pudo evitarlo?","o":["Detener y bloquear la máquina antes de intervenir","Nada, porque fue simplemente mala suerte","Trabajar más rápido para terminar antes la tarea","Usar un guante más grueso y seguir igual"],"w":"La causa fue intervenir la máquina en marcha: eso se controla."},{"q":"La mayoría de los accidentes son mala suerte y no se pueden prevenir.","vf":false,"w":"Falso. Casi siempre hay una causa que se pudo controlar."}]},{"s":"pe_autocuidado","v":[{"q":"¿Cuál de estas acciones ayuda a evitar un accidente?","o":["Detener y bloquear la máquina antes de destrabar","Destrabar con la máquina en marcha lenta","Sacar el resguardo para ver mejor","Trabajar más rápido en temporada alta"],"w":"Detener y bloquear antes de intervenir evita atrapamientos."},{"q":"¿Cuál de estas acciones NO ayuda a evitar accidentes?","o":["Operar un equipo sin estar autorizado","Usar el EPP todo el tiempo de exposición","Mantener el orden y el aseo","Informar las condiciones inseguras"],"w":"Operar sin capacitación ni autorización es una acción insegura."},{"q":"Tienes que limpiar un rodillo de la cinta. ¿Cuál es la secuencia segura?","o":["Detener, bloquear y avisar que estoy limpiando","Avisar y limpiar con la cinta en marcha lenta","Detener sin bloquear, si es un segundo","Limpiar con un paño largo sin detenerla"],"w":"Detener, bloquear y avisar: nunca “es un segundo”."}]},{"s":"accidente_avisa","v":[{"q":"Te hiciste un corte pequeño con el borde de una lata. ¿Qué haces?","o":["Aviso a mi jefatura de inmediato","Me pongo una curita y sigo trabajando","Lo aviso solo si empeora","Lo aviso al terminar el turno"],"w":"Por pequeño que sea, se avisa de inmediato."},{"q":"¿Por qué hay que avisar de inmediato incluso una lesión leve?","o":["Para atenderse y que quede acreditado como accidente laboral","Para que la jefatura sepa quién se equivocó","Solo para las estadísticas de accidentes de la empresa","Porque si no se avisa, se pierde el sueldo del día"],"w":"Lo que no se avisa a tiempo después es difícil de acreditar."},{"q":"Te golpeaste la mano con un carro y te duele poco. ¿Cuándo lo avisas?","o":["De inmediato, aunque parezca leve","Al final del turno, si sigue doliendo","Al día siguiente, si se hincha","Solo si necesito licencia"],"w":"Una lesión que parece leve puede empeorar; el aviso es inmediato."}]},{"s":"accidente_ley","v":[{"q":"La atención médica por un accidente del trabajo en la ACHS es gratuita para el trabajador.","vf":true,"w":"Verdadero. La cubre el seguro de la Ley 16.744."},{"q":"¿Quién paga la atención de un accidente del trabajo?","o":["El seguro de la Ley 16.744, sin costo para ti","El trabajador, con su Fonasa o su isapre","La empresa y el trabajador, en partes iguales","El trabajador, y después la empresa le reembolsa"],"w":"La atención por el seguro laboral es gratuita."},{"q":"¿Qué cubre el seguro de la Ley 16.744?","o":["Accidentes del trabajo, de trayecto y enfermedades laborales","Solo los accidentes ocurridos dentro de la planta","Solo las enfermedades profesionales diagnosticadas","Cualquier accidente, incluso durante las vacaciones"],"w":"Cubre trabajo, trayecto directo y enfermedades profesionales."}]},{"s":"accidente_trayecto","v":[{"q":"Un accidente de trayecto es el que ocurre:","o":["En el trayecto directo entre la casa y el trabajo","En cualquier viaje que hagas en tu día libre","Solo dentro de los patios y portería de la planta","En cualquier parada que hagas camino a la casa"],"w":"Así lo define la Ley 16.744, art. 5."},{"q":"Al salir del turno vas a la casa de un amigo y luego te accidentas camino a tu casa. ¿Es accidente de trayecto?","o":["No, porque se interrumpió el trayecto directo","Sí, todo lo que pasa después del turno lo es","Sí, si ocurre antes de medianoche","Sí, si avisas al día siguiente"],"w":"El desvío por motivos personales rompe el trayecto directo."},{"q":"Tuviste un accidente de trayecto. ¿Qué te ayuda a acreditarlo?","o":["Constancia en Carabineros, testigos y atención inmediata","Una foto del lugar tomada varios días después","Solo tu relato a la jefatura al día siguiente","Un certificado de tu médico particular"],"w":"Las pruebas inmediatas permiten acreditar el trayecto."}]},{"s":"accidente_companero","v":[{"q":"Un compañero cayó desde la plataforma de un camión y se queja de la espalda. ¿Qué haces?","o":["No lo muevo, llamo al 1404 de la ACHS y aviso","Lo levanto con cuidado y lo llevo en auto","Le pido que se pare para ver si puede caminar","Lo siento apoyado en la rueda mientras espero"],"w":"Podría tener una lesión de columna: no se mueve y se pide ayuda."},{"q":"¿Por qué no se debe mover a alguien que cayó o recibió un golpe fuerte?","o":["Porque puede tener una lesión de columna","Porque hay que esperar a la jefatura","Porque moverlo anula el seguro","Porque primero hay que sacar fotos"],"w":"Moverlo puede agravar una lesión de columna."},{"q":"Antes de ayudar a un compañero accidentado, ¿qué es lo primero?","o":["Asegurarme de no exponerme al mismo peligro","Moverlo de inmediato a un lugar cómodo","Darle agua para que se calme","Buscar al supervisor antes de acercarme"],"w":"Si te expones, puede haber dos lesionados en vez de uno."}]},{"s":"accidente_ocultar","v":[{"q":"Un trabajador se corta y dice “no es nada, no aviso”. ¿Qué consecuencia puede tener?","o":["Le costará acreditar que fue un accidente del trabajo","Ninguna, porque la herida es pequeña","Que le descuenten el día por no haber trabajado","Que lo cambien de puesto como sanción"],"w":"Sin aviso inmediato, cuesta acreditar el accidente y recibir la cobertura."},{"q":"¿Qué debe hacer un trabajador después de lesionarse en la línea?","o":["Avisar de inmediato a su jefatura para atenderse","Curarse solo y seguir para no atrasar la línea","Avisar solo si tiene que faltar al trabajo","Ir a su consultorio sin avisar a la empresa"],"w":"El aviso inmediato permite la atención en la ACHS y la denuncia."},{"q":"Si la empresa no hace la denuncia del accidente (DIAT), el propio trabajador o su familia pueden hacerla.","vf":true,"w":"Verdadero. La denuncia no depende solo de la empresa."}]},{"s":"accidente_casi","v":[{"q":"Un pallet cayó cerca de mí pero no me golpeó: como no pasó nada, no es necesario avisarlo.","vf":false,"w":"Falso. Los casi accidentes muestran una causa que hay que corregir."},{"q":"¿Qué es un casi accidente?","o":["Un hecho que pudo lesionar, pero esta vez no lo hizo","Un accidente con una lesión leve, sin licencia","Un accidente ocurrido fuera del horario del turno","Una condición insegura que nadie vio a tiempo"],"w":"No hubo lesión, pero la causa sigue presente."},{"q":"La grúa horquilla pasó rozándote en el pasillo. ¿Qué haces?","o":["Lo aviso a la jefatura para que se corrija","No digo nada, porque no me pasó nada","Se lo comento solo al operador de la grúa","Lo aviso solo si vuelve a pasar otra vez"],"w":"Cada casi accidente muestra dónde prevenir."}]},{"s":"accidente_auto","v":[{"q":"La mayoría de los accidentes se relacionan con:","o":["Acciones inseguras, como apurarse","La mala suerte de estar en el lugar equivocado","El clima de la temporada","Fallas de las máquinas imposibles de prever"],"w":"Por eso cuidarnos depende en gran parte de nuestras decisiones."},{"q":"Una lata se traba en la cinta. ¿Cuál es la decisión segura?","o":["Detener y bloquear antes de sacarla","Sacarla rápido con la cinta en marcha","Golpear la cinta para que avance","Sacarla con un cuchillo sin detener"],"w":"Detener y bloquear es la decisión que corta la cadena."},{"q":"“Es un segundo, no vale la pena detener la máquina.” Esta frase es:","o":["Una acción insegura que puede costar una mano","Una forma eficiente de trabajar en temporada","Aceptable si se usan guantes de nitrilo","Correcta si la máquina va a baja velocidad"],"w":"Un segundo basta para un atrapamiento."}]},{"s":"ind_grave","v":[{"q":"Un compañero queda atrapado en una máquina. Además de pedir ayuda, ¿qué corresponde?","o":["Paralizar, delimitar la zona y avisar de inmediato","Limpiar el área para seguir trabajando pronto","Desarmar la máquina para revisar qué falló","Esperar al final del turno para informar"],"w":"Ante un accidente grave: paralizar, delimitar y avisar."},{"q":"¿Cuál de estos es un accidente grave según la SUSESO?","o":["Una caída desde más de 1,8 m de altura","Un corte superficial en un dedo","Un golpe leve en la rodilla","Una picadura de insecto en el patio"],"w":"Caída de más de 1,8 m, amputación, atrapamiento, pérdida de conocimiento o rescate son graves."},{"q":"Después de un accidente grave, se puede seguir trabajando en el lugar apenas el lesionado fue trasladado.","vf":false,"w":"Falso. La faena queda paralizada y la zona delimitada hasta que se autorice."}]}]},{"id":"incendios","sec":"todos","mins":5,"title":"Prevención de incendios y uso del extintor","thumb":"incendios_ext","learn":[{"s":"incendios_tri","t":"El triángulo del fuego","x":"El fuego necesita tres cosas a la vez: <b>combustible</b> (lo que arde), <b>oxígeno</b> (el aire) y <b>calor</b> (una chispa, una llama, un cable recalentado). <b>Si quitas una, no hay fuego.</b> Prevenir es mantenerlas separadas. Para apagar se quita una: tapar el fuego le quita el oxígeno, y el extintor quita calor u oxígeno."},{"s":"pe_combustibles","t":"En la planta también hay combustible","x":"<ul><li><b>Cartón, etiquetas y pallets</b> de madera en bodega: arden rápido.</li><li><b>Gas, petróleo o combustible</b> de la caldera, los hornos y la grúa.</li><li><b>Aceites</b> de mantención y solventes.</li><li><b>Tableros eléctricos</b> con humedad o sobrecarga.</li></ul>En un incendio, el <b>humo</b> es lo que más daña a las personas: quita la visibilidad y se respira en segundos."},{"s":"pe_horno","t":"Hornos y caldera: calor todo el día","x":"Los hornos de secado y la caldera trabajan con <b>llama o calor</b> muchas horas. Alrededor no se acumula cartón, pallets ni basura, y los filtros y ductos se limpian según el programa. Si sientes <b>olor a gas o a quemado</b>, avisa de inmediato a la jefatura y no enciendas ni apagues interruptores, porque pueden generar una chispa."},{"s":"incendios_chispas","t":"Chispas del esmeril","x":"Las chispas del esmeril o la soldadura saltan varios metros y pueden quedar encendidas en el cartón o los pallets sin que se vea.<ul><li><b>Antes:</b> retira el material combustible o protégelo.</li><li><b>Durante:</b> dirige las chispas lejos de cartón, pallets y combustibles.</li><li><b>Al terminar:</b> revisa que no quede nada humeando.</li></ul>Mojar el piso no reemplaza retirar el combustible."},{"s":"incendios_enchufe","t":"Enchufes y cigarros","x":"<ul><li><b>No sobrecargues enchufes</b> ni conectes zapatillas o alargadores en cadena.</li><li>Si un enchufe o cable está <b>caliente, derretido, pelado o huele a quemado</b>, desconéctalo si es seguro, no lo uses y avisa.</li><li>Nunca lo enfríes con agua ni lo tapes con cinta.</li><li><b>No fumes</b> dentro de la planta ni cerca de combustibles: solo donde la empresa lo autorice.</li></ul>"},{"s":"incendios_clases","t":"Clases de fuego","x":"<ul><li><b>A:</b> sólidos (madera, cartón, papel).</li><li><b>B:</b> líquidos inflamables (combustibles, aceites de mantención, solventes).</li><li><b>C:</b> equipos eléctricos energizados.</li><li><b>D:</b> metales combustibles.</li><li><b>K:</b> aceites de cocina.</li></ul>Cada extintor indica en su etiqueta para qué clases sirve. <b>Nunca uses agua sobre un fuego eléctrico</b>: conduce la electricidad."},{"s":"incendios_acceso","t":"Extintores libres y a la vista","x":"La empresa debe tener extintores del tipo adecuado, en lugares de fácil acceso, señalizados y libres de obstáculos (DS 594). Tu parte:<ul><li>Nunca dejes pallets ni cajas delante.</li><li>Conoce dónde está el más cercano a tu puesto.</li><li>Avisa si falta, si la aguja del manómetro no está en verde o si tiene el sello roto.</li></ul>Un extintor tapado o descargado no sirve en una emergencia."},{"s":"incendios_ext","t":"Cómo usar el extintor","x":"Solo frente a un <b>amago</b> (fuego pequeño que recién empieza) y si sabes usarlo. Primero <b>da la alarma a viva voz</b>.<ul><li><b>1. Seguro:</b> sácalo; sin eso, la manilla no funciona.</li><li><b>2. Apunta</b> a la <b>base</b> del fuego, no a las llamas.</li><li><b>3. Aprieta</b> la manilla.</li><li><b>4. Barre</b> de lado a lado.</li></ul>","k":"Saca el seguro, apunta a la base, aprieta y barre."},{"s":"incendios_retirada","t":"Distancia y retirada","x":"<ul><li><b>Mantén distancia</b>: acércate solo lo necesario.</li><li>Ten siempre la <b>salida a tu espalda</b>.</li><li><b>Nunca le des la espalda al fuego</b>, ni siquiera cuando parece apagado: retrocede mirándolo, porque puede reavivarse.</li><li>Un extintor portátil se descarga en pocos segundos. <b>Si no se apaga, evacúa</b> y llama a Bomberos, 132.</li></ul>","k":"Si el fuego no se apaga en segundos, evacúa y llama al 132."},{"s":"incendios_self","t":"Autocuidado: incendios","x":"La mayoría de los accidentes se relacionan con una <b>acción insegura</b>. Aquí las típicas son <b>esmerilar junto al cartón</b>, sobrecargar un enchufe o querer apagar solo un fuego que ya creció. Decide seguro: <b>da la alarma primero</b>, no te arriesgues por salvar producto o equipos, y avisa condiciones inseguras, como un extintor tapado o un cable pelado."}],"quiz":[{"s":"incendios_tri","v":[{"q":"¿Qué tres cosas necesita el fuego?","o":["Combustible, oxígeno y calor","Combustible, humo y calor","Oxígeno, agua y una chispa","Calor, humo y electricidad"],"w":"Es el triángulo del fuego: si quitas una, el fuego se apaga."},{"q":"Al cubrir un fuego pequeño con una tapa, ¿qué elemento del triángulo le quitas?","o":["El oxígeno","El combustible","El calor","El humo"],"w":"Tapar el fuego impide que le llegue aire."},{"q":"Si se quita uno de los tres elementos del triángulo del fuego, el fuego se apaga.","vf":true,"w":"Verdadero. El fuego necesita los tres a la vez."}]},{"s":"pe_combustibles","v":[{"q":"El cartón y los pallets de madera de la bodega no se queman fácil.","vf":false,"w":"Falso. Son combustibles sólidos de clase A y arden rápido."},{"q":"En un incendio, ¿qué es lo que más daña a las personas?","o":["El humo, que se respira en segundos","El calor que acumulan las paredes","El ruido de la alarma de evacuación","El agua que usa Bomberos para apagar"],"w":"El humo intoxica y desorienta antes que las llamas alcancen a alguien."},{"q":"¿Cuál de estos materiales de la planta es combustible?","o":["Cartón, etiquetas y pallets de madera","Latas de conserva vacías y apiladas","Mesones de acero inoxidable de la línea","El agua de lavado de las canaletas"],"w":"Cartón y madera son combustibles clase A."}]},{"s":"incendios_extMal","v":[{"q":"Un trabajador apunta el extintor a las llamas, por encima del fuego. ¿Qué está haciendo mal?","o":["Debe apuntar a la base del fuego","Debe apuntar más alto, hacia el humo","Debe acercarse más, casi encima del fuego","Nada, mientras salga el agente extintor"],"w":"Se apunta a la base, donde está el combustible, no a las llamas."},{"q":"¿Hacia dónde se dirige la descarga del extintor?","o":["A la base del fuego","A la punta de las llamas","Al humo","Al centro de las llamas"],"w":"En la base está lo que arde."},{"q":"Para apagar un amago, el chorro del extintor se dirige a la parte alta de las llamas.","vf":false,"w":"Falso. Se dirige a la base del fuego y se barre de lado a lado."}]},{"s":"incendios_ext","v":[{"q":"¿Cuál es el orden correcto para usar el extintor?","o":["Sacar el seguro, apuntar a la base, apretar y barrer","Apretar, apuntar a las llamas y sacar el seguro","Apuntar a la base, apretar, sacar el seguro y barrer","Sacar el seguro, apretar, apuntar al humo y esperar"],"w":"Seguro, apuntar a la base, apretar y barrer."},{"q":"Tomas el extintor, aprietas la manilla y no sale nada. ¿Qué te faltó?","o":["Sacar el seguro","Agitarlo boca abajo","Apuntar a la base","Esperar a que tome presión"],"w":"Con el seguro puesto, la manilla no funciona."},{"q":"Antes de usar el extintor en un amago, ¿qué es lo primero?","o":["Dar la alarma a viva voz","Acercarme lo más posible al fuego","Abrir las puertas para que salga el humo","Buscar un balde de agua de apoyo"],"w":"Primero se avisa: si el fuego crece, todos deben saberlo."}]},{"s":"incendios_retirada","v":[{"q":"Intentaste apagar un amago y no se apaga en segundos. ¿Qué haces?","o":["Me retiro sin darle la espalda, evacúo y aviso","Sigo hasta vaciar completamente el extintor","Busco un segundo extintor y vuelvo a intentarlo","Le tiro agua para ayudar al extintor"],"w":"Si no se apaga en segundos, se evacúa. Tu vida vale más que la planta."},{"q":"Al combatir un amago, ¿dónde debe quedar la salida?","o":["A tu espalda","Al otro lado del fuego","A tu costado, cerca del fuego","Da lo mismo si el fuego es chico"],"w":"Con la salida a tu espalda, siempre puedes retirarte."},{"q":"Una vez apagado el fuego, puedes darle la espalda y retirarte, porque ya no hay riesgo.","vf":false,"w":"Falso. Puede reavivarse: se retrocede mirándolo."}]},{"s":"incendios_clases","v":[{"q":"Un fuego en un tablero eléctrico energizado es de clase:","o":["C","A","B","D"],"w":"Clase C: equipos eléctricos energizados."},{"q":"Se inflama el aceite de mantención de una máquina. ¿Qué clase de fuego es?","o":["B","A","C","K"],"w":"Los aceites de mantención son líquidos inflamables, clase B. La K es para aceites de cocina."},{"q":"Hay fuego en un tablero eléctrico. ¿Qué no debes hacer?","o":["Lanzarle agua","Dar la alarma de inmediato","Usar un extintor apto para clase C","Evacuar si no se apaga en segundos"],"w":"El agua conduce la electricidad y puede electrocutarte."}]},{"s":"incendios_chispas","v":[{"q":"Vas a esmerilar cerca de cartón y pallets. ¿Qué haces antes?","o":["Retiro el combustible y dirijo las chispas lejos","Esmerilo rápido para que salten menos chispas","Mojo bien el piso alrededor y comienzo","Pido a un compañero que mire y comienzo"],"w":"Una chispa puede quedar encendida en el cartón o la madera."},{"q":"Terminaste de esmerilar cerca de la bodega. ¿Qué debes hacer?","o":["Revisar que no quede nada humeando","Guardar el esmeril y retirarme","Barrer las chispas hacia un rincón","Nada, las chispas se apagan solas"],"w":"Una brasa escondida puede iniciar un incendio después."},{"q":"Las chispas del esmeril pueden saltar varios metros y quedar encendidas en el cartón sin que se vea.","vf":true,"w":"Verdadero. Por eso se retira el combustible y se revisa al terminar."}]},{"s":"incendios_viruta","v":[{"q":"¿Qué no debe acumularse alrededor de los hornos de secado y la caldera?","o":["Cartón, pallets y basura","Herramientas guardadas en su panel","Señalización de seguridad","Extintores señalizados"],"w":"El calor constante puede encender el material combustible."},{"q":"Sientes olor a gas cerca de los hornos. ¿Qué haces?","o":["Aviso sin encender ni apagar interruptores","Busco la fuga abriendo los paneles del horno","Sigo trabajando, es normal por el calor","Enciendo la luz para ver de dónde viene"],"w":"Un interruptor puede generar la chispa que enciende el gas."},{"q":"¿Por qué no se dejan pallets ni cartón junto al horno?","o":["Porque el calor puede encenderlos","Porque estorban la vista del operador","Porque se humedecen con el vapor","Porque se ensucian con el polvo"],"w":"Calor más combustible: falta solo el oxígeno, que siempre está."}]},{"s":"incendios_acceso","v":[{"q":"Hay pallets delante del extintor. ¿Qué haces?","o":["Los saco o aviso para que quede despejado","Nada, en una emergencia los muevo","Pongo un letrero encima de los pallets","Muevo el extintor detrás de los pallets"],"w":"Los extintores deben estar accesibles y libres de obstáculos."},{"q":"Al mirar el extintor de tu sector, ¿qué debes avisar?","o":["Que la aguja no está en verde o el sello está roto","Que la etiqueta está algo descolorida por el sol","Que está colgado a la vista de todos","Que está demasiado cerca de una salida"],"w":"Aguja fuera del verde o sello roto: puede estar descargado."},{"q":"El extintor debe estar señalizado, a la vista y libre de obstáculos.","vf":true,"w":"Verdadero. Así lo exige el DS 594."}]},{"s":"incendios_enchufe","v":[{"q":"¿Cuál es una práctica segura con los enchufes?","o":["No sobrecargarlos ni conectar zapatillas en cadena","Conectar varias zapatillas para tener más enchufes","Tapar con cinta un enchufe que está caliente","Usar alargadores en cadena solo en temporada"],"w":"La sobrecarga recalienta los cables y puede iniciar un incendio."},{"q":"Notas que un enchufe está caliente y huele a quemado. ¿Qué haces?","o":["Lo desconecto si es seguro, no lo uso y aviso","Lo sigo usando hasta terminar el turno","Lo mojo un poco para enfriarlo","Conecto el equipo en otro alargador del mismo enchufe"],"w":"Un enchufe caliente es una señal de falla: se deja de usar y se avisa."},{"q":"¿Dónde se puede fumar en la planta?","o":["Solo donde la empresa lo autorice","En la bodega, si no hay cartón cerca","En la sala de caldera, porque ya hay calor","En cualquier lugar abierto del patio"],"w":"Un cigarro es una fuente de calor: solo en el lugar autorizado."}]}]},{"id":"emergencias","sec":"todos","title":"Emergencias, sismos y evacuación","thumb":"quake","learn":[{"s":"emergencias_tipos","t":"¿Qué emergencias pueden ocurrir?","x":"<ul><li><b>Incendio.</b></li><li><b>Sismo.</b></li><li><b>Fuga de vapor, gas o amoníaco.</b></li><li><b>Corte de luz</b> con máquinas funcionando.</li><li><b>Derrame</b> de un químico.</li><li><b>Persona lesionada</b> o atrapada en una cámara de frío.</li></ul>Pensar antes qué harías en cada caso te ahorra segundos valiosos. Pregunta a tu jefatura cómo actuar en tu sector."},{"s":"emergencias_plan","t":"El plan de emergencia","x":"{EMP} debe tener un <b>plan de emergencia</b>. Tú debes conocer:<ul><li>Cómo se da la alarma.</li><li>Las <b>vías de evacuación</b> desde tu puesto, y una alternativa.</li><li>La <b>zona de seguridad</b> de tu planta: pregunta a tu jefatura cuál es.</li><li>Dónde están los extintores.</li><li>Quiénes son los encargados de emergencia de tu sector.</li></ul>Conócelo antes de necesitarlo."},{"s":"emergencias_sismo","t":"Durante un sismo","x":"SENAPRED recomienda: <b>“Agáchate, cúbrete y afírmate”</b>. Aléjate de racks, rumas de cajas y ventanas. No corras mientras se mueve el piso. Si estás en una máquina, <b>detenla</b>. Si operas la grúa horquilla: <b>detente, baja la carga al piso y frena</b>. Evacúa cuando termine el movimiento o te lo indiquen.","k":"Agáchate, cúbrete y afírmate; evacúa cuando termine el movimiento."},{"s":"emergencias_incendio","t":"Incendio","x":"<ul><li>Da la alarma de inmediato.</li><li>Solo si es un <b>amago</b> y sabes usarlo, usa el extintor con la <b>salida a tu espalda</b>.</li><li>Si el fuego crece o no se apaga en segundos, <b>evacúa</b> y llama a Bomberos, 132.</li><li>Con humo, <b>avanza agachado</b>, cerca del piso, donde el aire es más limpio.</li><li>Cierra las puertas al salir, sin llave.</li></ul>"},{"s":"emergencias_luz","t":"Corte de luz","x":"Quédate quieto hasta que veas bien. <b>No metas las manos</b>: las partes en movimiento siguen girando unos segundos y la energía puede volver en cualquier momento. Apaga tu máquina para que no parta sola cuando vuelva la energía. Camina despacio, sin correr a oscuras, y espera las instrucciones de tu jefatura."},{"s":"emergencias_fuga","t":"Fuga o derrame","x":"Aléjate y aleja a los demás. <b>Avisa</b> a tu jefatura. No toques el producto sin el EPP que indica la HDS. Si huele a gas, por ejemplo del cilindro de una grúa, o a amoníaco, <b>no hagas chispas</b>: no enciendas ni apagues interruptores ni uses equipos eléctricos, y evacúa. Ante una fuga de vapor, no intentes cerrar válvulas si no estás autorizado."},{"s":"pe_numeros","t":"Cómo pedir ayuda","x":"<b>Apréndelos de memoria:</b><ul><li><b>1404 · ACHS</b> (accidente del trabajo)</li><li><b>131 · SAMU</b> (ambulancia)</li><li><b>132 · Bomberos</b></li><li><b>133 · Carabineros</b></li><li><b>134 · PDI</b></li></ul>Da la <b>dirección exacta</b> de la planta, di qué pasó y cuántos lesionados hay. No cortes hasta que la operadora te lo indique. Avisa también a tu jefatura."},{"s":"emergencias_evac","t":"Evacuación","x":"Cuando se indique, sal por la <b>vía de evacuación</b>: camina rápido, <b>sin correr</b>, por la derecha y sin empujar. <b>No uses el celular para grabar</b>, no vuelvas por tus cosas y ayuda a visitas, temporeros nuevos o a quien lo necesite. Si hay humo, avanza agachado. Sigue las indicaciones de los encargados de emergencia."},{"s":"emergencias_conteo","t":"En la zona de seguridad","x":"Ve a la zona de seguridad y quédate ahí. Se <b>cuenta a las personas</b>: avisa si falta alguien o si viste a alguien herido o atrapado. <b>No vuelvas a entrar</b> hasta que se autorice, ni por tus cosas ni a buscar a alguien: si falta una persona, avisa a la jefatura y a Bomberos, que entran con el equipo adecuado.","k":"Nunca vuelvas a entrar hasta que se autorice."},{"s":"emergencias_auto","t":"Autocuidado en emergencias","x":"Las acciones inseguras típicas: <b>tapar salidas o extintores</b> con pallets, volver por la mochila, grabar con el celular, correr durante el sismo. La decisión segura: mantener las salidas despejadas, conocer tu zona de seguridad y seguir el plan. <b>Avisa</b> si ves una salida bloqueada, una luz de emergencia que no funciona o un extintor sin carga."}],"quiz":[{"s":"emergencias_sismo","v":[{"q":"Durante un sismo, SENAPRED recomienda:","o":["Agáchate, cúbrete y afírmate","Corre de inmediato hacia la salida","Ponte junto a un rack para afirmarte","Quédate de pie junto a una ventana"],"w":"Protege tu cabeza y aléjate de lo que puede caer."},{"q":"Estás en la bodega cuando empieza un sismo fuerte. ¿Qué haces?","o":["Me alejo de racks, me agacho, me cubro y me afirmo","Corro hacia la salida mientras se mueve el piso","Sujeto las rumas con las manos para que no caigan","Me quedo pegado al rack para afirmarme mejor"],"w":"Racks y rumas pueden caer: aléjate y protégete."},{"q":"Estás en una máquina de la línea cuando empieza un sismo. ¿Qué haces primero?","o":["La detengo y me protejo","Sigo para no perder producción","Corro a la salida sin detenerla","Me agacho junto a la cinta en marcha"],"w":"Una máquina en marcha durante el sismo agrega un peligro."}]},{"s":"emergencias_sismo","v":[{"q":"Durante el movimiento de un sismo, lo correcto es correr hacia la salida.","vf":false,"w":"Falso. Correr mientras se mueve el piso provoca caídas y golpes."},{"q":"¿Cuándo se evacúa en un sismo?","o":["Cuando termina el movimiento o lo indican","Apenas empieza a moverse el piso","Solo si se corta la luz durante el sismo","Solo si se cae algo cerca de tu puesto"],"w":"Se evacúa con el piso quieto o cuando lo indica el encargado."},{"q":"¿De qué te debes alejar durante un sismo?","o":["De racks, rumas de cajas y ventanas","De las paredes interiores de la sala","De tus compañeros de línea","De la zona de seguridad marcada"],"w":"Son los elementos que pueden caer o quebrarse."}]},{"s":"emergencias_grua","v":[{"q":"Si operas la grúa horquilla durante un sismo, debes:","o":["Detenerte, bajar la carga al piso y frenar","Levantar la carga para protegerla del golpe","Acelerar para salir de la bodega cuanto antes","Bajarte de inmediato y correr a la salida"],"w":"Una carga en altura puede caer sobre alguien."},{"q":"¿Por qué el operador de grúa debe bajar la carga al piso durante un sismo?","o":["Porque una carga en altura puede caer","Para que no se dañe el producto del pallet","Para ahorrar batería o combustible de la grúa","Porque así la grúa avanza más rápido a la salida"],"w":"Con la carga abajo, la grúa queda más estable."},{"q":"Durante un sismo, el operador de grúa horquilla debe detenerse, bajar la carga al piso y frenar.","vf":true,"w":"Verdadero. Así evita que la carga caiga o que la grúa se vuelque."}]},{"s":"emergencias_llamar","v":[{"q":"¿Cuál es el número de Bomberos?","o":["132","131","133","134"],"w":"131 SAMU, 132 Bomberos, 133 Carabineros."},{"q":"Hay un incendio que no se pudo controlar en la bodega. ¿A qué número llamas?","o":["132","131","133","1404"],"w":"El 132 es Bomberos."},{"q":"Al llamar a emergencias, ¿qué información debes dar?","o":["Dirección exacta, qué pasó y cuántos lesionados","Tu nombre completo y RUT solamente","Solo que es urgente, para no perder tiempo","El nombre de tu jefatura y de tu turno"],"w":"Con esos datos la ayuda llega al lugar correcto y preparada."}]},{"s":"pe_numeros","v":[{"q":"Hay un lesionado grave por un accidente del trabajo. ¿A qué número de la ACHS llamas?","o":["1404","131","132","133"],"w":"El 1404 es el número de emergencias de la ACHS."},{"q":"¿Cuál es el número del SAMU?","o":["131","132","133","134"],"w":"131 SAMU, 132 Bomberos, 133 Carabineros, 134 PDI."},{"q":"Llamaste a emergencias. ¿Cuándo cortas?","o":["Cuando la operadora me lo indique","Apenas termino de dar la dirección","Después de unos 30 segundos de llamada","Cuando escucho la sirena acercarse"],"w":"La operadora puede necesitar más datos o darte instrucciones."}]},{"s":"emergencias_luz","v":[{"q":"Se corta la luz mientras trabajas en la línea. ¿Qué haces?","o":["Me quedo quieto, apago mi máquina y no meto las manos","Saco la lata trabada aprovechando que paró","Corro hacia la salida aunque esté oscuro","Espero con la mano sobre el producto de la cinta"],"w":"Así evitas cortes y que la máquina parta sola al volver la luz."},{"q":"¿Por qué hay que apagar tu máquina cuando se corta la luz?","o":["Para que no parta sola al volver la energía","Para ahorrar electricidad mientras tanto","Porque el producto se enfría en la cinta","Para que no suene la alarma de la máquina"],"w":"Una máquina que parte sola puede atrapar a alguien."},{"q":"Justo después del corte de luz, la cinta parece detenida. ¿Puedes meter las manos?","o":["No: aún pueden girar y la energía puede volver","Sí, porque sin luz la cinta no tiene riesgo","Sí, si lo haces con los guantes puestos","Sí, si un compañero vigila el tablero"],"w":"Detenida por un corte no es lo mismo que bloqueada."}]},{"s":"emergencias_bloqueo","v":[{"q":"La salida de emergencia y el extintor están tapados por pallets. ¿Qué haces?","o":["Aviso y ayudo a despejarlos de inmediato","Nada, en una emergencia se mueven","Busco otra salida solo para mí","Dejo un espacio angosto para pasar"],"w":"Salidas y extintores deben estar siempre despejados."},{"q":"¿Por qué las salidas de emergencia deben estar siempre despejadas?","o":["Porque en una emergencia cada segundo cuenta","Porque se ven mejor en una inspección","Porque así lo pide el personal de aseo","Solo para que pueda pasar la grúa"],"w":"Mover pallets en una emergencia cuesta segundos que pueden salvar vidas."},{"q":"Una salida de emergencia bloqueada es:","o":["Una condición insegura que se debe avisar","Aceptable si es solo por poco tiempo","Un problema que corresponde solo a la jefatura","Normal durante la temporada alta"],"w":"Se despeja y se avisa de inmediato."}]},{"s":"emergencias_auto","v":[{"q":"Después de evacuar, puedo volver por mis cosas si es rápido.","vf":false,"w":"Falso. Nadie vuelve a entrar hasta que se autorice."},{"q":"Ya evacuaste y recuerdas que dejaste tu celular. ¿Qué haces?","o":["Me quedo en la zona de seguridad hasta que autoricen","Vuelvo corriendo, porque es solo un minuto","Le pido a un compañero que vaya a buscarlo","Vuelvo por otra puerta para no molestar a nadie"],"w":"Ningún objeto vale tu vida."},{"q":"¿Cuál es una acción insegura durante una evacuación?","o":["Grabar con el celular o volver por la mochila","Caminar rápido por la derecha, sin correr","Ayudar a una visita a llegar a la salida","Seguir la vía de evacuación señalizada"],"w":"Distraerse o volver retrasa la evacuación y te expone."}]},{"s":"emergencias_conteo","v":[{"q":"Al llegar a la zona de seguridad, lo correcto es:","o":["Quedarme para el conteo y avisar si falta alguien","Volver a mi puesto si todo parece normal","Irme a mi casa para no estorbar a nadie","Salir a la calle a mirar lo que pasa"],"w":"El conteo permite saber si alguien quedó atrapado."},{"q":"En el conteo notas que falta un compañero. ¿Qué haces?","o":["Aviso a la jefatura y a Bomberos; no entro","Entro a buscarlo yo mismo con cuidado","Espero en silencio a que aparezca solo","Lo llamo por celular y entro si no contesta"],"w":"Bomberos entra con el equipo adecuado; tú no vuelves a entrar."},{"q":"En la zona de seguridad se cuenta a las personas para saber si alguien quedó adentro.","vf":true,"w":"Verdadero. Por eso nadie se va ni vuelve a entrar sin autorización."}]}]},{"id":"senaletica","sec":"todos","title":"Señalización de seguridad","thumb":"signsAll","learn":[{"s":"senaletica_porque","t":"¿Para qué sirven las señales?","x":"Las señales te avisan de un peligro, una prohibición o una obligación <b>antes</b> de que te expongas, aunque no conozcas la zona o no leas el texto. En Chile siguen las normas <b>NCh 1410</b> (colores de seguridad) y <b>NCh 1411</b> (letreros de seguridad), y el <b>DS 594</b> exige señalizar los riesgos. En {EMP} las verás en líneas, cerradoras, sala de caldera, autoclaves, cámaras de frío, patio y bodegas."},{"s":"senaletica_formas","t":"Forma y color tienen significado","x":"<ul><li><b>Círculo rojo con barra:</b> prohibición.</li><li><b>Círculo azul:</b> obligación.</li><li><b>Triángulo amarillo con borde negro:</b> advertencia de peligro.</li><li><b>Rectángulo verde:</b> evacuación, salida y primeros auxilios.</li><li><b>Rectángulo rojo:</b> equipos contra incendio, como extintores y red húmeda.</li></ul>Aprende a leer la forma y el color: te dan el mensaje aunque la señal esté lejos o desteñida."},{"s":"senaletica_prohib","t":"Prohibición: círculo rojo con barra","x":"Indica algo que <b>no se puede hacer</b>, sin excepciones y aunque “nunca pase nada”. Ejemplos en la planta: <b>no fumar</b> donde hay cartón, gas o combustibles; <b>no pasar</b> por la zona de grúa horquilla; <b>no usar el celular</b> operando; <b>no entrar a la sala de caldera</b> si no eres operador autorizado. Que un compañero con experiencia lo haga no lo vuelve permitido."},{"s":"senaletica_oblig","t":"Obligación: círculo azul","x":"Indica lo que <b>debes usar o hacer</b> en esa zona: protector auditivo, cofia, mascarilla, lentes, guantes o calzado de seguridad. Si la zona está señalizada, el EPP es <b>obligatorio todo el tiempo que estés dentro</b>, aunque la máquina esté detenida, aunque “hoy no haya tanto ruido” o aunque solo entres dos minutos a dejar un recado. Póntelo <b>antes</b> de entrar.","k":"Si la señal es azul, el EPP va puesto antes de entrar y todo el tiempo."},{"s":"senaletica_adv","t":"Advertencia: triángulo amarillo","x":"Avisa de un <b>peligro cercano</b>: tránsito de grúa horquilla, riesgo eléctrico, superficies calientes y vapor en autoclaves, carga suspendida o piso resbaladizo. Al verla: <b>baja el ritmo</b>, mira a tu alrededor, escucha y busca el peligro antes de seguir. Si la advertencia es de grúa, camina por el pasillo peatonal y asegúrate de que el operador te vea."},{"s":"senaletica_evac","t":"Verde para salir, rojo para el fuego","x":"Las señales <b>verdes</b> muestran la vía de evacuación, la salida y los primeros auxilios (cruz blanca sobre fondo verde). Si suena la alarma, sigue las <b>flechas verdes</b> hasta la zona de seguridad sin correr. Las señales <b>rojas</b> marcan dónde están los extintores y equipos contra incendio. Conoce dónde están las de tu sector antes de que las necesites."},{"s":"quimicos_pictos","t":"Pictogramas de productos químicos","x":"Los envases de productos de aseo y sanitización llevan pictogramas del <b>Sistema Globalmente Armonizado (SGA)</b>, que en Chile regula el <b>DS 57</b>: <b>rombo de borde rojo, fondo blanco y símbolo negro</b>.<ul><li><b>Llama:</b> inflamable.</li><li><b>Líquido que daña una mano y una superficie:</b> corrosivo, como la soda cáustica.</li><li><b>Signo de exclamación:</b> irritante o nocivo.</li></ul><b>Envase sin etiqueta no se usa</b>: se aparta y se avisa."},{"s":"senaletica_piso","t":"Demarcación en el piso","x":"Las líneas pintadas en el piso también son señalización: separan los <b>pasillos peatonales</b> de las zonas de <b>tránsito de grúa horquilla</b> y de las áreas de acopio. Las franjas <b>amarillas y negras</b> marcan peligro. Camina siempre por tu pasillo, aunque el otro camino sea más corto, y <b>no dejes pallets, cajas ni bandejas sobre las líneas</b>, ni siquiera por poco rato."},{"s":"senaletica_auto","t":"Autocuidado: no te acostumbres a las señales","x":"Las acciones inseguras típicas: ignorar un letrero “porque siempre ha estado ahí”, cruzar la zona de grúa por el camino corto o entrar sin EPP “solo un momento”. El peligro sigue ahí aunque te acostumbres. La decisión segura: <b>obedecer cada señal, cada vez</b>, y dar el ejemplo a los temporeros nuevos, que copian lo que ven hacer."},{"s":"senaletica_visible","t":"Señales y extintores siempre visibles","x":"Una señal tapada no avisa nada. <b>Nunca pongas pallets, cajas ni bandejas</b> delante de una señal, un extintor o una salida, aunque falte espacio en temporada. El acceso al extintor debe quedar <b>libre</b>. Si ves una señal caída, rota, desteñida o tapada, despéjala si puedes y <b>avísalo</b> a tu jefatura para que se reponga.","k":"Nunca tapes una señal, un extintor ni una salida."}],"quiz":[{"s":"senaletica_oblig","v":[{"q":"Un círculo azul con el dibujo de un protector auditivo significa:","o":["Que usarlo es obligatorio en esa zona","Que se recomienda usarlo si hay ruido","Que ahí se entregan protectores","Que la zona tiene ruido solo a ratos"],"w":"El círculo azul indica una obligación: lo que debes usar o hacer en esa zona."},{"q":"En la entrada de la sala de cerradoras hay un círculo azul con una cofia y una mascarilla. ¿Qué indica?","o":["Que usar cofia y mascarilla es obligatorio","Que la cofia y la mascarilla son opcionales","Que está prohibido entrar con cofia","Que ahí se guardan cofias y mascarillas"],"w":"Azul es obligación: ese EPP se usa siempre dentro de la zona."},{"q":"El color azul en una señal circular indica una obligación.","vf":true,"w":"Verdadero. Círculo azul: algo que debes usar o hacer."}]},{"s":"senaletica_adv","v":[{"q":"¿Qué forma y color tiene una señal de advertencia de peligro?","o":["Triángulo amarillo con borde negro","Círculo amarillo con barra negra","Cuadrado amarillo con borde rojo","Triángulo rojo con fondo blanco"],"w":"La advertencia es un triángulo amarillo con borde y símbolo negro."},{"q":"Ves un triángulo amarillo con una grúa horquilla dibujada. ¿Qué haces?","o":["Bajo el ritmo y miro si viene la grúa","Paso rápido para no estorbar a la grúa","Espero que el operador toque la bocina","Sigo igual, porque no voy a operar la grúa"],"w":"La advertencia te pide más atención: hay un peligro cercano."},{"q":"Un triángulo amarillo con borde negro te indica:","o":["Un peligro cercano que exige más atención","Una obligación de usar EPP en la zona","Una información general del sector","La ruta hacia la salida de emergencia"],"w":"Amarillo con borde negro es advertencia de peligro."}]},{"s":"senaletica_prohib","v":[{"q":"El círculo rojo con una barra diagonal significa:","o":["Prohibición: eso no se hace","Peligro: hazlo con cuidado","Obligación: hazlo siempre","Incendio: hay un extintor cerca"],"w":"El círculo rojo con barra indica una acción prohibida, sin excepciones."},{"q":"En la puerta de la sala de caldera hay una señal de prohibido el paso a personal no autorizado. Tú no eres operador. ¿Qué haces?","o":["No entro, aunque sea por un momento","Entro solo si veo que no hay nadie","Entro rápido si tengo que avisar algo","Entro si un operador me acompaña a la puerta"],"w":"Una prohibición se respeta siempre: si necesitas algo, avisa al operador desde fuera."},{"q":"Una señal de prohibición se puede pasar por alto si un compañero con experiencia dice que no pasa nada.","vf":false,"w":"Falso. La prohibición no tiene excepciones, la diga quien la diga."}]},{"s":"senaletica_evac","v":[{"q":"¿Qué color tienen las señales de evacuación y de primeros auxilios?","o":["Verde","Rojo","Azul","Amarillo"],"w":"Verde: evacuación, salida y primeros auxilios."},{"q":"Suena la alarma de evacuación. ¿Qué señales sigues para llegar a la zona de seguridad?","o":["Las flechas verdes de vía de evacuación","Las señales rojas de los extintores","Las líneas amarillas del pasillo de grúas","Los círculos azules de uso de EPP"],"w":"Las señales verdes te llevan a la salida y a la zona de seguridad."},{"q":"Necesitas el botiquín de primeros auxilios. ¿Qué señal te indica dónde está?","o":["Rectángulo verde con una cruz blanca","Rectángulo rojo con una cruz blanca","Círculo azul con una cruz blanca","Triángulo amarillo con una cruz negra"],"w":"Los primeros auxilios se señalan en verde, con cruz blanca."}]},{"s":"senaletica_evac","v":[{"q":"Una señal roja con el dibujo de un extintor indica:","o":["Dónde está un equipo contra incendio","Que la zona tiene peligro de incendio","Que está prohibido hacer fuego ahí","La salida de emergencia más cercana"],"w":"El rojo marca la ubicación de extintores y equipos contra incendio."},{"q":"Se inicia un amago de fuego en unas cajas de cartón. ¿Qué color de señal te muestra dónde está el extintor?","o":["Rojo","Verde","Azul","Amarillo"],"w":"Los equipos contra incendio se señalizan en rojo."},{"q":"Las señales rojas de seguridad marcan la ubicación de extintores y equipos contra incendio.","vf":true,"w":"Verdadero. Verde te saca; rojo te muestra el extintor."}]},{"s":"quimicos_pictos","v":[{"q":"¿Cómo son los pictogramas SGA de un bidón de soda cáustica?","o":["Rombo de borde rojo, fondo blanco y símbolo negro","Círculo de borde rojo, fondo blanco y símbolo negro","Triángulo amarillo con borde y símbolo negro","Rombo de fondo rojo con símbolo blanco"],"w":"Los pictogramas SGA (DS 57) son rombos de borde rojo, fondo blanco y símbolo negro."},{"q":"El pictograma de un producto de sanitización muestra un líquido que cae y daña una mano y una superficie. ¿Qué peligro indica?","o":["Corrosivo: quema la piel y los ojos","Inflamable: se enciende con facilidad","Irritante leve: solo da picazón","Peligro para el medio ambiente"],"w":"Ese símbolo es corrosivo, como la soda cáustica: daña piel, ojos y materiales."},{"q":"Un envase tiene un rombo de borde rojo con una llama negra. ¿Qué indica?","o":["Que el producto es inflamable","Que el producto es corrosivo","Que hay un extintor cerca","Que el producto se debe calentar"],"w":"La llama en el rombo SGA indica un producto inflamable."}]},{"s":"senaletica_tapada","v":[{"q":"Para ahorrar espacio en temporada, un compañero apila pallets delante de una señal de advertencia y del extintor. ¿Qué es lo correcto?","o":["Despejar y dejar visibles la señal y el extintor","Dejarlo así, porque todos saben dónde están","Mover solo el extintor y dejar la señal tapada","Dejarlo así hasta que termine la temporada"],"w":"Señales y extintores deben estar siempre visibles y con acceso libre."},{"q":"¿Cuál es la condición correcta de una señal y de un extintor?","o":["Visibles, despejados y con acceso libre","Visibles solo cuando hay una inspección","Guardados en bodega para que no se dañen","Detrás de los pallets, protegidos de golpes"],"w":"Una señal tapada no avisa y un extintor bloqueado no sirve en una emergencia."},{"q":"Una señal tapada, rota o desteñida se debe avisar para que se reponga.","vf":true,"w":"Verdadero. Una señal que no se ve no protege a nadie."}]},{"s":"senaletica_piso","v":[{"q":"Puedo dejar pallets sobre la línea amarilla del pasillo si es por poco rato.","vf":false,"w":"Falso. Las líneas demarcan pasillos que deben estar siempre libres."},{"q":"Debes cruzar la planta y hay un pasillo peatonal demarcado junto a la zona de grúa. ¿Por dónde caminas?","o":["Por el pasillo peatonal demarcado","Por la zona de grúa si no viene ninguna","Por el camino más corto hasta mi puesto","Por encima de la línea amarilla del borde"],"w":"La demarcación separa personas y grúas: camina siempre por tu pasillo."},{"q":"¿Para qué sirven las líneas pintadas en el piso de la planta?","o":["Separar pasillos peatonales, grúas y acopio","Indicar dónde dejar material por un rato","Marcar solo la ruta de los camiones","Ordenar visualmente sin ser obligatorias"],"w":"Son señalización: separan el tránsito de personas, grúas y materiales."}]},{"s":"senaletica_oblig","v":[{"q":"En la zona está la señal de protector auditivo, pero hoy “no hay tanto ruido”. ¿Qué haces?","o":["Lo uso igual, todo el tiempo que esté ahí","Lo uso solo cuando la cerradora esté andando","Lo uso solo si me empiezan a doler los oídos","Lo llevo al cuello, listo para ponérmelo"],"w":"Si la zona está señalizada, el protector es obligatorio todo el tiempo."},{"q":"Entras a la zona de cerradoras solo dos minutos a dejar un recado. Hay señal azul de protector auditivo. ¿Qué haces?","o":["Me pongo el protector antes de entrar","Entro sin protector porque es poco rato","Entro tapándome los oídos con las manos","Entro sin protector si no me quedo cerca"],"w":"La obligación rige para todos los que entran, aunque sea un momento."},{"q":"Una señal de EPP obligatorio rige:","o":["Todo el tiempo que estés dentro de la zona","Solo cuando la máquina está funcionando","Solo para quienes operan las máquinas","Solo en las horas de mayor producción"],"w":"El EPP señalizado se usa siempre dentro de la zona, sin excepciones."}]}]},{"id":"uv","sec":"todos","title":"Radiación UV de origen solar","thumb":"uv_intro","learn":[{"s":"uv_intro","t":"Radiación UV: un peligro que no se siente","x":"El sol emite <b>radiación ultravioleta (UV)</b>: no se ve ni se siente como calor, pero daña la piel y los ojos. En {EMP} te expones al trabajar en el <b>patio de descarga</b>, la <b>romana</b>, la <b>portería</b>, la <b>carga de camiones</b> y cualquier tarea al aire libre, aunque el día esté fresco. El daño se va sumando durante toda la vida."},{"s":"uv_efectos","t":"Efectos en la salud","x":"<ul><li><b>Quemaduras</b> solares, que aparecen horas después.</li><li><b>Daño ocular</b>: irritación y, con los años, cataratas.</li><li><b>Envejecimiento</b> y manchas de la piel.</li><li><b>Cáncer de piel</b>, por la exposición acumulada durante años.</li></ul>Revisa tu piel: un lunar que cambia de forma, color o tamaño, o una herida que no sana, debe verlo un médico."},{"s":"uv_escala","t":"El índice UV","x":"Indica cuánta radiación UV llega. Mientras más alto, más rápido daña:<ul><li>1 a 2, <b>verde</b>: bajo.</li><li>3 a 5, <b>amarillo</b>: moderado.</li><li>6 a 7, <b>naranjo</b>: alto.</li><li>8 a 10, <b>rojo</b>: muy alto.</li><li>11 o más, <b>violeta</b>: extremo.</li></ul>Desde 3 hay que protegerse. Revisa el índice del día en el pronóstico del tiempo."},{"s":"uv_horario","t":"Horario de mayor radiación","x":"Entre septiembre y marzo la radiación es mayor aproximadamente entre las <b>10:00 y las 17:00</b>. Cuando se pueda, deja las tareas al sol para temprano o para el final de la tarde, y busca la sombra en las pausas. Un truco fácil: si <b>tu sombra es más corta que tú</b>, el sol está fuerte y la radiación es alta."},{"s":"uv_nublado","t":"Aunque esté nublado","x":"Las nubes <b>no detienen toda la radiación UV</b>: en un día nublado o fresco igual te puedes quemar, porque no sientes el calor que te advierte. Las superficies claras, como el cemento del patio, el agua o la latería, también reflejan parte de la radiación. Protégete siempre que trabajes al aire libre, aunque no haga calor."},{"s":"uv_ropa","t":"Ropa y EPP contra el sol","x":"<ul><li><b>Manga larga y pantalón largo</b>: la ropa es la mejor barrera.</li><li><b>Legionario o jockey con cubrenuca</b>: protege orejas y cuello.</li><li><b>Lentes con filtro UV</b>. Ojo: un lente oscuro sin filtro es peor, porque dilata la pupila y deja entrar más radiación.</li></ul>La empresa entrega estos elementos sin costo. Úsalos durante toda la exposición, no solo cuando sientas calor."},{"s":"uv_bloq","t":"Bloqueador solar","x":"Usa bloqueador <b>FPS 30 o más</b> en cara, orejas, cuello, nuca y manos. Aplícalo unos <b>20 a 30 minutos antes</b> de salir al sol y <b>reaplícalo cada 2 a 3 horas</b>, y antes si sudas mucho o te lavas. No reemplaza a la ropa ni a la sombra: es una barrera más. Si se acaba en tu puesto, avisa para que lo repongan.","k":"FPS 30 o más, reaplicado cada 2 a 3 horas."},{"s":"uv_sombra","t":"Sombra e hidratación","x":"Aprovecha la sombra en las pausas y para las tareas que se puedan hacer bajo techo. <b>Toma agua</b> durante toda la jornada aunque no tengas sed: al sol se pierde mucho líquido. Si sientes <b>mareo, dolor de cabeza, náuseas o calambres</b>, detente, busca la sombra y avisa de inmediato a tu jefatura. No esperes a que pase solo."},{"s":"uv_ley","t":"Qué dice la normativa","x":"La <b>Ley 20.096</b> (art. 19) obliga al empleador a proteger a quienes trabajan expuestos a radiación UV. El <b>DS 594</b> (art. 109 a) considera expuesto a quien trabaja al sol directo entre el <b>1 de septiembre y el 31 de marzo, de 10:00 a 17:00</b>, o con índice UV de 6 o más en cualquier época. La empresa informa el riesgo y entrega la protección; tú la usas siempre."},{"s":"uv_auto","t":"Autocuidado: “es solo un rato”","x":"La acción insegura típica con el sol es pensar <b>“es solo un rato”</b> y salir sin manga larga, legionario ni bloqueador, o sacarse la ropa por el calor. Diez minutos aquí y quince allá suman horas al final de la temporada. La decisión segura: <b>protegerte cada vez que sales al sol</b>. Avisar si falta bloqueador o sombra también es autocuidado.","k":"Cada exposición suma: protégete cada vez que sales al sol."}],"quiz":[{"s":"uv_intro","v":[{"q":"¿En cuál de estas tareas te expones a la radiación UV?","o":["Recibir camiones en el patio de descarga","Trabajar dentro de la cámara de frío","Seleccionar en una línea bajo techo","Etiquetar latas dentro de la bodega"],"w":"Toda tarea al aire libre te expone a la radiación UV."},{"q":"Cargas un camión en el patio en una mañana fresca de verano. ¿Estás expuesto a la radiación UV?","o":["Sí, aunque no haga calor debo protegerme","No, porque la UV solo llega con calor","Solo si trabajo después de almuerzo","Solo si estoy más de cuatro horas al sol"],"w":"La radiación UV no se siente como calor: si estás al aire libre, te expones."},{"q":"¿Qué trabajadores de la planta se exponen a la radiación UV?","o":["Los de patio, romana, portería y carga","Solo los que trabajan en verano","Solo los que se queman con facilidad","Solo los que trabajan sin casco"],"w":"Cualquier tarea al sol expone, todo el año, y el daño se acumula."}]},{"s":"uv_escala","v":[{"q":"Un índice UV de 8 a 10 corresponde a:","o":["Rojo: muy alto","Naranjo: alto","Violeta: extremo","Amarillo: moderado"],"w":"8 a 10 es rojo, riesgo muy alto."},{"q":"El pronóstico indica índice UV 6. ¿Qué nivel y color corresponde?","o":["Alto, naranjo","Moderado, amarillo","Muy alto, rojo","Bajo, verde"],"w":"6 a 7 es alto, color naranjo."},{"q":"¿Desde qué índice UV hay que protegerse?","o":["Desde 3, moderado, amarillo","Desde 6, alto, naranjo","Desde 8, muy alto, rojo","Desde 11, extremo, violeta"],"w":"Desde 3 la radiación ya daña: hay que protegerse."}]},{"s":"uv_horario","v":[{"q":"Entre septiembre y marzo, ¿en qué horario la radiación UV es mayor?","o":["Entre las 10:00 y las 17:00 aproximadamente","Entre las 7:00 y las 10:00 de la mañana","Solo entre las 13:00 y las 14:00","Entre las 17:00 y las 20:00"],"w":"Es cuando el sol está más alto."},{"q":"Debes ordenar bandejas en el patio y puedes elegir el horario. ¿Cuál es el mejor?","o":["Temprano, antes de las 10:00","A mediodía, cuando hay más luz","A las 15:00, después de almuerzo","Cualquiera, si llevo bloqueador"],"w":"Fuera de las 10:00 a 17:00 la radiación es menor."},{"q":"Si tu sombra es más corta que tu altura, la radiación UV está fuerte.","vf":true,"w":"Verdadero. Sombra corta significa sol alto y radiación alta."}]},{"s":"uv_nublado","v":[{"q":"Si el día está nublado, no hay radiación UV.","vf":false,"w":"Falso. Las nubes no detienen toda la radiación UV."},{"q":"Está nublado y fresco, y debes estar dos horas en la romana. ¿Qué haces?","o":["Me protejo igual: las nubes no detienen la UV","No me protejo: sin sol no hay radiación","Uso solo lentes oscuros por si sale el sol","Me protejo solo cuando sale el sol"],"w":"En días nublados igual llega radiación UV y puedes quemarte."},{"q":"¿Por qué hay que protegerse aunque esté nublado?","o":["Las nubes dejan pasar parte de la UV","Las nubes aumentan el calor del cuerpo","Porque en días nublados la UV se duplica","Solo porque lo exige el reglamento"],"w":"Parte de la radiación UV atraviesa las nubes."}]},{"s":"uv_bloq","v":[{"q":"¿Cada cuánto se reaplica el bloqueador?","o":["Cada 2 a 3 horas, y antes si sudas","Una vez al inicio del turno basta","Solo cuando la piel se pone roja","Cada 6 horas si es FPS 50"],"w":"El bloqueador pierde efecto con el tiempo, el sudor y el lavado."},{"q":"Te aplicaste bloqueador a las 8:00 y a las 11:00 sigues cargando camiones al sol, sudando. ¿Qué haces?","o":["Me lo vuelvo a aplicar","Nada, el de la mañana dura todo el día","Me aplico solo en la cara","Espero a sentir ardor para aplicar"],"w":"Ya pasaron 3 horas y sudas: hay que reaplicar."},{"q":"¿Cuándo se aplica por primera vez el bloqueador?","o":["Unos 20 a 30 minutos antes de salir al sol","Cuando ya llevas una hora al sol","Solo al terminar la jornada","Cuando sientes calor en la piel"],"w":"Se aplica antes de exponerse y se reaplica cada 2 a 3 horas."}]},{"s":"uv_mal","v":[{"q":"Un compañero carga camiones con polera de manga corta, sin legionario y sin lentes. ¿Qué le falta?","o":["Manga larga, legionario y lentes con filtro UV","Solo bloqueador; lo demás es opcional","Solo un jockey; la ropa da lo mismo","Nada, si toma agua está protegido"],"w":"La protección completa es ropa larga, legionario, lentes UV y bloqueador."},{"q":"¿Quién está bien protegido del sol?","o":["Quien usa manga larga, legionario, lentes UV y bloqueador","Quien usa polera corta y mucho bloqueador","Quien usa lentes oscuros sin filtro y jockey","Quien trabaja rápido para estar menos rato"],"w":"Ninguna medida sola basta: se combinan ropa, legionario, lentes y bloqueador."},{"q":"Usar manga corta con bloqueador protege igual que usar manga larga.","vf":false,"w":"Falso. La ropa es la mejor barrera; el bloqueador es una barrera más."}]},{"s":"uv_ropa","v":[{"q":"¿Para qué sirve el legionario o jockey con cubrenuca?","o":["Protege orejas y cuello del sol","Reemplaza al casco en el patio","Evita la deshidratación al sol","Reemplaza al bloqueador en la cara"],"w":"Cubre zonas que quedan expuestas al sol."},{"q":"¿Qué lentes debes usar para trabajar al sol?","o":["Lentes con filtro UV","Cualquier lente oscuro","Lentes oscuros sin certificación","No hace falta si uso jockey"],"w":"Un lente oscuro sin filtro dilata la pupila y deja entrar más radiación."},{"q":"¿Qué ropa protege mejor del sol en el patio?","o":["Manga larga y pantalón largo","Polera sin mangas y short, por el calor","Manga corta con bloqueador en los brazos","Ropa larga solo en la mañana"],"w":"La ropa larga es la barrera más efectiva contra la radiación UV."}]},{"s":"uv_bloq","v":[{"q":"¿Qué factor de protección mínimo se recomienda para el bloqueador?","o":["FPS 30 o más","FPS 15","FPS 8 si no te quemas fácil","Cualquiera, si se aplica bien"],"w":"Se recomienda FPS 30 o más."},{"q":"El bloqueador de tu puesto dice FPS 15. ¿Qué haces?","o":["Aviso, porque se recomienda FPS 30 o más","Lo uso, cualquier FPS protege igual","Me aplico dos capas y queda en FPS 30","Lo uso solo en las tardes"],"w":"El mínimo recomendado es FPS 30; dos capas no duplican el factor."},{"q":"Un bloqueador FPS 30 o más es la recomendación mínima para trabajar al sol.","vf":true,"w":"Verdadero. Y se reaplica cada 2 a 3 horas."}]},{"s":"uv_efectos","v":[{"q":"¿Qué efectos puede causar la radiación UV?","o":["Quemaduras, daño ocular y cáncer de piel","Solo quemaduras que pasan en días","Solo bronceado, que protege la piel","Daño solo en personas de piel clara"],"w":"La radiación UV daña piel y ojos, y el daño se acumula."},{"q":"Notas que un lunar del brazo cambió de color y tamaño. ¿Qué haces?","o":["Consulto a un médico","Me aplico más bloqueador encima","Nada, si no duele no es grave","Espero a que termine la temporada"],"w":"Un lunar que cambia es una señal de alerta que debe ver un médico."},{"q":"¿Por qué hay que protegerse del sol desde joven?","o":["El daño se acumula durante toda la vida","El daño se borra cada invierno","Solo los mayores tienen riesgo","La piel joven no se quema"],"w":"Cada exposición suma al daño acumulado."}]},{"s":"uv_auto","v":[{"q":"Hace calor y vas a cargar un camión “solo un rato”. ¿Qué haces?","o":["Me protejo igual: ropa larga, legionario, lentes y bloqueador","Me saco la polera para aguantar el calor","Salgo sin protección porque es poco tiempo","Me pongo solo bloqueador en la cara"],"w":"Cada exposición suma: la protección se usa siempre."},{"q":"Un compañero dice que no vale la pena protegerse para 15 minutos en la romana. ¿Qué es correcto?","o":["Cada exposición suma: se protege igual","Tiene razón: 15 minutos no dañan","Solo vale protegerse con índice extremo","Basta con ponerse a la sombra del camión"],"w":"Los ratos cortos se suman durante la temporada y la vida."},{"q":"Vas a la portería al sol por diez minutos. ¿Qué haces?","o":["Salgo con mi protección puesta","Salgo sin protección, es poco rato","Salgo sin protección si está nublado","Me protejo solo si son más de 30 minutos"],"w":"No hay exposición tan corta que no sume: protégete cada vez."}]}]},{"id":"enfermedades","sec":"todos","title":"Efectos en la salud y enfermedades profesionales","thumb":"bodyMap","learn":[{"s":"enfermedades_vs","t":"Accidente y enfermedad profesional","x":"Un <b>accidente</b> ocurre de golpe. Una <b>enfermedad profesional</b>, según la <b>Ley 16.744, art. 7</b>, es la causada de manera directa por el trabajo que realizas y que produce incapacidad o muerte. Aparece de a poco, a veces después de años, y casi siempre <b>sin dolor al comienzo</b>. Un resfrío contagiado en tu casa no lo es: debe haberla causado el trabajo."},{"s":"enfermedades_ruido","t":"Ruido: hipoacusia","x":"Cerradoras, compresores, caldera y algunas líneas dañan de a poco las células del oído. La pérdida auditiva por ruido es <b>permanente: no tiene cura</b>. El límite es <b>85 dB(A) para 8 horas</b>; cada 3 dB más, el tiempo permitido baja a la mitad. En zona señalizada, el protector va <b>puesto y ajustado sobre los oídos todo el tiempo</b>. Colgado al cuello no protege, y los audífonos de música no son protector.","k":"El oído dañado no se recupera: protector puesto todo el turno."},{"s":"pe_quim","t":"Químicos de aseo y humedad: dermatitis","x":"El contacto repetido con <b>detergentes, cloro, soda cáustica o ácidos</b>, y tener las manos mojadas muchas horas, puede causar <b>dermatitis</b>: enrojecimiento, picazón, grietas o ronchas. Usa los guantes que indica la <b>Hoja de Datos de Seguridad (HDS)</b> de cada producto, cámbialos si se rompen, sécate bien las manos y avisa cualquier irritación. Una crema no reemplaza al guante."},{"s":"pe_pelusa","t":"Polvo y pelusa: respiración","x":"Al seleccionar y procesar mosqueta se libera <b>polvo y pelusa</b> que irrita ojos, nariz y garganta, y puede causar tos, alergias o asma. Si tu puesto lo requiere, usa la <b>mascarilla indicada</b>, bien ajustada sobre nariz y boca, y mantén <b>funcionando la extracción</b>: apagarla por el ruido aumenta lo que respiras. Una polera sobre la cara no filtra la pelusa fina."},{"s":"enfermedades_musculo","t":"Lesiones musculoesqueléticas","x":"Levantar cajas doblando la espalda, girar con carga o repetir el mismo gesto todo el día en la línea daña <b>espalda, hombros y muñecas</b>. Al principio es cansancio; después, dolor que no se pasa. Usa ayuda mecánica, carga entre dos lo pesado, levanta con las piernas y aprovecha las pausas para mover el cuerpo. Avisa si el dolor se repite."},{"s":"enfermedades_vigilancia","t":"Vigilancia de la salud","x":"Cuando una evaluación ambiental confirma exposición sobre el <b>nivel de acción</b> (en ruido, <b>82 dB(A)</b> según el protocolo PREXOR), la ACHS incorpora a los trabajadores expuestos a un <b>programa de vigilancia de la salud</b> con exámenes periódicos, como la audiometría. Sirven para <b>detectar el daño temprano</b>, antes de que avance. Asistir es parte de tu protección, aunque te sientas bien.","k":"Asiste a tus exámenes de vigilancia aunque te sientas bien."},{"s":"enfermedades_senales","t":"Señales de alerta","x":"<ul><li><b>Zumbido</b> en los oídos al final del turno, o hablar cada vez más fuerte.</li><li><b>Picazón</b>, ronchas o grietas en las manos.</li><li><b>Tos</b> o nariz tapada que no se pasa.</li><li><b>Hormigueo</b> o dolor en manos, hombros o espalda.</li></ul>Si una molestia dura semanas, no esperes al próximo examen: avísalo a tu jefatura o al prevencionista."},{"s":"enfermedades_diep","t":"Si crees que es por el trabajo","x":"Avisa a tu jefatura. La empresa hace la <b>DIEP</b> (Denuncia Individual de Enfermedad Profesional) y te deriva a la <b>ACHS</b>, que evalúa si es de origen laboral. Si lo es, el seguro de la Ley 16.744 cubre la atención y los subsidios <b>sin costo para ti</b>. Si la empresa no hace la DIEP, <b>tú mismo puedes presentarte en la ACHS</b> y denunciarla."},{"s":"enfermedades_auto","t":"Autocuidado: la protección no tiene pausa","x":"Las acciones inseguras típicas: <b>sacarse los fonos “solo un rato”, tocar químicos sin guantes, no usar la mascarilla, faltar al examen</b>. El daño se suma día a día y no avisa. La decisión segura: protección todo el turno, ir a tus controles y avisar de inmediato si tu EPP está roto, te queda mal o no lo tienes."}],"quiz":[{"s":"enfermedades_vs","v":[{"q":"Según la Ley 16.744, una enfermedad profesional es:","o":["La causada de manera directa por el trabajo que realizas","Cualquier enfermedad que aparezca mientras trabajas","Solo la que se produce por un golpe en el trabajo","Cualquier enfermedad que te dé licencia médica"],"w":"Así la define el art. 7 de la Ley 16.744: la causa directa es el trabajo."},{"q":"¿En qué se diferencia una enfermedad profesional de un accidente?","o":["Aparece de a poco, a veces tras años","Siempre duele desde el primer día","No la cubre el seguro de la Ley 16.744","Solo afecta a quienes operan máquinas"],"w":"El accidente ocurre de golpe; la enfermedad profesional avanza de a poco."},{"q":"Te resfrías porque te contagió alguien en tu casa. ¿Es una enfermedad profesional?","o":["No, porque no la causó tu trabajo","Sí, si te enfermas en un día laboral","Sí, si faltas más de tres días","Sí, si tosiste en la línea"],"w":"Debe ser causada de manera directa por el trabajo que realizas."}]},{"s":"enfermedades_ruido","v":[{"q":"La pérdida auditiva causada por ruido:","o":["Es permanente: no tiene cura","Se recupera con descanso","Se recupera en las vacaciones","Se cura con tratamiento médico"],"w":"La hipoacusia por ruido no tiene cura: solo se previene."},{"q":"Un trabajador de cerradoras con hipoacusia por ruido deja ese puesto. ¿Qué pasa con su audición?","o":["No se recupera: el daño es permanente","Se recupera en unos meses","Se recupera si usa protector desde ahora","Mejora con el tiempo, lejos del ruido"],"w":"El daño auditivo por ruido no se revierte: por eso se protege desde el primer día."},{"q":"¿Por qué la hipoacusia por ruido se debe prevenir?","o":["Porque no tiene cura","Porque es muy cara de tratar","Porque solo aparece en la vejez","Porque es poco frecuente"],"w":"Lo perdido no se recupera: la única opción es prevenir."}]},{"s":"enfermedades_fonosMal","v":[{"q":"En una zona señalizada de protector auditivo, puedo sacármelo un rato si estoy cansado.","vf":false,"w":"Falso. Si la zona está señalizada, el protector es obligatorio todo el tiempo."},{"q":"¿Cuándo se usa el protector auditivo en una zona sobre 85 dB(A)?","o":["Todo el tiempo que estás en la zona","Solo cuando anda la máquina más cercana","Solo las primeras horas del turno","Solo cuando el ruido molesta"],"w":"Unos minutos sin protector en ruido alto ya suman daño."},{"q":"El protector te incomoda y la zona está señalizada. ¿Qué haces?","o":["Lo mantengo puesto y pido revisar si me queda mal","Me lo saco diez minutos cada hora","Me lo saco cuando hay menos ruido","Lo cambio por algodón en los oídos"],"w":"Se usa todo el tiempo; si molesta, se pide uno que ajuste bien."}]},{"s":"enfermedades_piel","v":[{"q":"Tocar soda cáustica o cloro sin guantes todos los días puede causar:","o":["Dermatitis en la piel","Callos que protegen la piel","Solo manchas que salen al lavar","Daño solo si eres alérgico"],"w":"El contacto repetido con químicos irrita y daña la piel."},{"q":"Tienes grietas y picazón en las manos por los productos de aseo. ¿Qué haces?","o":["Aviso y uso los guantes que indica la HDS","Me aplico crema y sigo sin guantes","Me lavo con más cloro para desinfectar","Espero a que se pase sola la irritación"],"w":"Son señales de dermatitis: se avisa y se usa el guante correcto."},{"q":"¿Dónde se indica qué guante usar con un producto químico?","o":["En la Hoja de Datos de Seguridad (HDS)","En la guía de despacho del proveedor","En el color del envase","En la factura de compra"],"w":"La HDS indica los peligros y el EPP de cada producto."}]},{"s":"enfermedades_polvo","v":[{"q":"La pelusa de la mosqueta puede irritar los ojos y las vías respiratorias.","vf":true,"w":"Verdadero. Por eso se usa la mascarilla indicada y la extracción."},{"q":"Seleccionas mosqueta y hay pelusa en el aire. ¿Qué haces?","o":["Uso la mascarilla indicada y mantengo la extracción","Me tapo la nariz con la polera","Apago la extracción porque hace ruido","Trabajo más rápido para salir luego"],"w":"La mascarilla bien ajustada y la extracción reducen lo que respiras."},{"q":"¿Qué puede causar la pelusa de la mosqueta?","o":["Irritación, tos y alergias","Solo manchas en la ropa","Daño solo si se traga","Nada, porque es un producto natural"],"w":"Que sea natural no la hace inofensiva para las vías respiratorias."}]},{"s":"enfermedades_vigilancia","v":[{"q":"Te citan a exámenes del programa de vigilancia de la salud. ¿Qué haces?","o":["Asisto: es parte de mi protección","No voy porque me siento bien","Voy solo si me queda tiempo libre","Voy solo si me duele algo"],"w":"Los exámenes detectan el daño antes de que lo sientas."},{"q":"¿Para qué sirven los exámenes periódicos de vigilancia de la salud?","o":["Detectar el daño temprano, antes de que avance","Decidir si el trabajador sirve para el cargo","Reemplazar el uso del protector auditivo","Cumplir un trámite sin efecto real"],"w":"Detectar temprano permite actuar antes de que el daño avance."},{"q":"¿Cuándo la ACHS incorpora a trabajadores a vigilancia de la salud por ruido?","o":["Cuando una evaluación confirma exposición sobre el nivel de acción","Cuando el trabajador lo pide por escrito","Solo después de un accidente del trabajo","Solo a los mayores de 50 años"],"w":"En ruido, el nivel de acción es 82 dB(A) según el protocolo PREXOR."}]},{"s":"enfermedades_fonosBien","v":[{"q":"¿Cuál trabajador está protegido frente al ruido?","o":["El que tiene los fonos puestos sobre los oídos","El que lleva los fonos colgados al cuello","El que se aleja un poco de la cerradora","El que usa audífonos con música"],"w":"El protector solo sirve puesto y ajustado sobre los oídos."},{"q":"Un compañero lleva los fonos colgados al cuello junto a la cerradora. ¿Está protegido?","o":["No: el protector solo sirve puesto sobre los oídos","Sí, porque los tiene a mano","Sí, si los usa la mitad del turno","Sí, si no está pegado a la máquina"],"w":"Colgado al cuello, el protector no protege nada."},{"q":"Para que el protector auditivo funcione, debe:","o":["Estar puesto y ajustado sobre los oídos","Estar a mano por si sube el ruido","Usarse en la mitad más ruidosa del turno","Tener música para tapar el ruido"],"w":"Los audífonos de música no son protector y suman más ruido."}]},{"s":"enfermedades_senales","v":[{"q":"Tienes zumbido en los oídos al final del turno hace semanas. ¿Qué haces?","o":["Lo aviso a mi jefatura o al prevencionista","Lo aguanto: es normal en la planta","Espero el examen del próximo año","Subo el volumen para escuchar mejor"],"w":"Es una señal de alerta: avisar permite evaluarla a tiempo."},{"q":"Hace un mes sientes hormigueo en las manos después de la línea. ¿Qué haces?","o":["Lo aviso a mi jefatura o al prevencionista","Lo aguanto hasta fin de temporada","Me tomo un analgésico y sigo","Espero a que el dolor sea fuerte"],"w":"Una molestia que se repite por semanas es una señal de alerta."},{"q":"¿Cuál es una señal de alerta de una posible enfermedad profesional?","o":["Tos o nariz tapada que no se pasa","Cansancio después de un turno largo","Hambre a media mañana","Sueño después de almuerzo"],"w":"Las molestias persistentes ligadas al trabajo se deben avisar."}]},{"s":"enfermedades_diep","v":[{"q":"La sigla DIEP significa:","o":["Denuncia Individual de Enfermedad Profesional","Declaración Interna de Exposición Permanente","Denuncia Inmediata de Evento Peligroso","Documento Individual de Examen Preventivo"],"w":"Con la DIEP se inicia la evaluación en la ACHS."},{"q":"Crees que tu dermatitis es por el trabajo. ¿Cuál es el paso correcto?","o":["Avisar para que hagan la DIEP y me deriven a la ACHS","Ir a mi consultorio y pedir licencia común","Esperar a que empeore para que se note","Comprar una crema y no decir nada"],"w":"La DIEP permite que la ACHS evalúe si la enfermedad es laboral."},{"q":"Si la empresa no hace la DIEP, tú mismo puedes presentarte en la ACHS.","vf":true,"w":"Verdadero. El trabajador también puede denunciar la enfermedad profesional."}]}]},{"id":"psicosocial","sec":"todos","title":"Riesgos psicosociales y bienestar en el trabajo","thumb":"psico_intro","learn":[{"s":"psico_intro","t":"¿Qué son los riesgos psicosociales?","x":"Son condiciones de la <b>organización del trabajo y de las relaciones</b> que pueden dañar la salud mental y física. No se ven como una máquina, pero también lesionan: un ritmo imposible por semanas en temporada, órdenes confusas o contradictorias, falta de apoyo o malos tratos pueden enfermar. No son un problema personal de cada uno: se evalúan y se corrigen."},{"s":"psico_factores","t":"Factores que influyen","x":"<ul><li><b>Carga y ritmo</b> de trabajo.</li><li><b>Claridad:</b> saber qué se espera de ti y quién te da las órdenes.</li><li><b>Apoyo</b> de compañeros y jefatura.</li><li><b>Buen trato</b> y respeto.</li><li><b>Equilibrio</b> entre trabajo, descanso y vida personal.</li></ul>Cuando estos factores están bien, el trabajo protege la salud; cuando fallan por mucho tiempo, la dañan."},{"s":"psico_estres","t":"El estrés laboral","x":"El estrés aparece cuando lo que se exige <b>supera, por mucho tiempo</b>, lo que se puede hacer. Es como una correa de máquina siempre tensa: aguanta un rato, pero si nunca se suelta, se corta. Algo de presión un día de mucho trabajo es normal; el problema es que sea <b>permanente</b>. El estrés también daña el cuerpo: sueño, presión, estómago y dolores."},{"s":"psico_senales","t":"Señales de alerta","x":"<ul><li>Cansancio que <b>no se pasa con el descanso</b>.</li><li>Problemas para dormir.</li><li>Irritabilidad o ganas de llorar.</li><li>Dolores de cabeza o de estómago frecuentes.</li><li>No querer ir a trabajar.</li></ul>Si duran semanas, en ti o en un compañero, no lo ignores ni lo ocultes: es el momento de conversar y pedir apoyo."},{"s":"psico_carga","t":"Si la carga de trabajo te supera","x":"Conversa con tu jefatura <b>a tiempo</b>: pregunta qué es prioritario, avisa si no alcanzas y pide instrucciones claras. Si no entiendes una orden, <b>pregunta</b> hasta tenerla clara. Quedarse callado y trabajar al límite no soluciona el problema: aumenta los errores y los accidentes. Saltarse un paso de seguridad para avanzar nunca es la salida.","k":"Si no alcanzas, avisa a tiempo: nunca te saltes un paso de seguridad."},{"s":"psico_apoyo","t":"Nos apoyamos como equipo","x":"Un equipo que se ayuda trabaja mejor y más seguro: compartir una carga pesada, <b>explicarle la tarea al temporero nuevo</b> con paciencia, preguntar “¿cómo estás?” a quien se ve agotado. El apoyo entre compañeros es uno de los factores que más protegen la salud mental. Ignorar o comentar a espaldas del compañero hace lo contrario."},{"s":"psico_respeto","t":"Buen trato","x":"Gritos, burlas, sobrenombres o humillaciones dañan la salud y el ambiente de trabajo. Con la <b>Ley Karin</b>, el maltrato puede constituir <b>acoso laboral</b>, incluso si ocurre una sola vez. Un error se corrige <b>con respeto, explicando y revisando juntos</b>, de preferencia en privado, nunca humillando frente al equipo. Saluda y pide las cosas por favor."},{"s":"psico_ceal","t":"El cuestionario CEAL-SM/SUSESO","x":"El <b>Protocolo de Vigilancia de Riesgos Psicosociales en el Trabajo</b> del MINSAL usa el cuestionario <b>CEAL-SM/SUSESO</b>, que reemplazó al ISTAS21. Evalúa <b>las condiciones del trabajo, no a las personas</b>. Cuando corresponda aplicarlo en tu centro de trabajo, tu participación es <b>anónima y voluntaria</b>, y tus respuestas son confidenciales: nadie de tu jefatura ve lo que respondes."},{"s":"psico_ayuda","t":"¿A quién recurrir?","x":"<ul><li>A tu <b>jefatura</b>.</li><li>Al <b>Comité Paritario, al Delegado de SST</b> o al asesor en prevención.</li><li>Si el malestar se debe al trabajo, la <b>ACHS</b> puede evaluarlo dentro del seguro de la Ley 16.744, sin costo para ti.</li></ul>Pedir ayuda no es debilidad: es una decisión responsable, igual que avisar una máquina con falla."},{"s":"psico_auto","t":"Autocuidado: cansado o apurado, el riesgo sube","x":"La mayoría de los accidentes se relacionan con una acción insegura, y el estrés y el cansancio las hacen más probables: te apuras, te saltas un paso, te distraes en la línea. La decisión segura: <b>reconocer que no estás bien, avisar y pedir apoyo antes de operar</b> una máquina o una grúa. Si ves a un compañero así, sugiérele avisar.","k":"Si no estás bien, avisa antes de operar."}],"quiz":[{"s":"psico_factores","v":[{"q":"Los riesgos psicosociales se relacionan con:","o":["La organización del trabajo y las relaciones","Solo las máquinas y herramientas","Solo los problemas personales de cada uno","El clima y la temperatura de la planta"],"w":"Carga, ritmo, claridad, apoyo y trato son factores psicosociales."},{"q":"¿Cuál de estos es un factor de riesgo psicosocial?","o":["Órdenes confusas y falta de apoyo","Un piso mojado en la línea","Un resguardo suelto en la cinta","El ruido de la cerradora"],"w":"Los riesgos psicosociales vienen de cómo se organiza el trabajo y del trato."},{"q":"En temporada, el ritmo es imposible por semanas y nadie explica las prioridades. Esto es:","o":["Un riesgo psicosocial que se debe abordar","Algo normal que no afecta la salud","Un problema personal de cada trabajador","Un riesgo que afecta solo a jefaturas"],"w":"Carga excesiva y falta de claridad son factores de riesgo psicosocial."}]},{"s":"psico_ceal","v":[{"q":"Cuando se aplique el cuestionario CEAL-SM en tu centro de trabajo, tu participación es:","o":["Anónima y voluntaria","Con nombre y RUT, obligatoria","Una prueba con nota","Revisada por tu jefatura"],"w":"Es anónima y voluntaria, para que puedas responder con sinceridad."},{"q":"Un compañero no quiere responder el CEAL-SM porque teme que su jefe lea sus respuestas. ¿Qué le dices?","o":["Que es anónimo y confidencial","Que el jefe revisa cada respuesta","Que debe poner su nombre","Que conviene responder que todo está bien"],"w":"Las respuestas son confidenciales: nadie de la jefatura las ve."},{"q":"¿Qué evalúa el cuestionario CEAL-SM/SUSESO?","o":["Las condiciones del trabajo, no a las personas","El rendimiento de cada trabajador","La salud mental de cada persona por separado","Quién merece un ascenso"],"w":"Busca mejorar las condiciones del trabajo para todos."}]},{"s":"psico_ceal","v":[{"q":"El cuestionario CEAL-SM/SUSESO reemplazó al ISTAS21.","vf":true,"w":"Verdadero. Es el instrumento actual del Protocolo de Vigilancia de Riesgos Psicosociales."},{"q":"¿Qué cuestionario usa hoy el protocolo de riesgos psicosociales del MINSAL?","o":["CEAL-SM/SUSESO","ISTAS21","PREXOR","TMERT"],"w":"El CEAL-SM/SUSESO reemplazó al ISTAS21."},{"q":"El cuestionario ISTAS21 fue reemplazado por:","o":["El CEAL-SM/SUSESO","El DS 44","La Ley Karin","El protocolo PLANESI"],"w":"Hoy se usa el CEAL-SM/SUSESO."}]},{"s":"psico_estres","v":[{"q":"El estrés laboral nunca afecta la salud física.","vf":false,"w":"Falso. Puede causar dolores, problemas de sueño, de estómago y más."},{"q":"¿Cuándo la presión del trabajo se vuelve dañina?","o":["Cuando es permanente, sin respiro","Cuando hay un día de mucho trabajo","Cuando hay cualquier presión","Solo cuando ocurre un accidente"],"w":"Algo de presión es normal; el daño viene cuando no se suelta nunca."},{"q":"El estrés laboral aparece cuando:","o":["Lo exigido supera por mucho tiempo lo que se puede hacer","Hay un pedido urgente una vez al mes","Te toca aprender una tarea nueva","Trabajas en equipo con otros"],"w":"Es la exigencia excesiva y prolongada la que daña."}]},{"s":"psico_senales","v":[{"q":"¿Cuál es una señal de alerta de estrés?","o":["Problemas para dormir e irritabilidad","Cansancio que se pasa al descansar","Hambre a la hora de almuerzo","Ganas de salir de vacaciones"],"w":"Dormir mal e irritarse por semanas son señales para prestar atención."},{"q":"Hace semanas duermes mal, tienes dolor de cabeza y no quieres ir a trabajar. ¿Qué haces?","o":["Lo reconozco como alerta y pido apoyo","Lo aguanto hasta que termine la temporada","Tomo más café y sigo igual","Lo oculto para no parecer débil"],"w":"Reconocer las señales a tiempo es el primer paso."},{"q":"Un cansancio que no se pasa con el descanso puede ser una señal de alerta de estrés.","vf":true,"w":"Verdadero. El cansancio normal se pasa al descansar; el que persiste es una alerta."}]},{"s":"psico_carga","v":[{"q":"Tienes más pedidos de los que alcanzas a sacar en el turno. ¿Qué haces?","o":["Converso a tiempo con mi jefatura para priorizar","Me salto pasos de seguridad para avanzar","No digo nada y trabajo al límite","Le paso pedidos a un compañero sin avisar"],"w":"Hablar a tiempo permite ordenar prioridades sin arriesgarse."},{"q":"No entiendes una instrucción de tu jefatura y te da vergüenza preguntar. ¿Qué haces?","o":["Pregunto hasta tener claro qué se espera","Hago lo que creo y veo si resulta","Copio lo que hace el de al lado","Espero que otro pregunte por mí"],"w":"La claridad en las tareas protege la salud y evita errores."},{"q":"Trabajar callado al límite de tus fuerzas:","o":["Aumenta los errores y los accidentes","Demuestra compromiso sin riesgos","Es la forma de cumplir la meta","Solo afecta tu rendimiento"],"w":"Quedarse callado no resuelve la sobrecarga y aumenta el riesgo."}]},{"s":"psico_grito","v":[{"q":"Un supervisor ve un error en la línea. ¿Cuál es la forma correcta de corregirlo?","o":["Explicar con respeto y revisar juntos","Gritar para que no se repita","Corregir frente a todos como ejemplo","Dejarlo pasar para evitar conflictos"],"w":"Corregir con respeto protege la salud y mejora el trabajo."},{"q":"Un supervisor grita “¿otra vez?” y humilla a un trabajador frente al equipo. Eso:","o":["Puede ser acoso laboral, aunque sea una vez","Es normal si el trabajador se equivocó","Solo es acoso si se repite muchas veces","Es parte de la autoridad del supervisor"],"w":"Con la Ley Karin, una sola humillación puede constituir acoso laboral."},{"q":"¿Qué efecto tienen los gritos y humillaciones en el trabajo?","o":["Dañan la salud y aumentan los errores","Mejoran la concentración del equipo","No afectan si el trabajador tiene experiencia","Solo molestan a quien es sensible"],"w":"El maltrato es un riesgo psicosocial que enferma y provoca errores."}]},{"s":"psico_apoyo","v":[{"q":"Un compañero se ve agotado e irritable hace semanas. Lo mejor es:","o":["Preguntarle cómo está y sugerirle pedir apoyo","No meterse, porque es su problema","Comentarlo con el resto del equipo","Decirle que todos están igual de cansados"],"w":"Cuidarnos entre todos también es prevención."},{"q":"Llega un temporero nuevo que no conoce la tarea. ¿Qué es lo correcto?","o":["Explicarle y apoyarlo mientras aprende","Dejar que aprenda solo equivocándose","Pedirle que no pregunte para no atrasar","Darle las tareas más pesadas"],"w":"El apoyo al nuevo previene errores, accidentes y estrés."},{"q":"¿Por qué es importante el apoyo entre compañeros?","o":["Es de lo que más protege la salud mental","Solo hace el trabajo más entretenido","Permite que algunos trabajen menos","No tiene efecto real en la salud"],"w":"El apoyo social es un factor protector clave."}]},{"s":"psico_ayuda","v":[{"q":"Si tu malestar se debe al trabajo, ¿quién lo evalúa dentro del seguro de la Ley 16.744?","o":["La ACHS","Tu Isapre o Fonasa","La Inspección del Trabajo","El Comité Paritario"],"w":"La ACHS evalúa y atiende según la Ley 16.744."},{"q":"Te sientes sobrepasado por el trabajo y no sabes a quién recurrir. ¿Cuál es una vía correcta?","o":["Mi jefatura, el Comité o Delegado, o la ACHS","Esperar a que se pase solo","Comentarlo solo en redes sociales","Pedir licencia común sin decir el motivo"],"w":"Hay vías claras de apoyo dentro y fuera de la empresa."},{"q":"Pedir ayuda por un problema de salud mental es señal de debilidad.","vf":false,"w":"Falso. Pedir ayuda a tiempo es una decisión responsable."}]},{"s":"psico_auto","v":[{"q":"Estás agotado al final de un turno largo y debes operar una máquina. ¿Qué es lo seguro?","o":["Avisar que no estoy bien antes de operar","Operar más rápido para terminar luego","Operar igual, porque conozco la máquina","Tomar una bebida energética y seguir"],"w":"El cansancio aumenta los errores: reconocerlo y avisar es autocuidado."},{"q":"¿Por qué el cansancio y el estrés aumentan los accidentes?","o":["Te apuras, te saltas pasos y te distraes","Solo porque bajan la fuerza de las manos","No influyen si tienes experiencia","Solo afectan a los trabajadores nuevos"],"w":"Hacen más probables las acciones inseguras."},{"q":"Un compañero dice “no dormí nada, pero igual voy a operar la cerradora”. ¿Qué haces?","o":["Le sugiero avisar a la jefatura antes de operar","Le digo que tome café y siga","No digo nada, es su decisión","Lo reemplazo sin avisar a nadie"],"w":"Operar sin estar bien pone en riesgo a todos: se avisa antes."}]}]},{"id":"karin","sec":"todos","title":"Ley Karin: trabajo libre de acoso y violencia","thumb":"karin_intro","learn":[{"s":"karin_intro","t":"¿Qué es la Ley Karin?","x":"La <b>Ley 21.643</b>, conocida como Ley Karin, rige desde el <b>1 de agosto de 2024</b>. Modificó el Código del Trabajo para <b>prevenir, investigar y sancionar</b> el acoso laboral, el acoso sexual y la violencia en el trabajo. Protege a todos: trabajadores de planta, temporeros, administrativos y jefaturas. Todas las personas tienen derecho a un trabajo libre de acoso y violencia."},{"s":"psico_respeto","t":"El respeto es tarea de todos","x":"La Ley Karin no busca solo denunciar: su objetivo es que <b>todos trabajemos en un ambiente de respeto</b>. Eso depende de cada uno: cómo hablamos, cómo pedimos las cosas, cómo recibimos al nuevo o al temporero, cómo corregimos un error. El buen trato también previene conflictos, accidentes y enfermedades. Y si algo no está bien, <b>avisar también es respetar</b>."},{"s":"karin_sexual","t":"Acoso sexual","x":"Son <b>requerimientos de carácter sexual, hechos en forma indebida y por cualquier medio, no consentidos</b> por quien los recibe, que amenacen o perjudiquen su situación laboral o sus oportunidades en el empleo. “Por cualquier medio” incluye comentarios, gestos, contacto físico y <b>mensajes, fotos o audios por celular o redes sociales</b>, también fuera del horario. Si la otra persona dice que no, se respeta."},{"s":"karin_laboral","t":"Acoso laboral","x":"Es toda agresión u hostigamiento, por cualquier medio, de la jefatura o de compañeros, que cause menoscabo, maltrato o humillación, o que amenace o perjudique la situación laboral. Con la Ley Karin <b>no requiere reiteración: basta una vez</b>. Ejemplos: gritar o insultar, humillar frente al equipo, aislar a alguien, burlarse de su origen o su forma de hablar.","k":"Una sola humillación basta para que sea acoso laboral."},{"s":"karin_terceros","t":"Violencia en el trabajo","x":"Es la ejercida por <b>terceros ajenos a la empresa</b>: clientes, proveedores, choferes, contratistas o visitas. Por ejemplo, un chofer que insulta o amenaza al portero porque lo hizo esperar, o a quien recibe su carga en la romana. La ley también la cubre: la empresa debe prevenirla y proteger a sus trabajadores, y se puede denunciar igual que el acoso."},{"s":"karin_protocolo","t":"Protocolo y Reglamento Interno","x":"El empleador debe tener un <b>protocolo de prevención</b> del acoso sexual, el acoso laboral y la violencia en el trabajo (Código del Trabajo, art. 211-A), y un <b>procedimiento de investigación</b> en el <b>Reglamento Interno</b>. Tienes derecho a conocerlos: pregunta a tu jefatura dónde están. Ahí se indica cómo y ante quién denunciar dentro de {EMP}."},{"s":"karin_denuncia","t":"Cómo denunciar","x":"La denuncia se presenta <b>ante el empleador o ante la Inspección del Trabajo</b>, por escrito o en forma verbal, y en ese caso se deja constancia por escrito. Es <b>reservada</b>: se maneja cuidando la intimidad de las personas. Cuenta los hechos con el mayor detalle posible: <b>qué pasó, cuándo, dónde, quién lo hizo y quién lo vio</b>. Guarda mensajes o fotos si los hay.","k":"Denunciar es un derecho, y la denuncia es reservada."},{"s":"karin_resguardo","t":"Protección y sin represalias","x":"Al recibir una denuncia, la empresa adopta de inmediato <b>medidas de resguardo</b> para proteger a la persona afectada: separar espacios, cambiar la jornada o dar atención psicológica temprana a través de la <b>ACHS</b>. La investigación interna debe terminar en un plazo máximo de <b>30 días</b>. Están <b>prohibidas las represalias</b> contra quien denuncia o declara como testigo de buena fe."},{"s":"karin_testigo","t":"No seas testigo silencioso","x":"Si ves una situación de acoso o violencia:<ul><li><b>No participes</b> ni te rías, aunque el grupo lo haga.</li><li><b>Acompaña</b> a la persona afectada y pregúntale cómo está.</li><li><b>Oriéntala</b> sobre cómo denunciar.</li><li>Si te citan como testigo, <b>cuenta con la verdad</b> lo que viste.</li></ul>El silencio permite que el maltrato continúe."},{"s":"karin_auto","t":"Autocuidado: la “broma” que daña","x":"Así como la mayoría de los accidentes se relacionan con una acción insegura, el acoso suele empezar con conductas que se normalizan: bromas pesadas, sobrenombres que molestan, reenviar fotos de un compañero al grupo. La decisión segura: <b>parar, no reenviar, borrar, respetar el “no”</b> y avisar. Si a alguien le duele, no es broma, aunque los demás se rían."}],"quiz":[{"s":"karin_intro","v":[{"q":"¿Desde cuándo rige la Ley Karin?","o":["1 de agosto de 2024","1 de enero de 2024","1 de agosto de 2023","1 de febrero de 2025"],"w":"La Ley 21.643 rige desde el 1 de agosto de 2024."},{"q":"La Ley Karin corresponde a la ley número:","o":["21.643","16.744","20.949","21.015"],"w":"Es la Ley 21.643, vigente desde el 1 de agosto de 2024."},{"q":"¿Qué busca la Ley Karin?","o":["Prevenir, investigar y sancionar el acoso y la violencia","Solo sancionar el acoso sexual","Regular las horas extra en temporada","Fijar los límites de carga manual"],"w":"Abarca acoso laboral, acoso sexual y violencia en el trabajo."}]},{"s":"karin_laboral","v":[{"q":"Para que exista acoso laboral, la conducta debe repetirse varias veces.","vf":false,"w":"Falso. Con la Ley Karin basta una sola vez."},{"q":"Un jefe humilla a gritos a un trabajador frente al equipo una sola vez. ¿Puede ser acoso laboral?","o":["Sí, con la Ley Karin basta una vez","No, debe repetirse al menos tres veces","No, solo si hay testigos que firmen","Solo si el trabajador tiene contrato indefinido"],"w":"La ley ya no exige reiteración."},{"q":"¿Cuál es un ejemplo de acoso laboral?","o":["Humillar a un compañero frente al equipo","Pedir que se cumpla el procedimiento","Corregir un error en privado y con calma","Asignar turnos según el contrato"],"w":"El acoso causa menoscabo, maltrato o humillación."}]},{"s":"karin_sexual","v":[{"q":"Un compañero envía mensajes de carácter sexual por celular a una colega que no los quiere. Eso puede ser:","o":["Acoso sexual","Algo privado sin importancia laboral","Violencia de terceros","Solo una falta de educación"],"w":"Son requerimientos sexuales no consentidos, por cualquier medio."},{"q":"Un supervisor hace comentarios sexuales a una temporera; ella le pide que pare y él insiste. Eso es:","o":["Acoso sexual","Un piropo sin importancia","Violencia de terceros","Un simple conflicto entre compañeros"],"w":"Son requerimientos sexuales indebidos y no consentidos."},{"q":"Un mensaje de carácter sexual no consentido enviado por WhatsApp puede ser acoso sexual.","vf":true,"w":"Verdadero. La ley dice “por cualquier medio”, incluido el celular."}]},{"s":"karin_terceros","v":[{"q":"El chofer de un proveedor insulta y amenaza al portero porque lo hizo esperar. Eso es:","o":["Violencia en el trabajo","Algo normal del rubro","Acoso sexual","Acoso laboral entre compañeros"],"w":"La violencia de clientes, proveedores o choferes está cubierta por la ley."},{"q":"Según la Ley Karin, la violencia en el trabajo es la ejercida por:","o":["Terceros, como clientes, proveedores o choferes","Solo la jefatura directa","Solo compañeros del mismo turno","Solo personas de otra planta de la empresa"],"w":"La violencia en el trabajo viene de personas ajenas a la empresa."},{"q":"La Ley Karin no cubre las agresiones de choferes de proveedores, porque no son de la empresa.","vf":false,"w":"Falso. La violencia de terceros también está cubierta y se denuncia."}]},{"s":"karin_denuncia","v":[{"q":"¿Ante quién se puede presentar una denuncia por acoso o violencia?","o":["Ante el empleador o la Inspección del Trabajo","Solo ante Carabineros","Solo ante el Comité Paritario","Solo ante la jefatura directa"],"w":"Ambos canales están disponibles y la denuncia es reservada."},{"q":"¿Cómo se maneja la información de una denuncia?","o":["Es reservada, cuidando la intimidad","Se publica para que todos sepan","Se comenta en la reunión de turno","Solo la conoce la persona denunciada"],"w":"La reserva protege a quien denuncia y a los involucrados."},{"q":"Al denunciar, ¿qué información conviene entregar?","o":["Qué pasó, cuándo, dónde y quién lo vio","Solo el nombre de la persona acusada","Solo cómo te sentiste ese día","Nada; la empresa lo averigua sola"],"w":"Los detalles concretos permiten investigar bien."}]},{"s":"karin_represalia","v":[{"q":"Después de una denuncia, se permite castigar al denunciante si la jefatura no está de acuerdo.","vf":false,"w":"Falso. No se permiten represalias contra quien denuncia o declara."},{"q":"Declaraste como testigo en una investigación y tu jefe te cambia a un peor turno como castigo. Eso es:","o":["Una represalia prohibida por la ley","Una decisión normal de la jefatura","Correcto, por haber declarado","Permitido si avisa con un día"],"w":"Quien denuncia o declara de buena fe está protegido."},{"q":"¿Qué protección tiene quien denuncia de buena fe?","o":["No puede sufrir represalias","Solo si la investigación le da la razón","Solo si denuncia en la Inspección","Ninguna mientras dure la investigación"],"w":"La ley prohíbe represalias contra denunciantes y testigos."}]},{"s":"karin_burla","v":[{"q":"Ves que unos compañeros se burlan de una colega. ¿Cuál es la reacción correcta?","o":["Acompañarla y orientarla sobre cómo denunciar","Reírme para no quedar mal con el grupo","No hacer nada, no es asunto mío","Esperar a ver si se repite"],"w":"No ser testigo silencioso: acompañar y orientar a denunciar."},{"q":"Un grupo se ríe de una colega por su forma de hablar y tú estás ahí. ¿Qué haces?","o":["No me río, la acompaño y le explico cómo denunciar","Me río un poco para no quedar mal","Me voy sin decir nada","Le digo a ella que no se lo tome a mal"],"w":"Reírse o callar permite que el maltrato siga."},{"q":"¿Por qué no hay que quedarse callado al ver burlas contra un compañero?","o":["Porque el silencio permite que el maltrato siga","Porque se gana un bono por denunciar","Porque solo así se evita una multa personal","No importa, si la persona no reclama"],"w":"El silencio también daña."}]},{"s":"karin_protocolo","v":[{"q":"El procedimiento de investigación del acoso y la violencia debe estar en:","o":["El Reglamento Interno","El contrato de trabajo","La guía de despacho","El libro de asistencia"],"w":"Además, el protocolo de prevención es obligatorio (Código del Trabajo, art. 211-A)."},{"q":"¿Qué documento exige el art. 211-A del Código del Trabajo?","o":["Un protocolo de prevención del acoso y la violencia","Un seguro de vida para cada trabajador","Un permiso municipal de funcionamiento","Un certificado de antecedentes"],"w":"El protocolo de prevención es obligatorio para el empleador."},{"q":"¿Tienes derecho a conocer el protocolo de prevención de tu empresa?","o":["Sí, y puedo preguntar a mi jefatura dónde está","No, es un documento interno de gerencia","Solo si presento una denuncia","Solo si soy jefatura"],"w":"Es un derecho de todos los trabajadores."}]},{"s":"karin_auto","v":[{"q":"Un compañero reenvía al grupo una foto burlesca de otro. ¿Qué es lo correcto?","o":["No reenviarla, pedir que la borre y avisar","Reenviarla, porque es solo una broma","Comentarla con risas en el grupo","Guardarla por si sirve después"],"w":"Si a alguien le duele, no es broma. Parar a tiempo protege a todos."},{"q":"Un compañero te pidió no usar un sobrenombre que le molesta. ¿Qué haces?","o":["Lo dejo de usar: si le duele, no es broma","Lo sigo usando, es de cariño","Lo uso solo cuando él no está","Lo uso si los demás se ríen"],"w":"Respetar el “no” es la base del buen trato."},{"q":"¿Cómo suele empezar el acoso en un equipo?","o":["Con bromas pesadas que se normalizan","Siempre con agresiones físicas","Solo cuando llega una jefatura nueva","Con correcciones hechas con respeto"],"w":"Las conductas pequeñas que se aceptan crecen si nadie las para."}]},{"s":"psico_respeto","v":[{"q":"¿De quién es tarea mantener un ambiente de respeto en el trabajo?","o":["De todos los que trabajamos en la empresa","Solo de Recursos Humanos","Solo de las jefaturas","Solo del Comité Paritario"],"w":"El respeto lo construimos entre todos."},{"q":"Además de permitir denunciar, ¿cuál es el objetivo principal de la Ley Karin?","o":["Que todos trabajemos en un ambiente de respeto","Aumentar las multas a los trabajadores","Reemplazar el Reglamento Interno","Que solo Recursos Humanos maneje los conflictos"],"w":"La ley busca prevenir, no solo sancionar."},{"q":"El buen trato en el trabajo también ayuda a prevenir accidentes y enfermedades.","vf":true,"w":"Verdadero. Un ambiente de respeto reduce el estrés y los errores."}]}]},{"id":"maquinas","sec":"planta","title":"Líneas, cintas y máquinas de proceso","thumb":"pe_planta","learn":[{"s":"pe_planta","t":"Las máquinas de nuestras plantas","x":"En la conservera y en la planta de mosqueta trabajamos con <b>cintas transportadoras, cerradoras de latas, llenadoras, peladoras, despalilladoras, picadoras y líneas de selección</b>. Todas tienen partes que giran, aprietan o cortan, y pueden atrapar una mano, una manga o el pelo en un segundo. Solo opera una máquina quien fue <b>capacitado y autorizado</b> para ella."},{"s":"pe_cinta_ok","t":"El resguardo está por algo","x":"Los <b>resguardos</b> (tapas, rejillas, barreras) separan tu cuerpo de las partes en movimiento. <b>Nunca se retiran ni se anulan</b> para trabajar más rápido, ni siquiera “para limpiar al paso”. Antes de partir la línea, revisa que los resguardos estén puestos y la parada de emergencia funcione. Si falta uno o está suelto, la máquina no se usa y se avisa a la jefatura.","k":"Sin resguardo, no se opera."},{"s":"pe_cinta_mal","t":"No intervengas equipos en movimiento","x":"Seleccionar fruta o latas desde la cinta en movimiento es parte del trabajo. Lo que <b>nunca</b> se hace es <b>intervenir</b> la máquina en movimiento: una lata trabada, una fruta atascada en un rodillo o algo que cayó dentro no se saca con la mano, un palo ni un guante grueso con la máquina andando. Tampoco se pasa por encima ni por debajo de una cinta."},{"s":"pe_parada","t":"La parada de emergencia","x":"Conoce dónde están los <b>botones o cordones de parada de emergencia</b> de tu línea y úsalos sin dudar si alguien queda atrapado o ves que está por ocurrir. <b>Primero se detiene la máquina</b>, después se ayuda: tirar de una persona atrapada con la máquina andando agrava la lesión. Nunca tapes las paradas con cajas ni las bloquees."},{"s":"loose","t":"Nada suelto","x":"<ul><li>Ropa ajustada y mangas cerradas.</li><li>Pelo completamente <b>dentro de la cofia</b>; un pañuelo suelto no basta.</li><li>Sin anillos, pulseras, relojes, collares ni audífonos colgando.</li><li>Guantes rotos o sueltos no se usan cerca de rodillos.</li></ul>Lo que cuelga se enreda primero y arrastra la mano, el brazo o la cabeza después."},{"s":"pe_bloqueo","t":"Limpiar o destrabar: máquina detenida y bloqueada","x":"Para limpiar, sanitizar, destrabar o reparar:<ul><li><b>Detén la máquina</b> con su interruptor o la parada de emergencia.</li><li>Espera que <b>todo deje de girar</b>.</li><li>Deja puesto el <b>bloqueo propio de la máquina</b> (parada enclavada, selector o seguro).</li><li><b>Avisa</b> que estás trabajando en ella.</li></ul>Solo quien la detuvo la vuelve a partir, cuando todos estén fuera de peligro.","k":"Detenida, bloqueada y avisada antes de meter las manos."},{"s":"pe_cerradora","t":"Cerradoras y llenadoras","x":"La cerradora trabaja a alta velocidad y con mucha fuerza. Solo la ajusta o repara <b>personal de mantención autorizado</b>, con la máquina detenida y bloqueada. Si una lata se atasca o la máquina suena distinto, <b>detén y avisa</b>; no la ajustes tú. Cuidado también con los <b>bordes de tapas y latas</b>: cortan como un cuchillo. Si la zona está señalizada, usa protector auditivo."},{"s":"pe_autocuidado","t":"Autocuidado: “es un segundo”","x":"La frase más repetida antes de un atrapamiento es <b>“es un segundo, no vale la pena parar”</b>. Parar la línea cuesta minutos; una mano no se recupera. La decisión segura: <b>detén, bloquea y avisa</b>. Si encuentras una máquina detenida con su bloqueo puesto, no la partas: alguien puede estar trabajando en ella. Avisa los resguardos sueltos y las paradas que no funcionan."}],"quiz":[{"s":"pe_cinta_ok","v":[{"q":"¿En qué condición se puede operar una cinta o línea?","o":["Con resguardos puestos y parada operativa","Sin resguardo si el operador tiene experiencia","Con la parada tapada para que nadie la toque","Con el resguardo abierto para limpiar al paso"],"w":"Los resguardos y la parada de emergencia deben estar siempre operativos."},{"q":"Antes de partir la línea, ¿qué revisas?","o":["Resguardos puestos y parada de emergencia funcionando","Solo que la cinta esté limpia","Solo que haya producto suficiente","Que el selector esté en máxima velocidad"],"w":"Sin resguardo o sin parada que funcione, la máquina no se usa."},{"q":"¿Para qué sirven los resguardos de una máquina?","o":["Separan el cuerpo de las partes en movimiento","Hacen que la máquina funcione más rápido","Protegen la máquina del agua del lavado","Solo sirven para cumplir con la fiscalización"],"w":"El resguardo impide que la mano llegue a la zona de atrapamiento."}]},{"s":"pe_cinta_mal","v":[{"q":"Se traba una lata en la cinta. ¿Qué haces?","o":["Detengo, bloqueo y recién ahí la saco","La saco rápido con la mano","La empujo con un palo con la cinta andando","Bajo la velocidad y la saco"],"w":"Nunca con la máquina en marcha: se detiene y se bloquea."},{"q":"Un frasco quedó atascado junto a un rodillo de la línea. ¿Qué es lo correcto?","o":["Detener, bloquear y avisar antes de sacarlo","Sacarlo con guantes gruesos con la línea andando","Golpear el rodillo para que se suelte","Esperar a que la máquina lo expulse sola"],"w":"Los atrapamientos ocurren justamente “para no parar la línea”."},{"q":"¿Qué diferencia hay entre seleccionar en la cinta e intervenirla?","o":["Seleccionar es parte del trabajo; intervenir exige detener y bloquear","Ninguna: ambas se hacen con la cinta andando","Intervenir se puede si es solo un segundo","Seleccionar exige bloquear la máquina"],"w":"Destrabar, limpiar o reparar se hace siempre con la máquina detenida y bloqueada."}]},{"s":"pe_bloqueo","v":[{"q":"Si una máquina se detuvo, ya es seguro meter las manos aunque no esté bloqueada.","vf":false,"w":"Falso. Puede volver a partir sola o porque otro la enciende: primero se bloquea."},{"q":"Una máquina se detuvo sola por un atasco. Antes de meter las manos, ¿qué falta?","o":["Dejar puesto su bloqueo y avisar","Nada, si está detenida ya es segura","Solo esperar diez segundos","Solo ponerse guantes más gruesos"],"w":"Detenida no es lo mismo que bloqueada."},{"q":"¿Cuál es el orden correcto para limpiar una máquina?","o":["Detener, esperar que pare, bloquear y avisar","Avisar, limpiar y después detener","Bloquear, limpiar y esperar que pare","Detener y limpiar mientras se frena"],"w":"Cada paso evita que la máquina se mueva con tus manos dentro."}]},{"s":"pe_bloqueo","v":[{"q":"¿Quién vuelve a partir una máquina que se detuvo para limpiarla o destrabarla?","o":["Quien la detuvo, cuando todos estén fuera de peligro","El supervisor, apenas llegue","Cualquier operador de la línea","El primero que note que está parada"],"w":"Quien la detuvo sabe si hay alguien expuesto."},{"q":"Encuentras una máquina detenida con la parada enclavada y nadie a la vista. ¿Qué haces?","o":["No la parto: puede haber alguien en ella","La parto para no atrasar la línea","La parto después de tocar la bocina","La parto si el selector está en automático"],"w":"El bloqueo indica que alguien está trabajando: solo lo retira quien lo puso."},{"q":"Terminaste de limpiar una cinta. ¿Cuándo la vuelves a partir?","o":["Cuando todos estén fuera de peligro y avisados","Apenas saco mis manos de la cinta","Cuando el supervisor me lo pida a gritos","Cuando llegue el producto a la línea"],"w":"Antes de partir, nadie puede estar expuesto."}]},{"s":"pe_parada","v":[{"q":"Un compañero queda con la manga atrapada en un rodillo. ¿Qué haces primero?","o":["Presiono la parada de emergencia","Tiro de él con fuerza para soltarlo","Voy a buscar al supervisor","Corto la manga con un cuchillo"],"w":"Primero se detiene la máquina, después se ayuda y se avisa."},{"q":"¿Qué está prohibido hacer con una parada de emergencia?","o":["Taparla con cajas o bloquearla","Usarla cuando ves un peligro","Saber dónde está en tu línea","Avisar si no funciona"],"w":"La parada debe estar siempre visible y al alcance."},{"q":"Ves que un compañero está por meter la mano en un rodillo en marcha. ¿Qué haces?","o":["Uso la parada de emergencia sin dudar","Le grito desde lejos y sigo","Voy a buscar al supervisor","Espero a ver si alcanza a sacarla"],"w":"La parada se usa ante un peligro, sin esperar."}]},{"s":"loose","v":[{"q":"Una trabajadora de la línea lleva el pelo largo bajo un pañuelo suelto. ¿Qué debe hacer?","o":["Tomarse el pelo completo dentro de la cofia","Nada, el pañuelo basta","Echarse el pelo hacia atrás","Trabajar un poco más lejos de la cinta"],"w":"El pelo y los pañuelos sueltos se enredan en los rodillos."},{"q":"¿Qué se debe sacar antes de trabajar en la línea?","o":["Anillos, pulseras y collares","Solo los relojes grandes","Nada, si las joyas son pequeñas","Solo los aros largos"],"w":"Cualquier joya puede engancharse y arrastrar la mano."},{"q":"Un pañuelo o el pelo suelto puede ser arrastrado por un rodillo en marcha.","vf":true,"w":"Verdadero. Lo que cuelga se enreda primero."}]},{"s":"pe_cerradora","v":[{"q":"La cerradora se desajustó. ¿Quién la arregla?","o":["Mantención autorizada, con la máquina bloqueada","El operador con más experiencia","Cualquiera que sepa algo de mecánica","El supervisor, con la máquina andando"],"w":"Solo mantención autorizada y con bloqueo."},{"q":"Una lata se atasca en la cerradora. ¿Qué haces?","o":["Detengo la máquina y aviso","La saco rápido con la mano","Ajusto yo mismo la cerradora","Sigo y la saco al final del turno"],"w":"La cerradora tiene mucha fuerza: se detiene y se avisa."},{"q":"Además del atrapamiento, ¿qué otro peligro tienen tapas y latas en la cerradora?","o":["Sus bordes cortan","Emiten gases tóxicos","Pueden explotar al cerrarse","Contaminan la piel con óxido"],"w":"Los bordes de tapas y latas cortan como un cuchillo."}]},{"s":"pe_cinta_mal","v":[{"q":"Retirar el resguardo para limpiar más rápido es una condición segura.","vf":false,"w":"Falso. Es una acción insegura: el resguardo nunca se anula."},{"q":"Un compañero retira el resguardo para limpiar más rápido. Eso es:","o":["Una acción insegura: el resguardo no se anula","Correcto si lo vuelve a poner después","Correcto si la línea va atrasada","Aceptable si tiene experiencia"],"w":"Sin resguardo, la mano llega a la zona de atrapamiento."},{"q":"Falta el resguardo de un rodillo y la línea está atrasada. ¿Qué haces?","o":["No opero y aviso a mi jefatura","Opero con cuidado hasta que lo repongan","Opero si un compañero me vigila","Opero a menor velocidad"],"w":"Sin resguardo no se opera, aunque haya apuro."}]}]},{"id":"cortes","sec":"planta","title":"Cuchillos, latas y cortes","thumb":"pe_guante","learn":[{"s":"pe_guante","t":"Los cortes, el accidente más común","x":"En una conservera los cortes con <b>cuchillos, bordes de latas, tapas, vidrio y flejes</b> son de los accidentes más frecuentes. Casi todos ocurren en la <b>mano que sujeta</b> el producto, no en la que corta: mantenla siempre <b>fuera de la línea de corte</b>. Las prisas, el cansancio y conversar mientras cortas multiplican el riesgo.","k":"La mano que sujeta, siempre fuera de la línea de corte."},{"s":"pe_epp_revisa","t":"Usa tus guantes y revísalos","x":"Si trabajas con cuchillo, latas o vidrio, usa los <b>guantes indicados para tu tarea</b>, por ejemplo anticorte. La empresa los entrega <b>sin costo</b> y su uso es obligatorio. <b>Revísalos antes de cada turno</b>: si están cortados, rotos o gastados, pide recambio antes de empezar. Un guante parchado con cinta o uno roto ya no protege."},{"s":"pe_cuchillo_ok","t":"Corta alejando el filo","x":"<ul><li>Corta <b>hacia afuera</b>, alejando el filo del cuerpo.</li><li>Sobre una tabla o mesa estable, <b>nunca en el aire</b> ni sobre la mano.</li><li>Mantén la mano que sujeta <b>fuera de la línea de corte</b>.</li><li>Concéntrate: no cortes mirando a otro lado ni conversando.</li><li>No gesticules con el cuchillo en la mano.</li></ul>"},{"s":"pe_cuchillo_guarda","t":"Cuchillo afilado y en su lugar","x":"Un cuchillo <b>sin filo</b> es más peligroso: obliga a hacer más fuerza y se resbala. Pide que lo afilen; no lo afiles en el borde de la mesa. Cuando no lo uses, <b>guárdalo con su protección</b>: en su funda o en el porta cuchillos. Nunca suelto entre la fruta, en el bolsillo ni bajo el agua de un lavadero, donde nadie lo ve."},{"s":"pe_cuchillo_cae","t":"Si se cae, déjalo caer","x":"Nunca intentes <b>atrapar un cuchillo que se cae</b>, ni frenarlo con el pie: es muy fácil tomarlo por el filo. Aléjate, deja que llegue al piso y recógelo después <b>por el mango</b>. Camina con el cuchillo apuntando al piso y pegado al cuerpo, y nunca lo entregues de mano en mano: déjalo sobre la mesa para que el otro lo tome."},{"s":"pe_latas","t":"Latas, tapas y vidrio","x":"Los bordes de latas, las tapas y los frascos rotos cortan como un cuchillo. Usa <b>guantes</b> al manipularlos. Los restos se retiran con <b>escobillón y pala, nunca con la mano</b>, aunque tengas guantes, y se botan en el <b>contenedor indicado</b>, no en el basurero común ni bajo la cinta. Si se quiebra un frasco en la línea, avisa: el producto cercano puede tener vidrio."},{"s":"accidente_avisa","t":"Si te cortas","x":"Presiona la herida con un paño limpio, <b>avisa de inmediato</b> a tu jefatura y retira el producto que pudo contaminarse con sangre. Aunque parezca leve, se registra y se atiende: un corte mal tratado se infecta, y como accidente del trabajo lo cubre la <b>ACHS</b>. Si el corte es profundo o no deja de sangrar, se llama al <b>1404</b> de la ACHS.","k":"Todo corte se avisa de inmediato, aunque sea pequeño."}],"quiz":[{"s":"pe_cuchillo_mal","v":[{"q":"¿Cuál es la forma segura de cortar?","o":["Hacia afuera, alejando el filo del cuerpo","Hacia el cuerpo, para tener más control","En el aire, sosteniendo la fruta en la mano","Rápido, para que el filo no se trabe"],"w":"Cortar hacia afuera y sobre la mesa aleja el filo del cuerpo."},{"q":"Ves a un compañero cortando hacia su cuerpo y sin guantes. ¿Qué está mal?","o":["Corta hacia el cuerpo y sin protección","Nada, si tiene experiencia","Solo que el cuchillo es muy grande","Solo que la mesa está baja"],"w":"El filo debe ir lejos del cuerpo y con los guantes indicados."},{"q":"Cortar el producto sosteniéndolo en el aire es seguro si el cuchillo está afilado.","vf":false,"w":"Falso. Se corta siempre sobre una tabla o mesa estable."}]},{"s":"pe_cuchillo_cae","v":[{"q":"Se te resbala el cuchillo de la mano. ¿Qué haces?","o":["Me alejo y lo dejo caer","Lo atrapo en el aire","Lo freno con el pie","Lo agarro del mango al vuelo"],"w":"Nunca se atrapa un cuchillo que cae."},{"q":"Un cuchillo resbala de la mesa. ¿Cuándo lo recoges?","o":["Cuando ya está en el piso, por el mango","Antes de que toque el piso","Cuando un compañero lo empuja hacia mí","Por la hoja, para no ensuciar el mango"],"w":"Se deja caer y se recoge por el mango."},{"q":"¿Por qué no se debe atrapar un cuchillo que cae?","o":["Porque es fácil tomarlo por el filo","Porque se puede quebrar la hoja","Porque se contamina con la mano","Porque lo prohíbe el área de calidad"],"w":"Al atraparlo en el aire, la mano suele cerrarse sobre el filo."}]},{"s":"pe_cuchillo_ok","v":[{"q":"¿En qué mano ocurren casi todos los cortes con cuchillo?","o":["En la mano que sujeta el producto","En la mano que sostiene el cuchillo","En ambas por igual","En ninguna, se cortan los antebrazos"],"w":"Por eso la mano que sujeta se mantiene fuera de la línea de corte."},{"q":"¿Dónde debe estar la mano que sujeta la fruta al cortar?","o":["Fuera de la línea de corte","Justo delante del filo, para guiarlo","Bajo el producto, sosteniéndolo en el aire","Sobre el filo, para apretar"],"w":"Si el cuchillo resbala, no debe encontrar tu mano en su camino."},{"q":"Al cortar, ¿qué mano corre más riesgo de cortarse?","o":["La que sujeta el producto","La que sostiene el cuchillo","La que descansa sobre la mesa","Ninguna si el cuchillo es bueno"],"w":"La mano que sujeta queda cerca del filo: debe estar fuera de su línea."}]},{"s":"pe_cuchillo_guarda","v":[{"q":"Un cuchillo sin filo es más seguro porque corta menos.","vf":false,"w":"Falso. Obliga a hacer más fuerza y se resbala."},{"q":"Tu cuchillo perdió el filo. ¿Qué haces?","o":["Pido que lo afilen","Sigo usándolo con más fuerza","Lo afilo en el borde de la mesa","Lo cambio por el de un compañero"],"w":"Un cuchillo sin filo se resbala: se pide afilarlo."},{"q":"¿Por qué un cuchillo sin filo es peligroso?","o":["Obliga a hacer más fuerza y se resbala","Porque corta más profundo","Porque se oxida más rápido","Porque se quiebra con facilidad"],"w":"La fuerza extra hace que el cuchillo se escape hacia la mano."}]},{"s":"pe_latas","v":[{"q":"Se quebró un frasco en la línea. ¿Cómo recoges los vidrios?","o":["Con escobillón y pala, al contenedor indicado","Con la mano, rápido y con cuidado","Los empujo bajo la cinta","Con la mano, pero con guantes puestos"],"w":"Los restos cortantes nunca se recogen con la mano."},{"q":"Hay bordes de latas y tapas rotas sobre la mesa. ¿Cómo los retiras?","o":["Con escobillón y pala, nunca con la mano","Con la mano, juntándolos en un montón","Con un paño, arrastrándolos al piso","Con la mano si uso guantes de látex"],"w":"Ni con guantes: los restos cortantes se retiran con escobillón y pala."},{"q":"¿Dónde se botan los restos de vidrio y latas?","o":["En el contenedor indicado","En el basurero común de la línea","Bajo la cinta, para barrer después","En una caja de cartón abierta"],"w":"En el contenedor indicado no cortan a quien retira la basura."}]},{"s":"accidente_avisa","v":[{"q":"Te hiciste un corte pequeño. ¿Qué haces?","o":["Presiono, aviso de inmediato y se registra","Sigo trabajando sin decir nada","Me pongo un guante encima y sigo","Me lavo y aviso al final del turno"],"w":"Todo corte se avisa: queda cubierto y se evita una infección."},{"q":"¿Por qué se avisa un corte aunque sea leve?","o":["Se atiende, se registra y se evita una infección","Solo para que no te descuenten el día","Es una formalidad sin efecto","Para que te cambien de puesto"],"w":"Un corte mal tratado se infecta; avisado, lo cubre la ACHS."},{"q":"Un compañero se cortó y sangra cerca de la fruta. ¿Qué es lo correcto?","o":["Presionar con paño limpio, avisar y retirar el producto","Mandarlo a lavarse y seguir con la fruta","Ponerle cinta adhesiva y seguir","Lavar la fruta y seguir la producción"],"w":"Se atiende la herida, se avisa y se retira el producto que pudo contaminarse."}]},{"s":"pe_epp_revisa","v":[{"q":"Al empezar el turno ves que tu guante tiene un corte. ¿Qué haces?","o":["Pido recambio antes de trabajar","Lo uso igual hasta el almuerzo","Lo parcho con cinta adhesiva","Trabajo sin guante para no atrasarme"],"w":"Un guante roto ya no protege: se cambia antes de empezar."},{"q":"¿Cuándo se revisan los guantes de trabajo?","o":["Antes de cada turno","Una vez por semana","Solo cuando se rompen del todo","Solo cuando lo pide el supervisor"],"w":"Revisarlos antes de empezar evita trabajar sin protección."},{"q":"La empresa debe entregar los guantes de trabajo sin costo para el trabajador.","vf":true,"w":"Verdadero. El EPP es gratis y su uso es obligatorio."}]}]},{"id":"pisos","sec":"planta","title":"Pisos mojados: resbalones y caídas","thumb":"pe_piso","learn":[{"s":"pe_resbalon","t":"El piso se moja solo por el lavado","x":"En una planta de alimentos el piso se moja <b>cuando se lava y sanitiza</b>. Fuera de eso, el piso de trabajo debe estar <b>seco y limpio</b>. Agua, jugo o aceite fuera del lavado (una fuga, un derrame o una manguera abierta) es una <b>condición insegura</b> que se corrige y se avisa. Las caídas al mismo nivel provocan esguinces, fracturas de muñeca y golpes en la cabeza.","k":"Piso húmedo solo durante el lavado; fuera de eso, seco."},{"s":"pe_botas","t":"Calzado antideslizante","x":"Usa las <b>botas o zapatos de seguridad antideslizantes</b> que te entrega la empresa sin costo. Revisa la suela antes del turno: si está <b>lisa, gastada o despegada</b>, pide recambio de inmediato, porque ya no agarra en el piso húmedo y puedes tropezar. Nunca trabajes en la línea con zapatillas ni con botas propias que no sean de seguridad."},{"s":"pe_piso","t":"Camina, no corras","x":"<ul><li><b>Camina</b> siempre, aunque vayas atrasado o te llamen con urgencia: correr es la forma más rápida de caer.</li><li>Mira dónde pisas y usa los <b>pasillos</b>; nunca pases por encima ni por debajo de una cinta.</li><li>Usa los <b>pasamanos</b> en escaleras y pasarelas.</li><li>En piso mojado, pasos cortos y sin cargar más de lo que te deja ver el piso.</li></ul>","k":"En la planta no se corre, aunque estés apurado."},{"s":"wetFloor","t":"Señaliza, seca y avisa","x":"Si ves agua, jugo o restos en el piso <b>fuera del lavado</b>, en este orden:<ul><li><b>Señaliza</b> con el letrero o cono para que nadie pase.</li><li><b>Seca o barre</b> el derrame.</li><li>Busca <b>de dónde viene</b>: fuga, manguera o derrame.</li></ul>Si no puedes corregirlo, por ejemplo porque la fuga sigue, deja señalizado y <b>avisa de inmediato</b> a tu jefatura. Cubrirlo con cartones no lo soluciona."},{"s":"orden_trip","t":"Latas, restos y mangueras: tropiezos","x":"Latas, tapas, restos de fruta, bandejas o mangueras en el pasillo provocan <b>tropiezos y caídas</b>, sobre todo cuando cargas cajas. Retira los restos con <b>escobillón y pala</b> apenas los veas, sin esperar el aseo del final del turno. <b>Enrolla las mangueras</b> después de usarlas y mantén <b>rejillas y tapas de canaletas</b> siempre en su lugar. Si no puedes retirarlo, señaliza y avisa."},{"s":"pe_espuma","t":"Durante el aseo","x":"Al lavar y sanitizar, con la línea detenida, el piso queda con agua y espuma, muy resbaladizo. <b>Señaliza la zona</b> y no dejes pasar a otros. Avanza <b>de adentro hacia afuera</b>, para no quedar atrapado ni pisar lo ya lavado. <b>Terminado el lavado, el piso se seca</b> o se deja escurrir antes de volver a trabajar, y las mangueras se enrollan."}],"quiz":[{"s":"pe_piso","v":[{"q":"Vas atrasado a tu puesto y el pasillo está mojado. ¿Qué haces?","o":["Camino sin correr, mirando dónde piso","Corro con cuidado para llegar a la hora","Paso por encima de la cinta para acortar","Corro por el borde seco del pasillo"],"w":"Llegar un minuto tarde es mejor que una caída."},{"q":"Te llaman con urgencia desde otra línea y el piso está húmedo. ¿Qué haces?","o":["Voy caminando con pasos cortos","Voy corriendo porque es urgente","Voy trotando por la orilla del pasillo","Cruzo por debajo de la cinta para llegar antes"],"w":"Ni la urgencia justifica correr en la planta."},{"q":"En la planta se puede correr si uno va apurado y el piso está seco.","vf":false,"w":"Falso. En la planta siempre se camina."}]},{"s":"pe_botas","v":[{"q":"La suela de tus botas está lisa. ¿Qué haces?","o":["Pido recambio","Las sigo usando con más cuidado","Uso zapatillas mientras tanto","Les hago surcos con un cuchillo"],"w":"Una suela gastada ya no agarra en el piso húmedo."},{"q":"¿Qué calzado se usa en la línea?","o":["Botas o zapatos de seguridad antideslizantes","Zapatillas con buena suela","Cualquier bota de goma propia","Zapatos cerrados de cuero"],"w":"Solo el calzado de seguridad antideslizante entregado por la empresa."},{"q":"Una de tus botas tiene la suela despegada en la punta. ¿Qué haces?","o":["Pido recambio: puedo tropezar y resbalar","La pego con cinta y sigo","La uso hasta fin de mes","La uso solo en las zonas secas"],"w":"El calzado dañado se cambia de inmediato."}]},{"s":"orden_trip","v":[{"q":"Hay latas y restos de fruta en el pasillo de la línea. ¿Qué haces?","o":["Los retiro con escobillón y pala","Paso por el lado con cuidado","Los empujo bajo la cinta","Espero el aseo del final del turno"],"w":"Los restos en el piso provocan tropiezos: se retiran apenas se ven."},{"q":"Vas cargando una caja y ves latas tiradas en tu camino. ¿Qué haces?","o":["Dejo la caja, retiro las latas y sigo","Paso por encima de las latas con cuidado","Las empujo con el pie hacia un lado","Sigo y aviso al final del turno"],"w":"Con la caja tapando la vista, una lata en el piso es una caída segura."},{"q":"¿Por qué no se deben dejar latas o restos en el piso?","o":["Provocan tropiezos y caídas","Solo porque se ve desordenado","Solo porque atraen insectos","Porque lo revisa calidad"],"w":"Son una condición insegura que causa caídas al mismo nivel."}]},{"s":"pe_espuma","v":[{"q":"Estás sanitizando el piso. ¿Qué haces con la zona?","o":["La señalizo y no dejo pasar hasta que escurra","Dejo pasar si caminan despacio","Señalizo solo si hay mucha espuma","Nada: todos saben que es hora de aseo"],"w":"Con agua y espuma el piso queda muy resbaladizo."},{"q":"¿En qué dirección avanzas al lavar el piso de un sector?","o":["De adentro hacia afuera","De afuera hacia adentro","En círculos desde el centro","Da lo mismo si queda limpio"],"w":"Así no quedas atrapado ni pisas lo ya lavado."},{"q":"Terminó el lavado y hay que volver a trabajar. ¿Qué se hace con el piso?","o":["Se seca o se deja escurrir antes de trabajar","Se trabaja de inmediato; se seca solo","Se le echa más detergente","Se cubre con cartones"],"w":"Después del lavado, el piso de trabajo vuelve a estar seco."}]},{"s":"pe_resbalon","v":[{"q":"Fuera del lavado, el piso de la línea debe estar:","o":["Seco y limpio","Siempre húmedo: es normal en alimentos","Con una capa de agua para enfriar","Con cartones para absorber el agua"],"w":"El piso solo se moja por el lavado."},{"q":"Agua en el piso fuera del horario de lavado es una condición insegura.","vf":true,"w":"Verdadero. Indica una fuga, derrame o manguera abierta que se corrige y se avisa."},{"q":"Ves agua en el piso a media mañana, fuera del lavado. ¿Qué significa?","o":["Hay una fuga, derrame o manguera abierta","Es normal en una planta de alimentos","Que pronto empieza el lavado","Que el piso se está enfriando"],"w":"Fuera del lavado, el agua en el piso es una condición insegura."}]},{"s":"wetFloor","v":[{"q":"Ves un derrame de jugo en el pasillo. ¿Qué haces primero?","o":["Lo señalizo con letrero o cono","Lo esquivo y sigo a mi puesto","Lo tapo con cartones","Espero que lo vea alguien de aseo"],"w":"Primero se señaliza para que nadie resbale, luego se seca y se busca el origen."},{"q":"¿Cuál es el orden correcto ante agua en el piso fuera del lavado?","o":["Señalizar, secar y buscar de dónde viene","Secar y avisar al final del turno","Buscar la fuga y después señalizar","Avisar y esperar sin señalizar"],"w":"Señalizar primero protege a los demás mientras corriges."},{"q":"No puedes secar el piso porque una manguera sigue perdiendo agua. ¿Qué haces?","o":["Dejo señalizado y aviso de inmediato","Lo dejo; alguien lo verá","Lo seco una vez y me voy","Lo cubro con cartones"],"w":"Si no puedes corregirlo, se señaliza y se avisa de inmediato."}]},{"s":"pe_resbalon","v":[{"q":"¿Qué lesiones pueden provocar las caídas al mismo nivel?","o":["Esguinces, fracturas de muñeca y golpes en la cabeza","Solo moretones leves","Solo cortes en las manos","Lesiones solo en personas mayores"],"w":"Una caída al mismo nivel puede ser grave."},{"q":"¿Por qué un resbalón en el piso mojado puede ser grave aunque no haya altura?","o":["Puede fracturar una muñeca o golpear la cabeza","No es grave porque no hay altura","Solo es grave si llevas un cuchillo","Solo es grave en la cámara de frío"],"w":"Al caer, se apoya la mano o se golpea la cabeza contra el piso."},{"q":"Una caída al mismo nivel:","o":["Puede causar fracturas y golpes en la cabeza","Nunca causa lesiones graves","Solo causa lesiones si hay escaleras","Solo afecta a quienes usan zapatillas"],"w":"Por eso el piso se mantiene seco y se camina sin correr."}]}]},{"id":"calor_vapor","sec":"planta","title":"Vapor, autoclaves y superficies calientes","thumb":"pe_autoclave","learn":[{"s":"pe_autoclave","t":"Calor en el proceso","x":"En {EMP} cocemos, esterilizamos y secamos con <b>vapor, agua caliente y aire caliente</b>: autoclaves, marmitas, escaldadores, túneles y hornos. El vapor a presión supera los <b>100 °C</b> y, al condensarse sobre la piel, entrega mucho más calor que el agua hirviendo. Por eso <b>una quemadura con vapor es más grave</b>. Cerca de la fuga, el vapor puede ser casi invisible."},{"s":"pe_vapor_mal","t":"Autoclaves: solo operador certificado","x":"Los autoclaves trabajan con vapor a presión. Según el <b>DS 10</b>, solo los opera quien tiene la <b>certificación de competencia de la SEREMI de Salud</b> y la autorización de {EMP}. Si no eres operador, no abres tapas, no mueves válvulas ni cambias programas, aunque lo hayas visto hacer muchas veces. Si el operador no está, esperas o avisas a la jefatura. Abrir con presión puede lanzar la tapa o una nube de vapor.","k":"Si no tienes certificación SEREMI, no operes un autoclave."},{"s":"pe_autoclave_ok","t":"Antes de abrir un autoclave","x":"El operador sigue el procedimiento:<ul><li>Termina el ciclo completo: el tiempo cumplido no basta.</li><li>Confirma que el <b>manómetro marca cero</b>.</li><li>Hace la <b>purga</b> según el procedimiento.</li><li>Abre de a poco, con la cara y el cuerpo al costado de la tapa.</li></ul>Si el manómetro no baja a cero o la tapa se traba, no se fuerza ni se golpea: se avisa a la jefatura.","k":"Nunca abras un autoclave sin manómetro en cero y purga hecha."},{"s":"pe_marmita","t":"Marmitas y líquidos calientes","x":"<ul><li>Revisa una marmita abierta <b>desde el costado</b>, nunca inclinado sobre ella.</li><li>Usa <b>guantes para calor y delantal</b> al vaciar o trasvasijar.</li><li>Traslada recipientes calientes con ayuda o en carro, caminando, y sin llenarlos hasta el borde.</li><li>Avisa si hay piso mojado o con grasa cerca: un resbalón con líquido caliente es doble accidente.</li></ul>"},{"s":"pe_fuga_vapor","t":"Cañerías y superficies calientes","x":"Cañerías de vapor, tapas y paredes de equipos pueden estar sobre <b>100 °C</b> aunque no salga vapor ni se note a distancia. No te apoyes, no dejes ropa secándose sobre ellas y respeta la señalización. Avisa si una cañería perdió su aislación. Ante una fuga de vapor: <b>aléjate, avisa a la jefatura y evita que otros pasen</b>. Nunca la tapes con un trapo ni con la mano: aunque parezca pequeña, quema gravemente."},{"s":"pe_calor","t":"Estrés por calor","x":"Cerca de hornos, túneles y cocedores el ambiente se calienta. <b>Toma agua seguido durante el turno, aunque no tengas sed</b>, y haz las pausas. Señales de alerta: <b>mareo, dolor de cabeza, náuseas, calambres</b>. Si te pasa, avisa, toma agua y recupérate en un lugar fresco. Si un compañero está confundido o con la piel muy caliente: llévalo a un lugar fresco, avisa y pide ayuda; si empeora, llama al <b>131</b>."},{"s":"pe_quemadura","t":"Si te quemas","x":"<ul><li>Enfría la zona con <b>agua corriente fresca de 10 a 20 minutos</b>.</li><li>Saca anillos o reloj antes de que se hinche.</li><li>No pongas pasta de dientes, aceite, cremas ni hielo.</li><li><b>No revientes las ampollas</b>: cúbrelas con un paño limpio.</li><li>Avisa a tu jefatura y acude a la <b>ACHS</b> (fono 1404).</li></ul>"}],"quiz":[{"s":"pe_vapor_mal","v":[{"q":"¿Cuándo se puede abrir la tapa de un autoclave?","o":["Con el manómetro en cero y la purga hecha","Apenas se cumple el tiempo del ciclo","Cuando deja de salir vapor por la válvula","Cuando el termómetro baja de 100 °C"],"w":"Solo sin presión: con el manómetro en cero y la purga según el procedimiento."},{"q":"El ciclo terminó, pero el manómetro todavía marca presión. ¿Qué corresponde?","o":["Esperar que marque cero y purgar según el procedimiento","Abrir la tapa de a poco para que el vapor salga despacio","Abrir parado al costado de la tapa, con guantes para calor","Golpear el manómetro por si la aguja quedó pegada"],"w":"El tiempo cumplido no basta: con presión, la tapa o el vapor pueden lanzarse."},{"q":"Si el tiempo de esterilización ya se cumplió, se puede abrir el autoclave aunque el manómetro marque algo de presión.","vf":false,"w":"Falso. Se abre solo con el manómetro en cero y la purga hecha."}]},{"s":"pe_autoclave","v":[{"q":"¿Quién puede operar un autoclave?","o":["Quien tiene certificación SEREMI y autorización de la empresa","Cualquiera que haya visto el procedimiento varias veces","El supervisor de turno, aunque no tenga la certificación","El trabajador con más antigüedad en la sala de autoclaves"],"w":"El DS 10 exige certificación de competencia de la SEREMI de Salud."},{"q":"El operador de autoclaves no está y el ciclo terminó. Un compañero te pide abrirlo. No tienes certificación. ¿Qué haces?","o":["No lo abro: espero al operador o aviso a la jefatura","Lo abro siguiendo paso a paso lo que he visto hacer","Lo abro solo si el manómetro ya está marcando cero","Abro primero la purga para adelantarle el trabajo"],"w":"Sin certificación no se opera, aunque parezca simple."},{"q":"¿Qué norma exige que los operadores de autoclaves tengan certificación de la SEREMI de Salud?","o":["El DS 10","El DS 594","La Ley 20.949","La Ley 21.643"],"w":"El DS 10 regula calderas, autoclaves y equipos que usan vapor."}]},{"s":"pe_autoclave","v":[{"q":"¿Por qué una quemadura con vapor suele ser más grave que con agua hirviendo?","o":["Porque al condensarse en la piel entrega mucho más calor","Porque el vapor arrastra químicos de la caldera hacia la piel","Porque el agua hirviendo se enfría antes de tocarte","Porque el vapor solo quema cuando sale con presión muy alta"],"w":"El vapor entrega su calor al condensarse sobre la piel."},{"q":"Comparada con una quemadura con agua hirviendo, una con vapor es:","o":["Más grave, porque el vapor entrega más calor","Igual, porque ambos están a 100 °C","Menos grave, porque el vapor es aire húmedo","Menos grave, porque se seca rápido en la piel"],"w":"El vapor quema más que el agua hirviendo."},{"q":"Una quemadura con vapor es menos grave que una con agua hirviendo.","vf":false,"w":"Falso. El vapor entrega más calor y quema más."}]},{"s":"pe_quemadura","v":[{"q":"Te quemas el antebrazo con agua de una marmita. ¿Qué haces primero?","o":["Agua corriente fresca de 10 a 20 minutos y aviso","Hielo directo sobre la piel para calmar el dolor","Pasta de dientes o aceite sobre la zona quemada","Reviento la ampolla con cuidado para que drene"],"w":"El agua fresca baja el calor de la piel; lo demás daña o infecta."},{"q":"¿Cuánto tiempo se enfría una quemadura con agua corriente fresca?","o":["Entre 10 y 20 minutos","Unos segundos, hasta que deje de arder","Entre 1 y 2 minutos","Más de una hora sin parar"],"w":"De 10 a 20 minutos y luego atención en la ACHS."},{"q":"A un compañero le sale una ampolla por quemadura. ¿Qué es lo correcto?","o":["No reventarla, cubrirla con un paño limpio e ir a la ACHS","Reventarla con una aguja limpia para que seque más rápido","Ponerle hielo envuelto en un paño encima de la ampolla","Untarle crema o aceite para que no se pegue la ropa"],"w":"La ampolla protege la herida: no se revienta."}]},{"s":"pe_fuga_vapor","v":[{"q":"Ves vapor saliendo de una unión de cañería en el pasillo. ¿Qué haces?","o":["Me alejo, aviso a la jefatura y evito que otros pasen","La tapo con un trapo mojado mientras llega mantención","Cierro con la mano la válvula más cercana","Sigo trabajando si la fuga es pequeña"],"w":"El vapor a presión quema gravemente: alejarse y avisar."},{"q":"¿Por qué no se tapa una fuga de vapor con un trapo o la mano?","o":["Porque quema gravemente aunque la fuga parezca pequeña","Porque el trapo mojado contamina el producto de la línea","Porque solo se prohíbe si hay un supervisor presente","Porque la fuga se arregla sola cuando baja la presión"],"w":"Una fuga pequeña de vapor igual puede causar una quemadura grave."},{"q":"Una cañería de vapor puede estar sobre 100 °C aunque no se vea vapor ni se note caliente a distancia.","vf":true,"w":"Verdadero. Por eso no te apoyas ni dejas ropa sobre ellas."}]},{"s":"pe_calor","v":[{"q":"Cerca de los túneles de cocción sientes mareo, dolor de cabeza y náuseas. ¿Qué haces?","o":["Aviso, tomo agua y me recupero en un lugar fresco","Sigo hasta la pausa, porque es cansancio normal del turno","Tomo una bebida energética y continúo en mi puesto","Me mojo la cara con agua fría y sigo en el puesto"],"w":"Son señales de estrés por calor: se avisa y se sale del calor."},{"q":"¿Cuándo debes tomar agua en una zona calurosa?","o":["Seguido durante el turno, aunque no tengas sed","Solo cuando sientas mucha sed","Solo en la colación, para no interrumpir","Al final del turno, para reponer lo perdido"],"w":"La sed llega tarde: hay que hidratarse antes."},{"q":"Un compañero junto al horno está confundido y con la piel muy caliente. ¿Qué haces?","o":["Lo llevo a un lugar fresco, aviso y pido ayuda; si empeora, 131","Le doy un café cargado para que se despabile y pueda seguir","Lo dejo descansar sentado en su puesto, junto al mismo horno","Le pido que termine la tarea y después vaya a descansar"],"w":"La confusión es una señal grave de golpe de calor."}]},{"s":"pe_marmita","v":[{"q":"Vas a vaciar una marmita con líquido caliente. ¿Qué protección es clave?","o":["Guantes para calor y delantal, con la cara lejos del vapor","Guantes de nitrilo delgados y una mascarilla de papel","Guantes multiflex de selección y la cotona de trabajo","Delantal impermeable sin guantes, para tener mejor agarre"],"w":"El líquido y el vapor queman: guantes para calor, delantal y distancia."},{"q":"Debes trasladar un recipiente con líquido caliente. ¿Cómo lo haces?","o":["Con ayuda o en carro, caminando y sin llenarlo al borde","Rápido y solo, para que el líquido no alcance a enfriarse","Lleno hasta el borde, para hacer menos viajes por el pasillo","Al trote, pero mirando bien el piso para no resbalar"],"w":"Un derrame de líquido caliente es una quemadura segura."},{"q":"Tienes que revisar una marmita abierta en cocción. ¿Cómo lo haces?","o":["Desde el costado, con la cara lejos del vapor","Inclinado sobre ella, para ver mejor el contenido","Acercando la cara para sentir si está a punto","Destapándola completa y asomándome por arriba"],"w":"El vapor sube directo a la cara de quien se inclina."}]}]},{"id":"caldera_general","sec":"planta","title":"La caldera: lo que todos deben saber","thumb":"pe_caldera_general","learn":[{"s":"pe_caldera_general","t":"¿Qué hace la caldera?","x":"La caldera calienta agua hasta convertirla en <b>vapor a presión</b>, que llega por cañerías a los autoclaves, marmitas y otros equipos. Hay caldera en ambas plantas. Funciona con <b>combustible y un quemador</b> y acumula mucha energía: una falla grave puede causar una <b>explosión, un incendio o quemaduras con vapor</b> que afectan a toda la planta. Por eso tiene reglas para todos, no solo para el operador."},{"s":"pe_caldera_ajena","t":"Solo personal autorizado","x":"La sala de caldera es de <b>acceso restringido</b>: entra el operador y quien él o la jefatura autoricen. Según el <b>DS 10</b>, la caldera solo la opera quien tiene <b>certificación de competencia de la SEREMI de Salud</b> y la autorización de {EMP}. Nadie más toca válvulas, quemadores, purgas ni controles, ni siquiera para apagar una alarma. Si necesitas algo de esa sala, pídeselo al operador.","k":"Si no eres operador certificado, no entres ni toques la caldera."},{"s":"pe_mano","t":"Lo que revisa el operador","x":"En cada turno el operador controla, entre otros:<ul><li>El <b>manómetro</b>, que indica la presión.</li><li>La <b>válvula de seguridad</b>, que libera presión si sube sobre el límite y así evita una explosión.</li><li>El <b>nivel de agua</b>.</li></ul>Todo queda registrado en el <b>libro de vida</b> de la caldera. Si ves que alguien amarra o bloquea la válvula de seguridad, avisa de inmediato."},{"s":"pe_fuga_vapor","t":"Cañerías y equipos con vapor","x":"Las cañerías que salen de la caldera llevan vapor sobre <b>100 °C</b> y queman aunque no se vea vapor. No te apoyes en ellas y no dejes ropa secándose encima: déjala donde indique la jefatura. Avisa si una cañería perdió su aislación. Ante una fuga de vapor: <b>aléjate y avisa de inmediato</b>, sin intentar taparla ni cerrar válvulas tú mismo."},{"s":"pe_caldera_alerta","t":"Tu parte","x":"<ul><li>La sala de caldera <b>no es bodega</b>: nada de cartón, pallets, cajas ni bidones. Son combustibles junto a un quemador y estorban el acceso.</li><li>Mantén libre la puerta y el acceso.</li><li>Si escuchas ruidos extraños, ves el manómetro más alto de lo habitual, sientes olor a gas o combustible, o ves humo: <b>aléjate y avisa</b> al operador y a la jefatura, sin encender ni apagar nada.</li></ul>","k":"Ante cualquier anomalía en la caldera, aléjate y avisa."}],"quiz":[{"s":"pe_caldera_ajena","v":[{"q":"¿Quién puede operar la caldera?","o":["El operador con certificación SEREMI y autorización","Cualquier trabajador de mantención que esté de turno","El jefe de turno, aunque no tenga la certificación","Quien haya recibido la charla de caldera de la empresa"],"w":"El DS 10 exige certificación de competencia de la SEREMI de Salud."},{"q":"Suena una alarma en la sala de caldera y no ves al operador. ¿Qué haces?","o":["Aviso al operador y a la jefatura, sin tocar los controles","Entro y apago la alarma desde el tablero de la caldera","Apago el quemador por seguridad mientras llega alguien","Abro la purga para bajar la presión y que pare la alarma"],"w":"Solo el operador certificado manipula la caldera."},{"q":"Para operar una caldera, el DS 10 exige:","o":["Certificación de competencia de la SEREMI de Salud","Solo licencia de conducir clase D y cédula vigente","Un año de antigüedad trabajando dentro de la planta","Autorización verbal del operador del turno anterior"],"w":"Es un requisito legal para calderas y autoclaves."}]},{"s":"pe_fuga_vapor","v":[{"q":"Ves una fuga de vapor en una cañería que viene de la caldera. ¿Qué haces?","o":["Me alejo y aviso de inmediato, sin intentar taparla","La envuelvo con cinta o un paño mientras llega mantención","Cierro yo mismo la válvula de salida de la caldera","Sigo trabajando y aviso al final del turno si continúa"],"w":"El vapor quema gravemente: alejarse y avisar."},{"q":"Tu cotona quedó mojada. ¿Dónde la dejas secar?","o":["Donde indique la jefatura, nunca sobre cañerías calientes","Sobre la cañería de vapor, porque se seca más rápido","Colgada en la puerta de la sala de caldera, que es tibia","Sobre la tapa de un autoclave que esté detenido"],"w":"Las cañerías y equipos calientes no son tendedero."},{"q":"Una cañería de vapor sin aislación puede quemar aunque no se vea vapor saliendo.","vf":true,"w":"Verdadero. Puede estar sobre 100 °C sin que se note."}]},{"s":"pe_combustibles","v":[{"q":"Si sobra espacio, la sala de caldera puede usarse para guardar cajas y pallets vacíos.","vf":false,"w":"Falso. La sala de caldera no es bodega."},{"q":"¿Qué se puede guardar en la sala de caldera?","o":["Nada ajeno a la caldera: no es bodega","Cartón y pallets, si quedan ordenados","Bidones de combustible, si están tapados","Cajas vacías, lejos del quemador"],"w":"Todo material ajeno es combustible y estorba el acceso."},{"q":"¿Por qué no se guardan cartón, pallets o bidones en la sala de caldera?","o":["Son combustibles junto a un quemador y estorban el acceso","Se humedecen con el vapor de la sala y se echan a perder","Solo está prohibido durante la temporada alta de proceso","El polvo del cartón tapa el manómetro y la válvula de agua"],"w":"Junto a un quemador, cualquier material combustible puede iniciar un incendio."}]},{"s":"pe_caldera_alerta","v":[{"q":"Pasas junto a la sala de caldera y escuchas un ruido fuerte y extraño. ¿Qué haces?","o":["Me alejo y aviso al operador y a la jefatura","Entro a revisar de dónde viene","Golpeo la cañería para ver si se suelta","Espero a ver si se repite antes de avisar"],"w":"Un ruido anormal puede anunciar una falla: se avisa de inmediato."},{"q":"Sientes olor a gas o combustible cerca de la caldera. ¿Qué haces?","o":["Me alejo, aviso de inmediato y no enciendo ni apago nada","Busco de dónde viene la fuga con una linterna o encendedor","Entro a la sala y apago el quemador para cortar el gas","Sigo trabajando, porque ese olor es normal cerca de la caldera"],"w":"Una chispa puede encender el gas: alejarse y avisar."},{"q":"El manómetro de la caldera marca más alto de lo habitual y nadie lo atiende. ¿Qué haces?","o":["Aviso de inmediato al operador y a la jefatura, sin tocar nada","Abro a mano la válvula de seguridad para que libere presión","Bajo la potencia del quemador desde el tablero de control","Anoto el valor en el libro de vida y sigo con mi trabajo"],"w":"La presión alta es una anomalía que debe atender el operador."}]},{"s":"pe_mano","v":[{"q":"¿Para qué sirve la válvula de seguridad de la caldera?","o":["Libera presión si sube del límite y evita una explosión","Mide el nivel de agua que queda dentro de la caldera","Regula el tamaño de la llama del quemador en cada turno","Indica cuándo hay que cargar más combustible a la caldera"],"w":"Es el dispositivo que impide que la presión llegue a un nivel peligroso."},{"q":"¿Dónde se registran las revisiones de la caldera?","o":["En el libro de vida de la caldera","En el reloj control","En la HDS del combustible","En el registro de entrega de EPP"],"w":"El libro de vida guarda el historial de revisiones."},{"q":"Un compañero amarra la válvula de seguridad para que no “moleste”. ¿Qué haces?","o":["Aviso de inmediato: esa válvula evita una explosión","Espero al final del turno para comentarlo con calma","La suelto yo mismo sin decir nada para no causar problemas","Lo dejo así, porque eso es tema exclusivo del operador"],"w":"Bloquear un dispositivo de seguridad es una falta grave que se avisa."}]},{"s":"pe_caldera_general","v":[{"q":"¿Qué produce la caldera y adónde va?","o":["Vapor a presión que llega a autoclaves y marmitas","Agua fría a presión para lavar las líneas de proceso","Aire comprimido para hacer funcionar las cerradoras","Electricidad de respaldo para los tableros de la planta"],"w":"El vapor de la caldera alimenta los equipos del proceso."},{"q":"¿Qué puede provocar una falla grave de la caldera?","o":["Explosión, incendio o quemaduras con vapor","Solo un corte de luz en los equipos de la planta","Solo un ruido molesto en la sala de caldera","Únicamente pérdida de producto en los autoclaves"],"w":"Acumula mucha energía y combustible."},{"q":"¿Por qué la caldera tiene reglas para todos y no solo para el operador?","o":["Porque acumula mucha energía y una falla afecta a toda la planta","Porque todos deben saber operarla por si hay una emergencia","Porque la ley obliga a rotar a sus operadores entre los trabajadores","Porque cualquiera puede ajustarla si el operador no está"],"w":"Todos cuidan su acceso, su orden y avisan anomalías; solo el operador la maneja."}]},{"s":"pe_caldera_ajena","v":[{"q":"Necesitas un repuesto guardado en la sala de caldera. ¿Qué haces?","o":["Se lo pido al operador; no entro por mi cuenta","Entro rápido a buscarlo si la puerta está abierta","Entro acompañado de un compañero que conozca la sala","Entro solo si el quemador está apagado en ese momento"],"w":"Es acceso restringido: solo el operador y quien se autorice."},{"q":"La puerta de acceso a la sala de caldera debe estar:","o":["Despejada, sin cajas ni pallets delante","Bloqueada con pallets para que nadie entre","Usada como apoyo para dejar materiales","Tapada con cartón para que no salga ruido"],"w":"El acceso libre permite actuar rápido en una emergencia."},{"q":"¿Quién puede entrar a la sala de caldera?","o":["El operador y quien él o la jefatura autoricen","Todo el personal de mantención de la planta","Cualquiera que vaya de paso, si no toca nada","Quien necesite abrigarse un rato en invierno"],"w":"La sala de caldera es de acceso restringido."}]}]},{"id":"quimicos","sec":"planta","title":"Químicos de aseo y sanitización","thumb":"pe_quim","learn":[{"s":"pe_quim","t":"Químicos en la planta","x":"Para mantener la inocuidad usamos <b>detergentes, desengrasantes, soda cáustica, cloro, ácidos y sanitizantes</b>. También hay aceites, lubricantes y combustibles en mantención y en la caldera. Bien usados son seguros; mal usados <b>queman la piel y los ojos</b> o liberan gases tóxicos. Que sean productos de aseo no los hace inofensivos: la soda y los ácidos son corrosivos."},{"s":"hds","t":"La Hoja de Datos de Seguridad (HDS)","x":"Todo producto debe tener su <b>HDS</b> vigente y a mano, y una etiqueta con sus pictogramas de peligro (DS 57). La HDS dice <b>qué peligro tiene, qué EPP usar, cómo guardarlo y qué hacer si salpica o se derrama</b>. No la reemplaza la factura ni lo que recuerde un compañero. Si te toca un producto nuevo, lee su HDS y etiqueta y <b>pregunta a tu jefatura antes</b> de usarlo."},{"s":"pe_mezcla","t":"Nunca mezclar","x":"<b>Cloro con ácido</b> o con amoníaco libera gases tóxicos que dañan los pulmones en minutos. Nunca mezcles productos ni los eches uno tras otro en el mismo balde sin enjuagar, aunque agregues mucha agua. Usa solo la <b>dilución indicada</b> por tu jefatura y la etiqueta: más concentrado no limpia mejor, es más peligroso. Si al limpiar sientes olor fuerte o picazón en la garganta: sal al aire libre, ventila y avisa.","k":"Nunca mezcles cloro con ácidos ni otros productos."},{"s":"pe_quim","t":"Tu EPP para sanitizar","x":"<ul><li><b>Guantes largos de nitrilo o PVC</b>.</li><li><b>Antiparras</b>: una salpicadura de soda en el ojo puede dejar ceguera. Los lentes ópticos comunes no protegen de salpicaduras.</li><li><b>Delantal impermeable</b> y botas.</li><li>Protección respiratoria si la HDS lo indica.</li></ul>El EPP es gratuito: si está roto o falta, pide recambio antes de empezar."},{"s":"containers","t":"Envases rotulados","x":"Todo envase debe estar <b>rotulado</b> con el nombre del producto, aunque sea por un rato. <b>Nunca</b> trasvasijes químicos a botellas de bebida, jugo o envases de alimentos, aunque los marques con plumón: alguien puede beberlo por error. Si sobra producto preparado, guárdalo en un envase rotulado y tapado, en su lugar."},{"s":"pe_bloqueo","t":"Sanitizar con la línea detenida","x":"La espuma y el agua a presión se aplican con la <b>máquina detenida y bloqueada</b> según el procedimiento. Una línea detenida por una pausa, sin bloqueo, puede partir en cualquier momento. Avisa que estás limpiando. No apuntes la manguera a <b>tableros eléctricos, motores ni personas</b>. Enjuaga según el procedimiento para que no queden residuos en el producto."},{"s":"quimicos_eyes","t":"Si salpica","x":"<ul><li><b>Ojos:</b> lava en el lavaojos al menos <b>15 minutos</b>, con los párpados abiertos. No te refriegues.</li><li><b>Piel:</b> saca la ropa contaminada y lava con mucha agua.</li><li>Avisa de inmediato y lleva la <b>HDS o la etiqueta</b> a la atención en la <b>ACHS</b> (fono 1404): así saben qué producto fue.</li></ul>","k":"Si te salpica en los ojos, lava 15 minutos y avisa de inmediato."},{"s":"spillS","t":"Derrames","x":"Si se derrama un químico, o ves un charco que no sabes qué es: <b>aleja a las personas, avisa y señaliza</b>. No lo toques ni lo huelas. Límpialo solo si sabes cómo y con el EPP que indica la HDS. Nunca con las manos, con un trapo sin guantes, ni echándole otro producto para neutralizarlo."},{"s":"quimicos_store","t":"Almacenamiento e higiene","x":"<ul><li>Envases <b>cerrados, rotulados</b> y sobre bandeja antiderrame, lejos del calor y de chispas.</li><li>El cloro, separado de los ácidos.</li><li>Devuelve cada producto a su lugar al terminar; no dejes bidones en pasillos ni junto a la línea.</li><li>No comas, bebas ni fumes mientras manipulas químicos.</li><li><b>Lávate las manos</b> al terminar y antes de comer.</li></ul>"}],"quiz":[{"s":"pe_mezcla","v":[{"q":"¿Qué pasa si mezclas cloro con un ácido?","o":["Se libera un gas tóxico que daña los pulmones","Se potencia la limpieza y se ahorra tiempo","Se neutralizan y quedan sin peligro","Solo cambia de color, sin riesgo"],"w":"Nunca se mezclan productos de limpieza."},{"q":"Un compañero propone echar cloro y un desincrustante ácido en el mismo balde para un piso muy sucio. ¿Qué haces?","o":["No lo hago: juntos liberan gas tóxico","Lo hago, pero con mascarilla de papel","Lo hago si el balde tiene mucha agua","Lo hago con la puerta abierta"],"w":"Diluir o ventilar no evita que se forme el gas."},{"q":"Echar cloro y luego un ácido en el mismo balde sin enjuagar es seguro si se agrega bastante agua.","vf":false,"w":"Falso. Igual se libera gas tóxico."}]},{"s":"hds","v":[{"q":"¿Dónde encuentras el EPP que debes usar con un químico?","o":["En su Hoja de Datos de Seguridad (HDS)","En la factura o guía de despacho del producto","En el envase del producto que se usaba antes","En lo que recuerde el compañero más antiguo"],"w":"La HDS indica peligros, EPP y primeros auxilios."},{"q":"Te piden usar un sanitizante que nunca has usado. ¿Qué haces antes?","o":["Leo su HDS y etiqueta, y pregunto a mi jefatura","Lo uso igual que el cloro, que ya conozco bien","Lo huelo para saber qué tan fuerte es el producto","Lo pruebo concentrado en una zona pequeña primero"],"w":"Cada producto tiene peligros y EPP distintos."},{"q":"La HDS de un producto indica:","o":["Sus peligros, el EPP, cómo guardarlo y qué hacer si salpica","Solo el precio, el proveedor y la forma de hacer el pedido","Solo la fecha de vencimiento y el número de lote del envase","Solo cuánto producto usar por litro de agua en cada limpieza"],"w":"Es la ficha de seguridad del producto (DS 57)."}]},{"s":"containers","v":[{"q":"Todo envase con un químico debe estar rotulado con el nombre del producto, aunque sea por un rato.","vf":true,"w":"Verdadero. Un envase sin rótulo puede confundirse."},{"q":"Sobró sanitizante preparado. ¿Dónde lo guardas?","o":["En un envase rotulado y tapado, en su lugar","En una botella de bebida limpia y marcada","En un balde abierto para usarlo después","En un envase de alimentos bien lavado"],"w":"Nunca en envases de alimentos o bebidas."},{"q":"¿Por qué nunca se trasvasija un químico a una botella de bebida?","o":["Porque alguien puede beberlo por error","Porque el producto pierde su efecto","Porque el plástico se disuelve de inmediato","Porque solo se prohíbe dentro de la bodega"],"w":"Aunque esté marcada, la botella invita a beber."}]},{"s":"quimicos_eyes","v":[{"q":"Te salpica soda en un ojo. ¿Qué haces?","o":["Lavo en el lavaojos 15 minutos, párpados abiertos, y aviso","Lavo un minuto en el lavamanos y sigo si ya no me arde","Me refriego el ojo con la manga limpia para sacar el producto","Me echo gotas para los ojos y espero a que se me pase"],"w":"Agua abundante 15 minutos y atención en la ACHS."},{"q":"¿Cuánto tiempo, como mínimo, se lava un ojo salpicado con un químico?","o":["15 minutos","1 minuto","3 minutos","Hasta que deje de arder"],"w":"El químico sigue dañando aunque ya no arda."},{"q":"Después de lavar el ojo, ¿qué llevas a la atención en la ACHS?","o":["La HDS o la etiqueta del producto","La boleta de compra del producto","Una muestra en una botella","Nada, basta con contar lo que pasó"],"w":"Así saben qué producto fue y cómo tratarlo."}]},{"s":"pe_quim","v":[{"q":"¿Qué protección es imprescindible al preparar soda cáustica?","o":["Antiparras y guantes largos de nitrilo o PVC","Solo una mascarilla de papel y guantes de látex","Guantes de cabritilla, gorro y delantal de género","Lentes ópticos comunes y guantes de tela gruesa"],"w":"La soda quema ojos y piel: ojos y manos siempre protegidos."},{"q":"¿Por qué las antiparras son imprescindibles al sanitizar con soda?","o":["Una salpicadura de soda en el ojo puede dejar ceguera","La soda tiene un olor muy fuerte que irrita la vista","Solo las exige la auditoría de calidad de la planta","Evitan que el producto se contamine con las pestañas"],"w":"El daño de la soda en el ojo puede ser permanente."},{"q":"Una salpicadura de soda cáustica en el ojo puede dejar ceguera.","vf":true,"w":"Verdadero. Por eso se usan antiparras y no lentes comunes."}]},{"s":"pe_mezcla","v":[{"q":"Más concentrado limpia mejor, así que conviene echar más producto.","vf":false,"w":"Falso. Se usa la dilución indicada: más concentrado es más peligroso."},{"q":"¿Qué dilución usas al preparar un sanitizante?","o":["La indicada por la jefatura y la etiqueta","La que deja el olor más fuerte","El doble, si la superficie está muy sucia","A ojo, según la experiencia"],"w":"La dilución correcta limpia y no expone a más riesgo."},{"q":"Un compañero echa el doble de soda “para que quede bien limpio”. ¿Qué le dices?","o":["Que use la dilución indicada: más concentrado es más peligroso","Que está bien, siempre que después enjuague con abundante agua","Que le agregue un poco de cloro para compensar la mezcla","Que así se ahorra tiempo, porque limpia en una sola pasada"],"w":"Más producto no limpia mejor y aumenta quemaduras y residuos."}]},{"s":"pe_bloqueo","v":[{"q":"¿Cuándo se sanitiza una máquina con espuma y agua a presión?","o":["Con la máquina detenida y bloqueada","Con la máquina andando a baja velocidad","Mientras la línea termina de vaciarse","Cuando faltan pocos minutos para el término"],"w":"Así nadie queda atrapado ni se moja un equipo energizado."},{"q":"Lavas con agua a presión. ¿Hacia dónde nunca apuntas la manguera?","o":["A tableros eléctricos, motores o personas","Al piso que queda bajo la cinta transportadora","A las bandejas que ya fueron desmontadas","Al desagüe y a las canaletas de la sala"],"w":"El agua en equipos eléctricos puede causar una descarga."},{"q":"La cinta está detenida por una pausa, pero sin bloqueo. ¿Puedes limpiar dentro de ella?","o":["No: primero se bloquea según el procedimiento","Sí, porque si está detenida no hay ningún riesgo","Sí, siempre que lo haga rápido y con cuidado","Sí, si un compañero vigila el botón de partida"],"w":"Una línea sin bloqueo puede partir en cualquier momento."}]},{"s":"spillS","v":[{"q":"Se derramó un bidón de ácido en la bodega de químicos. ¿Qué haces primero?","o":["Alejo a las personas, aviso y señalizo","Lo limpio de inmediato con un trapo","Le echo cloro para neutralizarlo","Lo diluyo con agua de la manguera"],"w":"Primero alejar, avisar y señalizar. Se limpia según la HDS."},{"q":"¿Cuándo puedes limpiar tú un derrame de químico?","o":["Si sé cómo y uso el EPP que indica la HDS","Siempre, si actúo rápido antes de que se extienda","Si es pequeño, aunque no tenga el EPP a mano","Si tengo guantes de tela y un trapo a mano"],"w":"Sin conocimiento ni EPP adecuado, el derrame te puede quemar."},{"q":"Ves un charco desconocido junto a los bidones. ¿Qué haces?","o":["Aviso, señalizo y no lo toco hasta saber qué es","Lo seco con papel de inmediato para que nadie resbale","Lo huelo de cerca para saber qué producto es","Lo tapo con cartón para que nadie lo pise y sigo"],"w":"Un líquido desconocido se trata como peligroso."}]}]},{"id":"ruido","sec":"planta","mins":5,"title":"Ruido y protección auditiva","thumb":"ruido_limite","learn":[{"s":"ruido_cilios","t":"El ruido daña sin doler","x":"Dentro del oído hay <b>células muy finas</b> que captan el sonido. El ruido fuerte, día tras día, las daña de a poco. No duele ni se nota... hasta que ya no escuchas bien. <b>La sordera por ruido es permanente</b>: esas células no se regeneran y ningún tratamiento las recupera. Por eso la única solución es prevenir."},{"s":"ruido_fuentes","t":"El ruido en la planta","x":"Las fuentes más fuertes suelen ser las <b>cerradoras, los compresores, la caldera y el esmeril</b>. Si trabajas cerca de ellas, también estás expuesto, aunque no seas tú quien las opera. El ruido no respeta cargos: afecta al operador, al ayudante y a quien pasa seguido por la zona."},{"s":"ruido_limite","t":"El límite de la ley","x":"El DS 594 fija <b>85 dB(A) como límite para una jornada de 8 horas</b>. Si tu puesto lo supera, o la zona está señalizada, <b>el protector es obligatorio todo el tiempo</b> que estés en ella. {EMP} debe entregártelo gratis y enseñarte a usarlo; tú debes usarlo bien y cuidarlo.","k":"Sobre 85 dB(A) o en zona señalizada, usa siempre tu protector."},{"s":"ruido_3db","t":"Más ruido, menos tiempo","x":"Los decibeles no suman como números normales: <b>cada 3 dB(A) más, la energía del ruido se duplica</b> y el tiempo permitido se reduce a la mitad.<ul><li>85 dB(A): 8 horas</li><li>88 dB(A): 4 horas</li><li>91 dB(A): 2 horas</li></ul>Una diferencia que parece pequeña en el número es enorme para tu oído."},{"s":"ruido_prexor","t":"Nivel de acción: 82 dB(A)","x":"El protocolo PREXOR del MINSAL fija un <b>nivel de acción de 82 dB(A)</b>, bajo el límite legal. Si en tu puesto se alcanza ese nivel, se activan la <b>evaluación del ambiente y la vigilancia de tu salud</b>, con audiometrías periódicas en la ACHS. Asiste a tus audiometrías: detectan el daño antes de que lo notes."},{"s":"ruido_metro","t":"La prueba del metro","x":"Si para hablar con alguien <b>a un metro de distancia tienes que gritar</b>, el ruido probablemente es alto. Protégete y avisa a tu jefatura para que se evalúe el puesto. La medición oficial la hace un especialista con instrumentos calibrados, no una aplicación del celular."},{"s":"plugs","t":"Tapones: póntelos bien","x":"Con las manos limpias:<ul><li><b>1.</b> Enrolla el tapón con los dedos hasta dejarlo delgado.</li><li><b>2.</b> Con la otra mano tira la oreja hacia arriba y atrás, para abrir el canal.</li><li><b>3.</b> Insértalo y sostenlo unos segundos mientras se expande.</li></ul>Mal puesto o a medio entrar, un tapón casi no protege."},{"s":"muffs","t":"Fonos (orejeras)","x":"Deben <b>cubrir la oreja completa</b> y sellar bien. Colgados del cuello no protegen nada. Pelo, gorros o patas gruesas de lentes bajo la almohadilla dejan pasar ruido. Revisa que las almohadillas no estén rotas ni endurecidas; si lo están, pide recambio antes de entrar a la zona."},{"s":"ruido_siempre","t":"Todo el tiempo, no a ratos","x":"Sacarte el protector “un ratito” en zona ruidosa te quita gran parte de la protección de toda la jornada, porque el daño se concentra justo en esos minutos sin protección. <b>Póntelo antes de entrar y sácatelo al salir.</b> No hay un tiempo “corto” que sea seguro sin protector, ni siquiera mientras esperas que la máquina parta.","k":"No te saques el protector en la zona ruidosa, ni un ratito."},{"s":"ruido_auto","t":"Autocuidado: tú decides","x":"La acción insegura típica es <b>sacarse el protector para conversar</b> o “porque es un corte corto”. La decisión segura: dejarlo puesto y <b>alejarse de la máquina para hablar</b>. Avisa si tus fonos están dañados o faltan tapones. Un <b>zumbido en los oídos</b> al terminar el turno es una alerta: el ruido te está afectando; avísalo y revisa cómo usas tu protector."}],"quiz":[{"s":"ruido_fuentes","v":[{"q":"Según el DS 594, ¿cuál es el límite de ruido para una jornada de 8 horas?","o":["85 dB(A)","82 dB(A)","90 dB(A)","100 dB(A)"],"w":"El DS 594 fija 85 dB(A) para 8 horas."},{"q":"Un puesto mide 87 dB(A) durante toda la jornada de 8 horas. Según el DS 594:","o":["Supera el límite: el protector es obligatorio","Está bajo el límite: no necesita protector","Solo debe protegerse quien opera la máquina","Recién sobre 100 dB(A) se exige protector"],"w":"Sobre 85 dB(A) en 8 horas se supera el límite legal."},{"q":"El límite de 85 dB(A) del DS 594 corresponde a una exposición de:","o":["8 horas","1 hora","4 horas","12 horas"],"w":"Es el límite para una jornada de 8 horas."}]},{"s":"ruido_cilios","v":[{"q":"La pérdida de audición por ruido se recupera con el tiempo.","vf":false,"w":"Falso. Es permanente; por eso se previene."},{"q":"¿Por qué la sordera por ruido es permanente?","o":["Las células del oído dañadas no se regeneran","El tímpano se rompe de inmediato","El oído se tapa con cera por el ruido","Solo afecta a personas mayores de 50 años"],"w":"Ningún tratamiento recupera esas células."},{"q":"El ruido fuerte daña la audición:","o":["De a poco y sin dolor, día tras día","Solo si provoca dolor de oído","Solo cuando hay un golpe muy fuerte","Solo a quien opera la máquina"],"w":"Como no duele, se nota cuando ya es tarde."}]},{"s":"ruido_metro","v":[{"q":"Hay demasiado ruido cuando...","o":["Tienes que gritar para hablar con alguien a 1 metro","Escuchas la máquina funcionando desde el pasillo","Hay música de fondo encendida en la sala de proceso","La máquina vibra un poco cuando la tocas con la mano"],"w":"Es la prueba simple del metro: protégete y avisa."},{"q":"Para hablar con un compañero a un metro debes gritar. ¿Qué haces?","o":["Me protejo y aviso a la jefatura para que evalúen el puesto","Sigo igual: si no me duele el oído, no hay ningún problema","Mido con una aplicación del celular y decido si me protejo","Hablo más fuerte y me acerco más para que me entienda"],"w":"Es una señal de ruido alto que debe evaluarse."},{"q":"¿Quién hace la medición oficial del ruido de un puesto?","o":["Un especialista con instrumentos calibrados","Cualquier compañero con su celular","El operador, a oído","Nadie: se estima por la marca de la máquina"],"w":"La medición válida requiere instrumentos y un especialista."}]},{"s":"enfermedades_fonosMal","v":[{"q":"Un compañero trabaja junto a la cerradora con los fonos en el cuello. ¿Cómo está protegido?","o":["No está protegido: los fonos deben cubrir las orejas","Está protegido, porque los tiene a mano para ponérselos","Está protegido si trabaja a más de dos metros de la máquina","Está protegido mientras no sienta dolor de oídos"],"w":"Los fonos protegen solo puestos sobre las orejas."},{"q":"Ves a un compañero así en la zona de la cerradora. ¿Qué le dices?","o":["Que se ponga los fonos cubriendo las orejas","Que está bien si la máquina está en vacío","Que basta con que los tenga cerca","Que se los ponga solo si le molesta"],"w":"Colgados del cuello no protegen nada."},{"q":"Los fonos protegen correctamente cuando:","o":["Cubren la oreja completa y sellan bien","Están colgados del cuello, listos para usar","Cubren media oreja para escuchar mejor","Tienen las almohadillas duras y gastadas"],"w":"Si no sellan, el ruido entra."}]},{"s":"plugs","v":[{"q":"Al ponerte un tapón, ¿qué haces con la oreja?","o":["La tiro hacia arriba y atrás para abrir el canal","La tiro hacia abajo y adelante para que entre mejor","La aprieto contra la cabeza mientras meto el tapón","Nada, solo empujo el tapón hasta que no se vea"],"w":"Así el tapón entra derecho y sella bien."},{"q":"¿Cuál es el orden correcto para ponerte un tapón?","o":["Enrollarlo, tirar la oreja y sostenerlo mientras se expande","Tirar la oreja, meterlo sin enrollar y soltarlo de inmediato","Mojarlo con agua y dejarlo a medio entrar para que respire","Enrollarlo y dejarlo apoyado en la entrada del oído"],"w":"Bien puesto, el tapón se expande y sella el canal."},{"q":"Un tapón mal puesto protege casi lo mismo que uno bien puesto.","vf":false,"w":"Falso. Mal puesto, casi no protege."}]},{"s":"ruido_siempre","v":[{"q":"¿Cuándo debes usar el protector en una zona ruidosa?","o":["Todo el tiempo que estés en la zona","Solo cuando la máquina suena más fuerte","Solo cuando sientes molestia","La mitad de la jornada"],"w":"Todo el tiempo, sin sacártelo a ratos."},{"q":"¿Cuándo te pones y te sacas el protector?","o":["Me lo pongo antes de entrar y me lo saco al salir","Me lo pongo apenas siento molestia por el ruido","Me lo saco un rato cada hora para que el oído descanse","Me lo pongo solo cuando estoy junto a la cerradora"],"w":"Así no quedas expuesto en ningún momento."},{"q":"Sacarte el protector “un ratito” en la zona ruidosa:","o":["Te quita gran parte de la protección de la jornada","No importa si dura menos de 15 minutos seguidos","Ayuda a que el oído descanse y se recupere","Solo afecta si la máquina está funcionando a plena carga"],"w":"No hay un tiempo corto seguro sin protector."}]},{"s":"ruido_limite","v":[{"q":"Si el ruido sube de 85 a 88 dB(A), el tiempo de exposición permitido...","o":["Se reduce a la mitad","Se mantiene igual","Se reduce en un tercio","Se duplica"],"w":"Cada 3 dB(A) más, la energía se duplica y el tiempo se reduce a la mitad."},{"q":"Si a 85 dB(A) se permiten 8 horas, ¿cuántas se permiten a 91 dB(A)?","o":["2 horas","4 horas","6 horas","1 hora"],"w":"Son 6 dB(A) más: el tiempo se divide a la mitad dos veces."},{"q":"Si el ruido sube de 85 a 88 dB(A), el tiempo permitido baja a 4 horas.","vf":true,"w":"Verdadero. Cada 3 dB(A) más, la mitad del tiempo."}]},{"s":"ruido_q_82","v":[{"q":"Según el PREXOR, ¿qué se activa cuando un puesto alcanza el nivel de acción de 82 dB(A)?","o":["La evaluación del ambiente y la vigilancia con audiometrías","El permiso para trabajar sin protector en ese puesto","Un cambio de turno obligatorio para todos los expuestos","Solo la instalación de un letrero de advertencia en la zona"],"w":"El nivel de acción activa la evaluación y la vigilancia de la salud."},{"q":"Tu puesto alcanza 82 dB(A), bajo el límite legal. ¿Qué corresponde según el PREXOR?","o":["Evaluar el ambiente e incluirte en vigilancia con audiometrías","Nada, porque todavía está bajo el límite de 85 dB(A)","Usar protector solo los días de más producción en temporada","Cambiarte de puesto de inmediato, sin evaluar el ambiente"],"w":"El PREXOR actúa antes de llegar al límite legal."},{"q":"¿Dónde se hacen las audiometrías de vigilancia de los expuestos a ruido?","o":["En la ACHS","En la portería de la planta","En cualquier farmacia","En la oficina de la jefatura"],"w":"Son parte de la vigilancia de la salud del PREXOR."}]},{"s":"ruido_zumbido","v":[{"q":"Al terminar el turno sientes un zumbido en los oídos. ¿Qué significa?","o":["Es una alerta del ruido: debo protegerme mejor y avisar","Es normal después de un turno y no tiene importancia","Que el protector funcionó perfecto durante la jornada","Que necesito limpiarme los oídos con un cotonito"],"w":"El zumbido indica que el ruido te está afectando."},{"q":"Varios días notas zumbido al salir del turno. ¿Qué haces?","o":["Aviso a mi jefatura y reviso cómo uso mi protector","Espero unos días a ver si se me pasa solo","Lo tapo escuchando música con audífonos en la casa","Me saco el protector a ratos para que el oído se acostumbre"],"w":"Avisar a tiempo permite corregir la protección."},{"q":"Un zumbido en los oídos al salir del turno indica que:","o":["El ruido te está afectando y debes revisar tu protección","Tu audición se fortaleció y se acostumbró al ruido","Fue un día normal de trabajo, sin nada que revisar","El protector quedó demasiado apretado y hay que soltarlo"],"w":"Es una señal de alerta, no algo normal."}]},{"s":"ruido_q_charla","v":[{"q":"Necesitas hablar con un compañero junto a la cerradora encendida. ¿Cuál es la decisión segura?","o":["Alejarnos de la máquina para hablar, sin sacarme el protector","Sacarme los fonos un ratito para escucharlo bien y volver","Levantar un fono solo mientras él me está hablando de cerca","Hablarle al oído, con los fonos colgando del cuello"],"w":"Para conversar, se sale de la zona ruidosa."},{"q":"¿Cuál es la acción insegura típica con el ruido?","o":["Sacarse el protector para conversar","Pedir reposición de tapones","Alejarse de la máquina para hablar","Avisar un zumbido al final del turno"],"w":"Es la causa más común de exposición evitable."},{"q":"Un compañero se saca los tapones “porque es un corte corto” junto a la cerradora. ¿Qué es lo correcto?","o":["Dejarlos puestos mientras esté en la zona","Sacarlos si el corte dura menos de 5 minutos","Sacarlos solo de un oído","Sacarlos si la máquina está en vacío"],"w":"No hay un tiempo corto seguro sin protector."}]}]},{"id":"tmert","sec":"planta","title":"Trabajo repetitivo y lesiones de extremidades superiores (TMERT)","thumb":"tmert_intro","learn":[{"s":"tmert_intro","t":"¿Qué son los TMERT?","x":"Son <b>trastornos musculoesqueléticos de extremidades superiores</b>: lesiones de <b>hombros, codos, muñecas y manos</b>, como tendinitis o síndrome del túnel carpiano. Aparecen <b>de a poco</b>, por tareas repetitivas, con fuerza o en malas posturas, no por un golpe. En la planta: seleccionar en la línea, embandejar, cortar y etiquetar durante todo el turno."},{"s":"tmert_factores","t":"Los principales factores de riesgo","x":"La Norma Técnica TMERT del MINSAL evalúa principalmente:<ul><li><b>Repetitividad:</b> el mismo movimiento muchas veces.</li><li><b>Fuerza:</b> apretar, empujar o sostener con esfuerzo.</li><li><b>Postura forzada:</b> muñeca doblada, brazos sobre los hombros.</li></ul>Además, el <b>tiempo de recuperación</b>: si faltan pausas, el riesgo sube. Mientras más factores se juntan en una tarea, mayor es el riesgo de lesión."},{"s":"pe_seleccion","t":"Repetitividad","x":"Al repetir el mismo gesto, el tendón roza una y otra vez, como una cuerda que pasa por una polea: con el tiempo se inflama. Ejemplos: <b>seleccionar mosqueta, llenar latas o embandejar</b> sin descanso. Si además lo haces con la muñeca doblada y sin pausas, juntas tres factores de riesgo a la vez."},{"s":"tmert_fuerza","t":"Fuerza","x":"Apretar fuerte un cuchillo sin filo, empujar carros pesados o sostener una pieza con una mano carga músculos y tendones. Mientras más fuerza y más tiempo, más daño.<ul><li>Usa cuchillos <b>afilados</b> y ayudas mecánicas.</li><li>Pide ayuda con cargas grandes.</li><li>Agarra con toda la mano, no solo con los dedos.</li></ul>"},{"s":"tmert_alto","t":"Posturas forzadas","x":"Las posturas que más dañan:<ul><li>Brazos <b>sobre los hombros</b>, por ejemplo al apilar alto.</li><li><b>Muñeca doblada</b> o girada.</li><li>Codos separados del cuerpo.</li></ul>Trabaja con las manos <b>entre la cintura y los hombros</b>, la muñeca recta y los codos cerca. Acércate a la pieza en vez de estirarte, y usa los niveles medios del rack. Si tu puesto te obliga a doblar la muñeca, ajústalo o avisa."},{"s":"tmert_pausa","t":"Pausas: el tiempo de recuperación","x":"Músculos y tendones se recuperan cuando descansan. Usa las <b>pausas establecidas</b>, suelta la herramienta unos segundos entre ciclos y, si están indicados, haz los ejercicios de pausa activa. Trabajar “de corrido” para salir antes acumula daño, aunque todo el grupo esté de acuerdo. Juntar las pausas al final del turno tampoco sirve: el tendón necesita descansar durante la jornada.","k":"No te saltes las pausas."},{"s":"tmert_alternar","t":"Alterna tareas","x":"Cambiar de tarea durante el turno hace trabajar otros músculos y deja descansar los que más usaste. Por ejemplo, alternar <b>corte, apilado y embandejado</b>. Coordina la rotación con tu jefatura: se organiza entre todos, no cada uno por su cuenta. Si una tarea ya te molesta, pide rotar antes de que duela más."},{"s":"tmert_herram","t":"Herramientas adecuadas","x":"Una buena herramienta mantiene la <b>muñeca recta</b> y reduce la fuerza:<ul><li>Mango del tamaño de tu mano y con la forma adecuada a la tarea.</li><li>Cuchillos afilados y herramientas en buen estado: cortan con menos esfuerzo.</li><li>Guantes de tu talla: uno grande obliga a apretar más.</li></ul>"},{"s":"tmert_sintomas","t":"Avisa los síntomas temprano","x":"Señales de alerta:<ul><li><b>Hormigueo</b> o adormecimiento de los dedos.</li><li><b>Dolor nocturno</b> en manos o muñecas que te despierta.</li><li>Pérdida de fuerza: se te caen las cosas.</li><li>Dolor de hombro o codo que no se pasa.</li></ul>Aunque el dolor aparezca de noche, puede venir del trabajo. Avisa a tu jefatura: tratado a tiempo en la ACHS, se recupera mejor.","k":"Si sientes hormigueo o dolor nocturno, avisa hoy."},{"s":"tmert_auto","t":"Autocuidado: no aguantes el dolor","x":"En TMERT, las acciones inseguras típicas son <b>aguantar el dolor</b>, saltarse las pausas para ir más rápido o forzar con la muñeca doblada. Tomar un analgésico y seguir igual solo esconde la alarma. La decisión segura: <b>pausar, corregir la postura, pedir ayuda y avisar</b>. Reportar una herramienta o mesa inadecuada también es autocuidado."}],"quiz":[{"s":"tmert_factores","v":[{"q":"¿Cuáles son los principales factores de riesgo de TMERT?","o":["Repetitividad, fuerza y postura forzada","Ruido, polvo y calor en la sala de proceso","Edad, peso y estatura de cada persona","Turno, horario de entrada y temporada"],"w":"Junto al tiempo de recuperación, son los factores de la Norma Técnica TMERT."},{"q":"Además de repetición, fuerza y postura, ¿qué factor aumenta el riesgo de TMERT?","o":["La falta de pausas para recuperarse","El ruido de las cerradoras de la línea","El uso de guantes multiflex en la selección","Trabajar en el turno de noche en temporada"],"w":"Sin tiempo de recuperación, el daño se acumula."},{"q":"Seleccionar todo el turno con la muñeca doblada y sin pausas combina:","o":["Repetitividad, postura forzada y falta de recuperación","Solo fuerza excesiva, porque la muñeca trabaja más","Solo un problema de orden y aseo en el puesto","Ningún factor, porque es una tarea liviana y sentada"],"w":"Una tarea liviana también lesiona si junta varios factores."}]},{"s":"tmert_intro","v":[{"q":"¿Qué zonas del cuerpo afectan los TMERT de extremidades superiores?","o":["Hombros, codos, muñecas y manos","Rodillas, tobillos y pies","Columna lumbar y caderas","Cuello, ojos y oídos"],"w":"Afectan las extremidades superiores."},{"q":"La tendinitis y el síndrome del túnel carpiano son ejemplos de:","o":["TMERT de extremidades superiores","Lesiones causadas por golpes y caídas","Enfermedades causadas por el ruido","Alergias causadas por la pelusa"],"w":"Son lesiones por trabajo repetitivo, fuerza o postura."},{"q":"¿Cómo aparecen habitualmente los TMERT?","o":["De a poco, por gestos repetidos, fuerza o malas posturas","De golpe, por una caída o un golpe fuerte en el brazo","Solo por un atrapamiento con una máquina de la línea","Solo en personas mayores de 50 años, por el desgaste"],"w":"Se acumulan con el tiempo; por eso se previenen a diario."}]},{"s":"tmert_alto","v":[{"q":"Apilas bandejas sobre la altura de tus hombros en el rack. ¿Qué es lo correcto?","o":["Usar niveles medios, con las manos entre cintura y hombros","Seguir así: si lo hago rápido, el esfuerzo dura menos tiempo","Estirarme en puntillas para alcanzar mejor el nivel más alto","Subir los brazos, pero turnándome entre una mano y la otra"],"w":"Brazos sobre los hombros es una postura forzada."},{"q":"¿Cuál de estas es una postura forzada?","o":["Brazos sobre los hombros al apilar alto","Manos entre la cintura y los hombros","Muñeca recta al cortar","Codos cerca del cuerpo al embandejar"],"w":"Las demás son posturas neutras."},{"q":"Una pieza queda lejos en la mesa. ¿Qué es lo correcto?","o":["Acercarme a la pieza en vez de estirar los brazos","Estirar más el brazo y doblar la muñeca","Alcanzarla con la punta de los dedos","Inclinarme sobre la mesa con los codos abiertos"],"w":"Estirarse separa los codos y fuerza hombro y muñeca."}]},{"s":"tmert_pausa","v":[{"q":"Saltarse las pausas para terminar antes ayuda a prevenir lesiones.","vf":false,"w":"Falso. Sin tiempo de recuperación, el daño se acumula."},{"q":"¿Para qué sirven las pausas en un trabajo repetitivo?","o":["Para que músculos y tendones se recuperen","Solo para ir al baño o tomar agua","Para bajar el ritmo de producción del turno","Solo cuando la tarea es pesada, no si es liviana"],"w":"La pausa es parte del trabajo seguro."},{"q":"Tu grupo propone trabajar “de corrido” sin pausas para salir antes. ¿Qué es lo correcto?","o":["Hacer las pausas: sin recuperación el daño se acumula","Aceptar, si todo el grupo está de acuerdo con la idea","Juntar todas las pausas al final y salir más temprano","Reemplazar las pausas por tomar café en el mismo puesto"],"w":"El acuerdo del grupo no cambia lo que necesitan los tendones."}]},{"s":"tmert_sintomas","v":[{"q":"Sientes hormigueo en los dedos y un dolor de muñeca que te despierta de noche. ¿Qué haces?","o":["Aviso pronto a mi jefatura","Aguanto hasta fin de temporada","Tomo un analgésico y sigo igual","Me pongo una muñequera sin decir nada"],"w":"Son síntomas tempranos: avisar a tiempo permite tratar y corregir."},{"q":"¿Cuál de estas es una señal temprana de TMERT?","o":["Hormigueo o dolor nocturno en manos y muñecas","Cansancio en las piernas después de caminar mucho","Hambre a media mañana, antes de la colación","Sed al trabajar un rato cerca de los hornos"],"w":"El hormigueo y el dolor nocturno son alertas típicas."},{"q":"Si el dolor de muñeca aparece solo de noche, no tiene relación con el trabajo y no hay que avisarlo.","vf":false,"w":"Falso. El dolor nocturno es una señal típica de TMERT."}]},{"s":"tmert_neutro","v":[{"q":"Una postura neutra para las manos es:","o":["Muñeca recta y codos cerca del cuerpo","Muñeca doblada hacia abajo, relajada","Codos separados y hombros levantados","Brazos estirados hacia adelante, rectos"],"w":"Así se reduce la carga en los tendones."},{"q":"¿A qué altura deben trabajar tus manos?","o":["Entre la cintura y los hombros","Sobre la altura de los hombros","A la altura de las rodillas","Lo más lejos posible del cuerpo"],"w":"Es la zona de menor esfuerzo."},{"q":"Al trabajar notas que tu muñeca queda doblada todo el rato. ¿Qué haces?","o":["Ajusto mi posición o aviso para corregir el puesto","Sigo igual, con el tiempo ya me voy a acostumbrar","Aprieto más fuerte la pieza para compensar la postura","Trabajo más rápido para terminar antes y descansar"],"w":"La muñeca doblada es una postura forzada que se corrige."}]},{"s":"tmert_alternar","v":[{"q":"Alternar entre corte, apilado y embandejado durante el turno:","o":["Reparte el esfuerzo entre distintos músculos","Aumenta el riesgo de TMERT por cambiar de ritmo","Solo sirve para que el turno no se haga aburrido","Hace más lento el aprendizaje de cada tarea"],"w":"Variar la tarea deja recuperarse a los músculos más usados."},{"q":"¿Cómo se organiza la rotación de tareas?","o":["Coordinada con la jefatura, entre todos","Cada uno cambia de tarea cuando quiere","La deciden solo los trabajadores más antiguos","No se rota, para no perder el ritmo de la línea"],"w":"Se organiza entre todos para que funcione."},{"q":"Llevas toda la mañana embandejando y te molesta el hombro. ¿Qué medida preventiva corresponde?","o":["Rotar a otra tarea coordinando con la jefatura","Cambiarme de tarea por mi cuenta, sin avisar a nadie","Seguir embandejando hasta la colación aunque duela","Cargar más bandejas por viaje para terminar antes"],"w":"Rotar a tiempo evita que la molestia se transforme en lesión."}]},{"s":"pe_cuchillo_ok","v":[{"q":"Un cuchillo sin filo obliga a hacer más fuerza con la mano.","vf":true,"w":"Verdadero. Herramientas afiladas reducen la fuerza necesaria."},{"q":"¿Qué herramienta reduce el riesgo de TMERT al cortar?","o":["Un cuchillo afilado, con mango a la medida de tu mano","Un cuchillo sin filo, para no cortarse durante el turno","Cualquier cuchillo, siempre que se apriete con fuerza","Un mango muy grueso, aunque no calce bien en la mano"],"w":"Filo y mango adecuado mantienen la muñeca recta y bajan la fuerza."},{"q":"Tus guantes son dos tallas más grandes. ¿Por qué es un problema?","o":["Obligan a apretar más fuerte la herramienta","Hacen que la mano transpire menos en el turno","Protegen más que los guantes de tu talla","Solo afectan la comodidad, no la salud"],"w":"Un guante grande aumenta la fuerza de agarre."}]},{"s":"tmert_auto","v":[{"q":"¿Cuál es la acción insegura típica que lleva a una lesión TMERT?","o":["Aguantar el dolor y seguir sin avisar","Usar las pausas establecidas del turno","Ajustar la altura de trabajo de la mesa","Reportar una mesa o herramienta inadecuada"],"w":"El dolor es una alarma: avisar y corregir a tiempo es autocuidado."},{"q":"Te duele la muñeca a mitad de turno. ¿Cuál es la decisión segura?","o":["Pausar, corregir la postura y avisar","Aguantar hasta que termine la temporada","Tomar un analgésico y seguir igual","Cambiar de mano sin decir nada"],"w":"Esconder el dolor deja avanzar la lesión."},{"q":"Avisar a la jefatura que una mesa de trabajo es muy baja es:","o":["Autocuidado: corrige una condición que lesiona","Una queja que no le corresponde al trabajador","Algo que solo puede hacer el supervisor de línea","Innecesario, porque con el tiempo uno se acostumbra"],"w":"Reportar condiciones inadecuadas también previene lesiones."}]}]},{"id":"horquilla","sec":"planta","mins":5,"title":"Grúa horquilla: convivir con seguridad","thumb":"horq_contacto","learn":[{"s":"horq_ciego","t":"Una máquina pesada con puntos ciegos","x":"La grúa horquilla pesa varias toneladas, no frena como un auto y <b>la parte trasera se abre al girar</b>. Además, <b>el operador no ve todo</b>: la carga, el mástil y la parte trasera le tapan la vista. Un peatón en el punto ciego es invisible, aunque la grúa vaya despacio o con luces."},{"s":"horq_licencia","t":"Solo la opera quien está autorizado","x":"Para operarla se necesita <b>licencia clase D y autorización escrita de la empresa</b>. Dentro de la planta, {EMP} exige ambas: la licencia sola no basta. Nadie más se sube a manejarla: ni “un ratito”, ni para moverla un metro, ni aunque tenga la llave puesta."},{"s":"horq_contacto","t":"Contacto visual antes de cruzar","x":"Antes de cruzar o acercarte: <b>detente, busca contacto visual</b> con el operador y <b>espera su señal</b>. Sabes que te vio cuando te mira y te hace una señal, no porque escuches el motor. <b>El peatón tiene prioridad</b>, pero nunca la des por segura. Respeta las <b>zonas demarcadas</b> y no camines por la ruta de la grúa.","k":"No cruces sin contacto visual y la señal del operador."},{"s":"horq_bajo","t":"Nunca bajo una carga levantada","x":"Un pallet de cajas o un bin mal apilado puede deslizarse en segundos. <b>Nadie pasa ni se queda bajo las horquillas levantadas</b>, aunque la grúa esté detenida: rodea a distancia o espera que baje la carga. Nadie viaja sobre las horquillas ni sobre la carga, y la grúa <b>nunca</b> se usa para elevar personas: para altura se usa el equipo habilitado.","k":"Nunca pases bajo una carga levantada."},{"s":"horq_patio","t":"Carga de camiones en el patio","x":"Al cargar un camión, la grúa entra y sale muchas veces.<ul><li>Espera <b>fuera de la zona de maniobra</b> hasta que el operador te indique.</li><li>Nunca te pongas entre la grúa y el camión o un rack: puedes quedar atrapado.</li><li>El camión debe estar <b>detenido y frenado</b>.</li></ul>"},{"s":"horq_preuso","t":"Operador: revisión antes de partir","x":"Antes de usarla en el turno, el operador hace la revisión con su <b>check list</b>: <b>frenos, bocina, luces, neumáticos, horquillas, cadenas y fugas</b>. Si algo falla, aunque parezca menor, la grúa no se usa, se avisa a la jefatura y se espera la reparación. Nadie la repara de forma improvisada."},{"s":"horq_operar","t":"Operador: al conducir","x":"<ul><li><b>Cinturón de seguridad siempre</b>, aunque el trayecto sea corto.</li><li>Carga baja, cerca del piso, y mástil inclinado hacia atrás.</li><li>Si la carga tapa la vista, <b>avanza en reversa</b> mirando el recorrido; nunca levantes la carga para ver por debajo.</li><li>Bocina en cruces y puertas; velocidad baja.</li><li>Nunca superes la capacidad indicada en su placa.</li></ul>"},{"s":"horq_estacionar","t":"Operador: al estacionar","x":"Al terminar o dejar la grúa sola, aunque sea por pocos minutos:<ul><li><b>Horquillas apoyadas en el piso.</b></li><li>Freno de estacionamiento puesto.</li><li>Motor apagado y <b>llave retirada</b>, para que nadie sin autorización la mueva.</li><li>En su lugar demarcado, lejos de salidas, extintores y pasillos.</li></ul>Nunca la dejes con la carga levantada ni con la llave puesta."},{"s":"horq_vuelco","t":"Si la grúa se vuelca","x":"El instinto dice “salta”, pero saltar es lo más peligroso: la máquina te puede aplastar. <b>Quédate dentro con el cinturón puesto</b>, afírmate fuerte al volante, apoya los pies e inclínate hacia el lado contrario a la caída. El cinturón es lo que te mantiene dentro de la estructura protectora."},{"s":"horq_auto","t":"Autocuidado: tú decides","x":"Con la grúa, las acciones inseguras típicas son <b>cruzar apurado sin contacto visual</b> o mirando el celular, y <b>manejarla sin autorización</b>. La decisión segura: detenerte y esperar la señal, y si no estás autorizado, esperar al operador o avisar. Avisa también las condiciones inseguras: pasillos bloqueados, piso dañado o grúa con fallas."}],"quiz":[{"s":"horq_licencia","v":[{"q":"¿Quién puede operar la grúa horquilla?","o":["Quien tiene licencia clase D y autorización escrita","Cualquiera que tenga licencia de auto clase B vigente","Quien tenga licencia D, aunque no esté autorizado","Quien haya visto operarla durante un mes completo"],"w":"La empresa exige licencia clase D y autorización escrita."},{"q":"Tienes licencia clase D, pero la empresa no te ha dado autorización escrita. ¿Puedes operar la grúa?","o":["No: se necesitan ambas","Sí, la licencia basta","Sí, si es solo dentro de la planta","Sí, si un operador me acompaña"],"w":"La licencia sola no basta."},{"q":"¿Qué exige la empresa para operar la grúa horquilla?","o":["Licencia clase D y autorización escrita","Solo la cédula de identidad","Licencia clase B y certificado médico","Solo la autorización verbal del jefe"],"w":"Son los dos requisitos para operarla."}]},{"s":"under","v":[{"q":"Un trabajador pasa caminando bajo las horquillas levantadas con carga. ¿Qué está mal?","o":["Nadie pasa ni se queda bajo una carga levantada","Nada, porque la grúa está detenida en ese momento","Solo que no lleva casco al pasar por debajo","Nada, si pasa rápido y el operador lo está viendo"],"w":"La carga puede deslizarse en segundos."},{"q":"La grúa tiene un pallet levantado justo en tu camino. ¿Qué haces?","o":["Rodeo a distancia o espero que baje la carga","Paso agachado por debajo para no golpearme","Paso rápido mientras la grúa está quieta","Paso por debajo solo si llevo el casco puesto"],"w":"Bajo una carga levantada no se pasa nunca."},{"q":"¿Por qué no se pasa bajo una carga levantada?","o":["Un pallet o bin puede deslizarse y caer en segundos","Solo porque le estorba la vista al operador de la grúa","Está prohibido solo dentro de la bodega, no en el patio","La carga se puede ensuciar o contaminar con el roce"],"w":"Aunque la grúa esté detenida, la carga puede caer."}]},{"s":"horq_ciego","v":[{"q":"Si el operador va concentrado, puedo cruzar rápido por delante aunque no me haya visto.","vf":false,"w":"Falso. Siempre contacto visual y esperar la señal del operador."},{"q":"¿Cuándo sabes que el operador te vio?","o":["Cuando hay contacto visual y te hace una señal","Cuando escuchas el motor y la bocina de la grúa","Cuando la grúa va despacio y con luces encendidas","Cuando llevas chaleco reflectante y estás cerca"],"w":"Solo el contacto visual y la señal lo confirman."},{"q":"¿Por qué el operador de la grúa no ve todo a su alrededor?","o":["La carga, el mástil y la parte trasera le tapan la vista","Opera siempre en reversa y mirando hacia atrás del todo","La cabina es oscura y los vidrios suelen estar sucios","La grúa no tiene espejos laterales como los camiones"],"w":"Esos puntos ciegos esconden a los peatones."}]},{"s":"horquilla_vision","v":[{"q":"La carga es alta y no deja ver hacia adelante. El operador debe:","o":["Avanzar en reversa, mirando hacia donde va","Avanzar de frente, tocando la bocina seguido","Levantar la carga para ver por debajo de ella","Avanzar de frente, asomándose por el costado"],"w":"Con la vista tapada se conduce en reversa, mirando el recorrido."},{"q":"Llevas un pallet alto de cajas y no ves al frente. ¿Cómo avanzas?","o":["En reversa, mirando el recorrido","De frente, más lento y con bocina","De frente, con la carga más arriba","De frente, guiándome por el sonido"],"w":"Levantar la carga además hace inestable la grúa."},{"q":"Conducir de frente con la vista tapada por la carga es:","o":["Una acción insegura: se avanza en reversa","Aceptable si se va tocando la bocina","Aceptable si se va a baja velocidad","Correcto si el pasillo es ancho y libre"],"w":"Si no ves, no puedes evitar a un peatón."}]},{"s":"horquilla_personas","v":[{"q":"La grúa horquilla nunca se usa para elevar personas, ni siquiera sobre un pallet.","vf":true,"w":"Verdadero. Para altura se usa el equipo habilitado para personas."},{"q":"Necesitas sacar una caja de un rack alto. Un compañero te ofrece subirte en un pallet sobre las horquillas. ¿Qué haces?","o":["No acepto y uso el equipo habilitado para personas","Acepto si el operador sube la carga muy despacio","Acepto si me afirmo bien del mástil de la grúa","Acepto si es solo un momento y bajo de inmediato"],"w":"Nadie viaja ni se eleva sobre las horquillas."},{"q":"¿Quién puede viajar sobre las horquillas o sobre la carga?","o":["Nadie","Solo el ayudante del operador","Quien use arnés","Quien vaya bien afirmado"],"w":"Es una prohibición sin excepciones."}]},{"s":"horq_preuso","v":[{"q":"En la revisión antes de partir, la bocina no funciona. ¿Qué corresponde?","o":["No usar la grúa y avisar a la jefatura","Usarla igual, pero con más cuidado en los cruces","Repararla con lo que encuentre en el taller","Usarla solo en el patio, donde hay más espacio"],"w":"Grúa con falla, grúa detenida."},{"q":"¿Qué revisa el operador en el check list antes de partir?","o":["Frenos, bocina, luces, neumáticos, horquillas, cadenas y fugas","Solo el nivel de combustible o la carga de la batería del equipo","Solo que el motor encienda bien y que la grúa avance y retroceda","Solo la limpieza de la cabina y el estado del asiento"],"w":"Cada punto puede causar un accidente si falla."},{"q":"Al revisar la grúa encuentras una fuga de aceite. ¿Qué haces?","o":["La dejo detenida y aviso a la jefatura","La uso y aviso al final del turno","Limpio la mancha y la uso con cuidado","La uso solo para mover cargas livianas"],"w":"Una falla, aunque parezca menor, detiene la grúa."}]},{"s":"horq_patio","v":[{"q":"La grúa está cargando un camión en el patio. ¿Dónde debes estar?","o":["Fuera de la zona de maniobra, hasta que el operador me indique","Entre la grúa y el camión, para guiar al operador de cerca","Detrás de la grúa, pegado a ella para ver cómo carga","Junto a la rampa del camión, para ayudar a acomodar la carga"],"w":"Se espera fuera de la zona de maniobra."},{"q":"¿Qué condición debe cumplir el camión antes de que la grúa lo cargue?","o":["Estar detenido y frenado","Tener el motor en marcha por si hay que moverlo","Tener las puertas cerradas","Estar avanzando despacio"],"w":"Un camión que se mueve puede botar la grúa o atrapar a alguien."},{"q":"¿Por qué nunca te pones entre la grúa y el camión o un rack?","o":["Puedes quedar atrapado entre la máquina y algo fijo","Le estorbas la vista al chofer del camión que espera","Ese espacio está reservado solo para los choferes","Te puedes ensuciar con la carga que se está subiendo"],"w":"Entre la máquina y algo fijo no hay escape."}]},{"s":"horq_q_horq","v":[{"q":"Al estacionar la grúa, las horquillas deben quedar:","o":["Apoyadas en el piso","A media altura","Levantadas con la carga","A la altura de la rodilla"],"w":"Horquillas al piso, freno puesto, motor apagado y llave fuera."},{"q":"Al dejar estacionada la grúa, el operador debe:","o":["Bajar horquillas, poner freno, apagar y sacar la llave","Dejarla encendida para no perder tiempo al volver a usarla","Dejar la llave puesta para que el siguiente operador parta","Dejarla frente al extintor, donde todos la vean"],"w":"Así nadie la mueve sin autorización ni se tropieza."},{"q":"¿Dónde no se debe estacionar la grúa?","o":["Frente a salidas, extintores o en pasillos","En su lugar demarcado para estacionar","Lejos de los pasillos de tránsito peatonal","En su área de carga habilitada y señalizada"],"w":"Bloquear salidas o extintores impide actuar en una emergencia."}]},{"s":"horq_q_vuelco","v":[{"q":"Si la grúa comienza a volcarse, el operador debe:","o":["Quedarse dentro con cinturón e inclinarse al lado contrario","Saltar rápido hacia afuera, lejos de la máquina","Soltar el volante, agacharse y cubrirse la cabeza","Saltar hacia el lado de la caída para llegar antes al piso"],"w":"Saltar es lo más peligroso: la máquina puede aplastarte."},{"q":"¿Por qué el cinturón es obligatorio en la grúa horquilla?","o":["En un vuelco te mantiene dentro de la estructura","Solo porque lo exige Carabineros en la vía pública","Evita que la carga se caiga de las horquillas","Ayuda a frenar la grúa en las pendientes"],"w":"Fuera de la estructura, la grúa te puede aplastar."},{"q":"Si la grúa se vuelca, lo más peligroso es saltar fuera de ella.","vf":true,"w":"Verdadero. Se queda adentro con el cinturón puesto."}]},{"s":"horq_q_ratito","v":[{"q":"Un compañero te pide mover la grúa “un ratito” porque el operador no está. No tienes autorización. ¿Qué haces?","o":["No la opero y aviso a la jefatura","La muevo con cuidado, es solo un metro","La muevo sin cinturón, porque es corto","La muevo si el compañero me guía"],"w":"Sin licencia y autorización escrita, no se opera."},{"q":"El operador dejó la grúa con la llave puesta y necesitas mover un pallet. No estás autorizado. ¿Qué haces?","o":["Espero al operador o aviso a la jefatura","La muevo solo un par de metros, con cuidado","La muevo si no hay nadie caminando cerca","La muevo con el cinturón puesto y despacio"],"w":"La llave puesta no es una autorización."},{"q":"Operar la grúa sin autorización, aunque sea “un ratito”:","o":["Es una acción insegura y no se hace","Está permitido si se va despacio","Está permitido dentro de la bodega","Está permitido si hay urgencia de despacho"],"w":"Es una de las acciones inseguras típicas con la grúa."}]}]},{"id":"patio_romana","sec":"planta","title":"Patio, romana y bodega: peatones y vehículos","thumb":"pe_romana","learn":[{"s":"transito_intro","t":"Un patio compartido","x":"En el patio, la romana y la bodega circulan <b>camiones, grúas horquilla, autos y personas</b> en el mismo espacio. Los atropellos ocurren sobre todo <b>en retroceso y en los puntos ciegos</b>. Conductores: respeten la velocidad indicada y la señalización. Peatones: nunca den por hecho que el conductor los vio."},{"s":"transito_ruta","t":"Ruta peatonal, chaleco y sin celular","x":"<ul><li>Camina por la <b>ruta peatonal demarcada</b>, aunque sea más larga.</li><li>Usa <b>chaleco reflectante</b>.</li><li><b>Sin celular ni audífonos</b> al caminar: no escucharías alarmas de retroceso ni bocinas. Si necesitas mirar el celular, detente en un lugar seguro fuera del tránsito.</li><li>No cortes camino entre camiones estacionados.</li></ul>"},{"s":"pe_romana","t":"La romana","x":"Durante el pesaje, <b>solo el camión</b> está sobre la plataforma: nadie se sube ni camina por ella, ni por el borde. Una persona encima altera el peso y queda expuesta a ser atropellada. El chofer baja solo con el camión <b>detenido y frenado</b>, de frente al camión, por los peldaños y con <b>tres puntos de apoyo</b>: dos manos y un pie, o dos pies y una mano. <b>Nunca salta</b> de la cabina: es causa común de torceduras y fracturas.","k":"Nunca te subas a la romana durante el pesaje."},{"s":"camion_conduccion_ciegos","t":"Puntos ciegos del camión","x":"Un camión no ve lo que está <b>justo detrás, delante del parachoques ni a su costado derecho</b>. Mientras más grande el camión, más grandes esas zonas. Si no ves los ojos del chofer en su espejo, él no te ve a ti, aunque esté de frente o con el motor encendido."},{"s":"camion_conduccion_retro_ok","t":"Camiones en retroceso","x":"El retroceso es el momento de más atropellos. La alarma avisa, pero <b>no protege</b>: nadie pasa por detrás de un camión que retrocede. Ubícate fuera de su recorrido y visible para el chofer. Chofer: si no ves bien atrás, usa un <b>señalero a la vista</b> o bájate a mirar antes de retroceder.","k":"Nunca pases detrás de un camión que retrocede."},{"s":"transito_contacto","t":"Contacto visual antes de cruzar","x":"Antes de cruzar frente a un camión o una grúa: <b>detente, busca contacto visual</b> con el conductor y <b>espera su señal</b>. El chaleco te hace visible, pero no reemplaza el contacto visual. <b>Nunca pases entre un camión y un andén</b>: un movimiento del camión te puede atrapar."}],"quiz":[{"s":"pe_romana","v":[{"q":"Durante el pesaje en la romana, solo el camión debe estar sobre la plataforma.","vf":true,"w":"Verdadero. Nadie se sube ni camina por la plataforma."},{"q":"Un camión se está pesando en la romana. ¿Quién puede estar sobre la plataforma?","o":["Solo el camión","El chofer, revisando la carga","Un ayudante, si va por el borde","Cualquiera, si el camión está detenido"],"w":"Sobre la romana, solo el camión."},{"q":"¿Por qué nadie debe subirse a la romana durante el pesaje?","o":["Altera el peso y queda expuesto a ser atropellado","Ensucia la plataforma y la balanza con barro","Solo los choferes pueden subir a la romana a revisar","La romana se descalibra con el frío y la humedad del suelo"],"w":"Es un riesgo de atropello y un error de pesaje."}]},{"s":"camion_carga_subir_ok","v":[{"q":"El chofer debe bajarse del camión en la romana. ¿Cómo lo hace?","o":["Detenido y frenado, de frente y con tres puntos de apoyo","Saltando desde la cabina para ganar tiempo en la fila","De espaldas al camión, con una mano ocupada con papeles","Con el motor en marcha, por si debe avanzar en la romana"],"w":"Tres puntos de apoyo evitan caídas al bajar."},{"q":"¿Qué significa bajar con tres puntos de apoyo?","o":["Dos manos y un pie, o dos pies y una mano, en contacto","Bajar en tres saltos cortos, de un peldaño a otro","Pisar tres peldaños a la vez para bajar más rápido","Afirmarse con una mano y bajar rápido, de espaldas al camión"],"w":"Siempre tres apoyos en contacto con el vehículo."},{"q":"Saltar desde la cabina o la plataforma del camión:","o":["Causa torceduras y fracturas: se baja por los peldaños","Es seguro si se cae con las rodillas bien dobladas","Es aceptable si la cabina no está muy alta del suelo","Ahorra tiempo y no tiene riesgo si se hace con cuidado"],"w":"Se baja de frente, por los peldaños y con tres puntos de apoyo."}]},{"s":"camion_conduccion_ciegos","v":[{"q":"¿Dónde están los puntos ciegos de un camión?","o":["Justo detrás, delante del parachoques y a su derecha","Solo dentro de la cabina, por los asientos y el tablero","Solo en el costado del chofer, bajo su ventana","Solo sobre el techo de la carga y en la parte alta"],"w":"Ahí el chofer no ve a un peatón."},{"q":"¿Cómo sabes si el chofer de un camión te puede ver?","o":["Si ves sus ojos en su espejo","Si escuchas el motor encendido","Si el camión tiene las luces prendidas","Si estás a dos metros del camión"],"w":"Si no ves sus ojos, no te ve."},{"q":"Estás parado justo delante del parachoques de un camión detenido. ¿Te ve el chofer?","o":["Probablemente no: es un punto ciego","Sí, porque está justo de frente a él","Sí, si el camión es alto y tiene buena vista","Sí, si el motor está encendido y con luces"],"w":"Delante del parachoques es una de las zonas que no ve."}]},{"s":"camion_conduccion_retro_mal","v":[{"q":"Un camión retrocede con alarma en el patio. ¿Dónde te ubicas?","o":["Fuera de su recorrido, visible para el chofer","Detrás del camión, para guiarlo bien de cerca","Detrás, porque la alarma ya avisa que viene","A un costado, pegado a la carrocería del camión"],"w":"Detrás de un camión que retrocede está su mayor punto ciego."},{"q":"El chofer va a retroceder y no ve bien atrás. ¿Qué corresponde?","o":["Usar un señalero a la vista o bajarse a mirar","Retroceder rápido, tocando la bocina varias veces","Confiar en la alarma de retroceso y en los espejos","Retroceder siguiendo los gritos de quien esté atrás"],"w":"Si no ve, el chofer necesita un señalero o mirar él mismo."},{"q":"La alarma de retroceso basta para proteger a quien pasa detrás de un camión.","vf":false,"w":"Falso. La alarma avisa, pero no protege: nadie pasa por detrás."}]},{"s":"transito_celular","v":[{"q":"Caminas por el patio y te llega un mensaje. ¿Qué haces?","o":["Me detengo en un lugar seguro, fuera del tránsito, a mirarlo","Lo leo caminando, siempre que vaya por la ruta peatonal marcada","Lo contesto mientras cruzo rápido hacia la bodega","Lo escucho con audífonos mientras sigo caminando"],"w":"Con la vista en el celular no ves los vehículos."},{"q":"¿Qué no debes hacer al caminar por el patio?","o":["Usar el celular o audífonos","Usar chaleco reflectante","Caminar por la ruta peatonal","Hacer contacto visual con los choferes"],"w":"Distraen la vista y el oído."},{"q":"¿Por qué no se usan audífonos en el patio?","o":["Porque no escuchas alarmas de retroceso ni bocinas","Porque se pueden caer y perder entre los camiones","Porque gastan la batería del celular durante el turno","Porque distraen solo a los choferes, no a los peatones"],"w":"Necesitas oír las advertencias de los vehículos."}]},{"s":"transito_cortaMal","v":[{"q":"Para llegar antes a la bodega, un compañero cruza entre dos camiones estacionados. ¿Qué es lo correcto?","o":["Ir por la ruta peatonal, aunque sea más largo","Cruzar entre los camiones si están apagados","Cruzar rápido si no hay grúas cerca","Pasar agachado bajo el acoplado"],"w":"Un camión estacionado puede moverse y no te ve."},{"q":"¿Por dónde se camina en el patio?","o":["Por la ruta peatonal demarcada, con chaleco reflectante","Por el centro del camino, donde hay más espacio para todos","Por cualquier lado, siempre que haya buena luz en el patio","Por detrás de los camiones estacionados, que están quietos"],"w":"La ruta peatonal separa a las personas de los vehículos."},{"q":"¿Por qué nunca se pasa entre un camión y un andén?","o":["Un movimiento del camión te puede atrapar contra el andén","El andén es solo para la carga y la descarga de productos","Solo está prohibido de noche, cuando hay poca luz en el patio","Ensucia la ropa de trabajo con la grasa del camión"],"w":"Entre el camión y algo fijo no hay escape."}]},{"s":"transito_contacto","v":[{"q":"Vas a cruzar frente a un camión detenido con el motor encendido. ¿Qué haces?","o":["Busco contacto visual con el chofer y espero su señal","Cruzo rápido, porque está detenido y no se moverá","Paso por detrás del camión, donde no hay peligro","Cruzo sin esperar si llevo chaleco reflectante puesto"],"w":"Si no te ve, te puede atropellar."},{"q":"¿Cuál es el orden correcto antes de cruzar frente a un vehículo?","o":["Detenerme, buscar contacto visual y esperar la señal","Levantar la mano para avisar y cruzar de inmediato","Cruzar primero y luego hacer contacto visual","Esperar que acelere el motor y cruzar enseguida"],"w":"Primero me ve, después cruzo."},{"q":"¿Basta el chaleco reflectante para cruzar frente a un camión?","o":["No: igual necesito contacto visual y la señal del chofer","Sí, porque el chofer siempre ve los chalecos reflectantes","Sí, si es de día y hay buena luz en el patio","Sí, si el camión va lento y tiene las luces encendidas"],"w":"El chaleco ayuda, pero no reemplaza el contacto visual."}]}]},{"id":"mosqueta","sec":"mosqueta","title":"Deshidratado de mosqueta: hornos, carros y embandejado","thumb":"pe_horno","learn":[{"s":"pe_descarga","t":"Recepción en el patio","x":"La mosqueta llega en <b>camiones y bins</b>. En el patio de descarga se mezclan camiones, grúa horquilla y personas.<ul><li>Camina por la ruta peatonal y usa <b>chaleco reflectante</b>.</li><li>Nunca te pongas detrás de un camión que retrocede: ubícate fuera de su recorrido y visible para el chofer.</li><li>Mientras la grúa baja un bin, aléjate: <b>nunca bajo la carga levantada</b>.</li></ul>"},{"s":"pe_mosq_vest","t":"Tu vestimenta en deshidratado","x":"Cotona verde y gorro {EMP} con cofia. Los guantes según la labor:<ul><li><b>Cabritilla</b>: hornos y carros calientes.</li><li><b>Multiflex</b>: selección y embandejado.</li></ul>Mascarilla y lentes cuando haya pelusa. El guante equivocado no protege: el multiflex no aísla del calor de un carro recién salido del horno."},{"s":"pe_seleccion","t":"Líneas de selección","x":"En las líneas seleccionas desde la cinta en movimiento: esa es tu tarea. Lo que <b>no se hace</b> es intervenirla en movimiento: si se traba, para destrabar, limpiar o ajustar, <b>se detiene y se bloquea</b>. <b>Nada suelto</b> (anillos, pulseras, bufandas), pelo tomado y manos fuera de rodillos. Conoce la <b>parada de emergencia</b>: sirve para detener la línea de inmediato si alguien queda atrapado.","k":"Detén y bloquea la cinta antes de destrabarla."},{"s":"pe_embandejado","t":"Embandejado","x":"La mesa debe quedar a la <b>altura de tus codos</b>, para no agacharte ni levantar los brazos. Llena la bandeja en la mesa, no en el aire. Bandejas grandes o llenas: <b>entre dos o con carro</b>. No apiles bandejas sobre la altura de tus hombros."},{"s":"pe_carro","t":"Carros de bandejas","x":"Un carro cargado pesa mucho y cuesta frenarlo. <b>Empújalo, no lo tires</b>, a velocidad de paso y mirando adelante. Antes de moverlo, revisa las <b>ruedas</b> y que las bandejas estén bien puestas. Cuidado con los pies y con atrapar las manos entre el carro y la pared o la puerta del horno."},{"s":"pe_horno","t":"Hornos de secado","x":"Dentro del horno hay <b>aire muy caliente</b>, y las bandejas y carros queman. Antes de entrar o sacar carros: <b>espera el tiempo indicado, ventila, usa guantes de cabritilla y avisa</b>. Nunca entres a un horno funcionando, ni siquiera para acomodar una bandeja. Si la puerta o el quemador fallan, avisa a tu jefatura.","k":"Nunca entres a un horno funcionando."},{"s":"pe_pelusa","t":"Polvo y pelusa","x":"La mosqueta seca suelta <b>pelusa que irrita ojos, piel y garganta</b>. Usa la mascarilla y los lentes indicados, manga larga y guantes. No te frotes los ojos con los guantes puestos ni te sacudas la ropa con aire comprimido. <b>Lávate bien al salir</b>."},{"s":"pe_calor","t":"Calor y turnos largos","x":"En temporada los turnos son largos y la zona de hornos es calurosa: <b>toma agua seguido aunque no tengas sed, haz las pausas y avisa</b> si sientes mareo, dolor de cabeza o náuseas. El cansancio aumenta los accidentes: si te sientes agotado, dilo a tu jefatura antes de seguir con tareas de riesgo."},{"s":"pe_hanta","t":"Bodegas y bins guardados","x":"La mosqueta viene del campo y los bins o bodegas cerrados pueden tener roedores. Antes de abrir una bodega cerrada por tiempo: <b>ventila al menos 30 minutos</b>. Para limpiar, <b>humedece con agua y cloro, nunca barras en seco</b>, y usa mascarilla y guantes. Si ves fecas o roedores, avisa a tu jefatura."}],"quiz":[{"s":"pe_carro","v":[{"q":"¿Cómo se mueve un carro de bandejas cargado?","o":["Empujándolo, despacio y mirando adelante","Tirándolo de espaldas para guiarlo","Al trote, para que agarre impulso","Tirándolo con una mano mientras camino"],"w":"Empujar te deja ver el camino y frenar mejor."},{"q":"Antes de mover un carro de bandejas cargado, revisas:","o":["Las ruedas y que las bandejas estén bien puestas","Solo que el horno de secado ya esté apagado","Solo que el carro esté limpio y sin restos de pelusa","Que la puerta del horno haya quedado bien cerrada"],"w":"Una rueda mala o una bandeja suelta pueden botar el carro."},{"q":"Llevas un carro y debes pasar junto a una pared. ¿Qué cuidas?","o":["No atrapar manos ni pies entre el carro y la pared","Ir más rápido para pasar luego por la parte angosta","Tirarlo de espaldas para ir viendo la pared","Soltarlo un poco antes para que siga solo por la inercia"],"w":"Entre el carro y la pared se producen atrapamientos."}]},{"s":"pe_horno","v":[{"q":"Antes de sacar un carro del horno de secado debes:","o":["Esperar, ventilar, usar guantes de cabritilla y avisar","Entrar rápido, sin guantes, para no perder el calor","Entrar con el horno funcionando a media potencia","Abrir la puerta y entrar de inmediato a sacar el carro"],"w":"El aire, las bandejas y los carros queman."},{"q":"Un compañero quiere entrar al horno funcionando a acomodar una bandeja. ¿Qué le dices?","o":["Que no: se detiene, se espera, se ventila y se avisa","Que entre rápido, pero con guantes de cabritilla puestos","Que entre solo si alguien le sostiene la puerta abierta","Que entre solo hasta la mitad, sin meterse completo"],"w":"Nunca se entra a un horno funcionando."},{"q":"Antes de entrar al horno de secado basta con usar guantes; no hace falta avisar.","vf":false,"w":"Falso. Se espera, se ventila, se usan guantes y se avisa."}]},{"s":"pe_pelusa","v":[{"q":"La pelusa de la mosqueta seca puede irritar los ojos, la piel y la garganta.","vf":true,"w":"Verdadero. Por eso se usan mascarilla, lentes, manga larga y guantes."},{"q":"¿Qué protección usas al trabajar con mosqueta seca con pelusa?","o":["Mascarilla y lentes indicados, manga larga y guantes","Solo el gorro con cofia y la cotona de trabajo habitual","Solo los guantes de cabritilla y el delantal impermeable","Solo la mascarilla, sin lentes ni manga larga"],"w":"La pelusa afecta ojos, piel y garganta."},{"q":"Terminas un turno con mucha pelusa. ¿Qué haces?","o":["Me lavo bien antes de salir","Me sacudo la ropa con aire comprimido","Me froto los ojos para sacar la pelusa","Me voy así, es solo polvo vegetal"],"w":"Lavarse evita seguir irritado fuera del turno."}]},{"s":"pe_descarga","v":[{"q":"Un camión retrocede en el patio de descarga. ¿Dónde te ubicas?","o":["Fuera de su recorrido, visible para el chofer","Detrás del camión, para guiarlo bien de cerca","Detrás, porque la alarma ya avisa que viene","A un costado, pegado a la carrocería del camión"],"w":"Detrás de un camión que retrocede está su mayor punto ciego."},{"q":"En el patio de descarga de mosqueta, ¿qué usas siempre?","o":["Chaleco reflectante y la ruta peatonal","Solo guantes de cabritilla y la cotona","Solo el gorro con cofia y la mascarilla","Lentes oscuros y fonos para el ruido"],"w":"Te hacen visible y te separan de los vehículos."},{"q":"La grúa horquilla baja un bin de mosqueta del camión. ¿Dónde te ubicas?","o":["Lejos, nunca bajo la carga levantada","Bajo el bin para guiarlo","Junto a las horquillas para afirmar el bin","Arriba del camión, empujando el bin"],"w":"Un bin puede deslizarse en segundos."}]},{"s":"pe_embandejado","v":[{"q":"¿A qué altura debe quedar la mesa de embandejado?","o":["A la altura de los codos","A la altura de las rodillas","Sobre los hombros","A la altura del mentón"],"w":"Así trabajas sin agacharte ni levantar los brazos."},{"q":"Una bandeja llena es grande y pesada. ¿Cómo la mueves?","o":["Entre dos o con carro","Sola, levantándola sobre la cabeza","Arrastrándola por el suelo","Sola, apoyada en la cadera"],"w":"Bandeja llena: con carro o entre dos."},{"q":"¿Hasta qué altura apilas bandejas?","o":["No más arriba de tus hombros","Hasta donde alcances con los brazos estirados","Hasta el tope del carro, sin importar tu estatura","Hasta que empiecen a tambalearse"],"w":"Apilar alto obliga a levantar los brazos y puede botar la pila."}]},{"s":"pe_mosq_vest","v":[{"q":"Vas a sacar un carro del horno de secado. ¿Qué guantes usas?","o":["Guantes de cabritilla","Guantes multiflex","Guantes de nitrilo delgados","Sin guantes, para mejor agarre"],"w":"Para hornos y carros calientes: cabritilla."},{"q":"Para seleccionar y embandejar mosqueta, ¿qué guante corresponde?","o":["Multiflex","Cabritilla","De soldador","De nitrilo largo"],"w":"Cada labor, su guante."},{"q":"¿Cuál es la vestimenta base en deshidratado?","o":["Cotona verde y gorro de la empresa con cofia","Ropa propia abrigada y un gorro de lana limpio","Overol azul de mantención y casco de seguridad","Cotona blanca, sin gorro ni cofia para el pelo"],"w":"Es la vestimenta indicada para el área."}]},{"s":"pe_seleccion","v":[{"q":"La cinta de selección se traba con una rama. ¿Qué haces?","o":["Detengo y bloqueo la línea antes de destrabarla","La saco con la mano mientras la cinta sigue andando","La empujo con un palo largo sin detener la cinta","Tiro fuerte de la rama para soltarla rápido y seguir"],"w":"La cinta no se interviene en movimiento."},{"q":"¿Qué corresponde en la línea de selección?","o":["Nada suelto y el pelo tomado","Anillos y pulseras bajo el guante","El pelo suelto bajo el gorro","Bufanda para el frío"],"w":"Lo suelto puede ser atrapado por rodillos."},{"q":"¿Para qué debes conocer la parada de emergencia de tu línea?","o":["Para detenerla de inmediato si alguien queda atrapado","Para pararla cada vez que quieras tomar un descanso","Para regular la velocidad de la cinta según la fruta","Para usarla en lugar del bloqueo cuando se limpia"],"w":"Es el modo más rápido de detener la línea en una emergencia."}]}]},{"id":"embandejado","sec":"mosqueta","title":"Patio de embandejado","thumb":"pe_embandejado_patio","learn":[{"s":"pe_embandejado_patio","t":"El patio de embandejado","x":"En el patio se embandeja la mosqueta y se arman los carros que van a los hornos. Ahí se juntan los riesgos: <ul><li>Tareas repetitivas de manos y muñecas.</li><li>Bandejas y rumas que pesan.</li><li>Carros en movimiento y grúa horquilla.</li><li>Sol, calor y piso con restos de fruta.</li></ul>Mantén el patio ordenado: pasillos libres, bandejas vacías apiladas en su lugar y restos de fruta barridos para no resbalar."},{"s":"pe_mosq_vest","t":"Tu vestimenta en el patio","x":"En embandejado usas <b>cotona verde y gorro {EMP} con cofia</b>, con el pelo completamente dentro. Los guantes dependen de la tarea:<ul><li><b>Multiflex</b>: selección y embandejado.</li><li><b>Cabritilla</b>: carros y bandejas calientes que salen del horno.</li></ul>El multiflex no aísla del calor. Tu EPP es gratis: revísalo antes de usarlo y pide recambio si está roto."},{"s":"pe_embandejado","t":"Mesa y postura","x":"Embandejar es repetir el mismo movimiento cientos de veces, y eso puede lesionar muñecas, hombros y espalda (protocolo TMERT).<ul><li>Mesa a la <b>altura de tus codos</b>: ni agachado ni con los brazos arriba.</li><li>Llena la bandeja apoyada en la mesa, no en el aire.</li><li>Muñeca recta y bandeja cerca del cuerpo.</li><li>Alterna tareas y haz las pausas indicadas.</li></ul>Si sientes dolor u hormigueo que se repite, avísalo a tiempo."},{"s":"pe_bandeja_dos","t":"Bandejas pesadas o apiladas","x":"Una bandeja llena o una ruma de bandejas se mueve <b>entre dos o con carro</b>, nunca sola y apurada. La Ley 20.949 fija un máximo de <b>25 kg</b> para hombres y <b>20 kg</b> para mujeres y menores de 18; las embarazadas no cargan. Al levantar: cerca del cuerpo, espalda recta y fuerza con las piernas, sin girar la cintura. No apiles sobre la altura de tus hombros y deja las rumas parejas y estables.","k":"Bandeja pesada: entre dos o con carro."},{"s":"pe_carro","t":"Carros","x":"Un carro con bandejas pesa mucho y cuesta frenarlo.<ul><li><b>Empújalo, no lo tires</b>: así ves hacia dónde vas y no te pasa por encima de los pies.</li><li>A velocidad de paso, mirando adelante.</li><li>Antes de moverlo revisa las <b>ruedas</b> y que las bandejas estén bien puestas.</li><li>Cuidado con atrapar las manos entre el carro y la pared o la puerta del horno.</li></ul>Carro con rueda trabada o dañada: no se usa, se avisa."},{"s":"horq_contacto","t":"Grúa horquilla en el patio","x":"La grúa trae y retira bins y pallets por el patio. El operador tiene <b>puntos ciegos</b> y la máquina no frena como un auto.<ul><li>Camina por la ruta peatonal.</li><li>Antes de cruzar, <b>detente, busca contacto visual</b> con el operador y espera su señal.</li><li>Nunca te pongas bajo una carga levantada ni entre la grúa y un pallet o una pared.</li></ul>Escuchar el motor no significa que el operador te vio.","k":"Nunca pases bajo una carga levantada."},{"s":"uv_ropa","t":"Sol","x":"Al aire libre la radiación UV daña piel y ojos, y es mayor <b>entre las 10 y las 17 horas</b>, también en días nublados. Protégete cada día:<ul><li>Jockey legionario o con cubrenuca y lentes con filtro UV.</li><li>Manga larga.</li><li>Bloqueador <b>FPS 30 o más</b>, aplicado antes de salir y repetido cada 2 a 3 horas.</li><li>Agua seguido y pausas a la sombra.</li></ul>"}],"quiz":[{"s":"pe_embandejado","v":[{"q":"¿A qué altura debe quedar la mesa de embandejado?","o":["A la altura de los codos","A la altura de la cintura, algo más baja","A la altura del pecho, para ver mejor","A la altura que tenga, si haces pausas"],"w":"A la altura de los codos no te agachas ni levantas los brazos."},{"q":"La mesa te obliga a trabajar con los hombros levantados. ¿Qué corresponde?","o":["Avisar para dejarla a la altura de tus codos","Seguir así y hacer más pausas durante el turno","Llenar las bandejas en el aire, más abajo","Cambiarte a otra mesa sin decir nada"],"w":"La mesa debe quedar a la altura de los codos; si no, se avisa para ajustarla."},{"q":"Para embandejar sin lesionarte, la mesa debe quedar:","o":["A la altura de tus codos","Bajo tus rodillas, para apoyar la bandeja","Sobre tus hombros, para no agacharte","A la altura de la mesa del compañero"],"w":"Codos: postura neutra, sin agacharse ni subir los brazos."}]},{"s":"pe_bandeja_dos","v":[{"q":"¿Cómo se mueve una bandeja llena y pesada?","o":["Entre dos o con carro","Solo, pero con la espalda bien recta","Arrastrándola por el piso hasta la ruma","Solo, tomándola rápido para no cansarte"],"w":"Bandeja pesada: entre dos o con carro."},{"q":"Tu compañero está ocupado y debes mover una ruma de bandejas llenas. ¿Qué haces?","o":["Uso un carro o espero ayuda","La llevo solo, de a poco y despacio","La arrastro por el piso del patio","Saco algunas bandejas y la llevo solo igual"],"w":"Una ruma pesada se mueve con carro o entre dos, sin improvisar."},{"q":"¿Cuál es la forma correcta de trasladar una ruma de bandejas llenas?","o":["Entre dos o en carro","Solo, abrazándola contra el pecho","Solo, en dos viajes rápidos","Empujándola por el piso con el pie"],"w":"Carga pesada o voluminosa: entre dos o con carro."}]},{"s":"pe_embandejado_patio","v":[{"q":"¿Hasta qué altura se pueden apilar las bandejas en el patio?","o":["Hasta la altura de los hombros","Hasta donde alcances con los brazos","Hasta la altura de la cabeza","Sin límite si la ruma está pareja"],"w":"Sobre los hombros se pierde el control de la carga y la ruma se vuelve inestable."},{"q":"Para terminar antes, un compañero apila bandejas por sobre su cabeza. ¿Qué es lo correcto?","o":["Apilar solo hasta los hombros, en rumas parejas","Seguir apilando si la ruma queda bien derecha","Subirse a una caja para apilar más alto","Apilar alto, pero solo con bandejas vacías"],"w":"La regla es no apilar sobre la altura de los hombros."},{"q":"Las bandejas se apilan como máximo hasta la altura de los hombros, en rumas parejas.","vf":true,"w":"Verdadero. Más arriba se pierde el control y la ruma puede caer."}]},{"s":"pe_carro","v":[{"q":"¿Cómo se mueve un carro con bandejas?","o":["Empujándolo, a paso y mirando adelante","Tirándolo de espaldas para guiarlo mejor","Corriendo, para aprovechar el impulso","Tirándolo de lado, con una mano"],"w":"Empujar permite ver el camino y evita que el carro te pase por los pies."},{"q":"Vas a mover un carro y notas que una rueda se traba. ¿Qué haces?","o":["No lo uso y aviso","Lo muevo tirándolo con más fuerza","Lo muevo solo si va con poca carga","Lo empujo entre dos para vencer la rueda"],"w":"Un carro con ruedas dañadas no se usa: se avisa."},{"q":"Tirar el carro hacia ti es más seguro que empujarlo, porque lo controlas mejor.","vf":false,"w":"Falso. Se empuja: ves hacia dónde vas y proteges tus pies."}]},{"s":"horq_contacto","v":[{"q":"La grúa horquilla pasa por el patio y debes cruzar. ¿Qué haces primero?","o":["Me detengo, busco contacto visual y espero su señal","Cruzo rápido, porque el peatón tiene preferencia","Cruzo si escucho el motor y la bocina","Cruzo por detrás de la grúa, donde no hay carga"],"w":"Solo sabes que te vio cuando te mira y te hace una señal."},{"q":"La grúa tiene un pallet levantado y está detenida. ¿Qué haces?","o":["La rodeo a distancia, nunca bajo la carga","Paso por debajo, porque está detenida","Paso rápido por debajo para no esperar","Me quedo cerca para ayudar a acomodar"],"w":"Nunca bajo una carga levantada: puede deslizarse en segundos."},{"q":"¿Cuál de estas acciones es peligrosa cerca de la grúa?","o":["Quedar entre la grúa y un pallet","Caminar por la ruta peatonal","Esperar la señal del operador","Rodear la carga a distancia"],"w":"Entre la grúa y un pallet o pared puedes quedar atrapado."}]},{"s":"uv_nublado","v":[{"q":"Trabajas en el patio un día nublado. ¿Te proteges del sol?","o":["Sí: legionario, manga larga, lentes y bloqueador","No, las nubes bloquean la radiación","Solo si sube la temperatura","Solo el bloqueador al llegar en la mañana"],"w":"La radiación UV atraviesa las nubes."},{"q":"Está nublado y un compañero sale al patio sin bloqueador ni lentes porque no hay sol. ¿Qué le dices?","o":["Que se proteja igual, la radiación UV pasa","Que tiene razón, con nubes no hace falta","Que basta con el jockey si está nublado","Que se ponga bloqueador solo si sale el sol"],"w":"Con nubes la radiación UV sigue llegando."},{"q":"En un día nublado no es necesario usar bloqueador ni lentes UV en el patio.","vf":false,"w":"Falso. La radiación UV llega igual con nubes."}]},{"s":"pe_mosq_vest","v":[{"q":"Debes sacar bandejas de un carro recién salido del horno. ¿Qué guantes usas?","o":["De cabritilla","Multiflex","Los mismos de embandejar","De nitrilo delgado"],"w":"El multiflex no aísla del calor; para carros calientes, cabritilla."},{"q":"¿Qué guante corresponde para embandejar mosqueta?","o":["Multiflex","De cabritilla","De soldador","Sin guantes, para tener más tacto"],"w":"Multiflex para selección y embandejado; cabritilla para lo caliente."},{"q":"Tu guante multiflex se rompió a media mañana. ¿Qué haces?","o":["Pido recambio, el EPP es gratis","Sigo así hasta terminar el turno","Lo compro yo al salir","Uso el guante de un compañero"],"w":"El EPP lo entrega la empresa sin costo y se cambia si se daña."}]}]},{"id":"polvo","sec":"mosqueta","title":"Polvo, pelusa y protección respiratoria","thumb":"pe_pelusa","learn":[{"s":"pe_pelusa","t":"El polvo que no se ve","x":"Al seleccionar, secar, moler o envasar mosqueta se libera <b>polvo fino y pelusa</b>, los pelitos de la semilla. Las partículas más dañinas son tan pequeñas que no se ven: flotan en el aire durante largo rato y se respiran sin que te des cuenta. Por eso la protección no depende de si ves polvo o no: depende de la tarea y del puesto."},{"s":"enfermedades_polvo","t":"Qué provoca","x":"<ul><li>Picazón y enrojecimiento de <b>ojos y piel</b>.</li><li>Estornudos, tos e irritación de garganta.</li><li>En algunas personas, <b>alergias o asma</b>, que pueden volverse permanentes.</li></ul>Si tus molestias se repiten turno tras turno, avisa a tu jefatura y a prevención: puede ser una enfermedad profesional. La ACHS evalúa si es de origen laboral y, si lo es, la atención es gratuita."},{"s":"pe_seleccion","t":"Primero, control en la fuente","x":"La mejor protección es que el polvo <b>no llegue al aire</b>: extracción y campanas funcionando, equipos cerrados y limpieza frecuente. La mascarilla es la última barrera, no la primera. Si la extracción no funciona, un equipo pierde polvo o una tapa quedó abierta, <b>avisa</b> a tu jefatura. No sigas trabajando como si nada en una nube de pelusa."},{"s":"orden_clean","t":"Limpiar sin levantar polvo","x":"<ul><li>Primero <b>aspira o humedece</b>, después recoge.</li><li>No barras en seco ni sacudas con un trapo seco.</li><li><b>Nunca soples con aire comprimido</b> sobre la ropa, el cuerpo o las mesas: el polvo queda flotando en el aire que respiras tú y tus compañeros, y el chorro puede herir ojos y piel.</li></ul>Usa la mascarilla también mientras limpias."},{"s":"pe_epp_give","t":"La mascarilla correcta","x":"Si tu puesto la exige, usa la <b>mascarilla o respirador para partículas certificado</b> que entrega {EMP}, <b>sin costo</b> para ti. Una mascarilla de tela, un pañuelo o la cofia sobre la boca <b>no filtran</b> las partículas finas. Agrega <b>lentes</b> cuando haya pelusa en el aire. Pide la mascarilla a tu jefatura antes de empezar, no a mitad del turno.","k":"Solo protege la mascarilla certificada."},{"s":"pe_epp_ok","t":"Bien ajustada","x":"<ul><li>Cubre <b>nariz y boca</b>, con los elásticos en su lugar.</li><li>Moldea el clip a tu nariz.</li><li>Prueba: tapa con las manos y aspira; debe hundirse un poco, sin aire por los bordes.</li><li>Con barba no sella bien: aféitate en la zona donde apoya.</li></ul>Cámbiala cuando esté sucia, húmeda, dañada o cueste respirar. Nunca la compartas."},{"s":"pe_filtro","t":"Ojos, piel y aseo","x":"<ul><li>Manga larga y guantes para que la pelusa no toque la piel.</li><li><b>No te frotes los ojos</b> con los guantes puestos.</li><li>Si te entra pelusa a los ojos, lávalos con agua limpia abundante, sin refregar.</li><li>Al salir, <b>lávate manos y cara</b> antes de comer, beber o fumar.</li></ul>Si la irritación sigue, avisa y consulta."},{"s":"pe_epp_mal","t":"Autocuidado: polvo","x":"Las acciones inseguras típicas: <b>bajarse la mascarilla al cuello \"un rato\"</b>, soplarse la ropa con aire, frotarse los ojos con guantes sucios y callar las molestias. Unos minutos sin mascarilla en plena exposición bastan para irritarte. La decisión segura: protección <b>todo el tiempo de exposición</b>, limpieza sin levantar polvo y avisar a tiempo.","k":"Nunca te bajes la mascarilla mientras haya polvo."}],"quiz":[{"s":"enfermedades_polvo","v":[{"q":"¿Qué puede provocar la pelusa de la mosqueta en algunas personas con el tiempo?","o":["Alergias o asma","Pérdida de audición","Quemaduras en la piel","Dolor de muñecas"],"w":"La pelusa irrita ojos, piel y vías respiratorias y puede causar alergias o asma."},{"q":"¿Qué partes del cuerpo irrita principalmente la pelusa de la mosqueta?","o":["Ojos, piel y vías respiratorias","Solo las manos, por el contacto","Solo la garganta, al tragarla","Los oídos y la espalda"],"w":"Ojos, piel y vías respiratorias."},{"q":"La pelusa de la mosqueta puede irritar ojos, piel y vías respiratorias.","vf":true,"w":"Verdadero. Por eso se usa mascarilla, lentes y manga larga."}]},{"s":"pe_seleccion","v":[{"q":"¿Cuál es la mejor forma de controlar el polvo?","o":["Que no llegue al aire: extracción y equipos cerrados","Que cada uno use mascarilla, aunque no haya extracción","Abrir puertas y ventanas para que corra el aire","Soplar las mesas al final de cada turno"],"w":"Se controla en la fuente; la mascarilla es la última barrera."},{"q":"Notas que la campana de extracción de tu sector dejó de funcionar. ¿Qué haces?","o":["Aviso a mi jefatura","Sigo trabajando con la mascarilla","Abro una puerta y sigo","Espero al final del turno para contarlo"],"w":"Sin extracción el polvo llega al aire: se avisa de inmediato."},{"q":"En el control del polvo, la mascarilla es:","o":["La última barrera, después de la extracción","La primera y más importante medida","Un reemplazo de la limpieza frecuente","Necesaria solo cuando se ve el polvo"],"w":"Primero que el polvo no llegue al aire; luego la mascarilla."}]},{"s":"orden_clean","v":[{"q":"¿Cómo se limpia el polvo de las mesas?","o":["Aspirando o humedeciendo","Sacudiendo con un trapo seco","Barriendo en seco con cuidado","Soplando con aire, lejos de los demás"],"w":"Aspirar o humedecer evita que el polvo quede flotando."},{"q":"Terminas el turno con la cotona llena de pelusa. Hay una manguera de aire comprimido cerca. ¿Qué haces?","o":["No me soplo; la sacudo poco y aspiro","Me soplo rápido con el aire comprimido","Me soplo, pero con los ojos cerrados","Le pido a un compañero que me sople"],"w":"El aire comprimido deja el polvo flotando y puede herir ojos y piel."},{"q":"Soplar las mesas con aire comprimido es una forma segura de limpiar si usas mascarilla.","vf":false,"w":"Falso. El polvo queda en el aire para todos y el chorro puede herir."}]},{"s":"pe_epp_give","v":[{"q":"¿Qué protege de las partículas finas de polvo?","o":["La mascarilla certificada para partículas","Una mascarilla de tela bien lavada","La cofia puesta sobre la boca","Un pañuelo húmedo en la cara"],"w":"Solo la mascarilla certificada filtra las partículas finas."},{"q":"Un compañero usa una mascarilla de tela de su casa en una zona con pelusa. ¿Qué le dices?","o":["Que pida la certificada, que es gratis","Que está bien si la lava a diario","Que la use doble para filtrar más","Que basta con tapar la boca"],"w":"La tela no filtra; la empresa entrega sin costo la certificada."},{"q":"Una mascarilla de tela protege igual que una mascarilla certificada para partículas.","vf":false,"w":"Falso. La tela no filtra las partículas finas."}]},{"s":"pe_epp_ok","v":[{"q":"¿Cuándo debes cambiar la mascarilla desechable?","o":["Si está sucia, húmeda o cuesta respirar","Solo al final de cada semana de trabajo","Cuando cumple un mes de uso continuo","Cuando ya no se ve tan blanca como al inicio"],"w":"Sucia, húmeda, dañada o con dificultad para respirar: se cambia."},{"q":"Tu mascarilla se mojó a mitad del turno. ¿Qué haces?","o":["La cambio por una nueva","La seco al sol y la uso","Sigo, se seca sola","La uso al revés"],"w":"Húmeda pierde capacidad de filtrar: se cambia."},{"q":"¿Qué haces si tu mascarilla está sucia y te cuesta respirar con ella?","o":["La cambio","Me la bajo un rato para respirar","La sacudo y sigo","Le corto un elástico"],"w":"Si cuesta respirar, está saturada: se cambia."}]},{"s":"pe_epp_ok","v":[{"q":"¿Cómo compruebas que la mascarilla quedó bien ajustada?","o":["Al aspirar se hunde, sin aire por los bordes","Si puedo hablar y respirar sin ningún esfuerzo","Si se ve bien puesta al mirarme en el espejo","Si los elásticos aprietan detrás del cuello"],"w":"La prueba de ajuste: al aspirar se hunde y no entra aire por los bordes."},{"q":"Un trabajador con barba usa mascarilla para partículas. ¿Qué pasa?","o":["No sella bien y el polvo entra por los bordes","Protege igual, la barba ayuda a filtrar","Protege más, porque queda más firme","Da lo mismo si el clip está ajustado"],"w":"La barba impide el sello en la cara."},{"q":"¿Qué parte de la mascarilla moldeas para que no entre aire?","o":["El clip de la nariz","Los elásticos, cortándolos","El borde inferior, doblándolo","Nada, se pone tal como viene"],"w":"El clip se moldea a la nariz para sellar."}]},{"s":"pe_pelusa","v":[{"q":"Tienes picazón en los ojos y tos todos los días al terminar el turno. ¿Qué haces?","o":["Aviso a mi jefatura y a prevención","Me aguanto, es normal en la temporada","Me compro gotas y no digo nada","Me saco la mascarilla para respirar mejor"],"w":"Molestias que se repiten pueden ser una enfermedad profesional: se avisan."},{"q":"Un compañero dice que su tos de cada temporada es normal y que no vale la pena avisar. ¿Qué le recomiendas?","o":["Que avise: puede ser una enfermedad profesional","Que espere a que termine la temporada","Que trabaje sin mascarilla para no ahogarse","Que se cambie de puesto sin decir nada"],"w":"Las molestias repetidas se avisan; la ACHS evalúa si son laborales."},{"q":"¿Qué haces si cada turno terminas con estornudos y ojos irritados por la pelusa?","o":["Lo aviso a mi jefatura y a prevención","Me acostumbro, es parte del trabajo","Uso gotas y no lo comento","Me bajo la mascarilla cuando estornudo"],"w":"Una molestia que se repite se avisa a tiempo."}]}]},{"id":"herramientas","sec":"mantencion","mins":5,"title":"Herramientas eléctricas portátiles","thumb":"herr_esmeril","learn":[{"s":"herr_revisar","t":"Revísala antes de enchufarla","x":"Usa solo las herramientas para las que estás capacitado y autorizado. Antes de enchufar, mira el <b>cable, el enchufe, la carcasa y el interruptor</b>. Cable pelado o parchado con cinta, enchufe quebrado o sin su pata de tierra, carcasa rota o gatillo que no vuelve: <b>no se usa</b>. Sepárala, márcala como fuera de servicio y avisa. Nunca la repares tú de forma improvisada.","k":"Herramienta dañada se separa y se informa."},{"s":"herr_esmeril","t":"Esmeril angular","x":"<ul><li>Siempre con su <b>protección del disco</b> y su <b>mango lateral</b> puestos.</li><li>Tómalo con las dos manos y con la pieza bien fija.</li><li>Dirige las chispas hacia el piso, lejos de personas, cartón, aceites y combustibles.</li><li>Nunca lo uses parado sobre una escalera ni lo bajes con el disco girando.</li><li>Espera que el disco pare antes de dejarlo.</li></ul>","k":"Nunca saques la protección del disco."},{"s":"herr_disco","t":"El disco correcto","x":"<ul><li>Las <b>RPM del disco</b> deben ser iguales o mayores que las de la máquina. Ejemplo: máquina de 11.000 RPM, disco de 11.000 o más.</li><li>Diámetro adecuado a la máquina y a su protección.</li><li>Disco de corte para cortar; de desbaste para desbastar.</li><li>Sin trizaduras, golpes ni humedad, y dentro de su fecha de vencimiento.</li></ul>Un disco que revienta lanza trozos como proyectiles."},{"s":"herr_desenchufar","t":"Desenchufa para cambiar accesorios","x":"Para cambiar <b>disco, broca u hoja</b>, para limpiar o para ajustar: <b>desenchufa o saca la batería</b>. Un gatillo apretado sin querer basta para un accidente. Retira la llave del mandril o la llave del disco antes de partir. Al enchufar, revisa que el interruptor esté apagado para que no parta sola."},{"s":"herr_circular","t":"Sierra circular de mano","x":"<ul><li>La <b>protección inferior</b> debe volver sola: nunca la amarres ni la trabes abierta.</li><li>Pieza apoyada y fija, nunca sostenida con la mano ni sobre la pierna.</li><li>Cuerpo fuera de la línea de corte: si la hoja se traba hay <b>contragolpe</b>.</li><li>Hoja afilada y adecuada al material.</li><li>Espera que la hoja pare antes de dejarla.</li></ul>"},{"s":"herr_caladora","t":"Caladora","x":"<ul><li>Base bien apoyada sobre la pieza.</li><li><b>Mira debajo</b>: la hoja sale por abajo; nada de manos, cables ni mesa en su camino.</li><li>Hoja adecuada al material y bien apretada.</li><li>Pieza fija con prensa, sin sostenerla bajo la línea de corte.</li><li>Saca la hoja de la pieza solo cuando se detenga.</li></ul>"},{"s":"herr_taladro","t":"Taladro","x":"<ul><li>Sujeta la pieza con prensa, no con la mano.</li><li>Broca bien apretada y llave del mandril retirada.</li><li>Usa el mango lateral: si la broca se traba, el taladro gira con fuerza y puede torcerte la muñeca.</li><li>Mangas ajustadas, pelo tomado y nada colgando: la broca enrolla lo que toca.</li><li>Antes de perforar un muro, confirma que no pasen cables ni cañerías.</li></ul>"},{"s":"herr_cables","t":"Cables y extensiones","x":"<ul><li>Extensiones en buen estado, sin uniones con cinta.</li><li><b>Desenrolla completo el carrete</b>: enrollado se calienta y puede quemarse.</li><li>No pases cables por agua ni por bordes filosos, ni los dejes cruzando pasillos o rutas de la grúa.</li><li>Lleva la herramienta del mango, nunca colgando del cable.</li><li>Desenchufa tomando el enchufe, sin tirar del cable.</li></ul>En la planta hay mucha agua: cable dañado o mojado puede dar una descarga."},{"s":"herr_epp","t":"Tu EPP y vestimenta","x":"En mantención de {EMP} usas <b>cotona verde, gorro {EMP} con cofia y guantes amarillos</b>; casco solo si la tarea lo exige. Con herramientas agregas:<ul><li><b>Lentes de seguridad bien ajustados</b>, siempre; con el esmeril, además careta facial si la tarea lo indica.</li><li>Protector auditivo con esmeril, sierra o taladro de percusión.</li><li>Mascarilla si cortas madera o desbastas.</li></ul>El EPP es gratis: revísalo y pide recambio si se daña."},{"s":"herr_auto","t":"Autocuidado: tú decides","x":"La mayoría de los accidentes con herramientas se relacionan con una acción insegura: <b>sacar la protección del esmeril</b>, montar un disco que \"igual calza\", cambiar el disco con la máquina enchufada o usar una herramienta con el cable dañado. La decisión segura: herramienta revisada, protección puesta, disco correcto y desenchufar para cambiar accesorios. Avisa las herramientas dañadas y sepáralas."}],"quiz":[{"s":"herr_cablePelado","v":[{"q":"El cable de la herramienta está pelado. ¿Qué haces?","o":["No la uso, la separo y aviso","Le pongo cinta aislante y sigo","La uso con guantes de goma","La uso solo para un trabajo corto"],"w":"Herramienta dañada: no se usa, se separa y se avisa."},{"q":"Encuentras un taladro con el cable parchado con cinta. ¿Qué corresponde?","o":["Marcarlo fuera de servicio y avisar","Usarlo si la cinta está bien puesta","Cambiar yo el cable con lo que haya","Usarlo lejos del agua"],"w":"Un cable parchado no es seguro: se retira y se informa."},{"q":"Al revisar el esmeril ves que al enchufe le falta la pata de tierra. ¿Qué haces?","o":["No lo uso y aviso","Lo enchufo con un adaptador","Lo uso si la carcasa está bien","Lo uso con zapatos de goma"],"w":"Enchufe dañado o sin tierra: no se usa."}]},{"s":"herr_esmeril","v":[{"q":"¿En qué condición debe estar el esmeril angular para usarlo?","o":["Con protección del disco y mango lateral puestos","Con mango lateral, aunque sin protección","Con protección, sujeto con una mano","Sin protección, si el disco es nuevo"],"w":"Protección y mango lateral siempre, y tomado con las dos manos."},{"q":"Un compañero saca el mango lateral del esmeril porque le estorba. ¿Qué le dices?","o":["Que lo ponga y use las dos manos","Que está bien si el disco es pequeño","Que lo use así, pero más despacio","Que basta con la protección del disco"],"w":"Mango lateral y protección van siempre puestos."},{"q":"El esmeril angular se puede usar sin protección del disco si el trabajo es corto.","vf":false,"w":"Falso. La protección va siempre puesta, sin importar la duración."}]},{"s":"herr_q_cambio","v":[{"q":"Debes cambiar el disco del esmeril. ¿Qué haces primero?","o":["Desenchufo la máquina","Suelto el gatillo y lo cambio","Pongo la máquina sobre el banco","Saco la protección del disco"],"w":"Desenchufado no puede partir por un gatillo apretado sin querer."},{"q":"Tu compañero cambia la broca con el taladro enchufado, diciendo que no tocará el gatillo. ¿Qué le dices?","o":["Que lo desenchufe antes de cambiarla","Que está bien si tiene cuidado","Que lo haga con guantes","Que lo apoye en el piso"],"w":"Cualquier cambio de accesorio se hace desenchufado o sin batería."},{"q":"Puedo cambiar el disco del esmeril con la máquina enchufada si no aprieto el gatillo.","vf":false,"w":"Falso. Se desenchufa siempre antes de cambiar accesorios."}]},{"s":"herr_q_disco","v":[{"q":"¿Qué disco puedes montar en el esmeril?","o":["Con RPM iguales o mayores que la máquina y sin daños","Con RPM menores, si es del diámetro correcto","Cualquiera que calce bien en el eje","Uno más grande, si le saco la protección"],"w":"RPM del disco iguales o mayores, diámetro correcto y sin daños."},{"q":"El esmeril marca 11.000 RPM. ¿Qué disco sirve?","o":["Uno de 13.300 RPM","Uno de 8.500 RPM","Uno de 6.600 RPM","Cualquiera, si es de corte"],"w":"El disco debe soportar igual o más RPM que la máquina."},{"q":"Un disco tiene una pequeña trizadura en el borde. ¿Lo usas?","o":["No, puede reventar","Sí, si es para desbastar","Sí, apretándolo bien","Sí, a baja velocidad"],"w":"Un disco dañado puede reventar y lanzar trozos."}]},{"s":"herr_epp","v":[{"q":"¿Qué protección ocular corresponde al usar el esmeril angular?","o":["Lentes de seguridad bien ajustados","Ninguna, si el trabajo es rápido","Lentes ópticos comunes","Solo si hay alguien mirando"],"w":"El esmeril lanza partículas: lentes de seguridad siempre."},{"q":"Vas a usar el esmeril cinco minutos. ¿Qué EPP agregas a tu vestimenta?","o":["Lentes de seguridad y protector auditivo","Solo guantes de cuero, por ser poco rato","Nada adicional, por ser un trabajo corto","Solo careta facial, sin protector auditivo"],"w":"La duración no cambia el riesgo: lentes y fonos."},{"q":"Con el esmeril angular, los lentes de seguridad solo son necesarios en trabajos largos.","vf":false,"w":"Falso. Los lentes van siempre, aunque el trabajo sea corto."}]},{"s":"herr_cables","v":[{"q":"¿Cómo usas el carrete de extensión?","o":["Desenrollado por completo","Enrollado, para que no estorbe","Desenrollando solo lo justo","Enrollado y tapado para protegerlo"],"w":"Enrollado se calienta y puede quemarse."},{"q":"Necesitas solo tres metros de una extensión de carrete de treinta. ¿Qué haces?","o":["La desenrollo entera","Saco tres metros y dejo el resto enrollado","La uso enrollada, es poco rato","La enrollo más apretada"],"w":"El carrete se desenrolla completo para que no se caliente."},{"q":"Un carrete de extensión enrollado puede calentarse y quemarse al usar una herramienta.","vf":true,"w":"Verdadero. Por eso se desenrolla completo."}]},{"s":"cables","v":[{"q":"Hay agua en el piso donde pasa la extensión. ¿Cuál es el riesgo principal?","o":["Descarga eléctrica","Ruido de la herramienta","Caída de la herramienta","Polvo en el aire"],"w":"Agua y electricidad: descarga eléctrica."},{"q":"Debes trabajar en un sector lavado de la planta y la extensión cruza un charco. ¿Qué haces?","o":["La paso por un lugar seco y elevado","La dejo así si el cable está bueno","La cubro con un cartón","Uso guantes y sigo"],"w":"Los cables no se pasan por agua."},{"q":"¿Dónde NO se deben dejar los cables de extensión?","o":["Sobre agua o cruzando la ruta de la grúa","Por un costado del pasillo","Colgados en altura de forma ordenada","Lejos de bordes filosos"],"w":"Agua, bordes filosos y pasillos dañan el cable o hacen tropezar."}]},{"s":"herr_q_circular","v":[{"q":"La protección inferior de la sierra circular de mano no vuelve sola a su lugar. ¿Qué haces?","o":["No la uso y aviso","La amarro abierta, así corta mejor","La uso con más cuidado","La empujo con el dedo al terminar"],"w":"La protección inferior debe volver sola; si no, la sierra no se usa."},{"q":"Cortas una tabla con la sierra circular. ¿Dónde pones el cuerpo?","o":["Fuera de la línea de corte","Detrás de la sierra, en línea","Sobre la tabla para afirmarla","Sosteniendo la pieza con la mano"],"w":"Si la hoja se traba hay contragolpe en la línea de corte."},{"q":"Para cortar una pieza corta con la sierra circular, un compañero la sostiene con la mano. ¿Qué es lo correcto?","o":["Fijarla con prensa o apoyarla bien","Sostenerla con guantes gruesos","Apoyarla sobre la pierna","Cortar rápido para no arriesgar"],"w":"La pieza va apoyada y fija, nunca sostenida con la mano."}]},{"s":"herr_q_caladora","v":[{"q":"Antes de cortar con la caladora, ¿qué revisas debajo de la pieza?","o":["Que no haya manos, cables ni mesa en el camino","Nada, la hoja corta solo por arriba","Que la otra mano sostenga la pieza abajo","Que la pieza esté mojada para cortar mejor"],"w":"La hoja de la caladora sale por debajo de la pieza."},{"q":"¿Cuándo sacas la hoja de la caladora de la pieza?","o":["Cuando la hoja se detiene","Con la hoja aún moviéndose","Apenas termino el corte","Tirando con fuerza hacia arriba"],"w":"Sacarla en movimiento la hace saltar o quebrarse."},{"q":"La hoja de la caladora corta también por debajo de la pieza.","vf":true,"w":"Verdadero. Por eso se revisa que no haya nada en su camino."}]},{"s":"herr_esmerilMal","v":[{"q":"El disco nuevo es más grande y no cabe con la protección. Un compañero dice que se la saques. ¿Qué haces?","o":["No lo monto: uso el disco correcto y aviso","Le saco la protección, es un corte corto","Corto lejos de los demás, sin protección","Lo monto y uso careta facial"],"w":"Sin protección, un disco que revienta te golpea a ti."},{"q":"¿Cuál es una acción insegura típica con el esmeril angular?","o":["Sacarle la protección del disco","Tomarlo con las dos manos","Usar lentes de seguridad","Esperar que el disco pare"],"w":"Sacar la protección es la acción insegura más común."},{"q":"Solo hay discos de diámetro mayor que el de tu esmeril. ¿Qué haces?","o":["Espero el disco correcto y aviso","Monto el grande sin protección","Monto el grande y corto con cuidado","Recorto el disco a la medida"],"w":"Un disco equivocado o sin protección puede reventar."}]}]},{"id":"altura","sec":"mantencion","title":"Trabajo en altura y uso de escaleras","thumb":"altura_intro","learn":[{"s":"altura_intro","t":"¿Qué es trabajo en altura?","x":"Se considera trabajo en altura desde <b>1,8 m</b> sobre el nivel inferior. Una caída de más de 1,8 m es <b>accidente grave</b>: se paraliza la tarea, se delimita y se avisa de inmediato. Pero caer de menos altura, como desde un pallet o la plataforma de un camión, también causa fracturas graves. En {EMP}: racks de bodega, techumbres, estanques, ductos y carga de camiones."},{"s":"altura_pallet","t":"Nunca sobre pallets ni horquillas","x":"Está prohibido subirse a un pallet, a una ruma de cajas, a una silla o a las <b>horquillas de la grúa</b> para alcanzar algo alto. Las horquillas no tienen baranda ni sujeción: un movimiento y caes desde varios metros. Usa una escalera adecuada o pide que bajen la carga con la grúa."},{"s":"altura_inspect","t":"Revisa la escalera antes de usarla","x":"Antes de subir, revisa:<ul><li>Peldaños completos y firmes.</li><li>Largueros sin grietas ni dobleces.</li><li>Zapatas antideslizantes en buen estado.</li><li>Sin aceite, barro ni grasa; tus zapatos también limpios.</li></ul>Si está dañada, <b>no la uses</b>: márcala, retírala y avisa. Nunca la arregles con alambre o cinta."},{"s":"altura_ladder_ok","t":"Escalera bien instalada","x":"<ul><li>Escalera de apoyo con ángulo <b>4 a 1</b>: por cada 4 m de altura, el pie va separado 1 m del muro.</li><li>Que <b>sobresalga</b> cerca de 1 m del apoyo superior.</li><li>Sobre piso firme, nivelado y seco.</li><li>Amarrada arriba o sujeta abajo por un compañero.</li><li>Escalera de tijera: <b>completamente abierta y con su seguro</b>, nunca cerrada y apoyada contra el muro.</li></ul>"},{"s":"altura_3p","t":"Sube y baja con 3 puntos de apoyo","x":"<ul><li>Siempre <b>3 puntos de apoyo</b>: dos manos y un pie, o dos pies y una mano.</li><li>De frente a la escalera y con las manos libres: herramientas en un bolso o cinturón.</li><li><b>No uses los últimos peldaños</b> ni te estires hacia los lados: baja y mueve la escalera.</li><li><b>Una persona a la vez.</b></li></ul>","k":"Tres puntos de apoyo, de frente y de a uno."},{"s":"altura_camion_mal","t":"Carga y descarga de camiones","x":"La plataforma del camión es un borde sin protección, a más de un metro del suelo. Las caídas típicas: <b>retroceder sin mirar al acomodar la carga, pisar la orilla o saltar al bajar</b>. Mantente lejos del borde, mira dónde pisas y baja <b>de frente</b>, por la escalera o los peldaños, con 3 puntos de apoyo. Con lluvia o escarcha la plataforma resbala más."},{"s":"altura_apilado","t":"Rumas altas y racks","x":"No trepes por las rumas ni por los racks para ordenar o sacar algo de arriba: se pueden deslizar o volcar contigo encima. Para bajar material alto, usa la grúa horquilla con su operador o una escalera adecuada. Respeta la altura máxima de apilamiento que indique tu jefatura y deja las rumas parejas y estables."},{"s":"altura_arnes","t":"Techumbres, estanques y ductos","x":"Toda plataforma, andamio o pasarela debe tener <b>baranda y rodapié</b>. Donde el borde no se pueda proteger, se usa <b>arnés de cuerpo completo</b> conectado a un <b>punto de anclaje adecuado</b>, nunca a una cañería o baranda débil. Revisa el arnés antes de usarlo. <b>No se sube a techos sin autorización</b>: las planchas traslúcidas no resisten el peso de una persona.","k":"Borde sin baranda: arnés conectado a un anclaje adecuado."},{"s":"altura_herram","t":"Herramientas amarradas y zona inferior","x":"Un objeto que cae desde la altura puede herir gravemente a quien está abajo.<ul><li>Amarra las herramientas o súbelas en un bolso, no en las manos.</li><li><b>Delimita y señaliza</b> la zona inferior con conos o cinta.</li><li>No pases bajo personas trabajando en altura ni retires la delimitación.</li></ul>Quien trabaja abajo usa casco si la tarea lo exige."},{"s":"altura_auto","t":"Autocuidado: no improvises","x":"En altura, la acción insegura típica es <b>improvisar \"por un segundo\"</b>: subirse a un pallet, a una silla o a las horquillas, o usar una escalera dañada. La decisión segura: <b>detenerte y buscar el equipo correcto</b>. Si ves un riesgo grave e inminente, tienes derecho a detener la tarea (Código del Trabajo, art. 184 bis). Avisar una escalera dañada o un borde sin protección también es autocuidado."}],"quiz":[{"s":"altura_intro","v":[{"q":"¿Desde qué altura se considera trabajo en altura?","o":["Desde 1,8 m","Desde 3 m","Desde 1 m","Solo sobre techos"],"w":"Desde 1,8 m sobre el nivel inferior."},{"q":"Un compañero cae desde una plataforma de 2,5 m. ¿Cómo se clasifica y qué se hace?","o":["Grave: se paraliza, delimita y avisa","Accidente leve si se levanta solo","Incidente: se registra y se sigue trabajando","Accidente grave, pero se termina la tarea"],"w":"Caída de más de 1,8 m es accidente grave."},{"q":"Vas a limpiar una canaleta a 2 m del piso. ¿Es trabajo en altura?","o":["Sí, supera 1,8 m","No, es menos de 3 m","No, si es una tarea corta","Solo si es sobre un techo"],"w":"Desde 1,8 m es trabajo en altura."}]},{"s":"altura_pallet","v":[{"q":"Necesitas una caja de la parte alta del rack. La grúa está al lado. ¿Qué haces?","o":["Pido que bajen la caja o uso una escalera adecuada","Me subo a las horquillas y el operador me eleva","Trepo por el rack con cuidado","Me subo a una ruma de cajas"],"w":"Las horquillas son para cargas, nunca para personas."},{"q":"¿Para qué sirven las horquillas de la grúa?","o":["Solo para cargas","Para cargas y personas, si van lento","Como plataforma en tareas cortas","Para elevar personas con arnés"],"w":"Las horquillas no tienen baranda ni sujeción."},{"q":"Puedo subirme a las horquillas de la grúa para alcanzar una caja si es solo un momento.","vf":false,"w":"Falso. Nunca se eleva a personas en las horquillas."}]},{"s":"altura_ladder_ok","v":[{"q":"Si la escalera debe apoyarse a 4 m de altura, ¿a qué distancia del muro va su pie?","o":["Aproximadamente a 1 m","Pegado al muro","A 2 m","A 4 m"],"w":"Regla 4 a 1: 4 m de alto, 1 m de separación."},{"q":"La escalera se apoya a 2 m del suelo. ¿A qué distancia del muro va su pie?","o":["A unos 50 cm","Pegado al muro","A 2 m","A 1,5 m"],"w":"Regla 4 a 1: un cuarto de la altura."},{"q":"¿Cómo se usa una escalera de tijera?","o":["Totalmente abierta y con su seguro","Cerrada y apoyada contra el muro","Abierta a medias, si es tarea corta","Sin seguro, si el piso es plano"],"w":"La tijera se usa completamente abierta y con su seguro."}]},{"s":"altura_mal_escalera","v":[{"q":"En la escalera no alcanzas el punto de trabajo. ¿Qué haces?","o":["Bajo y muevo o cambio la escalera","Me estiro hacia el lado","Subo al último peldaño","Me paro en la punta de los pies"],"w":"Estirarse o usar los últimos peldaños hace perder el equilibrio."},{"q":"¿Cuál de estas es una práctica insegura en la escalera?","o":["Pararse en los últimos peldaños","Subir de frente a la escalera","Subir con las manos libres","Llevar herramientas en un bolso"],"w":"Los últimos peldaños no dan apoyo para las manos."},{"q":"En una escalera de tijera se puede subir al último peldaño si un compañero la sujeta.","vf":false,"w":"Falso. Los últimos peldaños no se usan."}]},{"s":"altura_3p","v":[{"q":"\"3 puntos de apoyo\" significa:","o":["Dos manos y un pie, o dos pies y una mano","Subir de tres en tres peldaños","Tres personas sujetando la escalera","Escalera, muro y suelo"],"w":"Siempre tres extremidades en contacto con la escalera."},{"q":"Debes subir a la escalera con una caja de herramientas. ¿Cómo lo haces?","o":["Con las herramientas en un bolso y las manos libres","Con la caja en una mano y la otra en la escalera","Con la caja apoyada en el hombro","Lanzando la caja al compañero de arriba"],"w":"Necesitas las manos libres para mantener 3 puntos de apoyo."},{"q":"¿Cómo se baja de una escalera?","o":["De frente, con 3 puntos de apoyo","De espaldas a la escalera, mirando el piso","Saltando el último tramo con cuidado","De lado, sujetándome con una mano"],"w":"De frente y con 3 puntos de apoyo."}]},{"s":"altura_inspect","v":[{"q":"Encuentras una escalera con un peldaño suelto. ¿Qué haces?","o":["No la uso, la retiro y aviso","La uso con cuidado, saltando ese peldaño","La amarro con alambre","La dejo donde estaba sin decir nada"],"w":"Escalera dañada: se marca, se retira y se avisa."},{"q":"¿Qué revisas en una escalera antes de subir?","o":["Peldaños, largueros, zapatas y que esté limpia","Solo que tenga la altura que necesitas","Solo el color de la etiqueta","Nada, si la usaron en la mañana"],"w":"Peldaños firmes, largueros sanos, zapatas buenas y sin grasa."},{"q":"Una escalera tiene un larguero doblado. Tu compañero dice que \"aguanta igual\". ¿Qué haces?","o":["No la uso, la marco y aviso","La uso si subo despacio","La enderezo a golpes","La uso solo en los primeros peldaños"],"w":"Un larguero dañado puede ceder."}]},{"s":"altura_camion_ok","v":[{"q":"¿Cómo se baja correctamente de la plataforma del camión?","o":["De frente, por los peldaños, con 3 puntos de apoyo","Saltando de espaldas al suelo","Saltando de frente, flexionando las rodillas","Deslizándose por la orilla"],"w":"Saltar es la causa típica de lesiones al bajar del camión."},{"q":"Acomodas carga sobre la plataforma del camión. ¿Cuál es el error que más caídas provoca?","o":["Retroceder sin mirar","Mirar dónde pisas","Alejarse del borde","Bajar por los peldaños"],"w":"Retroceder sin mirar lleva al borde."},{"q":"Terminaste de cargar y estás sobre el camión. ¿Cómo bajas?","o":["Por la escalera o peldaños, de frente","Salto, es menos de dos metros","Me cuelgo de la baranda y me dejo caer","Pido que me bajen en las horquillas"],"w":"Se baja de frente con 3 puntos de apoyo."}]},{"s":"altura_3p","v":[{"q":"¿Cuántas personas pueden estar a la vez en una escalera portátil?","o":["Una","Dos, si es larga","Dos, si una sujeta","Tres, en tareas cortas"],"w":"Una persona a la vez."},{"q":"Tu compañero quiere subir detrás de ti en la misma escalera para pasarte una pieza. ¿Qué le dices?","o":["Que espere abajo y me la pase con una cuerda","Que suba despacio y sin herramientas","Que suba solo hasta la mitad de la escalera","Que suba si la escalera está bien amarrada"],"w":"Una persona a la vez en la escalera."},{"q":"En una escalera portátil sube solo una persona a la vez.","vf":true,"w":"Verdadero. Dos personas desestabilizan la escalera."}]},{"s":"altura_arnes","v":[{"q":"En un borde sin baranda donde corresponde usar arnés, ¿a qué lo conectas?","o":["A un punto de anclaje adecuado","A la cañería más cercana","A una baranda de tubo delgado","A nada, basta con tenerlo puesto"],"w":"Solo un anclaje adecuado resiste una caída."},{"q":"Trabajas sobre un estanque sin baranda. Tu compañero conecta su arnés a una cañería. ¿Qué le dices?","o":["Que lo conecte a un punto de anclaje adecuado","Que está bien si la cañería es gruesa","Que lo deje sin conectar para moverse mejor","Que se amarre a mi arnés"],"w":"Una cañería no está diseñada para detener una caída."},{"q":"Donde un borde no se puede proteger con baranda, ¿qué se usa?","o":["Arnés conectado a un anclaje adecuado","Cinturón de herramientas bien apretado","Arnés de cuerpo completo, aunque sin conectar","Una cinta de peligro a lo largo del borde"],"w":"Arnés anclado a un punto adecuado."}]},{"s":"altura_herram","v":[{"q":"Mientras un compañero trabaja en altura, la zona de abajo debe:","o":["Estar delimitada y señalizada","Usarse como pasillo con cuidado","Tener material acopiado","Quedar sin marcar si es poco rato"],"w":"Lo que cae puede herir a quien está abajo."},{"q":"¿Cómo subes las herramientas a una plataforma en altura?","o":["En un bolso o amarradas","En las manos, con cuidado","En los bolsillos","Lanzándolas a quien está arriba"],"w":"Herramientas amarradas o en bolso: manos libres y nada cae."},{"q":"Se puede pasar bajo una persona que trabaja en altura si se camina rápido.","vf":false,"w":"Falso. No se pasa bajo trabajos en altura."}]}]},{"id":"caldera","sec":"caldera","title":"Caldera: operación segura","thumb":"pe_caldera","learn":[{"s":"pe_caldera_general","t":"Una caldera es un recipiente a presión","x":"La caldera calienta agua hasta producir <b>vapor a presión</b> para autoclaves, marmitas y otros equipos. Acumula mucha energía: si falla el control de presión o el nivel de agua, puede <b>explotar</b>, causar un incendio o quemaduras graves con vapor. Por eso su instalación, operación y revisión están reguladas por el <b>DS 10</b> del Ministerio de Salud."},{"s":"pe_caldera","t":"Solo el operador certificado","x":"Según el DS 10, la caldera la opera solo quien tiene <b>certificación de competencia de la SEREMI de Salud</b> y la autorización de {EMP}. Nadie más manipula válvulas, quemadores, purgas ni controles, ni siquiera para apagar una alarma. El operador no deja la caldera funcionando sin vigilancia y la entrega en cada cambio de turno informando su estado.","k":"Sin certificación SEREMI, no se opera la caldera."},{"s":"pe_mano","t":"Revisión en cada turno","x":"<ul><li><b>Manómetro</b> dentro del rango de trabajo.</li><li><b>Nivel de agua</b> visible y correcto en el visor.</li><li><b>Válvula de seguridad</b> libre: nunca amarrada, bloqueada ni regulada a mano.</li><li><b>Purgas</b> según el procedimiento.</li><li>Quemador y combustible sin fugas.</li></ul>Todo queda anotado en el <b>libro de vida</b> de la caldera. Lo que no se anota, no se revisó."},{"s":"pe_caldera_ajena","t":"Sala de caldera: acceso restringido","x":"Solo entra el operador y quien él o la jefatura autoricen. Si una persona ajena necesita algo de la sala, se lo pide al operador. La puerta y el acceso deben quedar <b>siempre libres</b>, con buena ventilación e iluminación, y el extintor visible y a mano. La sala no es lugar de descanso ni de paso."},{"s":"pe_combustibles","t":"La sala no es bodega","x":"Junto a un quemador, cualquier material combustible es peligro de incendio. <b>Prohibido guardar cartón, pallets, cajas, trapos con aceite o bidones</b> en la sala de caldera, aunque haya espacio. El combustible de la caldera va solo en su estanque y sus cañerías. Prohibido fumar o usar llamas sin autorización. Si hay olor a combustible o una mancha de derrame, avisa."},{"s":"pe_calor","t":"Ruido y calor","x":"Junto a la caldera hay <b>ruido y calor</b>. Si el ruido supera los 85 dB(A), el protector auditivo es obligatorio todo el tiempo de exposición. Usa <b>guantes para calor</b> al tocar válvulas o tapas: las cañerías superan los 100 °C aunque no se vea vapor. Toma agua seguido. Ante una fuga de vapor, aléjate, aísla la zona y avisa: nunca la tapes con la mano o un trapo."},{"s":"pe_caldera_alerta","t":"Ante una anomalía","x":"Presión que sube sin control, nivel de agua que no se ve, ruidos extraños, olor a gas o humo: <b>aplica la parada de emergencia</b> según el procedimiento, aleja a las personas y avisa de inmediato. Si el nivel de agua desapareció del visor, <b>apaga el quemador y no agregues agua</b>: agua fría sobre una caldera recalentada puede provocar una explosión. Si no eres el operador: aléjate y avisa.","k":"Anomalía: parada de emergencia, alejar a las personas y avisar."}],"quiz":[{"s":"pe_caldera","v":[{"q":"¿Quién puede operar la caldera?","o":["Quien tiene certificación SEREMI y autorización de la empresa","Cualquier trabajador de mantención con experiencia","El supervisor de turno, aunque no tenga certificación","Quien haya visto operarla muchas veces"],"w":"El DS 10 exige certificación de competencia de la SEREMI de Salud."},{"q":"Suena una alarma en la caldera y el operador está en otra sala. Tú no eres operador. ¿Qué haces?","o":["Aviso al operador y no toco los controles","Apago la alarma desde el tablero","Bajo la presión abriendo una válvula","Apago el quemador para ir a lo seguro"],"w":"Nadie más que el operador manipula controles, ni para apagar una alarma."},{"q":"¿Qué norma regula la operación de calderas y exige operador certificado?","o":["El DS 10","El DS 594","La Ley 20.949","El DS 57"],"w":"El DS 10 regula calderas, autoclaves y equipos a vapor."}]},{"s":"pe_mano","v":[{"q":"Las revisiones de la caldera se registran en:","o":["El libro de vida de la caldera","Un cuaderno personal del operador","Un mensaje al supervisor","No se registran si todo está bien"],"w":"Lo que no se anota en el libro de vida, no se revisó."},{"q":"Al terminar la revisión del turno, todo estaba normal. ¿Qué haces con el registro?","o":["Lo anoto igual en el libro de vida","No anoto nada, porque no hubo fallas","Lo anoto solo al final de la semana","Le aviso de palabra al siguiente turno"],"w":"Se registra cada revisión, aunque todo esté normal."},{"q":"Toda revisión de la caldera se anota en el libro de vida, aunque todo esté normal.","vf":true,"w":"Verdadero. Lo que no se anota, no se revisó."}]},{"s":"pe_combustibles","v":[{"q":"Falta espacio en bodega y te piden dejar pallets en la sala de caldera. ¿Qué haces?","o":["No los dejo ahí y aviso a la jefatura","Los dejo lejos del quemador","Los dejo solo por el fin de semana","Los dejo si la puerta queda libre"],"w":"La sala de caldera no es bodega: combustible junto a un quemador."},{"q":"¿Qué se puede guardar en la sala de caldera?","o":["Nada ajeno a la caldera","Cartón doblado, si está ordenado","Bidones cerrados de aceite","Trapos limpios en un rincón"],"w":"Cualquier material combustible junto al quemador es riesgo de incendio."},{"q":"Se puede guardar cartón y pallets en la sala de caldera si hay espacio y no tapan la puerta.","vf":false,"w":"Falso. La sala de caldera no es bodega."}]},{"s":"pe_caldera_alerta","v":[{"q":"La presión sube y no baja con los controles. ¿Qué haces?","o":["Parada de emergencia, alejo a las personas y aviso","Espero unos minutos a ver si baja sola","Amarro la válvula de seguridad para que no bote","Abro todas las purgas a la vez"],"w":"Ante una anomalía: parada de emergencia según el procedimiento y aviso."},{"q":"Escuchas un ruido extraño en la caldera y sientes olor a gas. ¿Qué haces primero?","o":["Parada de emergencia y alejo a las personas","Busco la fuga con un encendedor","Sigo operando y lo anoto al final del turno","Llamo al técnico y sigo operando mientras"],"w":"Primero detener y alejar; luego avisar."},{"q":"No eres operador y ves salir humo de la sala de caldera. ¿Qué haces?","o":["Me alejo y aviso de inmediato","Entro a apagar el quemador","Abro las válvulas para bajar la presión","Espero a ver si el humo sigue"],"w":"Quien no es operador se aleja y avisa."}]},{"s":"pe_caldera_general","v":[{"q":"¿Para qué sirve la válvula de seguridad de la caldera?","o":["Libera presión si sube del límite","Regula la temperatura del agua de la caldera","Sirve para hacer las purgas diarias","Corta el combustible al quemador si hay falla"],"w":"La válvula de seguridad descarga el exceso de presión."},{"q":"La válvula de seguridad bota vapor seguido y un compañero propone amarrarla. ¿Qué haces?","o":["No la amarro y aviso a la jefatura","La amarro solo hasta que termine el turno","La regulo a mano para que bote menos","La tapo con un trapo mojado"],"w":"Bloquear la válvula de seguridad puede causar una explosión."},{"q":"La válvula de seguridad se puede bloquear un rato si bota mucho vapor.","vf":false,"w":"Falso. Nunca se amarra ni se bloquea."}]},{"s":"pe_mano","v":[{"q":"En la revisión ves que el nivel de agua ya no aparece en el visor. ¿Qué haces?","o":["Apago el quemador, no agrego agua y aviso","Agrego agua fría de inmediato","Subo la presión para revisar","Sigo operando y vuelvo a mirar luego"],"w":"Agua fría sobre una caldera recalentada puede provocar una explosión."},{"q":"¿Por qué no se agrega agua de golpe cuando el nivel desapareció del visor?","o":["Porque sobre la caldera recalentada puede explotar","Porque el agua se pierde por las purgas","Porque baja demasiado la temperatura del vapor","Porque ensucia el visor de nivel"],"w":"El agua fría sobre metal recalentado produce vapor violento."},{"q":"La caldera funciona y el visor de nivel está vacío. La decisión correcta es:","o":["Apagar el quemador y avisar","Agregar agua hasta llenar el visor","Abrir la válvula de seguridad a mano","Esperar a que el nivel vuelva solo"],"w":"Sin nivel visible: se apaga el quemador y se avisa."}]},{"s":"pe_caldera_ajena","v":[{"q":"Un trabajador de otra sección quiere entrar a la sala de caldera a buscar una herramienta. ¿Qué corresponde?","o":["Que se la pida al operador","Que entre rápido sin tocar nada","Que entre acompañado de un compañero","Que entre si la caldera está apagada"],"w":"La sala es de acceso restringido."},{"q":"¿Cómo deben quedar la puerta y el acceso a la sala de caldera?","o":["Siempre libres y despejados","Con material apoyado si no estorba","Cerrados con llave y el extintor afuera","Bloqueados para que nadie entre"],"w":"Acceso libre para salir y para llegar en una emergencia."},{"q":"¿Quién puede entrar a la sala de caldera?","o":["El operador y quien se autorice","Cualquier trabajador de {EMP}","Solo los contratistas de mantención","Cualquiera, si no toca los controles"],"w":"Solo personal autorizado entra a la sala."}]}]},{"id":"camaras_frio","sec":"frio","title":"Cámaras de frío","thumb":"pe_camara","learn":[{"s":"pe_camara","t":"Trabajar con frío","x":"En las cámaras la temperatura puede llegar a <b>18 grados bajo cero</b>. El frío entumece las manos, quita fuerza y destreza y aumenta los accidentes. Antes de entrar ponte la <b>ropa térmica completa</b> que entrega {EMP} sin costo: chaqueta, pantalón, guantes, gorro bajo el casco o la cofia y calzado antideslizante. La ropa debe estar <b>seca</b>: mojada pierde el abrigo. Si está rota, pide recambio."},{"s":"pe_camara_puerta","t":"Que nadie quede encerrado","x":"La puerta debe poder <b>abrirse desde adentro</b> y la cámara debe tener <b>alarma o timbre</b> interior y luz funcionando. Revísalos al comenzar el turno. Si algo no funciona, <b>no entres</b> y avisa a tu jefatura. Nunca trabes la puerta con cajas o pallets ni bloquees por dentro la manilla o el botón de apertura.","k":"Sin apertura interior y alarma funcionando, no se entra."},{"s":"pe_frio_mal","t":"Nunca entrar sin avisar","x":"<ul><li>Avisa a un compañero o a tu jefatura <b>cuando entras y cuando sales</b>.</li><li>Respeta los <b>tiempos de permanencia</b> que indique tu jefatura y sal a recuperarte en un lugar temperado.</li><li>Toma líquidos tibios en las pausas.</li><li>Al terminar el turno, revisa que no quede nadie adentro antes de cerrar.</li></ul>"},{"s":"pe_hielo","t":"Piso con hielo","x":"El piso de la cámara y la entrada pueden tener <b>hielo o escarcha</b>, sobre todo cerca de la puerta y de los evaporadores. Camina despacio, sin correr, con calzado antideslizante y sin llevar cargas que te tapen la vista. Avisa si hay acumulación de hielo o agua: se debe limpiar y señalizar. No subas a los racks para sacar cajas de arriba."},{"s":"horq_contacto","t":"Grúa y transpaleta en la cámara","x":"Dentro de la cámara el espacio es estrecho, el piso resbala y la visibilidad baja por el vapor del frío.<ul><li>Antes de cruzar, busca <b>contacto visual</b> con el operador y espera su señal.</li><li>Nunca te pongas entre la máquina y los racks.</li><li>Nunca bajo una carga levantada.</li></ul>El operador entra despacio, con luces y bocina en la puerta.","k":"Nunca entre la máquina y los racks."},{"s":"pe_camara","t":"Señales de alerta por frío","x":"<ul><li><b>Temblor fuerte</b>, manos torpes o adormecidas.</li><li>Piel <b>blanca o cerosa</b> en dedos, orejas o nariz.</li><li>Confusión, sueño o hablar enredado: es hipotermia.</li></ul>Si te pasa a ti o a un compañero: salgan de inmediato a un lugar temperado, cambien ropa mojada, abríguense y avisen. No frotes la piel congelada ni la acerques a una fuente de calor directa. Si empeora, llama a la ACHS al <b>1404</b>."}],"quiz":[{"s":"pe_camara_puerta","v":[{"q":"La alarma interior de la cámara no funciona. ¿Qué haces?","o":["No entro y aviso a mi jefatura","Entro igual, pero rápido","Dejo la puerta abierta con una caja","Entro y le pido a alguien que espere afuera"],"w":"Sin alarma ni apertura interior, si la puerta se cierra quedas atrapado."},{"q":"Al comenzar el turno, ¿qué revisas en la puerta de la cámara?","o":["Que abra desde adentro y que la alarma funcione","Solo que cierre bien, para no perder frío","Que tenga candado por fuera","Solo que esté limpia"],"w":"Apertura interior y alarma: que nadie quede encerrado."},{"q":"Un compañero traba la puerta abierta con un pallet para no usar la manilla. ¿Qué es lo correcto?","o":["Sacarlo y avisar si la apertura falla","Dejarlo, así nadie queda encerrado","Usar dos pallets para más seguridad","Trabarla solo cuando haya poca gente"],"w":"La puerta no se traba; si la apertura falla, se avisa."}]},{"s":"pe_frio_mal","v":[{"q":"¿Qué haces antes de entrar a una cámara de frío?","o":["Aviso a un compañero o a mi jefatura","Entro sin avisar si es poco rato","Cierro la puerta por dentro","Aviso solo si voy a estar más de una hora"],"w":"Avisar al entrar y al salir permite que alguien te busque."},{"q":"Terminas tu tarea dentro de la cámara. ¿Qué haces al salir?","o":["Aviso que salí","Nada, ya avisé al entrar","Cierro sin mirar adentro","Dejo la luz encendida como aviso"],"w":"Se avisa al entrar y al salir."},{"q":"Antes de entrar a una cámara de frío debes avisar a un compañero o a tu jefatura.","vf":true,"w":"Verdadero. Y también al salir."}]},{"s":"pe_camara","v":[{"q":"¿Qué ropa se usa para trabajar en la cámara?","o":["Ropa térmica completa con guantes y gorro","Solo un polerón grueso bajo la cotona","Solo la chaqueta térmica, sin pantalón","Ninguna especial si es poco rato"],"w":"El frío quita fuerza y destreza: ropa térmica completa."},{"q":"Tus guantes térmicos se rompieron. ¿Qué haces?","o":["Pido recambio sin costo","Entro sin guantes, es rápido","Uso guantes de látex","Los compro yo en la tarde"],"w":"El EPP lo entrega la empresa sin costo y se cambia si se daña."},{"q":"¿Qué pasa con las manos en el frío de la cámara?","o":["Se entumecen y pierden fuerza y destreza","Ganan fuerza y firmeza por el frío","No cambian si trabajas rápido y sin parar","Solo se enfrían, sin afectar el trabajo"],"w":"El frío aumenta los accidentes por pérdida de destreza."}]},{"s":"pe_hielo","v":[{"q":"Hay acumulación de hielo junto a la puerta de la cámara. ¿Qué haces?","o":["Camino despacio y aviso para que se limpie","Paso corriendo para no resbalar","Tiro sal y sigo sin avisar","No hago nada, es normal en la cámara"],"w":"El hielo se informa para limpiarlo y señalizarlo."},{"q":"¿Cómo se camina dentro de una cámara con escarcha en el piso?","o":["Despacio, con calzado antideslizante","Rápido, para salir antes del frío","Con pasos largos sobre el hielo","Arrastrando los pies con botas comunes"],"w":"Despacio y con calzado antideslizante."},{"q":"Con botas de seguridad puedes caminar rápido sobre la escarcha de la cámara.","vf":false,"w":"Falso. Sobre hielo o escarcha se camina despacio, aun con buen calzado."}]},{"s":"horq_contacto","v":[{"q":"Dentro de la cámara se acerca la grúa con un pallet. ¿Qué haces?","o":["Me detengo, hago contacto visual y espero","Me pego al rack para que pase la grúa","Sigo caminando; el operador me esquiva","Paso por debajo de la carga, que está alta"],"w":"Nunca entre la máquina y los racks; contacto visual primero."},{"q":"¿Dónde es más peligroso ubicarte cuando la grúa maniobra en la cámara?","o":["Entre la máquina y los racks","En la ruta peatonal, detenido","Fuera de la cámara","Frente al operador, con contacto visual"],"w":"Entre la máquina y el rack puedes quedar atrapado."},{"q":"¿Por qué la grúa es más peligrosa dentro de la cámara?","o":["Espacio estrecho, piso resbaloso y poca vista","Porque el frío la hace andar más rápido","Porque dentro de la cámara no tiene puntos ciegos","Porque el ruido se escucha más fuerte adentro"],"w":"Por eso se busca contacto visual y se respeta la distancia."}]},{"s":"pe_camara","v":[{"q":"Tu compañero tiembla mucho, habla enredado y parece confundido en la cámara. ¿Qué haces?","o":["Lo saco a un lugar temperado, lo abrigo y aviso","Le digo que se mueva más para calentarse","Le froto fuerte las manos con hielo","Lo dejo terminar y luego avisamos"],"w":"Son señales de hipotermia: salir, abrigar y avisar."},{"q":"Notas la punta de tus dedos blanca y adormecida. ¿Qué haces?","o":["Salgo a un lugar temperado y aviso","Los froto fuerte para que se calienten","Los acerco a una estufa encendida","Sigo trabajando hasta la pausa"],"w":"No se frota ni se calienta directo la piel congelada."},{"q":"La piel congelada se debe frotar fuerte para que recupere la circulación.","vf":false,"w":"Falso. No se frota: se abriga y se avisa."}]},{"s":"pe_camara","v":[{"q":"Tu ropa térmica quedó húmeda después del lavado de la cámara. ¿Qué haces?","o":["La cambio por ropa seca antes de entrar","Entro igual, se secará con el frío","Me pongo otra capa encima","Entro solo por poco rato"],"w":"La ropa mojada pierde el abrigo."},{"q":"¿Por qué la ropa térmica debe estar seca?","o":["Porque mojada pierde su capacidad de abrigar","Porque mojada pesa más y molesta al trabajar","Solo por higiene del producto almacenado","Porque la tela se daña y se rompe con el frío"],"w":"Mojada no abriga y aumenta el riesgo de hipotermia."},{"q":"Antes de entrar a la cámara te das cuenta de que tu chaqueta térmica está mojada. La decisión segura es:","o":["Pedir una seca antes de entrar","Entrar y salir más seguido","Usarla al revés","Entrar sin chaqueta, con polerón"],"w":"Ropa seca y completa antes de entrar."}]}]},{"id":"porteria","sec":"porteria","title":"Portería: control de acceso seguro","thumb":"pe_porteria","learn":[{"s":"pe_porteria","t":"La portería cuida la planta","x":"Desde la portería se controla quién y qué entra a {EMP}: <b>trabajadores, temporeros, visitas, proveedores, contratistas y camiones</b>. Un buen control evita accidentes con personas que no conocen la planta y permite saber <b>cuántas personas hay adentro</b> en una emergencia. Nadie entra ni sale sin quedar registrado, ni siquiera \"por un minuto\"."},{"s":"pe_registro","t":"Registro y reglas de ingreso","x":"<ul><li>Registra a cada visita y contratista con nombre, RUT, empresa, hora y a quién visita.</li><li>Entrega las <b>reglas básicas</b>: rutas peatonales, EPP, zonas prohibidas y punto de encuentro.</li><li>Avisa a quien lo recibe: la visita anda <b>siempre acompañada</b>.</li><li>Contratista sin documentación al día no ingresa.</li><li>Persona con signos de alcohol o drogas no ingresa: avisa a la jefatura.</li></ul>"},{"s":"pe_peaton","t":"Barrera y tránsito de camiones","x":"Al dar paso a un camión, ubícate <b>fuera de su trayectoria</b>, en la ruta peatonal y visible para el chofer: sus espejos tienen <b>puntos ciegos</b> adelante, a los costados y atrás. Indica la ruta y la velocidad máxima de la planta. Nunca te pares delante de un camión para detenerlo ni camines detrás de uno que retrocede. Usa chaleco reflectante.","k":"Nunca te pongas delante ni detrás de un camión en movimiento."},{"s":"pe_agresivo","t":"Personas molestas o agresivas","x":"<ul><li>Habla con calma, tono bajo y trato de usted.</li><li>No discutas ni respondas insultos.</li><li>Mantén distancia y una salida libre.</li><li><b>Pide apoyo</b> y, si hay riesgo, llama a Carabineros al <b>133</b>.</li><li>Registra lo ocurrido y avisa a tu jefatura: la violencia de terceros en el trabajo está cubierta por la Ley Karin.</li></ul>"},{"s":"pe_porteria_emerg","t":"Emergencias","x":"En una emergencia la portería es clave:<ul><li><b>Abre el paso</b> a bomberos y ambulancia y mantén libre el acceso.</li><li>Informa <b>cuántas personas hay en la planta</b> según el registro.</li><li>No dejes entrar a nadie ajeno.</li><li>Ten a mano los números: <b>131</b> SAMU, <b>132</b> Bomberos, <b>133</b> Carabineros y ACHS <b>1404</b>.</li></ul>","k":"En una emergencia, abre el paso y entrega el registro."},{"s":"uv_intro","t":"Sol y frío en la barrera","x":"En la barrera y el patio estás expuesto al <b>sol</b>, sobre todo entre las 10 y las 17 horas, y al frío de la noche y las mañanas. Usa jockey legionario, lentes con filtro UV, manga larga y bloqueador FPS 30 o más, repetido cada 2 a 3 horas, aunque esté nublado. En invierno, ropa de abrigo y para la lluvia. Toma agua durante el turno."},{"s":"pe_luz","t":"Turnos de noche y rondas","x":"<ul><li>Haz la ronda con <b>linterna</b> y avisa por radio o teléfono cuándo sales y cuándo vuelves.</li><li>Si ves una luz quemada o un sector oscuro, regístralo y avisa.</li><li>Ante un intruso o algo sospechoso, <b>no lo enfrentes</b>: mantén distancia, avisa a tu jefatura y llama al 133.</li><li>El cansancio nocturno es real: haz las pausas y avisa si te sientes agotado.</li></ul>"}],"quiz":[{"s":"pe_registro","v":[{"q":"Llega un contratista sin su documentación al día. ¿Qué haces?","o":["No ingresa hasta regularizar y aviso","Lo dejo pasar y que la traiga mañana","Lo dejo entrar si viene acompañado","Le pido que vuelva más tarde por otra puerta"],"w":"Contratista sin documentación al día no ingresa."},{"q":"Un contratista dice que su trabajo es corto y que los papeles están en la oficina de su empresa. ¿Qué corresponde?","o":["Que no ingrese hasta tener la documentación al día","Dejarlo entrar si firma el libro","Dejarlo entrar si es un trabajo de una hora","Dejarlo entrar y pedirle los papeles después"],"w":"La duración del trabajo no cambia la regla."},{"q":"Un contratista puede ingresar sin documentación al día si el trabajo dura menos de una hora.","vf":false,"w":"Falso. Sin documentación al día no ingresa."}]},{"s":"pe_agresivo","v":[{"q":"Un chofer te insulta por la espera. ¿Qué es lo correcto?","o":["Calma, no discutir, pedir apoyo y registrarlo","Responderle con firmeza en el mismo tono","Dejarlo pasar de inmediato para calmarlo","Ignorarlo por completo y no registrar nada"],"w":"Calma, distancia, apoyo y registro: es violencia en el trabajo."},{"q":"Una visita molesta se acerca gritando a la caseta y la situación se pone riesgosa. ¿Qué haces?","o":["Mantengo distancia, pido apoyo y llamo al 133","Salgo a enfrentarlo para que se calme","Le grito más fuerte para controlarlo","Lo dejo entrar para evitar problemas"],"w":"Si hay riesgo: distancia, apoyo y Carabineros 133."},{"q":"Después de recibir insultos de un proveedor, ¿qué haces?","o":["Lo registro y aviso a mi jefatura","Lo olvido, es parte del trabajo","Le respondo en su próxima visita","Le niego la entrada por mi cuenta para siempre"],"w":"La violencia de terceros se registra y se informa (Ley Karin)."}]},{"s":"pe_peaton","v":[{"q":"Al dar paso a un camión, debes ubicarte:","o":["Fuera de su trayectoria y visible para el chofer","Delante del camión, para que frene","Detrás del camión, para guiarlo","Junto a la rueda delantera, para hablar con el chofer"],"w":"Fuera de la trayectoria y fuera de los puntos ciegos."},{"q":"Un camión retrocede hacia la romana y el chofer no te ve. ¿Dónde te ubicas?","o":["Fuera de su recorrido, donde el chofer me vea","Detrás del camión, haciéndole señas con la mano","Pegado al costado del camión para guiarlo","Junto a la rueda trasera, avisándole a gritos"],"w":"Los espejos tienen puntos ciegos atrás y a los costados."},{"q":"¿Cuál es la forma correcta de detener un camión que entra sin registrarse?","o":["Barrera baja y señas desde un lugar seguro","Pararse delante del camión con los brazos arriba","Correr detrás del camión para alcanzarlo","Abrir la barrera y luego ponerse frente a él"],"w":"Nunca te pongas delante de un camión para detenerlo."}]},{"s":"pe_porteria_emerg","v":[{"q":"Se activa una emergencia en la planta. ¿Qué información entrega la portería a Bomberos?","o":["Cuántas personas hay adentro según el registro","Solo el nombre del jefe de turno de la planta","El horario de colación de todo el personal","El número de camiones que entraron en el día"],"w":"El registro permite saber si falta alguien."},{"q":"Durante una emergencia llega un proveedor que quiere entrar a dejar su carga. ¿Qué haces?","o":["No ingresa y mantengo libre el acceso","Lo dejo pasar rápido por el costado","Lo dejo entrar si no estorba","Le pido que deje la carga en el portón"],"w":"En emergencias no entra nadie ajeno y el acceso queda libre."},{"q":"Llega la ambulancia a la portería durante una emergencia. ¿Qué haces?","o":["Levanto la barrera, despejo el acceso y la guío","Le pido los datos para el registro antes de pasar","La hago esperar hasta que llegue la jefatura","Le indico que entre por el patio de camiones"],"w":"En una emergencia la portería abre el paso sin demoras."}]},{"s":"pe_registro","v":[{"q":"Llega una visita para reunirse con la gerencia. ¿Qué haces?","o":["La registro, le doy las reglas y aviso","La dejo pasar sola, porque conoce la planta","La registro y le indico que busque la oficina","Le pido que espere en el patio de camiones"],"w":"La visita se registra, recibe las reglas y anda acompañada."},{"q":"¿Qué reglas básicas entregas a una visita antes de entrar?","o":["Rutas, EPP, zonas prohibidas y punto de encuentro","Solo el horario de salida de la planta","Solo el nombre de la persona que visita","Ninguna, porque se las da quien la recibe"],"w":"Son las reglas que la protegen en la planta."},{"q":"Una visita registrada puede recorrer sola la planta si conoce el camino.","vf":false,"w":"Falso. La visita anda siempre acompañada."}]},{"s":"pe_luz","v":[{"q":"En la ronda nocturna ves a una persona desconocida dentro del recinto. ¿Qué haces?","o":["No la enfrento: me alejo, aviso y llamo al 133","La sigo de cerca para detenerla en la salida","Le grito y me acerco para identificarla","Sigo la ronda y lo comento al día siguiente"],"w":"No se enfrenta: distancia, aviso y Carabineros."},{"q":"¿Cómo se hace una ronda nocturna segura?","o":["Con linterna, avisando al salir y al volver","Sin linterna, para no ser visto","Sin avisar, para no interrumpir","Con el celular en la mano y sin radio"],"w":"Linterna y aviso permiten que alguien sepa dónde estás."},{"q":"En la ronda encuentras un sector oscuro por una luz quemada. ¿Qué haces?","o":["Lo registro y aviso","Paso rápido y sigo","Cambio la ampolleta subiendo a una caja","No hago nada, se ve de día"],"w":"Un sector oscuro es una condición insegura: se registra y se avisa."}]},{"s":"uv_intro","v":[{"q":"¿Qué protección usas en la barrera un día de verano?","o":["Legionario, lentes UV, manga larga y bloqueador","Solo un jockey común y polera de manga corta","Solo bloqueador aplicado al comenzar el turno","Lentes oscuros comunes y un gorro de lana"],"w":"Protección completa contra la radiación UV."},{"q":"Entre las 10 y las 17 horas debes estar en la barrera al sol. ¿Qué protección usas?","o":["Legionario, lentes UV, manga larga y bloqueador","Solo bloqueador en la mañana, al llegar","Solo un jockey común, sin cubrenuca","Ropa liviana de manga corta y lentes oscuros"],"w":"Protección completa en las horas de mayor radiación."},{"q":"En la barrera, el bloqueador se repite cada 2 a 3 horas, aunque esté nublado.","vf":true,"w":"Verdadero. Pierde efecto y la radiación UV pasa las nubes."}]}]},{"id":"grua_operacion","sec":"grua","mins":6,"title":"Operación segura de grúa horquilla","thumb":"horquilla_portada","learn":[{"s":"horquilla_autorizado","t":"Solo opera quien está autorizado","x":"Para operar la grúa en {EMP} se exige <b>licencia clase D</b> (maquinaria automotriz, Ley de Tránsito) y además estar <b>capacitado y autorizado por la empresa</b>. La licencia sola no basta. Antes de partir cada turno, el operador hace su <b>check list</b>: frenos, bocina, luces, neumáticos, horquillas, cadenas y fugas. Si algo falla, no se usa y se avisa.","k":"Clase D, capacitado y autorizado: si no, no se opera."},{"s":"horquilla_cinturon","t":"Cinturón: siempre puesto","x":"Si la grúa se vuelca, el cinturón te mantiene <b>dentro de la cabina, bajo el techo protector</b>. Sin cinturón, el cuerpo sale disparado y la máquina cae encima. Por eso va puesto <b>en todo recorrido</b>, aunque sea corto o dentro de la bodega. Si el cinturón está dañado o no abrocha, la grúa no se usa hasta repararlo."},{"s":"horquilla_centro","t":"Placa de carga y centro de carga","x":"La <b>placa de capacidad</b> indica cuántos kilos levanta la grúa, a qué <b>centro de carga</b> y hasta qué altura. La grúa funciona como un <b>balancín</b>: el eje delantero es el apoyo y el contrapeso va atrás. Si la carga queda <b>más lejos</b>, en las puntas o con un bin mal tomado, soporta <b>menos kilos</b> y la parte trasera se levanta. Pégala al respaldo y <b>nunca superes la placa</b>."},{"s":"horquilla_vision","t":"Si la carga tapa la vista: en reversa","x":"Dos bins apilados te tapan la visión hacia adelante. Entonces <b>avanza en reversa</b>, mirando hacia donde vas. Si igual no ves bien, pide a un compañero que te guíe con señas. <b>Nunca avances a ciegas</b> esperando que los demás se corran, ni levantes la carga para mirar por debajo. Toca la bocina en cruces, puertas y esquinas."},{"s":"horquilla_bajas","t":"Horquillas bajas al circular","x":"<ul><li>Lleva las horquillas <b>bajas, a unos 15 cm del piso</b>, y el mástil inclinado hacia atrás.</li><li>Sube la carga <b>solo frente al rack o la ruma</b>, detenido.</li><li>No gires con la carga en alto.</li><li>Ve a velocidad moderada, según las reglas internas de la planta.</li></ul>Carga baja: la grúa es más estable y ves mejor."},{"s":"horquilla_rampa","t":"Pendientes y rampas","x":"En una rampa, <b>con carga, la carga siempre va hacia arriba</b>: sube de frente y baja en reversa. Así no se cae de las horquillas.<ul><li>Nunca gires ni cruces de lado en una pendiente.</li><li>Sin carga, las horquillas van hacia abajo de la pendiente.</li><li>Antes de cargar un camión desde la rampa, confirma que esté frenado y calzado.</li></ul>"},{"s":"horquilla_vuelco","t":"Volcamiento lateral","x":"La grúa se puede volcar hacia el lado al <b>girar rápido</b>, al girar con la <b>carga en alto</b>, al pasar por <b>hoyos, lomos o pisos mojados</b>, o al andar de lado en una pendiente. Si se vuelca: <b>no saltes</b>. Quédate dentro con el cinturón, <b>afírmate al volante</b>, apoya los pies e inclínate al lado contrario a la caída.","k":"Si se vuelca: no saltes, afírmate y quédate dentro."},{"s":"horquilla_personas","t":"Nunca levantar personas","x":"Las horquillas son para cargas. <b>Nunca levantes a una persona</b> sobre las horquillas, sobre un pallet o dentro de un bin para alcanzar algo del rack, ni la lleves de pasajero. No tiene baranda ni sujeción: un movimiento y cae desde altura. Para subir, se usa el <b>equipo diseñado para personas</b>. Subirse o subir a alguien a las horquillas es una <b>falta grave</b> que puede ser sancionada."},{"s":"horquilla_estacionar","t":"Al estacionar","x":"<ul><li>Horquillas <b>apoyadas en el piso</b>.</li><li><b>Freno de estacionamiento</b> puesto.</li><li>Motor apagado y <b>llave retirada</b>.</li><li>En su lugar, lejos de salidas, extintores, pasillos y cruces.</li></ul>Así nadie tropieza con las horquillas y nadie no autorizado la puede mover. Hazlo siempre, aunque te bajes por pocos minutos."},{"s":"horquilla_auto","t":"Autocuidado: tú decides","x":"La mayoría de los accidentes se relacionan con una acción insegura. Con la grúa, las típicas son <b>apurarse</b> porque hay un camión esperando o la línea necesita bins, girar rápido con carga y <b>no ponerse el cinturón</b> porque es un tramo corto. La decisión segura: <b>trabajar con calma</b>. Avisa a tu jefatura o al asesor en prevención los pisos dañados y las fallas de la grúa."}],"quiz":[{"s":"horquilla_q_quien","v":[{"q":"¿Quién puede operar la grúa horquilla en la planta?","o":["Quien tiene licencia clase D y está capacitado y autorizado","Quien tiene licencia clase D, aunque no esté autorizado","Quien está autorizado, aunque no tenga licencia","Quien sepa manejarla y esté disponible"],"w":"Se exigen ambas cosas: licencia clase D y autorización de la empresa."},{"q":"Un compañero con licencia clase B te pide la llave para mover la grúa un metro. ¿Qué haces?","o":["No se la paso: no está autorizado","Se la paso, porque es solo un metro","Se la paso si yo lo voy guiando a pie","Se la paso si la grúa va sin carga"],"w":"Nadie sin licencia y autorización la mueve, ni un metro."},{"q":"Basta con tener licencia clase D para operar la grúa horquilla en la planta.","vf":false,"w":"Falso. Además debe estar capacitado y autorizado por la empresa."}]},{"s":"horquilla_altas","v":[{"q":"¿Cuál es la forma correcta de circular con carga?","o":["Horquillas bajas y mástil inclinado hacia atrás","Carga en alto, para ver por debajo","Carga a media altura para ganar tiempo","Horquillas bajas y mástil hacia adelante"],"w":"Carga baja: más estabilidad y mejor visión."},{"q":"¿A qué altura aproximada se llevan las horquillas al circular?","o":["Unos 15 cm del piso","A la altura del pecho del operador","A la altura del primer nivel del rack","Rozando el piso para frenar mejor"],"w":"Bajas, a unos 15 cm del piso."},{"q":"¿Cuándo se sube la carga a la altura del rack?","o":["Detenido y frente al rack","Mientras me acerco, para ganar tiempo","Al girar hacia el pasillo del rack","Desde que la tomo en el patio"],"w":"Se sube solo detenido frente al rack; nunca girar con la carga en alto."}]},{"s":"horquilla_q_vision","v":[{"q":"Llevas dos bins apilados que no te dejan ver hacia adelante. ¿Qué haces?","o":["Avanzo en reversa, mirando hacia donde voy","Avanzo de frente tocando la bocina","Subo la carga para mirar por debajo","Avanzo de frente asomándome por el lado"],"w":"Si la carga tapa la vista, se avanza en reversa."},{"q":"La carga te tapa la vista y en reversa tampoco ves bien. ¿Qué haces?","o":["Pido a un compañero que me guíe con señas","Avanzo despacio, aunque sea a ciegas","Levanto la carga para ver por debajo","Toco la bocina seguido y sigo avanzando"],"w":"Si no ves, un guía con señas."},{"q":"¿Cuál de estas prácticas es correcta con una carga voluminosa?","o":["Avanzar en reversa mirando el recorrido","Levantar la carga para ver por debajo","Avanzar de frente esperando que se corran","Ir más rápido para pasar luego el cruce"],"w":"Nunca avanzar a ciegas."}]},{"s":"horquilla_centro_mal","v":[{"q":"¿Cuál es la forma correcta de llevar el bin?","o":["Pegado al respaldo de las horquillas","Tomado en la punta de las horquillas","Con una sola horquilla bajo el bin","Separado del respaldo para equilibrar"],"w":"Carga lejos del respaldo: menos capacidad y riesgo de levantar la parte trasera."},{"q":"Al tomar un bin, quedó solo en las puntas de las horquillas. ¿Qué pasa?","o":["La grúa soporta menos kilos y puede levantarse atrás","La grúa soporta más kilos por la palanca","No cambia, si el bin está dentro de la placa","Solo cambia si hay pendiente"],"w":"Como un balancín: más lejos, menos capacidad."},{"q":"La placa de la grúa dice 2.500 kg y debes mover una carga de 2.800 kg. ¿Qué haces?","o":["No la muevo y aviso a la jefatura","La muevo despacio y con la carga baja","La muevo con un contrapeso extra atrás","La muevo si es un tramo corto"],"w":"Nunca se supera la capacidad de la placa."}]},{"s":"horquilla_q_rampa","v":[{"q":"Debes bajar una rampa con un bin cargado. ¿Cómo lo haces?","o":["En reversa, con la carga hacia arriba de la rampa","De frente, con la carga hacia abajo","De lado, para ir más despacio","De frente, con el mástil inclinado adelante"],"w":"Con carga, la carga siempre mira hacia arriba de la pendiente."},{"q":"Debes subir una rampa con un bin cargado. ¿Cómo lo haces?","o":["De frente, con la carga hacia arriba","En reversa, con la carga hacia abajo","En diagonal, para suavizar la pendiente","De lado, girando en la mitad"],"w":"Con carga: subir de frente, bajar en reversa."},{"q":"Vas sin carga por una rampa. ¿Hacia dónde van las horquillas?","o":["Hacia abajo de la pendiente","Hacia arriba de la pendiente","Da lo mismo sin carga","Levantadas a media altura"],"w":"Sin carga, las horquillas van hacia abajo."}]},{"s":"horquilla_vuelco","v":[{"q":"La grúa empieza a volcarse hacia un lado. ¿Qué haces?","o":["Me quedo dentro con cinturón, afirmado","Salto rápido hacia el lado contrario","Suelto el volante y me agacho en el asiento","Salto hacia el lado de la caída para alejarme"],"w":"Saltar es lo más peligroso: la máquina te puede aplastar."},{"q":"¿Cuál de estas acciones puede volcar la grúa hacia el lado?","o":["Girar rápido con la carga en alto","Circular con la carga baja","Bajar la rampa en reversa con carga","Tocar la bocina en un cruce"],"w":"Giros rápidos, carga en alto, hoyos y pendientes de lado provocan vuelcos."},{"q":"¿Por qué no se debe saltar de una grúa que se vuelca?","o":["Porque la máquina te puede aplastar","Porque te puedes torcer un tobillo al caer","Porque la grúa se detiene sola al volcarse","Porque puedes dañar el cinturón al soltarlo"],"w":"El cinturón te mantiene dentro de la estructura protectora."}]},{"s":"horquilla_q_pers","v":[{"q":"Un compañero te pide que lo subas en un bin sobre las horquillas para sacar algo del rack. ¿Qué haces?","o":["Me niego: se usa el equipo para personas","Lo subo despacio, con mucho cuidado","Lo subo si se afirma bien del mástil","Lo subo si no supera la altura del techo"],"w":"Nunca se eleva a personas en las horquillas: es falta grave."},{"q":"¿Puede un compañero viajar de pasajero en la grúa?","o":["No, nunca","Sí, sentado en las horquillas","Sí, de pie en el estribo","Sí, en tramos cortos"],"w":"La grúa no lleva pasajeros."},{"q":"Un compañero puede subirse a un bin sobre las horquillas para sacar algo del rack, si subo despacio.","vf":false,"w":"Falso. Las horquillas son solo para cargas."}]},{"s":"horquilla_portada","v":[{"q":"¿Cuándo debes usar el cinturón de seguridad en la grúa?","o":["En todo recorrido, aunque sea corto","Solo fuera de la bodega","Solo cuando llevas carga","Solo en rampas y pendientes"],"w":"El cinturón te mantiene bajo el techo protector si se vuelca."},{"q":"El cinturón de la grúa no abrocha. ¿Qué haces?","o":["No la uso y aviso","La uso solo dentro de la bodega","La uso sin carga","La uso y lo anoto al final del turno"],"w":"Sin cinturón funcionando, la grúa no se usa."},{"q":"El cinturón de la grúa va puesto en todo recorrido, aunque sea corto y dentro de la bodega.","vf":true,"w":"Verdadero. Si se vuelca, te mantiene bajo el techo protector."}]},{"s":"horquilla_q_estac","v":[{"q":"Terminas tu turno. ¿Cómo dejas la grúa?","o":["Horquillas al piso, freno, motor apagado y sin llave","Horquillas a media altura, lista para la próxima carga","Encendida y frenada, por si alguien la necesita","Con la llave puesta, para el siguiente operador"],"w":"Así nadie tropieza ni la mueve sin autorización."},{"q":"Te bajas cinco minutos de la grúa. ¿Qué haces?","o":["Bajo las horquillas, freno, apago y saco la llave","La dejo encendida con el freno puesto","Dejo la carga arriba para no perder tiempo","La dejo en el pasillo con la llave puesta"],"w":"Siempre igual, aunque sea por pocos minutos."},{"q":"¿Dónde NO se estaciona la grúa?","o":["Frente a una salida o un extintor","En su lugar demarcado de estacionamiento","Lejos de los cruces de peatones","Fuera de los pasillos de circulación"],"w":"Lejos de salidas, extintores, pasillos y cruces."}]},{"s":"horquilla_q_apuro","v":[{"q":"Hay un camión esperando y te piden apurarte. ¿Cuál es la decisión segura?","o":["Trabajar con calma, carga baja y cinturón","Girar más rápido, con la carga en alto","Llevar más bins de los que permite la placa","Andar sin cinturón para subir y bajar rápido"],"w":"El apuro no carga más rápido: carga accidentes."},{"q":"La línea pide bins con urgencia y el tramo es corto. ¿Qué haces?","o":["Mantengo velocidad moderada y cinturón puesto","Me salto el cinturón por ser corto","Llevo tres bins apilados aunque no vea","Giro rápido en las esquinas"],"w":"La urgencia no cambia las reglas."},{"q":"¿Cuál es la acción insegura más típica al operar con apuro?","o":["Girar rápido con carga y no usar cinturón","Tocar la bocina en los cruces","Avanzar en reversa con carga alta","Revisar el check list antes de partir"],"w":"Apurarse lleva a giros rápidos y a omitir el cinturón."}]}]},{"id":"horquilla_checklist","sec":"grua","title":"Revisión pre-uso y cuidado de la grúa","thumb":"horquilla_checklist_porque","mins":5,"learn":[{"s":"horquilla_checklist_porque","t":"El check-list diario","x":"Antes de usar la grúa en <b>cada turno</b>, revísala con el <b>check-list</b> de {EMP}, aunque otro operador la haya usado antes. Solo la opera quien tiene <b>licencia clase D vigente</b> y está <b>autorizado</b> por la empresa. Un freno que falla con un pallet de latas en alto no se arregla en el momento: la revisión toma unos minutos y te dice si la máquina puede trabajar <b>hoy</b>."},{"s":"horquilla_checklist_vuelta","t":"La vuelta alrededor","x":"Con el <b>motor apagado</b> y el freno puesto, da una <b>vuelta completa</b> a la grúa y mira: <ul><li><b>Neumáticos</b>: cortes, desgaste y pernos sueltos.</li><li><b>Fugas</b>: manchas de aceite, combustible o líquido hidráulico en el piso.</li><li>Golpes, piezas sueltas o protecciones que falten.</li><li><b>Techo protector</b> y respaldo de carga firmes.</li></ul>Una mancha nueva bajo la grúa es un aviso: anótala e informa."},{"s":"horquilla_checklist_horq","t":"Horquillas, cadenas y mástil","x":"<ul><li><b>Horquillas</b>: sin trizaduras ni dobladuras, parejas entre sí y con sus <b>trabas</b> puestas.</li><li><b>Cadenas</b> del mástil: sin eslabones dañados y con tensión pareja a ambos lados.</li><li><b>Mástil</b>: sin golpes; <b>mangueras hidráulicas</b> sin fugas, grietas ni roces.</li></ul>Estas piezas sostienen la carga. Si una falla, el pallet cae sobre quien esté cerca, aunque la carga sea liviana."},{"s":"horquilla_checklist_cabina","t":"Desde el asiento, motor encendido","x":"Sentado y con el <b>cinturón puesto</b>, enciende y prueba: <ul><li><b>Freno de servicio</b> y freno de estacionamiento.</li><li><b>Dirección</b>: suave y sin juego.</li><li><b>Bocina</b>, <b>luces</b> y baliza.</li><li><b>Alarma de retroceso</b>.</li><li>Subir, bajar e inclinar el mástil sin tirones ni ruidos.</li><li>Tablero sin luces de alerta.</li></ul>Un dispositivo de aviso que no funciona también es una falla."},{"s":"horquilla_checklist_falla","t":"Si algo falla","x":"<ul><li><b>No la uses</b>, ni \"solo un rato\" ni con cargas livianas.</li><li><b>Informa</b> de inmediato a tu jefatura.</li><li><b>Bloquéala</b>: saca la llave y pon la tarjeta <b>NO OPERAR</b> o el aviso que use la planta.</li><li>Anota la falla en el check-list.</li></ul>Así el siguiente turno no la usa sin saber. Si reparar no es tu función, no intentes repararla.","k":"Grúa con falla: no se usa, se informa y se bloquea."},{"s":"horquilla_checklist_firma","t":"Marca con la verdad","x":"El check-list es un <b>registro</b>: tu firma dice que la grúa se revisó de verdad. <b>Nunca lo firmes sin revisar</b>, no lo dejes firmado de antemano y no marques bien algo que está mal. Si un ítem falla, márcalo y describe lo que viste. Ese registro permite que mantención la repare y protege al próximo operador. Si no hay formulario, pídelo antes de operar."},{"s":"horquilla_checklist_glp","t":"Si tu grúa es a gas: cambio de cilindro","x":"Según el manual del fabricante y lo que indique tu jefatura: <ul><li><b>Motor apagado</b> y válvula del cilindro <b>cerrada</b> antes de soltarlo.</li><li>En lugar <b>ventilado</b>, lejos de fuego y sin fumar.</li><li><b>Guantes y lentes</b>: el gas líquido quema la piel por frío.</li><li>Cilindro bien fijo en su soporte y conexión firme.</li><li>Busca fugas con <b>agua jabonosa</b>: si hace burbujas, hay fuga.</li></ul>","k":"Las fugas de gas se buscan con agua jabonosa, jamás con fuego."},{"s":"horquilla_checklist_bateria","t":"Si tu grúa es eléctrica: carga de batería","x":"<ul><li>Carga solo en el <b>lugar destinado</b>, ventilado y señalizado.</li><li>Grúa apagada, llave fuera y freno puesto antes de conectar.</li><li>Conecta y desconecta con el <b>cargador apagado</b>, para no hacer chispas.</li><li><b>No fumes</b> ni uses llamas: las baterías de plomo ácido liberan <b>hidrógeno</b>, un gas inflamable, al cargar.</li><li>Si hay riesgo de ácido, usa guantes y lentes.</li></ul>"},{"s":"horquilla_checklist_combustible","t":"Carga de combustible","x":"Si tu grúa usa diésel o bencina: <ul><li><b>Motor apagado</b> siempre, aunque sea un momento.</li><li>Nadie fuma ni enciende llamas cerca.</li><li>No llenes hasta rebalsar y limpia de inmediato cualquier derrame.</li><li>Ten ubicado el <b>extintor</b> más cercano.</li><li>Cierra bien la tapa del estanque antes de mover la grúa.</li></ul>Basta el vapor del combustible y una chispa para iniciar un incendio."},{"s":"horquilla_checklist_auto","t":"Autocuidado: tú decides","x":"La mayoría de los accidentes se relacionan con una <b>acción insegura</b>. Aquí las típicas son <b>saltarse la revisión</b> porque \"ayer andaba bien\" o hay apuro, firmar sin mirar y <b>usar la grúa con una falla</b> conocida. La decisión segura: revisarla en cada turno y <b>detenerla si algo falla</b>. Avisar una falla a tu jefatura o al asesor en prevención también es autocuidado."}],"quiz":[{"s":"horquilla_checklist_porque","v":[{"q":"¿Cuándo se hace el check-list de la grúa horquilla?","o":["Antes de usarla, en cada turno","Una vez por semana, el día lunes","Solo cuando hace ruidos extraños","Cuando lo pide mantención"],"w":"La revisión es en cada turno y antes de operar: algo pudo cambiar desde el último uso."},{"q":"Llegas al turno de noche y la grúa la usó el turno de día sin problemas. ¿Qué corresponde?","o":["Hacer mi propio check-list antes de operar","Usarla, porque el turno de día ya la revisó","Revisar solo los frenos y partir","Hacer el check-list al terminar el turno"],"w":"Cada operador revisa la grúa antes de usarla en su turno, aunque otro la haya usado."},{"q":"Si el check-list del turno anterior está firmado, el operador que llega puede usar la grúa sin revisarla.","vf":false,"w":"Falso. Cada operador hace su propia revisión antes de usarla en su turno."}]},{"s":"horquilla_checklist_q_frenos","v":[{"q":"Al probar la grúa, el freno se siente blando. ¿Qué haces?","o":["No la uso, informo a mi jefatura y la bloqueo","La uso con cuidado y a poca velocidad","La uso hasta terminar y aviso al final","La uso solo para cargas livianas"],"w":"Grúa con falla: no se usa, se informa y se bloquea para que nadie la use sin saber."},{"q":"Detectaste una falla en la grúa y ya avisaste a tu jefatura. ¿Qué falta para que el próximo turno no la use?","o":["Sacar la llave y poner la tarjeta NO OPERAR","Dejarla estacionada en su lugar de siempre","Contarle al compañero que entra después","Dejar la llave puesta para mantención"],"w":"Bloquearla con la llave fuera y la tarjeta NO OPERAR evita que otro la use sin saber."},{"q":"¿Cuál es el orden correcto ante una falla de la grúa?","o":["No usarla, informar y bloquearla","Usarla con cuidado, informar y anotar","Repararla, probarla y seguir operando","Anotarla en el check-list y seguir"],"w":"Primero no se usa, luego se informa y se bloquea con llave fuera y tarjeta."}]},{"s":"horquilla_checklist_llama","v":[{"q":"Un compañero acerca un encendedor al cilindro de gas para ver si tiene fuga. ¿Qué le dices?","o":["Que se detenga: la fuga se busca con agua jabonosa","Que lo haga rápido y con el motor apagado","Que lo haga al aire libre para ventilar","Que use un fósforo, que es más seguro"],"w":"Una llama puede encender el gas. Con agua jabonosa, las burbujas muestran la fuga sin riesgo."},{"q":"¿Cómo se busca una fuga en la conexión del cilindro de gas?","o":["Con agua jabonosa: si hace burbujas, hay fuga","Acercando una llama pequeña a la conexión","Oliendo de cerca la válvula abierta","Apretando la conexión con más fuerza"],"w":"Las fugas se buscan con agua jabonosa. Jamás con fuego, y oler de cerca no es un método seguro."},{"q":"Al aplicar agua jabonosa en la conexión del cilindro aparecen burbujas. ¿Qué significa?","o":["Que hay una fuga de gas en la conexión","Que la conexión quedó bien apretada","Que el cilindro está casi vacío","Que el agua reaccionó con el metal"],"w":"Las burbujas indican fuga: cierra la válvula, no enciendas la grúa y avisa."}]},{"s":"horquilla_checklist_vuelta","v":[{"q":"En la vuelta alrededor ves una mancha nueva de aceite bajo la grúa. ¿Qué haces?","o":["La anoto en el check-list e informo antes de operar","La limpio y opero normalmente","Opero y reviso de nuevo al final del turno","La dejo, porque toda grúa gotea algo"],"w":"Una mancha nueva puede ser una fuga de frenos o hidráulica: se anota y se informa."},{"q":"¿En qué condición se hace la vuelta alrededor de la grúa?","o":["Con el motor apagado y el freno puesto","Con el motor encendido para oír ruidos","Con la carga levantada para ver el mástil","Mientras otro la mueve lentamente"],"w":"La inspección visual se hace con la grúa detenida y segura."},{"q":"Si el techo protector de la grúa está suelto, se puede operar igual mientras no se levante carga en altura.","vf":false,"w":"Falso. El techo protector y el respaldo deben estar firmes: es una falla que se informa."}]},{"s":"horquilla_checklist_cabina","v":[{"q":"La alarma de retroceso no suena, pero la bocina sí. ¿Puedes usar la grúa?","o":["No: es una falla, se informa y no se usa","Sí, tocando la bocina al retroceder","Sí, si retrocedo poco y despacio","Sí, si un compañero me hace señas"],"w":"Un dispositivo de aviso que falla es una falla de la grúa. Se informa y no se usa."},{"q":"¿Qué se prueba desde el asiento, con el motor encendido?","o":["Frenos, dirección, bocina, luces, alarma y mástil","Solo que el motor encienda bien","Neumáticos, pernos y manchas en el piso","Solo el nivel de combustible"],"w":"Desde el asiento se prueban los mandos; los neumáticos y fugas se ven en la vuelta."},{"q":"Al probar el mástil, sube con tirones y hace ruidos extraños. ¿Qué corresponde?","o":["No operar e informar la falla","Operar solo con pallets livianos","Subirlo varias veces hasta que se suavice","Operar y avisar si empeora"],"w":"Si no levanta bien, no sale: se informa y se bloquea."}]},{"s":"horquilla_checklist_horq","v":[{"q":"En la revisión ves un eslabón dañado en la cadena del mástil. ¿Qué corresponde?","o":["Detener la grúa e informar la falla","Seguir operando solo cargas livianas","Lubricar la cadena y seguir","Revisarla de nuevo al final del turno"],"w":"La cadena sostiene la carga: si se corta, la carga cae, aunque sea liviana."},{"q":"Una horquilla tiene una trizadura pequeña cerca del codo. ¿Qué haces?","o":["No opero e informo para que la cambien","Opero con la carga centrada en la otra","La marco con pintura y sigo operando","Opero solo a baja altura"],"w":"Una horquilla trizada puede romperse con la carga. Se informa y la grúa no se usa."},{"q":"Si una manguera hidráulica del mástil tiene una grieta pero no gotea, la grúa se puede usar.","vf":false,"w":"Falso. Una manguera con grietas puede reventar con la presión y la carga caer. Se informa."}]},{"s":"horquilla_checklist_q_glp","v":[{"q":"Al cambiar el cilindro de gas, ¿qué se hace primero?","o":["Apagar el motor y cerrar la válvula del cilindro","Soltar la conexión con el motor en marcha","Ponerse guantes y soltar el cilindro","Llevar la grúa a un lugar cerrado"],"w":"Motor apagado y válvula cerrada antes de desconectar, en lugar ventilado y lejos de fuego."},{"q":"¿Dónde se cambia el cilindro de gas de la grúa?","o":["En un lugar ventilado, lejos de fuego y sin fumar","En una bodega cerrada, para que no le llegue viento","Junto a la caldera, donde hace calor","En cualquier lugar si se hace rápido"],"w":"El gas se acumula en lugares cerrados. El cambio va en lugar ventilado y sin fuentes de fuego."},{"q":"¿Por qué se usan guantes y lentes al cambiar el cilindro de gas?","o":["Porque el gas líquido quema la piel por frío","Porque el cilindro está muy caliente","Solo para no ensuciarse las manos","Porque lo exige la norma de tránsito"],"w":"El gas licuado que escapa congela la piel y puede dañar los ojos."}]},{"s":"horquilla_checklist_q_comb","v":[{"q":"Vas a cargar diésel en la grúa y solo será un momento. ¿Cómo debe estar el motor?","o":["Apagado, siempre","Encendido, para no forzar la partida","En ralentí, si es solo un momento","Apagado solo si es bencina"],"w":"El motor va apagado siempre al cargar combustible: el vapor y una chispa bastan para un incendio."},{"q":"Al cargar combustible, el motor de la grúa puede quedar encendido si es solo un momento.","vf":false,"w":"Falso. El motor va apagado siempre al cargar combustible, y nadie fuma cerca."},{"q":"Al cargar combustible se derramó un poco en el piso. ¿Qué haces?","o":["Lo limpio de inmediato","Lo dejo, porque se evapora solo","Lo tapo con un cartón y sigo","Lo limpio al terminar el turno"],"w":"El combustible derramado genera vapores inflamables y hace resbalar: se limpia de inmediato."}]},{"s":"horquilla_checklist_q_bat","v":[{"q":"¿Dónde se carga la batería de una grúa eléctrica?","o":["En el lugar destinado, ventilado y sin fuego","En cualquier enchufe cercano de la bodega","En una sala cerrada, para que no se moje","Junto a la zona de cambio de gas"],"w":"Las baterías de plomo ácido liberan hidrógeno al cargar: lugar ventilado y nada de fuego."},{"q":"¿Qué gas inflamable pueden liberar las baterías de plomo ácido mientras se cargan?","o":["Hidrógeno","Oxígeno","Gas licuado","Monóxido de carbono"],"w":"El hidrógeno es inflamable: por eso no se fuma ni se hacen chispas al cargar."},{"q":"¿Cómo se conecta la grúa al cargador de batería?","o":["Grúa apagada y con el cargador apagado","Con la grúa encendida para que cargue más","Con el cargador encendido, de un tirón","Da igual, si el lugar es ventilado"],"w":"Conectar y desconectar con el cargador apagado evita chispas cerca del hidrógeno."}]},{"s":"horquilla_q_apuro","v":[{"q":"Hay apuro y la grúa \"ayer andaba bien\". ¿Cuál es la decisión segura?","o":["Hacer el check-list igual: toma unos minutos","Saltarme la revisión solo por hoy","Firmar el check-list y revisarla después","Revisar solo lo que falló la última vez"],"w":"Saltarse la revisión es la acción insegura típica. Unos minutos evitan un accidente."},{"q":"Tu jefe te pide sacar un pedido urgente. ¿Qué haces con el check-list?","o":["Lo hago completo antes de operar","Lo firmo ahora y lo reviso más tarde","Lo dejo para el próximo turno","Le pido a un compañero que lo firme"],"w":"El check-list se hace de verdad antes de operar. Firmar sin revisar es engañarte a ti mismo."},{"q":"Dejar el check-list firmado de antemano para ahorrar tiempo es una práctica aceptable si la grúa es nueva.","vf":false,"w":"Falso. La firma es constancia de una revisión real, aunque la grúa sea nueva."}]}]},{"id":"camion_conduccion","sec":"conductores","title":"Conducción segura de camiones","thumb":"camion_conduccion_intro","mins":5,"learn":[{"s":"camion_conduccion_intro","t":"Manejas un camión cargado","x":"Un camión con pallets de conservas pesa varias toneladas: <b>necesita más distancia para frenar</b> y tiene <b>zonas que no ves</b>. Para conducirlo necesitas la <b>licencia profesional que corresponde al vehículo</b> (Ley de Tránsito 18.290), vigente y contigo. Un choque durante un despacho o un retiro de materia prima es <b>accidente del trabajo</b> (Ley 16.744): se avisa de inmediato y se atiende en la ACHS, fono 1404."},{"s":"camion_conduccion_revision","t":"Revisión antes de salir","x":"Antes de cada salida, da una vuelta al camión y revisa:<ul><li><b>Frenos</b> y freno de mano.</li><li><b>Neumáticos</b>: presión, cortes y pernos.</li><li><b>Luces</b>, intermitentes y <b>alarma de retroceso</b>.</li><li><b>Espejos</b> limpios y bien puestos.</li><li>Fugas bajo el camión.</li><li>Documentos al día: revisión técnica, permiso de circulación y SOAP.</li></ul>Si algo falla, <b>no salgas</b> y avisa a tu jefatura."},{"s":"camion_conduccion_ciegos","t":"Puntos ciegos","x":"Alrededor del camión hay zonas que <b>no ves</b>, ni siquiera con los espejos:<ul><li><b>Atrás</b>: la zona más grande.</li><li><b>Al lado derecho</b>, junto a la cabina.</li><li><b>Justo delante</b> de la cabina.</li></ul>Antes de mover el camión en el andén o el patio, mira los espejos y <b>da una vuelta</b> si alguien pudo acercarse. Para los peatones: si no ves los espejos del camión, el conductor no te ve."},{"s":"camion_conduccion_retro_ok","t":"Retroceder con ayuda","x":"Retroceder es la maniobra más riesgosa: atrás está tu zona ciega más grande.<ul><li>Usa un <b>señalero</b> (tu ayudante), siempre <b>visible en tu espejo</b>.</li><li>Acuerden antes las señales: avanzar, parar.</li><li>La <b>alarma de retroceso</b> debe funcionar.</li><li>Retrocede lento. Si pierdes de vista al señalero, <b>detente</b>.</li><li>Si estás solo y no ves, <b>bájate y mira</b>.</li></ul>","k":"Si pierdes de vista al señalero, detente."},{"s":"camion_conduccion_velocidad","t":"Velocidad y distancia","x":"Respeta los <b>límites de velocidad</b>: en zona urbana el máximo general es <b>50 km/h</b>, y dentro de la planta, el señalizado. Deja <b>más distancia</b> con el vehículo de adelante que en un auto: con carga, el camión tarda más en detenerse. Baja la velocidad con <b>lluvia, neblina, ripio y curvas</b>, en caminos rurales hacia los predios y cerca de colegios. Llegar unos minutos tarde no es grave; un choque sí."},{"s":"camion_conduccion_fatiga","t":"Fatiga y sueño","x":"El sueño al volante es traicionero: <b>cierras los ojos un segundo y el camión sigue avanzando</b>. Señales: bostezos, pestañeo seguido, no recordar los últimos kilómetros.<ul><li>Duerme bien antes de tu turno y respeta los descansos.</li><li>En carga interurbana, la ley no permite manejar más de <b>5 horas continuas</b>.</li><li>Si tienes sueño, <b>detente en un lugar seguro</b>.</li><li>Avisa si un medicamento te da sueño.</li></ul>"},{"s":"camion_conduccion_cabina","t":"Cinturón y celular","x":"<ul><li><b>Cinturón de seguridad</b> siempre, para ti y para tu <b>ayudante</b>, aunque el viaje sea corto.</li><li>El <b>celular</b> quita tus ojos y tu mente del camino. La Ley de Tránsito <b>prohíbe manipularlo</b> al conducir: ni llamar con la mano, ni escribir, ni mirar videos.</li><li>Si necesitas llamar o revisar una dirección, <b>detente en un lugar seguro</b>.</li><li>Programa el GPS antes de partir.</li></ul>"},{"s":"camion_conduccion_alcohol","t":"Cero alcohol y cero drogas","x":"La Ley 20.580, conocida como Tolerancia Cero, establece:<ul><li>desde <b>0,3 g/l</b> y bajo 0,8 g/l: <b>bajo la influencia</b> del alcohol;</li><li>desde <b>0,8 g/l</b>: <b>estado de ebriedad</b>.</li></ul>En el trabajo la regla es <b>cero alcohol y cero drogas</b>. El alcohol de la noche anterior puede seguir en tu sangre. Si alguien llega bajo sus efectos, <b>no conduce</b> y se avisa a la jefatura.","k":"Al trabajar: cero alcohol y cero drogas."},{"s":"camion_conduccion_obra","t":"Al llegar al cliente o al predio","x":"Antes de entrar a un centro de distribución, a un cliente o a un predio agrícola, <b>mira el lugar</b>:<ul><li><b>Cables eléctricos</b> aéreos: la carrocería no debe acercarse a ellos.</li><li><b>Terreno blando</b>, barro, zanjas o rellenos que pueden ceder.</li><li><b>Pendientes</b>: no cargues ni descargues en desnivel.</li><li>Personas y niños alrededor.</li></ul>Si no es seguro, <b>no entres</b>: coordina otro punto y avisa a tu jefatura."},{"s":"camion_conduccion_auto","t":"Autocuidado al volante","x":"La mayoría de los accidentes se relacionan con <b>acciones inseguras</b>. En el camión, la típica es <b>el apuro</b>: retroceder sin mirar, saltarse la revisión, contestar el celular o manejar con sueño para llegar antes. La decisión segura: <b>revisar, mirar y, si dudas, bajarte a ver</b>. Avisa también las condiciones inseguras: frenos raros, un espejo roto, un acceso peligroso."}],"quiz":[{"s":"camion_conduccion_revision","v":[{"q":"En la revisión antes de salir notas que el freno está raro. ¿Qué haces?","o":["No salgo y aviso a mi jefatura","Salgo despacio y lo reviso a la vuelta","Salgo y lo comento al final del día","Salgo, pero solo a clientes cercanos"],"w":"Un camión con falla no sale. Una falla en ruta, con carga, es mucho más peligrosa."},{"q":"Al revisar el camión ves que la alarma de retroceso no suena. ¿Qué corresponde?","o":["No salir y avisar para que la reparen","Salir y tocar la bocina al retroceder","Salir y retroceder solo con espejos","Salir si el ayudante va de señalero"],"w":"La alarma de retroceso es parte de la revisión: si falla, el camión no sale."},{"q":"Vas a salir a despacho y ves que la revisión técnica del camión está vencida. ¿Qué haces?","o":["No salgo y aviso a mi jefatura","Salgo, porque es un viaje corto","Salgo por caminos con menos control","Salgo y la renuevo la próxima semana"],"w":"Los documentos al día son parte de la revisión antes de salir."}]},{"s":"camion_conduccion_ciegos","v":[{"q":"¿Dónde está la zona ciega más grande de un camión?","o":["Atrás del camión","Al lado izquierdo de la cabina","Justo delante de la cabina","Al lado derecho de la cabina"],"w":"Atrás no ves nada directamente. Por eso al retroceder se usa señalero."},{"q":"Un compañero camina junto al lado derecho de la cabina del camión. ¿Qué debe saber?","o":["Que ahí está en un punto ciego del conductor","Que ahí el conductor lo ve por la ventana","Que es el lugar más seguro para caminar","Que solo es peligroso si el camión retrocede"],"w":"El lado derecho junto a la cabina es una zona que el conductor no ve, ni con espejos."},{"q":"Si un peatón no puede ver los espejos del camión, el conductor tampoco lo ve a él.","vf":true,"w":"Verdadero. Si no ves los espejos del camión, estás en un punto ciego."}]},{"s":"camion_conduccion_retro_mal","v":[{"q":"Debes retroceder al andén, no tienes señalero y alguien podría pasar atrás. ¿Qué haces?","o":["Me bajo a mirar y retrocedo solo si está despejado","Retrocedo lento confiando en la alarma","Retrocedo mirando solo los espejos","Toco la bocina y retrocedo de inmediato"],"w":"Atrás está la zona ciega más grande. Si estás solo y no ves, te bajas a mirar."},{"q":"Retrocedes con señalero y de pronto ya no lo ves en el espejo. ¿Qué haces?","o":["Me detengo hasta volver a verlo","Sigo lento, porque ya conoce la maniobra","Sigo, porque la alarma está sonando","Acelero un poco para terminar rápido"],"w":"Si pierdes de vista al señalero, te detienes: puede estar en tu zona ciega."},{"q":"¿Dónde debe ubicarse el señalero que te guía al retroceder?","o":["Siempre visible en el espejo del conductor","Justo detrás del camión, al centro","Dentro de la cabina, junto al conductor","Donde quiera, si la alarma funciona"],"w":"El señalero debe verse en el espejo y fuera de la trayectoria del camión."}]},{"s":"camion_conduccion_auto","v":[{"q":"Vas atrasado con el despacho. ¿Cuál es la decisión segura?","o":["Hacer la revisión y maniobrar con calma igual","Saltarme la revisión solo por esta vez","Retroceder sin señalero para ganar tiempo","Compensar el atraso subiendo la velocidad"],"w":"La mayoría de los accidentes vienen del apuro. Unos minutos no valen un accidente."},{"q":"Llegas a un cliente y no estás seguro de si cabes en el acceso. ¿Qué haces?","o":["Me bajo a mirar antes de maniobrar","Entro lento y veo si alcanzo","Le pido al cliente que me avise si choco","Entro de retroceso para salir más rápido"],"w":"Si dudas, bájate y mira: revisar toma un minuto."},{"q":"Notas que un espejo del camión quedó suelto después de un viaje. ¿Qué corresponde?","o":["Avisar a la jefatura para que lo reparen","Dejarlo así si aún se ve algo","Ajustarlo con cinta y no decir nada","Esperar a que se caiga para avisar"],"w":"Avisar las condiciones inseguras también es autocuidado."}]},{"s":"camion_conduccion_alcohol","v":[{"q":"Según la Ley 20.580, ¿desde qué nivel de alcohol en la sangre hay estado de ebriedad?","o":["Desde 0,8 g/l","Desde 0,3 g/l","Desde 0,5 g/l","Desde 1,0 g/l"],"w":"Desde 0,3 g/l es bajo la influencia; desde 0,8 g/l, ebriedad. En el trabajo: cero."},{"q":"Según la Ley 20.580, un conductor con 0,4 g/l de alcohol en la sangre está:","o":["Bajo la influencia","En estado de ebriedad","Dentro de lo permitido","Sin efectos legales"],"w":"Desde 0,3 g/l y bajo 0,8 g/l es bajo la influencia del alcohol."},{"q":"Según la Ley 20.580, ¿desde qué nivel se considera conducir bajo la influencia del alcohol?","o":["Desde 0,3 g/l","Desde 0,8 g/l","Desde 0,1 g/l","Desde 0,5 g/l"],"w":"0,3 g/l: bajo la influencia. 0,8 g/l: ebriedad."}]},{"s":"c5au_alcohol","v":[{"q":"Si el examen marca menos de 0,3 g/l, puedo conducir el camión de la empresa sin problema.","vf":false,"w":"Falso. La regla al trabajar es cero alcohol y cero drogas."},{"q":"Anoche tomaste varias cervezas y hoy te toca conducir temprano. ¿Qué haces?","o":["Aviso a mi jefatura antes de conducir","Manejo, porque ya dormí unas horas","Tomo café y manejo con cuidado","Manejo solo trayectos cortos"],"w":"El alcohol de la noche anterior puede seguir en la sangre. La regla es cero."},{"q":"Un compañero llega al turno con olor a alcohol y va a conducir. ¿Qué corresponde?","o":["Que no conduzca y avisar a la jefatura","Dejarlo manejar si dice que está bien","Que maneje, pero acompañado","Esperar a que termine el despacho"],"w":"Quien llega bajo los efectos del alcohol no conduce: se avisa a la jefatura."}]},{"s":"camion_conduccion_fatiga","v":[{"q":"Vas manejando y empiezas a bostezar y pestañear seguido. ¿Qué haces?","o":["Me detengo en un lugar seguro a descansar","Abro la ventana y subo la música","Acelero para llegar antes","Tomo una bebida energética y sigo"],"w":"Son señales de sueño. La ventana o la música no lo quitan: detente en un lugar seguro."},{"q":"¿Cuál de estas es una señal de sueño al volante?","o":["No recordar los últimos kilómetros","Tener hambre a media mañana","Sentir frío en la cabina","Tener ganas de escuchar música"],"w":"Bostezos, pestañeo seguido y no recordar el camino son señales de sueño."},{"q":"Tomaste un remedio para el resfrío que da sueño y hoy te toca conducir. ¿Qué haces?","o":["Aviso a mi jefatura antes de conducir","Manejo y paro si me da mucho sueño","Tomo café cargado y manejo igual","Manejo con la ventana abierta"],"w":"Un medicamento que da sueño es un riesgo al volante: avisa antes de conducir."}]},{"s":"camion_conduccion_celu_mal","v":[{"q":"Suena el celular mientras manejas. ¿Qué haces?","o":["Me detengo en un lugar seguro y devuelvo la llamada","Contesto rápido sosteniéndolo con la mano","Leo el mensaje en el próximo semáforo","Contesto en altavoz sosteniéndolo"],"w":"El celular quita tus ojos y tu mente del camino. Úsalo detenido en un lugar seguro."},{"q":"Necesitas revisar la dirección del cliente en el celular. ¿Cuándo lo haces?","o":["Detenido en un lugar seguro","En una recta con poco tráfico","En el semáforo en rojo","A baja velocidad, mirando rápido"],"w":"La Ley de Tránsito prohíbe manipular el celular al conducir."},{"q":"Escribir un mensaje en el celular está permitido mientras el camión está detenido en un taco.","vf":false,"w":"Falso. En un taco sigues conduciendo. Para usar el celular, detente en un lugar seguro."}]},{"s":"camion_conduccion_cabina","v":[{"q":"El ayudante también debe usar cinturón de seguridad, aunque el viaje sea corto.","vf":true,"w":"Verdadero. Todos los que van en la cabina usan cinturón, siempre."},{"q":"El despacho es a pocas cuadras de la planta. ¿Quiénes usan cinturón en la cabina?","o":["El conductor y el ayudante","Solo el conductor","Nadie, en trayectos cortos","Solo el ayudante"],"w":"El cinturón es para todos los ocupantes, aunque el viaje sea corto."},{"q":"Tu ayudante dice que en viajes urbanos no necesita cinturón. ¿Qué le respondes?","o":["Que se lo ponga: es para todos y siempre","Que tiene razón si vamos lento","Que solo es obligatorio en carretera","Que se lo ponga si hay Carabineros"],"w":"Cinturón para todos los ocupantes, en cualquier trayecto."}]},{"s":"camion_conduccion_obra","v":[{"q":"Al llegar a un predio ves cables eléctricos sobre el punto de carga. ¿Qué haces?","o":["No cargo ahí: busco otro punto y coordino","Cargo rápido y me voy","Levanto los cables con un palo seco","Cargo con cuidado de no tocarlos"],"w":"Un contacto con cables eléctricos puede ser mortal. Si no es seguro, no entres."},{"q":"El punto de descarga del cliente es un terreno con barro y una zanja cerca. ¿Qué haces?","o":["No entro y coordino un punto firme","Entro rápido para no quedar pegado","Entro y descargo lo más cerca posible","Le pido al cliente que me empuje si me entierro"],"w":"El terreno blando puede ceder y volcar el camión. Si no es seguro, no entres."},{"q":"El cliente te pide descargar en una pendiente pronunciada. ¿Qué corresponde?","o":["Buscar un lugar plano y coordinar con el cliente","Descargar con el freno de mano puesto","Descargar rápido antes de que se mueva","Descargar solo la mitad ahí"],"w":"No se descarga en desnivel: la carga y el camión pueden moverse."}]}]},{"id":"camion_estiba","sec":"conductores","title":"Estiba y amarre de la carga","thumb":"camion_estiba_intro","mins":5,"learn":[{"s":"camion_estiba_intro","t":"Carga suelta = peligro","x":"Una carga mal estibada puede <b>caer a la vía</b>, golpear a alguien al soltar los amarres o <b>volcar el camión</b> en una curva. En {EMP} la carga típica son pallets de latas y frascos: si un pallet se corre, se desarma y cae. La regla: <b>la carga va estibada y amarrada para que no se mueva ni caiga</b>. Antes de salir, tú como conductor revisas que vaya bien puesta y bien amarrada.","k":"La carga va estibada y amarrada, aunque el viaje sea corto."},{"s":"camion_estiba_peso","t":"Distribuye el peso","x":"<ul><li>Lo <b>más pesado abajo</b> y al centro, sobre los ejes.</li><li>Lo liviano arriba: nunca frascos bajo pallets pesados.</li><li>Reparte el peso a ambos lados.</li><li>Apoya la carga contra la <b>cabecera</b>, sin espacios.</li></ul>Si el peso va alto o cargado a un lado, el camión se inclina en las curvas y puede volcar. Si va todo atrás, la dirección se pone liviana y cuesta controlar el camión."},{"s":"camion_estiba_larga","t":"Pallets altos y carga que sobresale","x":"<ul><li>Pallets <b>envueltos con film</b>, sin cajas rotas ni aplastadas.</li><li>Pallets altos o carga larga: amárralos en <b>varios puntos</b>, no solo en un extremo.</li><li>Lo que <b>sobresale atrás</b> se señaliza con <b>bandera o paño rojo</b> de día y con <b>luz roja</b> de noche.</li><li>Nada debe sobresalir hacia los lados.</li></ul>Si no cabe de forma segura, se busca otro camión u otro viaje."},{"s":"camion_estiba_amarre","t":"Eslingas, cintas y tensores","x":"Antes de usarlos, revísalos:<ul><li>Cinta sin <b>cortes, quemaduras ni hilos sueltos</b>.</li><li><b>Etiqueta legible</b> con su capacidad.</li><li>Tensor y ganchos sin deformaciones.</li></ul>Usa <b>suficientes amarres</b>, engánchalos en los puntos de amarre del camión y tensa con el tensor, sin alargar la palanca con un tubo. Una cinta dañada <b>se retira</b>: no se arregla con nudos.","k":"Cinta dañada o sin etiqueta no se usa."},{"s":"camion_estiba_canto_mal","t":"Protege los cantos vivos","x":"Si una cinta se apoya en un <b>canto vivo</b>, se puede cortar: el borde de un pallet, un fleje metálico o una esquina con filo cortan la cinta con el roce y la tensión, y la carga queda suelta. Además, la cinta sin protección aplasta las cajas de las esquinas.<ul><li>Pon <b>cantoneras</b> o protectores en cada esquina donde pase la cinta.</li><li>Revisa la cinta en esos puntos al llegar.</li></ul>"},{"s":"camion_estiba_frenado","t":"Al frenar, la carga sigue","x":"Cuando el camión frena de golpe, la carga <b>sigue avanzando</b> con la fuerza que llevaba. Si no está amarrada o hay huecos, <b>se corre hacia la cabina</b> y puede aplastarla; en una curva, se cae por los lados. Por eso: carga <b>apoyada contra la cabecera</b>, sin huecos y bien amarrada. Y maneja suave: <b>frena y dobla con anticipación</b>, sin maniobras bruscas."},{"s":"camion_estiba_revisar","t":"Revisa los amarres en el camino","x":"Con las vibraciones, los baches y los caminos de ripio, la carga se asienta y <b>los amarres se sueltan</b>.<ul><li>Revisa antes de salir.</li><li>Detente en un <b>lugar seguro</b> para revisar después de los primeros kilómetros y tras caminos en mal estado.</li><li>Si la carga se movió, <b>reacomódala y vuelve a tensar</b>.</li><li>Al llegar, revisa antes de soltar: la carga pudo quedar apoyada en la cinta.</li></ul>"},{"s":"camion_estiba_sobrecarga","t":"No sobrecargues","x":"Cada camión tiene una <b>capacidad máxima de carga</b> indicada por el fabricante. Si la pasas:<ul><li>los <b>frenos</b> rinden menos;</li><li>los <b>neumáticos</b> y la suspensión se dañan;</li><li>el camión <b>vuelca</b> con más facilidad.</li></ul>Verifica el peso en la <b>romana</b> de la planta. Si te piden cargar más de lo que el camión soporta, <b>avisa a tu jefatura</b> y divide el despacho en dos viajes."},{"s":"camion_estiba_auto","t":"Autocuidado en la estiba","x":"La mayoría de los accidentes se relacionan con una <b>acción insegura</b>. En la estiba, la típica es pensar \"<b>es cerquita, no la amarro</b>\" o usar una cinta dañada \"por esta vez\". La decisión segura: <b>amarrar siempre</b>, aunque sean dos cuadras. Avisa también las condiciones inseguras: cintas rotas, puntos de amarre dañados, falta de cantoneras o pallets mal envueltos."}],"quiz":[{"s":"camion_estiba_intro","v":[{"q":"¿Cuál es la regla para la carga del camión?","o":["Estibada y amarrada para que no se mueva ni caiga","Bien apilada, porque su propio peso la sujeta","Amarrada solo en viajes por carretera","Envuelta en film, que reemplaza los amarres"],"w":"El peso y el film no bastan: al frenar o doblar, la carga se mueve si no va amarrada."},{"q":"Antes de salir a despacho, ¿quién revisa que la carga vaya bien amarrada?","o":["El conductor del camión","Solo el operador de la grúa","El cliente al recibirla","Nadie, si la cargó personal de bodega"],"w":"El conductor revisa la estiba y los amarres antes de salir, aunque otro haya cargado."},{"q":"Si los pallets van bien envueltos con film, no es necesario amarrarlos al camión.","vf":false,"w":"Falso. El film mantiene unidas las cajas, pero no impide que el pallet se corra."}]},{"s":"camion_estiba_peso","v":[{"q":"¿Dónde va lo más pesado de la carga?","o":["Abajo, al centro y contra la cabecera","Arriba, para que aplaste y afirme","Al final de la plataforma","Cargado a un lado, junto a la baranda"],"w":"Así el camión es más estable y la carga no se corre al frenar."},{"q":"Debes cargar pallets de latas pesados y cajas de frascos livianos. ¿Cómo los ubicas?","o":["Latas abajo y frascos arriba, sin huecos","Frascos abajo y latas arriba, bien juntos","Latas atrás y frascos contra la cabecera","Todo a un lado para descargar más fácil"],"w":"Lo pesado va abajo y lo frágil y liviano arriba, todo contra la cabecera."},{"q":"¿Qué puede pasar si la carga va alta o cargada a un solo lado?","o":["Que el camión se incline y vuelque en una curva","Que el camión gaste menos combustible","Que la carga se afirme mejor en el viaje","Que solo se dañen los neumáticos traseros"],"w":"El peso alto o a un lado desestabiliza el camión en las curvas."}]},{"s":"camion_estiba_canto_mal","v":[{"q":"La cinta de amarre queda apoyada en el borde con filo de la carga. ¿Qué haces?","o":["Pongo una cantonera entre la cinta y el borde","Tenso más la cinta para que no se mueva","Pongo dos cintas juntas en ese punto","La dejo, porque la cinta es resistente"],"w":"Sin cantonera, el canto vivo corta la cinta con el roce y la tensión."},{"q":"¿Para qué sirve una cantonera en el amarre?","o":["Evita que el canto vivo corte la cinta","Hace que la cinta se tense sola","Reemplaza a uno de los amarres","Sirve solo para que la carga se vea ordenada"],"w":"La cantonera protege la cinta y las cajas en las esquinas."},{"q":"Al llegar al cliente ves que la cinta tiene un corte justo donde tocaba una esquina. ¿Qué pasó?","o":["Faltó cantonera en el canto vivo","La cinta venía mala de fábrica","El tensor quedó poco apretado","La lluvia debilitó la cinta"],"w":"Donde hay filo va cantonera; esa cinta se retira."}]},{"s":"camion_estiba_amarre","v":[{"q":"Una cinta con cortes se puede usar si la carga es liviana.","vf":false,"w":"Falso. Una cinta dañada se retira: puede cortarse con la tensión o en un frenazo."},{"q":"Una cinta de amarre tiene la etiqueta borrada, pero se ve en buen estado. ¿Qué haces?","o":["No la uso: sin etiqueta no sé su capacidad","La uso si la carga es liviana","La uso doblada para que resista más","La uso y la reviso al llegar"],"w":"Sin etiqueta legible no se conoce su capacidad: no se usa."},{"q":"El tensor cuesta y un compañero propone alargar la palanca con un tubo. ¿Qué le dices?","o":["Que no: puede romper la cinta o el tensor","Que sí, así queda más firme","Que sí, pero solo en la última vuelta","Que use un fierro más largo"],"w":"Alargar la palanca sobrepasa la capacidad del tensor y de la cinta."}]},{"s":"camion_estiba_larga","v":[{"q":"Llevas carga que sobresale atrás del camión. ¿Qué haces?","o":["Bandera roja y amarre en varios puntos","Bandera roja solo si viajo de noche","Un amarre firme en la punta que sobresale","Nada, porque igual se ve desde atrás"],"w":"Lo que sobresale se señaliza para que lo vean, y se amarra en varios puntos."},{"q":"Vas a viajar de noche con carga que sobresale atrás. ¿Cómo se señaliza?","o":["Con luz roja en el extremo","Con un paño blanco reflectante","Con la luz de freno del camión","No se señaliza si va bien amarrada"],"w":"De día, bandera o paño rojo; de noche, luz roja."},{"q":"Un pallet no cabe completo y sobresaldría por un costado. ¿Qué corresponde?","o":["Buscar otro camión u otro viaje","Amarrarlo bien y señalizar el costado","Ladearlo un poco para que quepa","Llevarlo así si el camino es corto"],"w":"Nada debe sobresalir a los lados. Si no cabe seguro, otro camión u otro viaje."}]},{"s":"camion_estiba_frenado","v":[{"q":"Al frenar de golpe, ¿qué hace una carga sin amarrar?","o":["Sigue avanzando y se corre hacia la cabina","Se queda quieta por su propio peso","Se va hacia la parte de atrás","Se aplasta, pero no se mueve"],"w":"La carga sigue con la fuerza que llevaba. Por eso va contra la cabecera y amarrada."},{"q":"¿Por qué la carga debe ir contra la cabecera y sin huecos?","o":["Para que no tome impulso y se corra al frenar","Para descargar más rápido en el cliente","Para que el camión gaste menos","Porque así cabe más carga atrás"],"w":"Un hueco deja que la carga tome impulso al frenar."},{"q":"¿Cómo conviene manejar con una carga pesada?","o":["Frenando y doblando con anticipación","Frenando fuerte al final para probar amarres","Tomando las curvas rápido para no ladearse","A cualquier ritmo, si va bien amarrada"],"w":"Las maniobras bruscas mueven la carga, aunque vaya amarrada."}]},{"s":"camion_estiba_revisar","v":[{"q":"¿Cuándo se revisan los amarres?","o":["Antes de salir y también en el camino","Solo al llegar a destino","Solo antes de salir, si quedaron firmes","Solo cuando se escucha un ruido"],"w":"Las vibraciones y los baches sueltan los amarres. Revisa detenido en un lugar seguro."},{"q":"Acabas de pasar un camino de ripio en mal estado. ¿Qué haces?","o":["Me detengo en un lugar seguro y reviso los amarres","Sigo y reviso al llegar al cliente","Sigo, porque en la planta quedaron bien","Miro por el espejo sin detenerme"],"w":"Después de caminos malos se revisa: la carga se asienta y los amarres se sueltan."},{"q":"Al llegar al cliente, conviene revisar la carga antes de soltar los amarres.","vf":true,"w":"Verdadero. La carga pudo correrse y quedar apoyada en la cinta: al soltar puede caer."}]},{"s":"camion_estiba_sobrecarga","v":[{"q":"Si el camión \"aguanta\", se puede cargar un poco más de su capacidad máxima.","vf":false,"w":"Falso. Con sobrecarga frena peor y vuelca más fácil. Si sobra carga, se hace otro viaje."},{"q":"La romana muestra que el camión va sobre su capacidad. ¿Qué haces?","o":["Aviso a mi jefatura y se divide en dos viajes","Salgo despacio para cuidar los frenos","Salgo, porque la diferencia es poca","Inflo más los neumáticos y salgo"],"w":"Respeta la capacidad del camión: si sobra carga, otro viaje."},{"q":"¿Qué le pasa a un camión sobrecargado?","o":["Frena peor y vuelca con más facilidad","Se afirma mejor en las curvas","Solo gasta un poco más de combustible","No le pasa nada si el viaje es corto"],"w":"La sobrecarga reduce el frenado y daña neumáticos y suspensión."}]},{"s":"camion_estiba_auto","v":[{"q":"El despacho es a dos cuadras. ¿Amarras la carga?","o":["Sí, la carga siempre se amarra","No, es muy cerca","Solo si hay curvas en el camino","Solo los pallets de arriba"],"w":"Un frenazo puede ocurrir en cualquier cuadra. La carga siempre va amarrada."},{"q":"Solo queda una cinta con hilos sueltos y hay apuro por salir. ¿Qué haces?","o":["No la uso y pido una cinta en buen estado","La uso por esta vez con cuidado","La uso y le hago un nudo en lo dañado","Salgo con un amarre menos"],"w":"Usar una cinta dañada por esta vez es la acción insegura típica."},{"q":"Ves que un punto de amarre del camión está doblado. ¿Qué haces?","o":["Aviso a mi jefatura para que lo reparen","Amarro igual en ese punto","Lo enderezo a golpes y sigo","Lo dejo para la próxima revisión"],"w":"Avisar las condiciones inseguras también es autocuidado."}]}]},{"id":"camion_carga","sec":"conductores","title":"Carga y descarga del camión","thumb":"camion_carga_intro","mins":5,"learn":[{"s":"camion_carga_intro","t":"El patio de carga","x":"En el patio y los andenes de {EMP} se juntan <b>camiones, grúas horquilla, proveedores con materia prima y peatones</b>. Los accidentes típicos al cargar y descargar son:<ul><li><b>caídas</b> desde la plataforma o la cabina;</li><li><b>golpes y aplastamientos</b> con la carga;</li><li><b>atropellos</b> en el patio;</li><li>lesiones por levantar mal.</li></ul>Usa tu chaleco reflectante y camina por las rutas peatonales."},{"s":"camion_carga_preparar","t":"Antes de cargar: asegura el camión","x":"<ul><li><b>Motor apagado</b> y llave fuera del contacto.</li><li><b>Freno de mano</b> puesto.</li><li><b>Calzos</b> en las ruedas, sobre todo en pendiente o cuando la grúa entra a la plataforma.</li><li>Conos o señalización alrededor, donde la planta lo indique.</li></ul>Un camión que se mueve mientras alguien está arriba o mientras la grúa carga puede botar a una persona o la carga."},{"s":"camion_carga_subir_ok","t":"Subir y bajar: 3 puntos de apoyo","x":"Saltar de la plataforma o de la cabina causa torceduras, fracturas y golpes.<ul><li>Sube y baja <b>de frente</b> al camión, usando peldaños y asideros.</li><li>Mantén <b>3 puntos de apoyo</b>: dos manos y un pie, o dos pies y una mano.</li><li>No bajes con carga en las manos: pásala a otro.</li><li>Cuidado con peldaños mojados o con barro.</li></ul>","k":"Nunca saltes: baja de frente con 3 puntos de apoyo."},{"s":"camion_carga_borde","t":"La plataforma es un borde","x":"Sobre la plataforma estás sobre el nivel del piso: una caída desde ahí puede causar fracturas y golpes en la cabeza.<ul><li>No camines <b>de espaldas</b> mientras tiras o acomodas carga.</li><li>Mantente lejos del borde.</li><li>No te subas <b>sobre la carga</b> suelta ni a pilas de pallets inestables.</li><li>No estés arriba mientras la grúa deja o saca carga.</li></ul>"},{"s":"camion_carga_grua","t":"Coordina con la grúa horquilla","x":"La grúa horquilla <b>solo la opera quien está capacitado y autorizado</b> por la empresa. Mientras carga el camión:<ul><li>Ubícate en una <b>zona segura</b>, fuera de su recorrido.</li><li>Haz <b>contacto visual</b> con el operador antes de acercarte.</li><li>Acuerden señales simples: parar, subir, bajar.</li><li>Nadie arriba de la plataforma mientras la grúa deja o saca carga.</li></ul>"},{"s":"camion_carga_susp_mal","t":"Nadie bajo carga suspendida","x":"Una carga levantada puede <b>caer en cualquier momento</b>: un pallet quebrado, cajas mal envueltas o una horquilla mal puesta.<ul><li>Nunca te pares ni camines <b>bajo la carga</b> ni en su zona de caída.</li><li>No guíes la carga con las manos desde abajo.</li><li>Acércate solo cuando esté apoyada y la grúa detenida.</li></ul>Vale igual para la pluma del camión, si tiene.","k":"Nunca te pongas bajo una carga levantada."},{"s":"camion_carga_equipo","t":"Cajas y carga larga: con técnica y en equipo","x":"<ul><li>Levanta con <b>espalda recta</b>, piernas flectadas y la carga pegada al cuerpo, sin girar el tronco.</li><li>Sin ayuda mecánica, el máximo es <b>25 kg</b> para hombres y <b>20 kg</b> para mujeres y menores de 18 (Ley 20.949). Las embarazadas no cargan.</li><li>Carga <b>larga o incómoda</b>: entre dos o más, del mismo lado, avisando \"a la cuenta de tres\".</li><li>Para más peso, usa transpaleta o grúa.</li></ul>"},{"s":"camion_carga_obra","t":"Descarga con gente alrededor","x":"En el local del cliente o en la calle hay <b>personas, niños y vehículos</b> que no conocen el riesgo.<ul><li><b>Delimita</b> la zona de descarga con conos o cinta.</li><li>Pide con respeto que se <b>alejen</b> mientras descargas.</li><li>No dejes que el cliente ayude subiéndose al camión.</li><li>Deja la carga <b>estable</b> y sin bloquear el paso ni las salidas.</li></ul>"},{"s":"camion_carga_epp","t":"Tu EPP para cargar","x":"La empresa entrega el EPP <b>sin costo</b> (Ley 16.744, art. 68) y tú lo usas siempre, aunque la tarea sea corta:<ul><li><b>Zapatos de seguridad</b>: la carga puede caer a los pies.</li><li><b>Guantes</b>: flejes, astillas de pallet y bordes de latas cortan.</li><li><b>Chaleco reflectante</b>: para que te vean en el patio y en la calle.</li><li><b>Casco</b> donde se exija, como en algunos centros de distribución.</li></ul>Si se daña, pide recambio."},{"s":"camion_carga_auto","t":"Autocuidado al cargar","x":"La mayoría de los accidentes se relacionan con <b>acciones inseguras</b>. Aquí la típica es <b>el apuro</b>: saltar del camión, pasar bajo la carga \"un segundito\" o levantar solo lo que es para dos. La decisión segura: <b>bajar de frente, esperar a que la carga se apoye y pedir ayuda</b>. Avisa también las condiciones inseguras: peldaños rotos, pallets quebrados o calzos que faltan."}],"quiz":[{"s":"camion_carga_preparar","v":[{"q":"Antes de que la grúa cargue el camión, ¿qué se hace?","o":["Motor apagado, freno de mano y calzos","Motor andando para salir rápido","Solo freno de mano, sin apagar el motor","Nada: eso lo ve el operador de la grúa"],"w":"Así el camión no se mueve mientras alguien trabaja arriba o la grúa carga."},{"q":"¿Para qué se ponen calzos en las ruedas antes de cargar?","o":["Para que el camión no se desplace mientras se carga","Para que el camión quede más alto","Para que los neumáticos no se desinflen","Para marcar dónde estacionar"],"w":"Los calzos evitan que el camión se mueva, sobre todo en pendiente o cuando la grúa entra."},{"q":"Si el camión tiene el freno de mano puesto, no hace falta apagar el motor para cargarlo.","vf":false,"w":"Falso. Motor apagado, llave fuera, freno de mano y calzos."}]},{"s":"camion_carga_subir_mal","v":[{"q":"Tu compañero termina de descargar y salta desde la plataforma al piso. ¿Qué le dices?","o":["Que baje de frente con 3 puntos de apoyo","Que salte con las rodillas flectadas","Que salte solo si el piso está seco","Nada, porque la plataforma es baja"],"w":"Saltar causa torceduras y fracturas. Se baja de frente con 3 puntos de apoyo."},{"q":"¿Cómo se baja correctamente de la plataforma del camión?","o":["De frente, usando peldaños y asideros","De espaldas al camión, de un salto","Sentado en el borde y deslizándose","Con una caja en las manos para ahorrar viajes"],"w":"De frente al camión y con 3 puntos de apoyo, sin carga en las manos."},{"q":"Debes bajar del camión y tienes una caja en las manos. ¿Qué haces?","o":["Paso la caja a otro y bajo con 3 puntos de apoyo","Bajo con la caja apoyada en el pecho","Salto con la caja para no soltarla","Lanzo la caja al piso y salto"],"w":"Con carga en las manos no tienes 3 puntos de apoyo."}]},{"s":"camion_carga_subir_ok","v":[{"q":"¿Qué son los 3 puntos de apoyo?","o":["Dos manos y un pie, o dos pies y una mano","Tres pasos rápidos para bajar","Casco, guantes y zapatos de seguridad","Peldaño, asidero y baranda de la carga"],"w":"Siempre tres puntos en contacto con el camión al subir o bajar."},{"q":"Vas a subir a la cabina con un termo en una mano. ¿Cuál es el problema?","o":["Pierdes una mano para los 3 puntos de apoyo","Ninguno, si subes despacio","Ninguno, si el peldaño está seco","Que el termo se puede abrir"],"w":"Con algo en la mano no puedes mantener 3 puntos de apoyo: déjalo arriba o pásalo a otro."},{"q":"Los peldaños del camión están con barro. ¿Qué haces?","o":["Los limpio y subo con 3 puntos de apoyo","Subo rápido para no resbalar","Subo apoyándome solo en la puerta","Subo por las ruedas"],"w":"Los peldaños mojados o con barro hacen resbalar: límpialos y usa los 3 puntos."}]},{"s":"camion_carga_borde","v":[{"q":"Sobre la plataforma puedo caminar de espaldas si voy mirando la carga.","vf":false,"w":"Falso. De espaldas no ves el borde: es una de las caídas más típicas."},{"q":"Estás sobre la plataforma acomodando pallets. ¿Qué es lo correcto?","o":["Moverme de frente y lejos del borde","Tirar la carga caminando hacia atrás","Pararme sobre los pallets para alcanzar","Trabajar en el borde para bajar más rápido"],"w":"De espaldas no ves el borde, y subirse a la carga suelta es inestable."},{"q":"La grúa horquilla va a sacar un pallet de la plataforma. ¿Dónde estás tú?","o":["Abajo, fuera de su recorrido","Arriba, sujetando el pallet","Arriba, en el borde para guiar","Sobre otro pallet para ver mejor"],"w":"Nadie arriba de la plataforma mientras la grúa deja o saca carga."}]},{"s":"camion_carga_grua","v":[{"q":"La grúa horquilla viene a dejar un pallet en el camión. ¿Dónde estás tú?","o":["En zona segura y a la vista del operador","Arriba de la plataforma para recibirlo","Junto a las horquillas para guiarlo","Detrás de la grúa para avisarle"],"w":"Fuera del recorrido de la grúa y a la vista del operador."},{"q":"Necesitas acercarte a la grúa horquilla que está cargando. ¿Qué haces primero?","o":["Contacto visual con el operador y espero","Me acerco por detrás para no molestar","Le grito desde lejos y avanzo","Me acerco rápido mientras está detenida"],"w":"Antes de acercarte, contacto visual: el operador debe saber que estás ahí."},{"q":"El operador de la grúa no llegó y hay un pallet pendiente. ¿Qué haces?","o":["Espero a un operador capacitado y autorizado","Lo cargo yo, porque es solo uno","Le pido al chofer del proveedor que la maneje","Lo muevo yo despacio con la grúa"],"w":"La grúa solo la opera quien está capacitado y autorizado."}]},{"s":"camion_carga_susp_mal","v":[{"q":"La grúa levanta un pallet y un compañero se para debajo para guiarlo. ¿Qué corresponde?","o":["Pedirle que salga de la zona de caída","Ayudarle a guiarlo desde abajo","Dejarlo, porque es un pallet liviano","Pedir que la grúa suba más rápido"],"w":"Nunca bajo la carga levantada ni en su zona de caída."},{"q":"¿Cuándo puedes acercarte a un pallet que movió la grúa?","o":["Cuando está apoyado y la grúa detenida","Mientras baja, para guiarlo con las manos","Cuando está a media altura","En cualquier momento, si hay contacto visual"],"w":"Una carga levantada puede caer en cualquier momento."},{"q":"Si la carga levantada es liviana, se puede pasar por debajo un momento.","vf":false,"w":"Falso. Cualquier carga levantada puede caer: nunca se pasa por debajo."}]},{"s":"camion_carga_equipo","v":[{"q":"Sin ayuda mecánica, ¿cuál es el máximo de carga manual para un hombre adulto?","o":["25 kg","50 kg","40 kg","30 kg"],"w":"Ley 20.949: 25 kg para hombres. Para mujeres y menores de 18, 20 kg."},{"q":"Sin ayuda mecánica, ¿cuál es el máximo de carga manual para una mujer?","o":["20 kg","25 kg","15 kg","30 kg"],"w":"Mujeres y menores de 18: 20 kg. Las embarazadas no cargan."},{"q":"Un trabajador de 17 años debe mover cajas. ¿Cuál es su máximo sin ayuda mecánica?","o":["20 kg","25 kg","30 kg","15 kg"],"w":"Los menores de 18 tienen un máximo de 20 kg."}]},{"s":"camion_carga_equipo","v":[{"q":"Hay que bajar una carga larga e incómoda. ¿Cómo se hace?","o":["Entre dos o más, del mismo lado y coordinados","Uno solo, arrastrándola por la plataforma","Tirándola desde la plataforma al piso","Entre dos, cada uno a su ritmo"],"w":"Lo largo se lleva en equipo, del mismo lado y avisando cada movimiento."},{"q":"Van a levantar entre dos una carga larga. ¿Cómo coordinan el movimiento?","o":["Uno avisa y levantan juntos a la cuenta de tres","Cada uno levanta cuando está listo","El más fuerte levanta primero","Levantan en silencio para concentrarse"],"w":"Avisar a la cuenta de tres hace que el peso se reparta parejo."},{"q":"¿Cómo se ubican dos personas que llevan una carga larga?","o":["Del mismo lado de la carga","Uno a cada lado, en diagonal","Uno adelante caminando de espaldas","Da lo mismo, si la carga es liviana"],"w":"Del mismo lado y coordinados, para moverse juntos y ver el camino."}]},{"s":"camion_carga_obra","v":[{"q":"Descargas frente a un local y unos niños se acercan a mirar. ¿Qué haces?","o":["Delimito y les pido que se alejen","Sigo, porque ya se van a correr","Les pido que me ayuden con las cajas","Descargo más rápido para terminar"],"w":"Los niños y los clientes no conocen el riesgo: tú delimitas y alejas."},{"q":"El cliente quiere subirse al camión para ayudarte a bajar las cajas. ¿Qué haces?","o":["Le explico con respeto que no puede subir","Lo dejo subir si tiene zapatos firmes","Lo dejo, así terminamos antes","Le paso guantes y que suba"],"w":"No dejes que el cliente se suba al camión: no conoce el riesgo."},{"q":"Terminaste de descargar en la vereda del cliente. ¿Cómo dejas la carga?","o":["Estable y sin bloquear el paso ni las salidas","Apilada lo más alto posible","Junto a la puerta para que la entren","Donde quede, el cliente la ordena"],"w":"La carga queda estable y sin bloquear el paso de las personas."}]},{"s":"camion_carga_epp","v":[{"q":"Si son pocas cajas, puedo descargar sin guantes ni zapatos de seguridad.","vf":false,"w":"Falso. El EPP se usa siempre que estés expuesto al riesgo, aunque la tarea sea corta."},{"q":"¿Quién paga el EPP que usas para cargar y descargar?","o":["La empresa, sin costo para ti","Tú, descontado del sueldo","Mitad la empresa y mitad tú","La mutualidad"],"w":"La Ley 16.744, art. 68, obliga a la empresa a entregar el EPP sin costo."},{"q":"Tus guantes se rompieron a mitad de la descarga. ¿Qué haces?","o":["Pido recambio y sigo con guantes nuevos","Sigo sin guantes para terminar","Sigo con los rotos hasta el final","Uso unos guantes de cocina"],"w":"Los flejes y astillas cortan. Si el EPP se daña, se pide recambio."}]}]},{"id":"vehiculo_menor","sec":"vehiculos","title":"Conducción de vehículos menores","thumb":"pe_auto","learn":[{"s":"pe_auto","t":"Revisión antes de salir","x":"Solo conduce un vehículo de {EMP} quien está <b>autorizado</b> y tiene <b>licencia vigente</b> para ese vehículo, clase B en autos y camionetas. Antes de salir revisa:<ul><li><b>Neumáticos</b>, incluido el de repuesto.</li><li><b>Luces</b>, también las de freno, y <b>frenos</b>.</li><li><b>Espejos</b>, cinturones y niveles.</li><li>Documentos al día: permiso de circulación, revisión técnica y <b>SOAP</b>.</li></ul>Si algo falla o falta, no salgas y avisa.","k":"Si el vehículo no pasa la revisión, no sale."},{"s":"pe_cinturon","t":"Cinturón siempre","x":"Todos los ocupantes usan <b>cinturón</b>, adelante y atrás, aunque el trayecto sea corto o dentro de la ciudad: lo exige la Ley de Tránsito. En un choque, quien va atrás sin cinturón sale proyectado contra el parabrisas o contra quienes van adelante. Antes de partir, revisa que todos lo tengan puesto. No lleves objetos sueltos en la cabina: en un frenazo salen disparados."},{"s":"pe_celular","t":"Celular: cero","x":"La Ley de Tránsito prohíbe manipular el celular mientras conduces. A <b>60 km/h</b> avanzas casi <b>17 metros por segundo</b>: una mirada de <b>2 segundos</b> son <b>más de 30 metros a ciegas</b>. Tampoco escribas en semáforos ni en tacos: sigues conduciendo. Si debes contestar o revisar una dirección, <b>detente en un lugar seguro</b>. Programa el GPS antes de partir."},{"s":"camion_conduccion_alcohol","t":"Cero alcohol y cero drogas","x":"La Ley 20.580 establece que desde <b>0,3 g/l</b> se conduce <b>bajo la influencia</b> del alcohol y desde <b>0,8 g/l</b> en <b>estado de ebriedad</b>. En el trabajo la regla es <b>cero alcohol y cero drogas</b>, también al manejar vehículos de la empresa. El alcohol de la noche anterior puede seguir en tu sangre, y algunos medicamentos dan sueño: si es tu caso, avisa antes de conducir.","k":"Con alcohol, drogas o sueño, no se maneja."},{"s":"camion_conduccion_fatiga","t":"Sueño, velocidad y clima","x":"Si tienes sueño (bostezos, pestañeo seguido, no recordar los últimos kilómetros), <b>detente en un lugar seguro</b> y descansa: abrir la ventana o subir la música no lo quita. Respeta los <b>límites de velocidad</b>: en zona urbana el máximo general es <b>50 km/h</b>. Con <b>lluvia, neblina o ripio</b>, baja la velocidad y aumenta la distancia con el vehículo de adelante."},{"s":"pe_auto_planta","t":"Dentro de la planta","x":"En los patios de {EMP} circulan peatones, grúas horquilla y camiones, y manda el <b>peatón</b>:<ul><li>Respeta la <b>velocidad máxima</b> señalizada y las rutas de vehículos.</li><li>Cede el paso en los <b>cruces peatonales</b>.</li><li>Estaciona solo en los lugares indicados.</li><li>Nunca frente a <b>salidas de emergencia, extintores</b> o accesos de camiones.</li></ul>Antes de retroceder, mira: una grúa o una persona pueden estar detrás."}],"quiz":[{"s":"pe_celular","v":[{"q":"Vas a 60 km/h y miras el celular 2 segundos. ¿Cuánto avanzas a ciegas?","o":["Más de 30 metros","Unos 5 metros","Unos 10 metros","Menos de 2 metros"],"w":"A 60 km/h avanzas casi 17 metros por segundo: 2 segundos son más de 30 metros."},{"q":"Estás detenido en un taco y te llega un mensaje urgente. ¿Qué haces?","o":["Espero a detenerme en un lugar seguro","Lo respondo, porque el auto está quieto","Lo leo rápido sin responder","Lo dicto con el teléfono en la mano"],"w":"En un taco sigues conduciendo. El celular se usa detenido en un lugar seguro."},{"q":"¿Cuándo conviene programar el GPS para ir a una reunión?","o":["Antes de partir, detenido","En el primer semáforo en rojo","En una recta con poco tráfico","Mientras manejo, si voy lento"],"w":"Manipular el celular al conducir está prohibido: prográmalo antes de salir."}]},{"s":"pe_cinturon","v":[{"q":"En un trayecto corto dentro de la ciudad, el cinturón trasero es opcional.","vf":false,"w":"Falso. Todos los ocupantes lo usan siempre, adelante y atrás."},{"q":"Llevas a dos compañeros atrás hasta la otra planta, a pocas cuadras. ¿Qué corresponde?","o":["Que todos usen cinturón antes de partir","Que solo el copiloto use cinturón","Que lo usen si salimos a carretera","Que lo usen si van más de dos atrás"],"w":"El cinturón es obligatorio para todos, adelante y atrás, en cualquier trayecto."},{"q":"¿Qué le pasa a un pasajero trasero sin cinturón en un choque?","o":["Sale proyectado contra el parabrisas o los de adelante","Queda protegido por el respaldo delantero","No le pasa nada si el choque es lento","Solo corre riesgo el conductor"],"w":"Sin cinturón, el cuerpo sigue avanzando y golpea a otros o sale proyectado."}]},{"s":"pe_auto","v":[{"q":"Al revisar el vehículo notas que una luz de freno no funciona. ¿Qué haces?","o":["No salgo y aviso","Salgo y la cambio a la vuelta","Salgo, porque es de día","Salgo y freno con anticipación"],"w":"Si algo falla, el vehículo no sale y se avisa."},{"q":"En la revisión ves que un neumático está con poco aire y con un corte. ¿Qué haces?","o":["No salgo y aviso para que lo cambien","Salgo despacio hasta la bencinera","Salgo y lo reviso al volver","Le pongo aire y salgo igual"],"w":"Un neumático cortado puede reventar en ruta: no se sale y se avisa."},{"q":"¿Qué neumáticos se revisan antes de salir?","o":["Los cuatro y también el de repuesto","Solo los delanteros","Solo los que se ven bajos","Solo el de repuesto, una vez al mes"],"w":"Si tienes una pana, necesitas el repuesto en buen estado."}]},{"s":"pe_auto","v":[{"q":"Vas a usar la camioneta y ves que el SOAP está vencido. ¿Qué haces?","o":["No salgo y aviso a mi jefatura","Salgo, porque es un trayecto corto","Salgo y lo renuevo después","Salgo por calles con menos control"],"w":"Los documentos al día son parte de la revisión: permiso de circulación, revisión técnica y SOAP."},{"q":"Un compañero sin licencia vigente te pide manejar la camioneta de la empresa. ¿Qué le dices?","o":["Que no: necesita licencia y autorización","Que puede si va dentro de la planta","Que puede si yo voy de copiloto","Que puede si maneja despacio"],"w":"Solo conduce quien está autorizado y tiene licencia vigente para ese vehículo."},{"q":"¿Qué licencia se necesita, como mínimo, para conducir un auto o camioneta de la empresa?","o":["Clase B vigente","Clase D vigente","Clase C vigente","Ninguna, si es dentro de la planta"],"w":"Para autos y camionetas, clase B vigente, además de la autorización de la empresa."}]},{"s":"camion_conduccion_alcohol","v":[{"q":"Según la Ley 20.580, ¿desde qué nivel de alcohol se conduce bajo la influencia?","o":["Desde 0,3 g/l","Desde 0,8 g/l","Desde 0,5 g/l","Desde 1,0 g/l"],"w":"Desde 0,3 g/l es bajo la influencia; desde 0,8 g/l, ebriedad. En el trabajo: cero."},{"q":"Anoche tomaste en un cumpleaños y hoy debes ir en la camioneta a otra planta. ¿Qué haces?","o":["Aviso a mi jefatura y no conduzco","Manejo, porque ya dormí","Tomo café y manejo despacio","Manejo solo dentro de la ciudad"],"w":"El alcohol de la noche anterior puede seguir en la sangre. La regla es cero."},{"q":"Con 0,2 g/l de alcohol en la sangre puedo conducir un vehículo de la empresa.","vf":false,"w":"Falso. Al trabajar la regla es cero alcohol y cero drogas."}]},{"s":"camion_conduccion_fatiga","v":[{"q":"Vuelves de una reunión y empiezas a bostezar y pestañear seguido. ¿Qué haces?","o":["Me detengo en un lugar seguro y descanso","Abro la ventana y subo la música","Acelero para llegar antes","Me como algo y sigo"],"w":"Son señales de sueño: la ventana o la música no lo quitan."},{"q":"¿Cuál de estas es una señal de sueño al volante?","o":["Pestañear seguido y bostezar","Tener hambre a media mañana","Sentir frío en las manos","Tener ganas de oír música"],"w":"Bostezos, pestañeo seguido y no recordar los últimos kilómetros son señales de sueño."},{"q":"Tienes sueño manejando y un compañero te dice que abras la ventana y subas la música. ¿Qué le respondes?","o":["Que eso no lo quita: hay que detenerse a descansar","Que tiene razón y sigo con la ventana abierta","Que mejor acelero para llegar antes","Que tomaré un café en el camino sin parar"],"w":"La ventana o la música no quitan el sueño: detente en un lugar seguro."}]},{"s":"pe_auto_planta","v":[{"q":"Dentro del patio de la planta, ¿quién tiene la preferencia?","o":["El peatón","El vehículo más grande","Quien va más apurado","El que llega primero al cruce"],"w":"En la planta manda el peatón: cede el paso y respeta los cruces."},{"q":"No encuentras estacionamiento y hay espacio frente a un extintor. ¿Qué haces?","o":["Busco un lugar indicado, nunca frente al extintor","Me estaciono ahí por unos minutos","Me estaciono ahí con las intermitentes","Me estaciono y dejo la llave puesta"],"w":"Las salidas de emergencia y los extintores siempre despejados."},{"q":"Dentro de la planta puedo pasar la velocidad máxima señalizada si el patio está vacío.","vf":false,"w":"Falso. La velocidad máxima se respeta siempre: una grúa o un peatón pueden aparecer."}]}]},{"id":"pvd","sec":"admin","title":"Trabajo con computador: ergonomía y pausas","thumb":"pvd_intro","learn":[{"s":"pvd_intro","t":"Muchas horas frente a la pantalla","x":"Administrativos, jefaturas, encargados de romana y de despacho pasan horas frente al computador. Una mala postura no duele el primer día, pero sumada día a día puede terminar en dolor de cuello, espalda, hombros y muñecas. Ajustar tu puesto toma cinco minutos: pantalla, silla, teclado y mouse. Si algo de tu puesto no se puede ajustar, avisa a tu jefatura."},{"s":"pvd_pantalla","t":"La pantalla","x":"<ul><li>El <b>borde superior a la altura de los ojos</b> o un poco más abajo.</li><li>A unos <b>50 a 70 cm</b>: más o menos un brazo estirado.</li><li><b>De frente</b>, no girada a un lado, para no torcer el cuello.</li></ul>Si la pantalla está baja, ponle una base firme. Si usas dos pantallas, la principal va al frente."},{"s":"pvd_silla","t":"Silla, espalda y pies","x":"<ul><li>Regula la altura: <b>codos en ángulo recto</b>, a la altura del escritorio.</li><li>Espalda <b>apoyada en el respaldo</b>, sobre todo la zona lumbar.</li><li><b>Pies planos</b> en el suelo o en un apoyapiés.</li><li>Hombros relajados, sin encorvarte hacia la pantalla.</li></ul>Si tu silla no se regula o está dañada, avisa a tu jefatura.","k":"Espalda apoyada, codos en ángulo recto y pies apoyados."},{"s":"pvd_teclado","t":"Teclado y mouse","x":"<ul><li>Teclado <b>cerca</b>, frente a ti, a la altura de los codos.</li><li><b>Muñecas rectas</b>: ni dobladas hacia arriba ni hacia los lados.</li><li>Mouse <b>al lado del teclado</b>, sin estirar el brazo.</li><li>Antebrazos apoyados en el escritorio.</li></ul>Estirar el brazo hacia el mouse durante horas carga el hombro y el codo."},{"s":"pvd_vista","t":"Descansa la vista: 20-20-20","x":"Una <b>recomendación práctica</b>, no una norma legal: cada <b>20 minutos</b>, mira algo lejano, a unos 6 metros, durante <b>20 segundos</b>. Parpadea a propósito: frente a la pantalla parpadeamos menos y los ojos se secan. Ojos cansados, ardor o visión borrosa son señales para descansar. Si se repiten, consulta."},{"s":"pvd_pausas","t":"Pausas activas","x":"Estar quieto en la misma postura también cansa, aunque no cargues peso. Cada cierto rato:<ul><li><b>Levántate</b> y camina un poco.</li><li>Estira cuello, hombros, espalda y muñecas, sin forzar.</li><li>Cambia de postura.</li></ul>Aprovecha tareas como ir a la impresora, a la romana o a bodega para moverte."},{"s":"pvd_notebook","t":"Notebook y celular","x":"<ul><li>El notebook plano obliga a agachar la cabeza. Si lo usas muchas horas, ponlo sobre una <b>base</b> y usa <b>teclado y mouse aparte</b>.</li><li>El <b>celular</b>: súbelo a la altura de los ojos en vez de doblar el cuello.</li><li>Evita trabajar en la cama o el sillón si haces teletrabajo.</li></ul>"},{"s":"pvd_luz","t":"Luz y reflejos","x":"<ul><li>Pon la pantalla <b>al costado de la ventana</b>, no de frente ni de espaldas a ella.</li><li>Usa cortinas o persianas si el sol pega en la pantalla.</li><li>Ajusta el brillo a la luz del lugar.</li><li>Limpia la pantalla.</li></ul>Los reflejos te obligan a forzar la vista y a torcer la postura para ver."},{"s":"pvd_sintomas","t":"Señales de alerta","x":"Los <b>trastornos musculoesqueléticos de extremidades superiores (TMERT)</b> avisan antes:<ul><li>Dolor en cuello, hombros, codos o muñecas.</li><li>Hormigueo o adormecimiento en manos y dedos.</li><li>Pérdida de fuerza.</li></ul>Si se repiten, <b>avisa a tu jefatura</b> y consulta en la ACHS. No te automediques: consultar a tiempo evita que se vuelva crónico.","k":"Hormigueo o dolor que se repite: avisa y consulta."},{"s":"pvd_auto","t":"Autocuidado: termino y paro","x":"La mayoría de los accidentes y lesiones se relacionan con una acción insegura. Frente al computador, la típica es <b>\"termino esto y paro\"</b>: horas encorvado sin moverte, ignorando el dolor. La decisión segura: <b>ajusta tu puesto y haz la pausa ahora</b>. Avisa también las condiciones inseguras: silla rota, pantalla sin ajuste o reflejos que no se pueden evitar."}],"quiz":[{"s":"pvd_pantalla","v":[{"q":"¿A qué altura debe estar el borde superior de la pantalla?","o":["A la altura de los ojos o algo más abajo","Bien por encima de la línea de los ojos","A la altura del pecho","A la altura del teclado"],"w":"Así el cuello queda recto, sin mirar hacia arriba ni agacharse."},{"q":"¿A qué distancia de los ojos conviene ubicar la pantalla?","o":["A unos 50 a 70 cm","A unos 20 cm, para ver mejor","A más de un metro y medio","Lo más cerca posible"],"w":"Más o menos a un brazo estirado, de frente."},{"q":"Tu pantalla está girada hacia un lado del escritorio. ¿Qué haces?","o":["La pongo de frente a mí","Giro la silla de vez en cuando","La dejo y giro el cuello","La subo un poco más"],"w":"La pantalla va de frente para no torcer el cuello."}]},{"s":"pvd_cel_mal","v":[{"q":"Un compañero revisa el celular horas con el cuello doblado hacia abajo. ¿Qué le recomiendas?","o":["Subir el celular a la altura de los ojos","Bajar más la cabeza para ver mejor","Usar el celular acostado","Cambiar a letra más pequeña"],"w":"Sube el celular a la altura de los ojos en vez de doblar el cuello."},{"q":"¿Qué postura es correcta al usar el celular un rato largo?","o":["Celular a la altura de los ojos, cuello recto","Celular sobre las piernas, cuello doblado","Celular en la mesa, inclinado sobre él","Celular de lado, con el hombro"],"w":"Doblar el cuello por horas carga la columna cervical."},{"q":"Doblar el cuello por horas para mirar el celular no tiene efectos si uno es joven.","vf":false,"w":"Falso. A cualquier edad, el cuello doblado por horas causa dolor y lesiones."}]},{"s":"pvd_teclado","v":[{"q":"Al escribir, ¿cómo deben estar las muñecas?","o":["Rectas, con el teclado cerca","Dobladas hacia arriba","Colgando fuera del escritorio","Dobladas hacia los lados"],"w":"Muñecas rectas y mouse junto al teclado, sin estirar el brazo."},{"q":"Tu mouse está al otro extremo del escritorio y estiras el brazo para usarlo. ¿Qué haces?","o":["Lo pongo junto al teclado","Lo dejo, así hago ejercicio","Lo uso con la otra mano","Acerco la silla al mouse"],"w":"Estirar el brazo durante horas carga hombro y codo."},{"q":"¿Dónde deben quedar los antebrazos al usar el teclado?","o":["Apoyados en el escritorio","Levantados en el aire","Apoyados en las piernas","Cruzados sobre el teclado"],"w":"Antebrazos apoyados y teclado a la altura de los codos."}]},{"s":"pvd_vista","v":[{"q":"La regla 20-20-20 es una norma legal obligatoria en Chile.","vf":false,"w":"Falso. Es una recomendación práctica para descansar la vista."},{"q":"¿Qué tipo de indicación es la regla 20-20-20?","o":["Una recomendación práctica para la vista","Una obligación del DS 594","Una norma del Código del Trabajo","Una exigencia legal de la mutualidad"],"w":"Es una recomendación práctica, no una norma legal."},{"q":"Un compañero dice que lo pueden sancionar por no cumplir la regla 20-20-20. ¿Es correcto?","o":["No: es una recomendación práctica, no una norma","Sí: es una norma legal de la Ley 16.744","Sí: la exige el DS 44","Solo si trabaja más de 8 horas"],"w":"La regla 20-20-20 es una recomendación para descansar la vista."}]},{"s":"pvd_vista","v":[{"q":"Según la regla 20-20-20, ¿qué haces cada 20 minutos?","o":["Miro algo lejano durante 20 segundos","Cierro los ojos 20 minutos","Me levanto y camino 20 metros","Bajo el brillo de la pantalla"],"w":"Mira algo lejano, a unos 6 metros, durante 20 segundos."},{"q":"En la regla 20-20-20, ¿a qué distancia aproximada debes mirar?","o":["A unos 6 metros","A unos 20 cm","A unos 2 metros","A unos 50 metros"],"w":"Cada 20 minutos, 20 segundos mirando a unos 6 metros."},{"q":"Llevas una hora frente a la planilla sin despegar la vista. Según la regla 20-20-20, ¿qué debiste hacer?","o":["Mirar lejos 20 segundos cada 20 minutos","Descansar 20 minutos cada hora","Acercarme más a la pantalla","Subir el brillo al máximo"],"w":"Pausas breves y frecuentes para la vista."}]},{"s":"pvd_silla","v":[{"q":"¿Cómo deben quedar los pies al sentarte frente al computador?","o":["Planos en el suelo o en un apoyapiés","Colgando de la silla","Cruzados bajo la silla","Apoyados en la rueda de la silla"],"w":"Pies apoyados, espalda en el respaldo y codos en ángulo recto."},{"q":"¿A qué altura regulas la silla?","o":["Codos en ángulo recto con el escritorio","Lo más baja posible, para apoyar la espalda","Con los hombros levantados hacia la mesa","Con las rodillas más altas que la cadera"],"w":"Codos en ángulo recto, a la altura del escritorio."},{"q":"Tu silla no se puede regular y terminas encorvado. ¿Qué haces?","o":["Aviso a mi jefatura para cambiarla","Me acostumbro con el tiempo","Me siento en el borde de la silla","Pongo una caja para sentarme más alto"],"w":"Si tu silla no se regula, se avisa."}]},{"s":"pvd_luz","v":[{"q":"¿Dónde conviene poner la pantalla respecto de la ventana?","o":["Al costado de la ventana","De frente a la ventana","De espaldas a la ventana","Pegada a la ventana"],"w":"Al costado se evitan reflejos y encandilamiento."},{"q":"El sol de la tarde pega directo en tu pantalla. ¿Qué haces?","o":["Uso la cortina o persiana","Subo el brillo al máximo","Me acerco más a la pantalla","Me inclino para ver entre reflejos"],"w":"Los reflejos obligan a forzar la vista y la postura."},{"q":"Poner la pantalla de espaldas a la ventana evita los reflejos.","vf":false,"w":"Falso. Con la ventana detrás, la luz se refleja en la pantalla. Lo correcto es al costado."}]},{"s":"pvd_notebook","v":[{"q":"Si usas notebook muchas horas, ¿qué es lo recomendable?","o":["Ponerlo en una base y usar teclado y mouse aparte","Usarlo sobre las piernas en el sillón","Bajar el brillo al mínimo","Usarlo plano sobre el escritorio"],"w":"Así la pantalla sube a la altura de los ojos y las manos quedan bien."},{"q":"¿Por qué el notebook plano en el escritorio causa dolor de cuello?","o":["Porque obliga a agachar la cabeza","Porque la pantalla es más pequeña","Porque el teclado está muy alto","Porque calienta las manos"],"w":"La pantalla queda baja y obliga a mirar hacia abajo."},{"q":"Al poner el notebook en una base, ¿qué más necesitas?","o":["Teclado y mouse aparte","Una silla más baja","Un segundo notebook","Una lámpara frente a la pantalla"],"w":"Con el notebook en alto, el teclado y mouse externos mantienen las muñecas bien."}]},{"s":"pvd_sintomas","v":[{"q":"Tienes hormigueo en las manos varias veces a la semana. ¿Qué haces?","o":["Aviso a mi jefatura y consulto en la ACHS","Espero a que se pase solo","Tomo un antiinflamatorio sin consultar","Me pongo una muñequera y sigo"],"w":"Es una señal de alerta de TMERT: se avisa y se consulta a tiempo."},{"q":"¿Cuál de estas es una señal de alerta de TMERT?","o":["Pérdida de fuerza en las manos","Ojos secos al final del día","Sueño después de almuerzo","Frío en los pies"],"w":"Dolor, hormigueo, adormecimiento o pérdida de fuerza en extremidades superiores."},{"q":"Hace semanas te duele el codo al usar el mouse. ¿Qué corresponde?","o":["Avisar y consultar antes de que empeore","Esperar unas semanas más","Cambiar de mano sin decir nada","Seguir hasta las vacaciones"],"w":"Consultar a tiempo evita que se vuelva crónico."}]},{"s":"pvd_pausas","v":[{"q":"Las pausas activas sirven solo para quienes cargan peso.","vf":false,"w":"Falso. Estar quieto también cansa: levántate, estira y camina."},{"q":"Llevas dos horas sentado y sientes la espalda rígida. ¿Qué haces?","o":["Me levanto, estiro y camino un poco","Me recuesto en la silla y sigo","Termino primero y después paro","Tomo un analgésico y sigo"],"w":"Hacer la pausa ahora, no después de terminar."},{"q":"¿Cómo deben hacerse los estiramientos en una pausa activa?","o":["Suaves, sin forzar","Con rebotes fuertes","Hasta sentir dolor","Solo con las piernas"],"w":"Se estira cuello, hombros, espalda y muñecas, sin forzar."}]}]},{"id":"oficina","sec":"admin","title":"Riesgos en la oficina","thumb":"of_intro","learn":[{"s":"of_intro","t":"La oficina también tiene riesgos","x":"En la oficina no hay grúas ni autoclaves, pero sí accidentes:<ul><li>Caídas por cables, cajones abiertos o pisos mojados.</li><li>Golpes por archivadores que se vuelcan.</li><li>Riesgo eléctrico por zapatillas sobrecargadas.</li><li>Caídas al subirse a una silla.</li></ul>Todo accidente, aunque parezca leve, se avisa de inmediato a tu jefatura y se atiende en la ACHS, fono 1404."},{"s":"of_caidas","t":"Caídas al mismo nivel","x":"<ul><li><b>Cables</b> por el piso: ordénalos por la orilla o pide canaletas; nunca los tapes con una alfombra.</li><li><b>Cajones</b> abiertos: ciérralos apenas los uses.</li><li>Alfombras levantadas, piso mojado o café derramado: <b>señaliza, limpia o avisa</b>.</li><li>No camines leyendo el celular, sobre todo en escaleras.</li></ul> Un tropiezo en la oficina también es un accidente del trabajo y se avisa."},{"s":"of_cajones","t":"Archivadores","x":"<ul><li>Abre <b>un cajón a la vez</b>: con dos o más abiertos arriba, el peso se va hacia adelante y el mueble se puede volcar.</li><li>Pon lo <b>pesado en los cajones de abajo</b>.</li><li>Cierra cada cajón al terminar.</li><li>Si el mueble es alto, debe estar firme o anclado a la pared: si se mueve, avisa.</li></ul>"},{"s":"of_electrico","t":"Riesgo eléctrico","x":"<ul><li><b>No conectes una zapatilla a otra</b> en cadena: se sobrecargan y pueden provocar un incendio.</li><li>No enchufes estufas, hervidores y equipos a la vez en el mismo enchufe.</li><li>Desenchufa tomando el enchufe, no tirando del cable.</li><li>Cable pelado, enchufe caliente u olor a quemado: <b>deja de usarlo y avisa</b>.</li><li>Nunca eches agua sobre un equipo eléctrico.</li></ul>"},{"s":"of_silla_mal","t":"La silla no es escalera","x":"Para alcanzar un archivo alto, <b>nunca te subas a una silla</b>, menos si tiene ruedas: se desliza o gira y la caída es casi segura. Tampoco a cajas ni a un escritorio. Usa una <b>escalera o un piso de altura</b> en buen estado, o pide ayuda. Y deja lo de uso frecuente a una altura cómoda, entre la cintura y los hombros.","k":"La silla no es escalera, menos con ruedas."},{"s":"of_orden","t":"Orden y aseo","x":"<ul><li>Nada de cajas ni archivos en el piso, en los pasillos ni frente a las salidas.</li><li>Escritorio ordenado: menos cosas que caen.</li><li>Café o agua derramada: límpiala de inmediato.</li><li>Tijeras y cartoneros, cerrados y guardados.</li></ul>El orden es la medida de prevención más barata que existe. Si algo bloquea una salida, despéjalo o avisa."},{"s":"of_evac","t":"Emergencias y evacuación","x":"<ul><li>Conoce las <b>vías de evacuación</b> y la <b>zona de seguridad</b>.</li><li>Puertas, pasillos y extintores, siempre <b>despejados</b>.</li><li>En un sismo: <b>agáchate, cúbrete y afírmate</b>, lejos de ventanas y muebles altos.</li><li>Evacúa caminando cuando se indique, sin correr y sin volver por tus cosas.</li></ul>","k":"Conoce tu salida y mantenla despejada."},{"s":"of_trayecto","t":"Accidente de trayecto","x":"Es el que ocurre en el <b>trayecto directo, de ida o regreso</b>, entre tu casa y el trabajo (Ley 16.744, art. 5). Está cubierto. Si te desvías por motivos personales, puede dejar de serlo. Si te pasa:<ul><li>Avisa a tu jefatura.</li><li>Acude a la <b>ACHS</b>.</li><li>Guarda pruebas: parte o constancia de Carabineros, testigos u otros medios.</li></ul>"},{"s":"of_auto","t":"Autocuidado: es un segundo","x":"La mayoría de los accidentes se relacionan con una acción insegura. En la oficina, la típica es <b>\"es un segundo\"</b>: subirse a la silla, saltar el cable, dejar el cajón abierto. La decisión segura: <b>busca la escalera, ordena el cable, cierra el cajón</b>. Y avisa las condiciones inseguras: enchufes dañados, muebles sueltos, salidas bloqueadas. Avisar también es autocuidado."}],"quiz":[{"s":"of_silla_mal","v":[{"q":"Necesitas un archivo de la repisa alta. ¿Cómo lo alcanzas?","o":["Con una escalera o un piso de altura adecuado","Subido a la silla, con cuidado","Subido a la silla, sujetando el respaldo","Parado sobre el escritorio"],"w":"La silla con ruedas se desliza y gira. Se usa escalera o piso adecuado."},{"q":"Un compañero se sube a una silla con ruedas para cambiar un archivador. ¿Qué haces?","o":["Le pido que baje y busque una escalera","Le sujeto la silla para que no se mueva","Lo dejo, si es rápido","Le paso una caja para que suba más"],"w":"Sujetar la silla no evita la caída: se usa escalera o piso adecuado."},{"q":"Subirse a una silla sin ruedas es una forma segura de alcanzar un archivo alto.","vf":false,"w":"Falso. Ninguna silla es escalera. Se usa una escalera o un piso de altura en buen estado."}]},{"s":"of_electrico","v":[{"q":"Se puede conectar una zapatilla eléctrica a otra zapatilla si faltan enchufes.","vf":false,"w":"Falso. Las zapatillas en cadena se sobrecargan y pueden provocar un incendio."},{"q":"Faltan enchufes para el hervidor, la estufa y el computador. ¿Qué haces?","o":["Pido una instalación adecuada y no sobrecargo","Conecto una zapatilla a otra","Enchufo todo en una sola zapatilla","Uso un adaptador doble en cada enchufe"],"w":"No sobrecargues enchufes ni conectes zapatillas en cadena."},{"q":"¿Cuál es la forma correcta de desenchufar un equipo?","o":["Tomando el enchufe, no el cable","Tirando del cable con fuerza","Tirando del cable, pero suave","Con el pie, tirando del cable"],"w":"Tirar del cable lo daña y puede dejar partes expuestas."}]},{"s":"of_cajones","v":[{"q":"¿Por qué conviene abrir un solo cajón del archivador a la vez?","o":["Porque con varios abiertos se puede volcar","Para que no se mezclen los papeles","Para que los rieles no se desgasten","Para no hacer ruido en la oficina"],"w":"Con varios cajones abiertos arriba, el peso se va hacia adelante y el mueble se vuelca."},{"q":"¿Dónde guardas las carpetas más pesadas del archivador?","o":["En los cajones de abajo","En el cajón de arriba","En el cajón del medio","Sobre el archivador"],"w":"Lo pesado abajo da estabilidad al mueble."},{"q":"Notas que el archivador alto se mueve al abrir un cajón. ¿Qué haces?","o":["Aviso para que lo afirmen o anclen","Abro los cajones de a dos para equilibrar","Pongo un libro bajo una pata","Lo dejo, siempre ha sido así"],"w":"Un mueble alto debe estar firme o anclado."}]},{"s":"of_caidas","v":[{"q":"Un cable cruza el pasillo de la oficina. ¿Qué haces?","o":["Lo ordeno por la orilla o pido canalizarlo","Lo salto cada vez que paso","Le pongo una alfombra encima","Lo pego al piso con cinta de papel"],"w":"Los cables por el piso son una causa típica de caídas. Taparlos con alfombra crea otro tropiezo."},{"q":"Alguien derramó café en el pasillo. ¿Qué haces?","o":["Lo limpio o señalizo y aviso","Paso por el lado con cuidado","Espero a que lo limpie aseo","Lo seco con el pie"],"w":"Piso mojado: señaliza, limpia o avisa."},{"q":"Bajas la escalera de la oficina revisando el correo en el celular. ¿Qué riesgo hay?","o":["Caer por no mirar dónde pisas","Ninguno, si voy despacio","Solo que se me caiga el celular","Ninguno, si me afirmo con la otra mano"],"w":"No camines leyendo el celular, sobre todo en escaleras."}]},{"s":"of_electrico","v":[{"q":"Notas olor a quemado en un enchufe. ¿Qué haces?","o":["Dejo de usarlo y aviso de inmediato","Sigo trabajando y aviso al final","Le echo agua para enfriarlo","Lo desenchufo tirando del cable"],"w":"No uses lo dañado y avisa. Nunca agua sobre equipos eléctricos."},{"q":"El cable del hervidor está pelado. ¿Qué haces?","o":["No lo uso y aviso para que lo cambien","Lo envuelvo con cinta y lo uso","Lo uso con cuidado de no tocarlo","Lo uso solo un rato"],"w":"Un cable pelado puede dar una descarga: no se usa y se avisa."},{"q":"Un enchufe está caliente al tacto. ¿Qué significa?","o":["Que puede estar sobrecargado o dañado","Que funciona normalmente","Que hace frío en la oficina","Que el equipo está ahorrando energía"],"w":"Enchufe caliente es una señal de peligro: deja de usarlo y avisa."}]},{"s":"of_evac","v":[{"q":"En un sismo, ¿cuál es la conducta recomendada?","o":["Agacharse, cubrirse y afirmarse","Correr de inmediato por la escalera","Pararse junto a la ventana","Salir a buscar el auto"],"w":"Es la recomendación de SENAPRED. Lejos de ventanas y muebles altos."},{"q":"Durante un sismo estás junto a un archivador alto y una ventana. ¿Qué haces?","o":["Me alejo de ellos, me agacho, cubro y afirmo","Sujeto el archivador para que no caiga","Me quedo junto a la ventana para salir","Corro hacia la salida"],"w":"Lejos de ventanas y muebles altos que pueden caer."},{"q":"Se da la orden de evacuar. ¿Qué haces?","o":["Salgo caminando a la zona de seguridad","Vuelvo por mi cartera y el celular","Corro por la escalera","Espero en mi puesto a que pase"],"w":"Se evacúa caminando, sin correr y sin volver por tus cosas."}]},{"s":"of_trayecto","v":[{"q":"Un accidente en el trayecto directo de tu casa al trabajo está cubierto por la Ley 16.744.","vf":true,"w":"Verdadero. El accidente de trayecto está definido en el art. 5 de la Ley 16.744."},{"q":"¿Qué es un accidente de trayecto?","o":["El que ocurre en el trayecto directo entre la casa y el trabajo","Cualquier accidente fuera del horario laboral","Solo el que ocurre en un vehículo de la empresa","El que ocurre dentro del estacionamiento"],"w":"Ley 16.744, art. 5: trayecto directo, de ida o regreso."},{"q":"De vuelta a casa te desvías a hacer compras personales y te caes en el supermercado. ¿Qué pasa?","o":["Puede no considerarse accidente de trayecto","Es accidente de trayecto igual","Es accidente del trabajo","Lo cubre la empresa directamente"],"w":"Si te desvías por motivos personales, puede dejar de ser trayecto directo."}]},{"s":"accidente_trayecto","v":[{"q":"Si sufres un accidente de trayecto, ¿qué te sirve como prueba?","o":["Parte de Carabineros, testigos u otros medios","Solo tu palabra al llegar a la ACHS","Solo una foto publicada en redes","Un certificado de tu jefatura"],"w":"Avisa a tu jefatura, acude a la ACHS y guarda las pruebas."},{"q":"Te atropellan camino al trabajo. ¿Qué haces?","o":["Aviso, voy a la ACHS y guardo pruebas","Voy a cualquier consulta y no aviso","Espero unos días a ver si se pasa","Voy al trabajo y aviso a fin de mes"],"w":"Avisar, atenderse en la ACHS y guardar pruebas permite acreditar el accidente."},{"q":"Tuviste un accidente de trayecto y hubo testigos. ¿Qué conviene hacer?","o":["Anotar sus nombres y teléfonos","No hace falta, basta con avisar","Pedirles que vayan a la empresa","Solo sacar una foto del lugar"],"w":"Los testigos sirven como prueba del accidente de trayecto."}]},{"s":"orden_exitBad","v":[{"q":"Hay cajas y pallets apilados frente a la puerta de salida. ¿Qué es eso?","o":["Una condición insegura: despejo o aviso","Algo normal en una bodega u oficina","Un problema que le toca solo a aseo","Algo aceptable si es por pocos días"],"w":"Las salidas y los pasillos siempre despejados. Avisar también es autocuidado."},{"q":"Un proveedor dejó cajas frente al extintor y la salida. ¿Qué haces?","o":["Las despejo o aviso para que las retiren","Las dejo hasta que alguien las use","Paso por el lado con cuidado","Le saco una foto y sigo"],"w":"En una emergencia, cada segundo cuenta: salida y extintor despejados."},{"q":"Se pueden dejar cajas frente a una salida de emergencia si se retiran antes del fin de semana.","vf":false,"w":"Falso. Las salidas deben estar despejadas siempre: una emergencia no avisa."}]},{"s":"of_auto","v":[{"q":"¿Cuál es el acto inseguro más típico en la oficina?","o":["Pensar que es un segundo y subirse a la silla","Buscar la escalera para alcanzar algo","Ordenar los cables por la orilla","Cerrar los cajones al terminar"],"w":"Un segundo de apuro puede costar meses de recuperación."},{"q":"Dejaste un cajón abierto y piensas cerrarlo después. ¿Cuál es la decisión segura?","o":["Cerrarlo de inmediato","Dejarlo hasta terminar la tarea","Avisar a los demás que está abierto","Ponerle una silla delante"],"w":"La decisión segura es corregir de inmediato: es un segundo."},{"q":"Ves un enchufe suelto en la pared de la oficina. ¿Qué haces?","o":["Aviso para que lo reparen","Lo uso con cuidado","Lo arreglo yo con cinta","No hago nada, no es mío"],"w":"Avisar las condiciones inseguras también es autocuidado."}]}]},{"id":"admin_planta","sec":"admin","title":"Administrativos en la planta: ingreso seguro","thumb":"pe_admin_planta","learn":[{"s":"pe_admin_planta","t":"Antes de entrar a la planta","x":"Si trabajas en oficina y debes entrar a una zona de proceso, <b>avisa a la jefatura de esa área</b> y usa el EPP de la zona, igual que los operarios: en la conservera, <b>cofia, mascarilla, pechera y botas</b>. En patio y romana, chaleco reflectante y zapatos de seguridad. La jefatura te indica el EPP exacto. Sin EPP no se entra, aunque sea un minuto.","k":"En la planta, el EPP de la zona, aunque sea un minuto."},{"s":"pe_filtro","t":"Inocuidad: el filtro sanitario","x":"En {EMP} cuidamos tu seguridad y también la <b>inocuidad</b> de los alimentos:<ul><li>Sácate <b>anillos, aros, reloj y pulseras</b>.</li><li>Pasa por el <b>pediluvio</b> y <b>lávate las manos</b> al entrar.</li><li>Cofia cubriendo todo el pelo.</li><li>No entres con comida ni bebidas.</li></ul>Las joyas pueden caer al producto o engancharse en una máquina."},{"s":"senaletica_piso","t":"Por la ruta peatonal","x":"Camina solo por las <b>rutas demarcadas</b>, atento a grúas horquilla, carros y camiones. Sin celular mientras caminas por la planta o el patio. Los pisos de la conservera suelen estar <b>mojados</b>: camina, no corras, y usa pasamanos en escaleras. Respeta la señalética y no pases bajo cintas ni cadenas de zonas restringidas."},{"s":"pe_no_operar","t":"No operes nada","x":"No toques máquinas, tableros, válvulas, la grúa ni los autoclaves, aunque sea para ayudar. Solo opera quien está <b>capacitado y autorizado</b>. Si ves una lata trabada, una fuga de vapor o algo raro, <b>no lo destrabes ni lo manipules</b>: avisa al operador o a la jefatura del área. Los autoclaves trabajan con vapor a presión: mantente alejado.","k":"Si no es tu equipo, no se toca."},{"s":"pe_cinta_mal","t":"Respeta las zonas de proceso","x":"<ul><li>No te acerques a cintas ni máquinas <b>en movimiento</b>: atrapan ropa, pelo y manos.</li><li>No distraigas a quien opera: espera a que te atienda.</li><li>Respeta la señalética y las zonas restringidas.</li><li>Fuera de tu oficina, tú eres el visitante: sigue las instrucciones del área.</li></ul>"},{"s":"pe_peaton","t":"Patio y romana","x":"En el patio y la romana circulan camiones y grúas horquilla:<ul><li>Usa <b>chaleco reflectante</b>.</li><li>Camina por la <b>ruta peatonal</b>.</li><li>Busca <b>contacto visual</b> con el conductor antes de cruzar.</li><li>Nunca te pongas detrás de un camión o una grúa que retrocede.</li></ul>Si no ves los ojos del conductor, él no te ve."}],"quiz":[{"s":"pe_admin_planta","v":[{"q":"Debes entrar a la conservera a revisar algo. ¿Qué haces primero?","o":["Aviso a la jefatura del área y me pongo el EPP","Entro rápido así como estoy","Entro solo hasta la mitad de la sala","Entro con el EPP de la oficina"],"w":"Siempre con el EPP de la zona y avisando a la jefatura del área."},{"q":"¿Qué EPP necesitas para entrar a la zona de proceso de la conservera?","o":["Cofia, mascarilla, pechera y botas","Solo chaleco reflectante","Solo zapatos de seguridad","Ninguno, si no toco producto"],"w":"En la conservera: cofia, mascarilla, pechera y botas, como los operarios."},{"q":"Si voy a entrar a la sala de proceso solo un minuto, no necesito ponerme el EPP.","vf":false,"w":"Falso. Sin EPP no se entra, aunque sea un minuto."}]},{"s":"pe_filtro","v":[{"q":"Vas a entrar a la sala de proceso con tu anillo y tu reloj. ¿Qué haces?","o":["Me los saco y me lavo las manos","Los cubro con el guante y entro","Entro, porque no voy a tocar producto","Me saco solo el reloj y entro"],"w":"Las joyas pueden caer al producto o engancharse en una máquina."},{"q":"¿Por qué se pasa por el pediluvio y se lavan las manos al entrar?","o":["Para cuidar la inocuidad de los alimentos","Solo para refrescarse","Porque es parte de la evacuación","Para que no se gaste el EPP"],"w":"El filtro sanitario protege el alimento que se produce."},{"q":"¿Qué se hace con la comida o bebida al entrar a la zona de proceso?","o":["No se entra con ellas","Se dejan en un rincón de la sala","Se guardan en el bolsillo de la pechera","Se pueden llevar si están cerradas"],"w":"No se entra con comida ni bebidas a la zona de proceso."}]},{"s":"pe_no_operar","v":[{"q":"Ves una lata trabada en la cinta. Eres administrativo. ¿Qué haces?","o":["Aviso al operador o a la jefatura","La saco yo con cuidado","Apago la máquina desde el tablero","La empujo con un palo"],"w":"No se opera ni se destraba lo que no te corresponde."},{"q":"Un operador te pide que muevas la grúa horquilla un par de metros. ¿Qué haces?","o":["No: no estoy capacitado ni autorizado","La muevo despacio, si es poco","La muevo si él me va guiando","La muevo si nadie está cerca"],"w":"Solo opera quien está capacitado y autorizado."},{"q":"Un administrativo puede abrir la válvula de un autoclave si el operador no está.","vf":false,"w":"Falso. Los autoclaves trabajan con vapor a presión: solo los opera personal autorizado."}]},{"s":"pe_autoclave","v":[{"q":"Pasas cerca de los autoclaves y ves que sale vapor por un costado. ¿Qué haces?","o":["Me alejo y aviso al operador o a la jefatura","Cierro yo la válvula más cercana","Me acerco a ver de dónde sale","Sigo, porque es normal que salga vapor"],"w":"Una fuga de vapor puede causar quemaduras graves: no se manipula, se avisa."},{"q":"¿Por qué un administrativo debe mantenerse alejado de los autoclaves?","o":["Porque trabajan con vapor a presión","Porque hacen mucho ruido","Porque están siempre detenidos","Porque son muy delicados"],"w":"El vapor a presión puede causar quemaduras graves."},{"q":"Un autoclave tiene un ruido raro y no hay nadie cerca. ¿Qué haces?","o":["Aviso de inmediato a la jefatura","Lo apago desde el tablero","Abro la tapa para revisar","Espero a ver si se detiene"],"w":"Si algo está raro, se avisa: no se manipula."}]},{"s":"pe_piso","v":[{"q":"El piso de la sala de proceso está mojado y vas apurado. ¿Cómo caminas?","o":["Camino sin correr y por la ruta demarcada","Corro por el borde seco","Camino rápido con pasos largos","Corro, porque las botas no resbalan"],"w":"Los pisos mojados hacen resbalar: camina, no corras."},{"q":"¿Qué haces al bajar una escalera húmeda en la planta?","o":["Uso el pasamanos y bajo sin correr","Bajo rápido para salir antes","Bajo leyendo el celular","Bajo con las manos en los bolsillos"],"w":"Pasamanos y sin correr, sobre todo en zonas mojadas."},{"q":"Ves un charco grande en la ruta peatonal. ¿Qué corresponde?","o":["Rodearlo y avisar a la jefatura del área","Pasar corriendo por encima","Pasar por la ruta de grúas","Ignorarlo, porque siempre hay agua"],"w":"Una condición insegura se avisa; la ruta de grúas no es alternativa."}]},{"s":"pe_cinta_mal","v":[{"q":"Necesitas hablar con un operador que está trabajando en la cinta. ¿Qué haces?","o":["Espero a que pueda atenderme","Lo llamo tocándole el hombro","Me acerco por el lado de la cinta","Le grito para que me oiga"],"w":"No distraigas a quien opera: una distracción en la cinta puede causar un atrapamiento."},{"q":"¿Por qué no te debes acercar a una cinta en movimiento?","o":["Porque puede atrapar ropa, pelo o manos","Porque se puede ensuciar el producto","Porque hace ruido","Porque se puede detener"],"w":"Las partes en movimiento atrapan."},{"q":"Una zona tiene una cadena con un letrero de acceso restringido. ¿Qué haces?","o":["No paso y pregunto a la jefatura","Paso por debajo si es algo rápido","Paso si nadie me está viendo","Paso si llevo el EPP de la zona"],"w":"Se respeta la señalética y las zonas restringidas."}]},{"s":"pe_peaton","v":[{"q":"Puedo caminar por el patio mirando el celular si voy apurado.","vf":false,"w":"Falso. En el patio: ruta peatonal, atención y sin celular."},{"q":"Vas a cruzar el patio y se acerca un camión. ¿Qué haces?","o":["Busco contacto visual con el chofer","Cruzo rápido delante del camión","Cruzo por detrás del camión","Cruzo levantando la mano sin mirar"],"w":"Si no ves los ojos del conductor, él no te ve."},{"q":"¿Qué usas para caminar por el patio y la romana?","o":["Chaleco reflectante y ruta peatonal","Solo la ropa de oficina","Ruta de camiones, que es más corta","Gorro y mascarilla"],"w":"En el patio: chaleco reflectante y ruta peatonal."}]}]},{"id":"admin_atencion","sec":"admin","title":"Atención de choferes, proveedores y visitas","thumb":"pe_ventanilla","learn":[{"s":"pe_ventanilla","t":"Atención con calma","x":"En la oficina, la romana y el despacho atendemos choferes, proveedores y visitas. Da <b>instrucciones claras</b>: dónde estacionar, dónde descargar, por dónde caminar y dónde esperar. Los choferes externos esperan en el <b>lugar habilitado</b> y no recorren la planta por su cuenta. Escucha, repite lo que entendiste y ofrece una solución: un buen trato evita conflictos."},{"s":"pe_registro","t":"Registro y reglas","x":"Toda visita se <b>registra en portería</b> y recibe las reglas básicas de {EMP}:<ul><li>EPP de la zona.</li><li>Rutas peatonales y zonas prohibidas.</li><li>Qué hacer en una emergencia.</li></ul>Si la visita entra a la planta, va <b>acompañada</b> todo el tiempo y cumple el filtro sanitario. Nadie entra sin registro, aunque tenga apuro.","k":"Visita registrada, con EPP y acompañada."},{"s":"pe_agresivo","t":"Si alguien se pone agresivo","x":"<ul><li>Habla con <b>calma y tono bajo</b>: si sube la voz, tú la bajas.</li><li>No discutas ni respondas insultos.</li><li>Mantén <b>distancia</b>, con el mesón entre ambos y la salida libre.</li><li>Pide <b>apoyo</b> a un compañero o a tu jefatura.</li><li>Si hay amenaza, <b>retírate</b> y llama al 133.</li></ul>Nunca salgas del mesón a enfrentar a alguien.","k":"Calma, distancia y apoyo: nunca enfrentes."},{"s":"ap_karin","t":"Violencia de terceros: Ley Karin","x":"La Ley 21.643, o Ley Karin, vigente desde el 1 de agosto de 2024, incluye la <b>violencia de clientes, proveedores y choferes</b> hacia los trabajadores. Si te insultan, amenazan o agreden:<ul><li><b>Registra</b>: fecha, hora, qué dijo o hizo y testigos.</li><li><b>Informa</b> a tu jefatura.</li><li>Puedes <b>denunciar</b> según el protocolo de {EMP}.</li><li>Pide apoyo psicológico en la ACHS.</li></ul>"},{"s":"transito_retro","t":"Al salir al patio","x":"Si sales a coordinar una carga o a revisar la romana:<ul><li>Usa <b>chaleco reflectante</b>.</li><li>Camina por la <b>ruta peatonal</b>.</li><li>Nunca te pongas <b>detrás de un camión que retrocede</b>: es su punto ciego más grande.</li><li>Haz <b>contacto visual</b> con el conductor antes de acercarte.</li></ul>Si no ves los ojos del chofer, él no te ve."}],"quiz":[{"s":"pe_agresivo","v":[{"q":"Un chofer llega molesto por la espera y levanta la voz. ¿Qué es lo correcto?","o":["Calma, no discuto y pido apoyo","Le respondo con el mismo tono","Lo dejo pasar sin registro","Salgo del mesón a calmarlo"],"w":"Calma, distancia y apoyo."},{"q":"Un proveedor comienza a gritarte en la ventanilla. ¿Cómo respondes?","o":["Con calma y en tono bajo","Subiendo la voz para que me escuche","Ignorándolo hasta que se calme","Respondiendo a sus insultos"],"w":"Si sube la voz, tú la bajas."},{"q":"Un chofer te amenaza con golpearte. ¿Qué haces?","o":["Me retiro, pido apoyo y llamo al 133","Salgo del mesón a enfrentarlo","Le respondo la amenaza","Sigo atendiéndolo como si nada"],"w":"Ante una amenaza: retírate, pide apoyo y llama a Carabineros."}]},{"s":"pe_registro","v":[{"q":"Una visita debe entrar a la planta. ¿Cómo entra?","o":["Registrada, con EPP y acompañada","Sola, para no perder tiempo","Registrada, pero sin EPP si es corto","Con EPP, pero sin registro"],"w":"Registrada, con EPP y acompañada todo el tiempo."},{"q":"Un proveedor conocido dice que viene todas las semanas y no necesita registrarse. ¿Qué haces?","o":["Lo registro igual en portería","Lo dejo pasar porque lo conozco","Lo dejo pasar si va rápido","Le pido que se registre a la salida"],"w":"Nadie entra sin registro, aunque sea conocido o tenga apuro."},{"q":"Una visita registrada puede recorrer la planta sola si ya recibió las reglas básicas.","vf":false,"w":"Falso. La visita que entra a la planta va acompañada todo el tiempo."}]},{"s":"transito_retro","v":[{"q":"Para coordinar una descarga puedo pararme detrás del camión mientras retrocede.","vf":false,"w":"Falso. Atrás está el punto ciego más grande del camión."},{"q":"Sales a coordinar una descarga y el camión empieza a retroceder. ¿Dónde te ubicas?","o":["Fuera de su trayectoria, a la vista del chofer","Detrás del camión para guiarlo","Junto a la rueda trasera","Detrás, pero gritando para que sepa"],"w":"Nunca detrás de un camión que retrocede: es su punto ciego."},{"q":"Vas a acercarte a un camión en el patio. ¿Qué haces antes?","o":["Hago contacto visual con el chofer","Me acerco por detrás","Toco la carrocería para que sepa","Me acerco por el lado derecho de la cabina"],"w":"Si no ves los ojos del chofer, él no te ve."}]},{"s":"ap_distancia","v":[{"q":"Atiendes a un chofer alterado. ¿Dónde te conviene estar?","o":["Con el mesón entre ambos y salida libre","Frente a él, fuera del mesón","En un rincón donde nadie nos vea","Muy cerca de él para calmarlo"],"w":"Distancia y salida libre te permiten retirarte si es necesario."},{"q":"¿Qué debe quedar libre cuando atiendes a alguien alterado?","o":["Tu salida","Su paso hacia la planta","El mesón para que se apoye","La puerta de bodega"],"w":"Mantener tu salida libre te permite retirarte si la situación empeora."},{"q":"Un proveedor alterado quiere pasar detrás del mesón para hablar contigo. ¿Qué haces?","o":["Mantengo el mesón entre ambos","Lo dejo pasar para calmarlo","Salgo yo del mesón a su lado","Lo empujo para que no pase"],"w":"El mesón entre ambos da distancia; pedir apoyo evita quedar solo."}]},{"s":"karin_terceros","v":[{"q":"Un chofer de un proveedor te insulta seguido cada vez que viene. ¿Qué corresponde?","o":["Registro, informo y puedo denunciar","Aguanto, porque es un tercero","Le respondo de la misma forma","Dejo de atenderlo sin avisar"],"w":"La Ley Karin incluye la violencia de clientes, proveedores y choferes."},{"q":"¿La Ley Karin protege frente a la violencia de personas externas, como proveedores o choferes?","o":["Sí, incluye a terceros","No, solo entre compañeros","No, solo de jefaturas","Solo si hay golpes"],"w":"La Ley 21.643 incluye la violencia de terceros hacia los trabajadores."},{"q":"¿Desde cuándo está vigente la Ley Karin?","o":["Desde el 1 de agosto de 2024","Desde el 1 de enero de 2023","Desde febrero de 2025","Desde marzo de 2024"],"w":"La Ley 21.643 está vigente desde el 1 de agosto de 2024."}]},{"s":"ap_registra","v":[{"q":"Después de un episodio de agresión verbal en la ventanilla, ¿qué registras?","o":["Fecha, hora, qué pasó y testigos","Solo el nombre de su empresa","Solo mi opinión sobre el chofer","Nada, si no hubo golpes"],"w":"Un buen registro sirve para informar y denunciar."},{"q":"¿Para qué sirve registrar una agresión de un tercero?","o":["Para informar y respaldar la denuncia","Para poder cobrarle al tercero","Solo para las estadísticas","Para nada, si no hay testigos"],"w":"Registrar fecha, hora, qué pasó y testigos respalda la denuncia."},{"q":"Tras una agresión de un proveedor quedaste muy afectado. ¿Dónde puedes pedir apoyo?","o":["En la ACHS, además de informar a tu jefatura","Solo con tus compañeros","En ninguna parte, es parte del trabajo","Solo con el proveedor"],"w":"Puedes pedir apoyo psicológico en la ACHS."}]},{"s":"pe_ventanilla","v":[{"q":"Un chofer pregunta dónde descargar. ¿Qué le indicas?","o":["Dónde estacionar, descargar y esperar","Que busque a alguien en la planta","Que entre y pregunte en producción","Solo el número del andén asignado"],"w":"Instrucciones claras evitan que recorra la planta sin saber."},{"q":"Un chofer externo quiere bajar a recorrer la planta mientras descargan. ¿Qué le dices?","o":["Que espere en el lugar habilitado","Que puede pasear por el patio","Que entre a la sala de proceso","Que espere detrás del camión"],"w":"Los choferes externos esperan en el lugar habilitado y no recorren la planta."},{"q":"Un proveedor está molesto porque su pedido no aparece. ¿Cuál es un buen primer paso?","o":["Escucharlo y ofrecer una solución","Decirle que no es mi problema","Pedirle que vuelva otro día","Explicarle que está equivocado"],"w":"Escuchar y ofrecer solución evita que el conflicto crezca."}]}]}]});
